			},
			path:     "/compat/ollama/v1/chat/completions",
			env:      map[string]string{"OPENAI_API_KEY": "sk-global"},
			response: `{"id":"compat","model":"gpt-5.5","usage":{"prompt_tokens":1,"completion_tokens":1}}`,
