			}

			var logBytes bytes.Buffer
			srv := &Server{logger: slog.New(slog.NewTextHandler(&logBytes, &slog.HandlerOptions{Level: slog.LevelInfo}))}
			headers := tc.headers.Clone()
			srv.applyUpstreamAuthFallback(tc.provider, tc.credential, headers)

			if got := headers.Get("authorization"); got != tc.wantAuth {
				t.Errorf("Authorization = %q, want %q", got, tc.wantAuth)
			}
			if got := headers.Get("x-api-key"); got != tc.wantXAPIKey {
				t.Errorf("x-api-key = %q, want %q", got, tc.wantXAPIKey)
			}
			if got := headers.Get("x-goog-api-key"); got != tc.wantXGoogKey {
				t.Errorf("x-goog-api-key = %q, want %q", got, tc.wantXGoogKey)
			}
			if got := headers.Get("api-key"); got != tc.wantAzureKey {
				t.Errorf("api-key = %q, want %q", got, tc.wantAzureKey)
			}
			logText := logBytes.String()
			if count := strings.Count(logText, "placeholder auth replaced from env"); count != tc.wantLogCount {
				t.Fatalf("fallback log count = %d, want %d (logs %q)", count, tc.wantLogCount, logText)
			}
			for _, key := range tc.env {
				if key != "" && strings.Contains(logText, key) {
					t.Fatalf("fallback log leaked key value: %q", logText)
				}
			}
		})
	}
}

func clearAuthFallbackEnv(t *testing.T) {
	t.Helper()
	for _, name := range []string{"OPENAI_API_KEY", "ANTHROPIC_API_KEY", "GEMINI_API_KEY", "GOOGLE_API_KEY", "AZURE_OPENAI_API_KEY", "OPENAI_COMPAT_API_KEY", "OPENROUTER_API_KEY"} {
		t.Setenv(name, "")
	}
}

package gateway

import (
	"net/http"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

type AuthMode string

const (
	AuthModePAYG         AuthMode = "payg"
	AuthModeOAuth        AuthMode = "oauth"
	AuthModeSubscription AuthMode = "subscription"
	AuthModeUnknown      AuthMode = "unknown"
)

var subscriptionUserAgentPrefixes = []string{
	"claude-cli/",
	"claude-code/",
	"codex-cli/",
	"cursor/",
	"claude-vscode/",
	"github-copilot/",
	"anthropic-cli/",
	"antigravity/",
}

// ClassifyAuthMode classifies the caller from header shape only. It is pure and
// must never log header values: token shapes are enough for policy.
func ClassifyAuthMode(h http.Header) AuthMode {
	if mode, ok := classifyHeaderAuthMode(h); ok {
		return mode
	}
	return AuthModeUnknown
}

// ClassifyResolvedAuthMode includes the credential resolver's final BYOK/config
// key. Header-only classification labeled a configured subscription/OAuth token
// as PAYG whenever the client omitted Authorization, creating phantom spend.
func ClassifyResolvedAuthMode(h http.Header, credential providers.Credential) AuthMode {
	if mode, explicit := classifyCredentialAuthKind(credential); explicit {
		return mode
	}
	if mode, ok := classifyHeaderAuthMode(h); ok {
		return mode
	}
	return classifyCredential(credential)
}

func classifyHeaderAuthMode(h http.Header) (AuthMode, bool) {
	ua := strings.ToLower(h.Get("user-agent"))
	for _, prefix := range subscriptionUserAgentPrefixes {
		if strings.Contains(ua, prefix) {
			return AuthModeSubscription, true
		}
	}

	auth := strings.TrimSpace(h.Get("authorization"))
	if auth != "" {
		scheme, value, ok := strings.Cut(auth, " ")
		if !ok || !strings.EqualFold(scheme, "bearer") {
			return AuthModeOAuth, true
		}
		return classifyCredential(providers.Credential{Key: strings.TrimSpace(value), Scheme: "bearer"}), true
	}

	if strings.TrimSpace(h.Get("x-api-key")) != "" || strings.TrimSpace(h.Get("x-goog-api-key")) != "" {
		return AuthModePAYG, true
	}
	return AuthModeUnknown, false
}

func classifyCredential(credential providers.Credential) AuthMode {
	if mode, explicit := classifyCredentialAuthKind(credential); explicit {
		return mode
	}
	token := strings.TrimSpace(credential.Key)
	lower := strings.ToLower(token)
	switch {
	case token == "":
		return AuthModeUnknown
	case strings.HasPrefix(lower, "sk-ant-oat"), strings.HasPrefix(lower, "sk-ant-sid"), strings.HasPrefix(lower, "sess-"):
		return AuthModeSubscription
	case strings.HasPrefix(lower, "bearer "), strings.HasPrefix(lower, "ya29."), strings.Count(token, ".") >= 2:
		return AuthModeOAuth
	case strings.HasPrefix(token, "sk-ant-api"), strings.HasPrefix(token, "sk-"), strings.HasPrefix(token, "AIza"), strings.HasPrefix(token, "AKIA"), strings.HasPrefix(token, "ASIA"):
		return AuthModePAYG
	case strings.EqualFold(credential.Scheme, "bearer"):
		return AuthModeOAuth
	default:
		return AuthModeUnknown
	}
}

// classifyCredentialAuthKind trusts only resolver-stamped credential metadata.
// Bedrock API keys travel over Bearer but are paid AWS credentials, not OAuth;
// IAM access keys are likewise PAYG. An unknown explicit kind fails closed rather
// than falling back to a token-shape guess.
func classifyCredentialAuthKind(credential providers.Credential) (AuthMode, bool) {
	switch strings.ToLower(strings.TrimSpace(credential.AuthKind)) {
	case "":
		return AuthModeUnknown, false
	case "bedrock_api_key", "aws_access_keys":
		return AuthModePAYG, true
	default:
		return AuthModeUnknown, true
	}
}

package gateway

import (
	"net/http"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func TestClassifyAuthModeTable(t *testing.T) {
	cases := []struct {
		name string
		h    http.Header
		want AuthMode
	}{
		{"ua subscription wins over payg token", http.Header{"User-Agent": {"codex-cli/1.0"}, "Authorization": {"Bearer sk-ant-api123"}}, AuthModeSubscription},
		{"claude code ua", http.Header{"User-Agent": {"Claude-Code/2.0"}}, AuthModeSubscription},
		{"anthropic oat token is subscription credential", http.Header{"Authorization": {"Bearer sk-ant-oat-abc"}}, AuthModeSubscription},
		{"anthropic payg", http.Header{"Authorization": {"Bearer sk-ant-api-abc"}}, AuthModePAYG},
		{"generic sk payg", http.Header{"Authorization": {"Bearer sk-project"}}, AuthModePAYG},
		{"jwt oauth", http.Header{"Authorization": {"Bearer aaa.bbb.ccc"}}, AuthModeOAuth},
		{"non bearer oauth", http.Header{"Authorization": {"Basic abc"}}, AuthModeOAuth},
		{"x api key payg", http.Header{"X-Api-Key": {"sk-agent"}}, AuthModePAYG},
		{"google api key payg", http.Header{"X-Goog-Api-Key": {"AIza"}}, AuthModePAYG},
		{"bearer unknown is oauth", http.Header{"Authorization": {"Bearer opaque-token"}}, AuthModeOAuth},
		{"missing credential is unknown", http.Header{}, AuthModeUnknown},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := ClassifyAuthMode(tc.h); got != tc.want {
				t.Fatalf("ClassifyAuthMode = %s, want %s", got, tc.want)
			}
		})
	}
}

func TestClassifyResolvedAuthModeUsesConfiguredCredential(t *testing.T) {
	if got := ClassifyResolvedAuthMode(http.Header{}, providers.Credential{Key: "sk-ant-oat-configured"}); got != AuthModeSubscription {
		t.Fatalf("configured subscription = %s", got)
	}
	if got := ClassifyResolvedAuthMode(http.Header{}, providers.Credential{Key: "sk-ant-api-configured"}); got != AuthModePAYG {
		t.Fatalf("configured PAYG = %s", got)
	}
	if got := ClassifyResolvedAuthMode(http.Header{}, providers.Credential{Key: "opaque", Scheme: "bearer"}); got != AuthModeOAuth {
		t.Fatalf("configured bearer = %s", got)
	}
}

func TestClassifyResolvedAuthModeBedrockCredentialsArePAYG(t *testing.T) {
	for _, tc := range []struct {
		name       string
		header     http.Header
		credential providers.Credential
	}{
		{
			name:       "opaque API key transported as bearer",
			header:     http.Header{"Authorization": {"Bearer opaque-bedrock-token"}},
			credential: providers.Credential{Key: "opaque-bedrock-token", Scheme: "bearer", AuthKind: "bedrock_api_key"},
		},
		{
			name:       "Claude Code user agent still bills AWS",
			header:     http.Header{"User-Agent": {"claude-cli/2.0"}},
			credential: providers.Credential{Key: "opaque-bedrock-token", Scheme: "bearer", AuthKind: "bedrock_api_key"},
		},
		{
			name:       "IAM access keys",
			header:     http.Header{},
			credential: providers.Credential{Key: "AKIAEXAMPLE:secret", AuthKind: "aws_access_keys"},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := ClassifyResolvedAuthMode(tc.header, tc.credential); got != AuthModePAYG {
				t.Fatalf("ClassifyResolvedAuthMode = %s, want PAYG for explicit Bedrock credential", got)
			}
		})
	}
}

package gateway

import (
	"encoding/json"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// breakpointPlanOptimizerID labels the cache-breakpoint planner in
// x-cave-optimization and on the telemetry row, so a request whose breakpoints we
// planned is never indistinguishable from one we left alone.
//
// It is deliberately absent from cacheOptimizerIDs. Anthropic-direct breakpoints
// are the provider_causal_cache method, so listing this id there would start
// attributing cache savings to planner-placed breakpoints. That promotion needs
// the exact provider/method/optimizer tuple discipline in
// docs/SAVINGS_ACCOUNTING.md and is a deliberate later change with its own
// review. Today the planner claims no tokens, no ratio, and no dollars.
const breakpointPlanOptimizerID = "cache-breakpoint-plan"

// breakpointPlanModeFrontier is the one value that enables the planner. It names
// what is placed — a rolling frontier breakpoint plus the lookback guard — rather
// than promising a saving. "", "off", and any unrecognized value all mean off,
// normalized in the config loader AND re-checked here.
const breakpointPlanModeFrontier = "frontier"

// BreakpointPlanner is the optional adapter capability that places provider-native
// cache routing metadata on the upstream request: Anthropic cache_control
// breakpoints, OpenAI prompt_cache_key. Neither is model-visible, so both are
// byte-safe under honesty rule #2 — they are hints on the upstream request only.
//
// ok=false means "leave the body exactly as it is", which is what every parse
// anomaly, every unsupported shape, and every already-managed request returns.
type BreakpointPlanner interface {
	PlanCacheBreakpoints(body []byte, meta providers.RequestMetadata, payg bool) ([]byte, bool)
}

// breakpointPlanAllowed reports whether the planner may run for this request.
//
// Two gates, both fail-closed: the operator flag (default off — the lever does
// not ship on by default, it ships behind the escalation ladder), and the session
// tripwire, which takes the lever away for the rest of a session that measured
// harm from it.
func (s *Server) breakpointPlanAllowed(sessionID string) bool {
	if s.breakpointPlan != breakpointPlanModeFrontier {
		return false
	}
	return s.ledger.LeverAllowed(sessionID, leverBreakpointPlan)
}

// planBreakpoints runs the adapter's planner over the bytes that are actually
// going upstream. An adapter without the capability, a planner that declined, an
// empty result, or output that is not valid JSON all leave the body untouched.
func (s *Server) planBreakpoints(adapter providers.Adapter, body []byte, meta providers.RequestMetadata, payg bool) ([]byte, bool) {
	planner, ok := adapter.(BreakpointPlanner)
	if !ok {
		return nil, false
	}
	out, ok := planner.PlanCacheBreakpoints(body, meta, payg)
	if !ok || len(out) == 0 || !json.Valid(out) {
		return nil, false
	}
	return out, true
}

// observeSession records one completed call in the session ledger and logs any
// lever the harm tripwire just froze. It is content-blind: only token counters
// and lever names cross this boundary.
func (s *Server) observeSession(sessionID string, active []lever, usage providers.UsageObservation, requestID string) {
	froze := s.ledger.Observe(sessionID, active, usage)
	if len(froze) == 0 || s.logger == nil {
		return
	}
	for _, lv := range froze {
		s.logger.Warn("harm tripwire froze an optimization lever for this session",
			"lever", string(lv),
			"request_id", requestID,
			"cache_creation_input_tokens", usage.CacheCreationInputTokens,
			"strikes", tripwireStrikesToFreeze)
	}
}

// tripwireDisclosure renders the x-caveman-tripwire header value for a session,
// or "" when nothing is frozen.
//
// The freeze is decided from a call's usage, which the proxy only learns AFTER
// the response headers have gone to the client — so the request that trips the
// wire cannot carry its own disclosure. The header appears on every later request
// of that session, which is precisely the set of requests the freeze changes.
func (s *Server) tripwireDisclosure(sessionID string) string {
	frozen := s.ledger.FrozenLevers(sessionID)
	if len(frozen) == 0 {
		return ""
	}
	parts := make([]string, 0, len(frozen))
	for _, lv := range frozen {
		parts = append(parts, string(lv)+"=frozen")
	}
	return strings.Join(parts, ",")
}

package gateway

import (
	"crypto/sha256"
	"net/http"
	"strconv"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/anthropic"
	"github.com/JuliusBrussee/caveman/proxy/providers/openai"
)

// The cache-breakpoint planner adds provider-native cache metadata to the
// UPSTREAM request only — cache_control and prompt_cache_key are never shown to
// the model — so it is byte-safe under honesty rule #2. It still ships default
// OFF behind breakpoint_plan / CAVEMAN_BREAKPOINT_PLAN, because default-on is a
// claim the escalation ladder has not earned yet.

// planPAYGHeaders is a custom agent on its own Anthropic key: payg, and it
// identifies its session so the ledger can account for it.
var planPAYGHeaders = map[string]string{
	"x-api-key":         "sk-ant-api-test",
	"anthropic-version": "2023-06-01",
	"x-cave-session":    "sess-plan-1",
}

// planRespBody carries provider cache counters so the session ledger has real
// numbers to account.
func planRespBody(cacheCreation int) string {
	return `{"id":"msg","type":"message","model":"claude-sonnet-4-6","content":[{"type":"text","text":"ok"}],` +
		`"usage":{"input_tokens":1000,"output_tokens":10,"cache_read_input_tokens":0,` +
		`"cache_creation_input_tokens":` + strconv.Itoa(cacheCreation) + `}}`
}

func newBreakpointPlanServer(t *testing.T, adapter providers.Adapter, rt *captureTransport, cfg Config) (*Server, *captureSink) {
	t.Helper()
	sink := &captureSink{}
	if cfg.Auth == nil {
		cfg.Auth = stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "active"}}
	}
	cfg.Adapters = []providers.Adapter{adapter}
	cfg.Creds = passthroughTestCreds{}
	cfg.Sink = sink
	cfg.HTTPClient = &http.Client{Transport: rt}
	return New(cfg), sink
}

// planBody is a cold-start agent request: no cache_control anywhere.
const planBody = `{"model":"claude-sonnet-4-6","max_tokens":1024,` +
	`"tools":[{"name":"read","input_schema":{}}],` +
	`"system":"You are an agent.",` +
	`"messages":[{"role":"user","content":[{"type":"text","text":"hello"}]}]}`

// TestBreakpointPlanIsOffByDefault is the default-off pin: an unconfigured wrap
// forwards the request byte-identically and claims nothing.
func TestBreakpointPlanIsOffByDefault(t *testing.T) {
	rt := &captureTransport{responses: []string{planRespBody(0)}}
	srv, sink := newBreakpointPlanServer(t, anthropic.New("https://upstream.test"), rt, Config{})

	rec := serveBody(t, srv, "/v1/messages", planBody, planPAYGHeaders)

	if string(rt.bodies[0]) != planBody {
		t.Fatalf("default must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], planBody)
	}
	if got := rec.Header().Get("x-cave-optimization"); strings.Contains(got, breakpointPlanOptimizerID) {
		t.Fatalf("default disclosed the planner: %q", got)
	}
	if row := sink.last(t); len(row.OptimizationIDs) != 0 {
		t.Fatalf("default row claimed an optimization: %v", row.OptimizationIDs)
	}
}

// TestBreakpointPlanUnknownFlagValueIsOff: the flag fails closed. Anything the
// config loader does not recognize normalizes to "off", and the decision point
// re-checks the exact enabling value rather than "not empty".
func TestBreakpointPlanUnknownFlagValueIsOff(t *testing.T) {
	for _, mode := range []string{"", "off", "on", "true", "Frontier", "aggressive"} {
		t.Run("mode="+mode, func(t *testing.T) {
			rt := &captureTransport{responses: []string{planRespBody(0)}}
			srv, _ := newBreakpointPlanServer(t, anthropic.New("https://upstream.test"), rt,
				Config{BreakpointPlan: mode})

			serveBody(t, srv, "/v1/messages", planBody, planPAYGHeaders)

			if string(rt.bodies[0]) != planBody {
				t.Fatalf("flag %q enabled the planner: %s", mode, rt.bodies[0])
			}
		})
	}
}

// TestBreakpointPlanPlacesAndDiscloses: enabled, the planner places its cold-start
// set, names itself on the response and the row — and mints nothing.
func TestBreakpointPlanPlacesAndDiscloses(t *testing.T) {
	rt := &captureTransport{responses: []string{planRespBody(0)}}
	srv, sink := newBreakpointPlanServer(t, anthropic.New("https://upstream.test"), rt,
		Config{BreakpointPlan: breakpointPlanModeFrontier})

	rec := serveBody(t, srv, "/v1/messages", planBody, planPAYGHeaders)

	upstream := string(rt.bodies[0])
	if got := strings.Count(upstream, `"cache_control"`); got != 3 {
		t.Fatalf("upstream carries %d breakpoints, want 3: %s", got, upstream)
	}
	if !strings.Contains(rec.Header().Get("x-cave-optimization"), breakpointPlanOptimizerID) {
		t.Fatalf("optimization header = %q", rec.Header().Get("x-cave-optimization"))
	}
	row := sink.last(t)
	if strings.Join(row.OptimizationIDs, ",") != breakpointPlanOptimizerID {
		t.Fatalf("row optimizations = %v", row.OptimizationIDs)
	}
	// The planner mints nothing until its id earns a place in the minting set
	// under the provider/method/optimizer discipline (docs/SAVINGS_ACCOUNTING.md).
	if row.SavingsUSD != 0 {
		t.Fatalf("the planner booked a saving: %v", row.SavingsUSD)
	}
	if cacheOptimizerIDs[breakpointPlanOptimizerID] {
		t.Fatal("the planner id was added to the cache-savings minting set")
	}
}

// TestBreakpointPlanNeverRunsInRecordMode: record is an unconditional
// wire-preservation boundary, and so is the request-wide pass-through opt-out.
func TestBreakpointPlanNeverRunsInRecordMode(t *testing.T) {
	for _, tc := range []struct {
		name    string
		mode    string
		headers map[string]string
	}{
		{name: "record mode", mode: "record", headers: planPAYGHeaders},
		{name: "pass-through opt-out", mode: "active", headers: map[string]string{
			"x-api-key":         "sk-ant-api-test",
			"x-cave-session":    "sess-plan-1",
			"x-cave-transforms": "caveman.pass-through.v1",
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			rt := &captureTransport{responses: []string{planRespBody(0)}}
			srv, _ := newBreakpointPlanServer(t, anthropic.New("https://upstream.test"), rt, Config{
				BreakpointPlan: breakpointPlanModeFrontier,
				Auth:           stubAuth{rc: RequestContext{Label: "local", RuntimeMode: tc.mode}},
			})

			serveBody(t, srv, "/v1/messages", planBody, tc.headers)

			if string(rt.bodies[0]) != planBody {
				t.Fatalf("%s was transformed: %s", tc.name, rt.bodies[0])
			}
		})
	}
}

// TestBreakpointPlanSetsOpenAISessionCacheKey covers the cross-provider half:
// OpenAI's routing key is set from the session, hashed, and the raw session id
// never leaves the proxy.
func TestBreakpointPlanSetsOpenAISessionCacheKey(t *testing.T) {
	body := `{"model":"gpt-5.6","instructions":"You are an agent.","input":"hello"}`
	rt := &captureTransport{}
	srv, _ := newBreakpointPlanServer(t, openai.New("https://upstream.test"), rt,
		Config{BreakpointPlan: breakpointPlanModeFrontier})

	serveBody(t, srv, "/v1/responses", body, map[string]string{
		"authorization":  "Bearer sk-openai-test",
		"x-cave-session": "sess-plan-1",
	})

	upstream := string(rt.bodies[0])
	if !strings.Contains(upstream, `"prompt_cache_key":"`+openai.SessionCacheKey("sess-plan-1")+`"`) {
		t.Fatalf("session prompt_cache_key missing: %s", upstream)
	}
	if strings.Contains(upstream, "sess-plan-1") {
		t.Fatalf("the raw session id reached the provider: %s", upstream)
	}
}

// TestBreakpointPlanNeedsASession: without x-cave-session there is no stable
// scope to key on, so OpenAI's arm declines rather than invent one.
func TestBreakpointPlanNeedsASession(t *testing.T) {
	body := `{"model":"gpt-5.6","instructions":"You are an agent.","input":"hello"}`
	rt := &captureTransport{}
	srv, _ := newBreakpointPlanServer(t, openai.New("https://upstream.test"), rt,
		Config{BreakpointPlan: breakpointPlanModeFrontier})

	serveBody(t, srv, "/v1/responses", body, map[string]string{"authorization": "Bearer sk-openai-test"})

	if string(rt.bodies[0]) != body {
		t.Fatalf("a sessionless request was keyed: %s", rt.bodies[0])
	}
}

// TestTripwireFreezesTheToolSchemaStrip is the first consumer of LeverAllowed,
// end to end: a session whose cache-creation blows up after the strip ran loses
// the strip, fails open to the untouched catalog, and is told so in a header.
func TestTripwireFreezesTheToolSchemaStrip(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	// One quiet call establishes the baseline, then three spikes strike.
	responses := []string{
		planRespBody(1_000),
		planRespBody(10 * tripwireCacheCreationFloorTokens),
		planRespBody(10 * tripwireCacheCreationFloorTokens),
		planRespBody(10 * tripwireCacheCreationFloorTokens),
		planRespBody(1_000),
	}
	rt := &captureTransport{responses: responses}
	comp := &toolSchemaStripCompressor{}
	srv, _ := newToolSchemaStripServer(t, comp, rt, Config{
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	headers := map[string]string{"x-cave-session": "sess-harm"}
	for k, v := range subscriptionAgentHeaders {
		headers[k] = v
	}

	var last string
	for i := 0; i < len(responses); i++ {
		rec := serveBody(t, srv, "/v1/messages", body, headers)
		last = rec.Header().Get("x-caveman-tripwire")
	}

	if last != toolSchemaStripOptimizerID+"=frozen" {
		t.Fatalf("x-caveman-tripwire = %q, want the frozen strip", last)
	}
	// The last request ran with the lever frozen: the catalog goes upstream
	// exactly as the caller wrote it (fail-open to pass-through).
	final := rt.bodies[len(rt.bodies)-1]
	if sha256.Sum256(final) != sha256.Sum256([]byte(body)) {
		t.Fatalf("a frozen lever still rewrote the request: %s", final)
	}
	if comp.strips != len(responses)-1 {
		t.Fatalf("strip ran %d times, want %d (frozen on the last)", comp.strips, len(responses)-1)
	}
	// A different session is unaffected — the freeze is session-scoped.
	if !srv.ledger.LeverAllowed("sess-other", leverToolSchemaStrip) {
		t.Fatal("freezing one session took the strip from every session")
	}
}

// TestTripwireIsInertWithoutASession: a caller that does not identify its session
// keeps every lever forever. The tripwire needs a session to attribute harm to.
func TestTripwireIsInertWithoutASession(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	responses := []string{}
	for i := 0; i < 6; i++ {
		responses = append(responses, planRespBody(10*tripwireCacheCreationFloorTokens))
	}
	rt := &captureTransport{responses: responses}
	comp := &toolSchemaStripCompressor{}
	srv, _ := newToolSchemaStripServer(t, comp, rt, Config{
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	for i := 0; i < len(responses); i++ {
		rec := serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)
		if got := rec.Header().Get("x-caveman-tripwire"); got != "" {
			t.Fatalf("sessionless traffic was frozen: %q", got)
		}
	}
	if comp.strips != len(responses) {
		t.Fatalf("strip ran %d times, want %d", comp.strips, len(responses))
	}
}

package gateway

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"log/slog"
	"os"
	"path/filepath"
	"strconv"
	"sync/atomic"
)

// Body capture is a local diagnostic instrument, off unless CAVE_CAPTURE_DIR is
// set. It writes the bytes a request carried on BOTH sides of the transform —
// what the client sent and what the upstream received — so the question "what
// was actually in that request" is answered by observation.
//
// Bodies are stored BASE64-encoded (`body_encoding: "base64"`), never as JSON
// strings. A request body is arbitrary bytes and the truncation-style
// compressors this instrument diagnoses cut mid-rune, so a JSON string would
// silently substitute U+FFFD for invalid UTF-8 and the file would fail its own
// recorded sha256. The recorded hash always covers the WHOLE body and always
// verifies against the decoded bytes.
//
// It exists because it was not answerable before. The 2026-08-06 agent bench
// measured a wrap arm whose prefix carried ~61k tokens the bare arm's did not,
// and no artifact in the repo could say what those bytes were: the CLI
// transcript records what the agent sent, provider usage records what the
// provider counted, and nothing recorded what went over the wire between them.
// Every diagnosis of that gap was inference. See
// docs/research/agent-efficiency/2026-08-07-where-the-tokens-go.md.
//
// It is deliberately NOT wired to any product surface, telemetry sink, or
// savings figure. Captured bytes are request payloads — complete, UNREDACTED
// prompts, by design: redacted bytes cannot answer the question the instrument
// exists for. They belong on the operator's own disk, under a directory the
// operator named, and nowhere else. There is no TTL, no rotation, and no
// upload; deleting a capture directory is the operator's job.
//
// Nothing here may slow or fail traffic. record() hashes nothing, writes
// nothing, and never blocks: it hands the job to a single writer goroutine
// through a bounded queue and DROPS the record when the queue is full (drops are
// counted and logged, and the gap they leave in `seq` is itself visible in the
// file listing).
type bodyCapture struct {
	dir     string
	logger  *slog.Logger
	seq     atomic.Uint64
	jobs    chan captureJob
	queued  atomic.Int64
	dropped atomic.Uint64
}

const (
	// captureBodyLimit caps what one side of one request may put on disk. Over the
	// cap the body is omitted ENTIRELY rather than stored partially: a prefix that
	// fails the record's own sha256 is worse evidence than no bytes at all. The
	// hash and the length still describe the whole body.
	captureBodyLimit = 4 << 20
	// captureQueueDepth and captureQueueBytes bound what the instrument may hold in
	// memory while the writer catches up. Past either bound a record is dropped —
	// the request path never waits on a disk write.
	//
	// The byte budget is reserved on the FULL body size, not the stored
	// (capped) size, because the queue really does hold the full bytes — the
	// writer needs them to hash the whole body before applying captureBodyLimit.
	// A burst of over-cap bodies therefore transiently occupies budget for
	// records that store no bytes; that is the budget bounding memory, its job.
	captureQueueDepth = 32
	captureQueueBytes = 32 << 20
	// captureDropLogEvery keeps drop reporting visible without letting a slow disk
	// turn into a log flood.
	captureDropLogEvery = 64
)

// newBodyCapture returns nil when capture is off, so the hot path costs one nil
// check. A directory that cannot be created disables capture rather than
// failing the proxy: an instrument must never be able to break traffic.
func newBodyCapture(dir string, logger *slog.Logger) *bodyCapture {
	if dir == "" {
		return nil
	}
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return nil
	}
	c := &bodyCapture{dir: dir, logger: logger, jobs: make(chan captureJob, captureQueueDepth)}
	go c.run()
	return c
}

// capturedRequest is one request's two bodies plus the identity needed to line
// it up against a provider response. Sizes and hashes are recorded next to the
// bodies so a capture stays interpretable even when a body is omitted.
type capturedRequest struct {
	Seq         uint64 `json:"seq"`
	RequestID   string `json:"request_id"`
	Provider    string `json:"provider"`
	Endpoint    string `json:"endpoint"`
	RuntimeMode string `json:"runtime_mode"`
	Optimizers  string `json:"optimizers"`
	// RetryOriginal marks the SECOND record written for a request id after the
	// upstream rejected the transformed bytes and the proxy resent the original
	// (the 4xx fail-open in proxy.go and chatgpt.go). Its presence means the
	// earlier record for that id did not serve the request — these bytes did.
	RetryOriginal bool `json:"retry_original,omitempty"`
	// BodyEncoding names how ClientBody/UpstreamBody are encoded in this file, so a
	// reader never has to guess. Always "base64".
	BodyEncoding   string `json:"body_encoding"`
	ClientBytes    int    `json:"client_bytes"`
	UpstreamBytes  int    `json:"upstream_bytes"`
	ClientSHA256   string `json:"client_sha256"`
	UpstreamSHA256 string `json:"upstream_sha256"`
	Transformed    bool   `json:"transformed"`
	ClientBody     []byte `json:"client_body,omitempty"`
	UpstreamBody   []byte `json:"upstream_body,omitempty"`
	// UpstreamOmitted flags the pass-through case: identical bodies are stored
	// once. ClientOmitted/UpstreamOmitted*Reason* name the other two reasons bytes
	// are absent — "oversize" (over captureBodyLimit) and "streamed" (the caller
	// forwarded the body without ever holding it whole). In every case the hash and
	// the length still describe the whole body.
	UpstreamOmitted       bool   `json:"upstream_body_omitted_identical"`
	ClientOmittedReason   string `json:"client_body_omitted,omitempty"`
	UpstreamOmittedReason string `json:"upstream_body_omitted,omitempty"`
}

// captureMeta is the identity of one captured attempt. It carries no bytes so
// the byte slices stay explicit at the call site.
type captureMeta struct {
	RequestID     string
	Provider      string
	Endpoint      string
	RuntimeMode   string
	Optimizers    string
	RetryOriginal bool
}

// captureBody is one side's body as the CALLER holds it. wholeBody is the normal
// case; streamedBody is for a caller that forwarded the body straight through and
// only ever held a bounded prefix of it (the ChatGPT streaming path), which can
// still state the whole body's length and hash truthfully but has no bytes to
// store.
type captureBody struct {
	bytes []byte
	total int
	sum   string
}

func wholeBody(b []byte) captureBody { return captureBody{bytes: b, total: len(b)} }

func streamedBody(total int, sumHex string) captureBody {
	return captureBody{total: total, sum: sumHex}
}

type captureJob struct {
	seq      uint64
	meta     captureMeta
	client   captureBody
	upstream captureBody
	size     int64
	// barrier is a test-only ordering marker: the writer closes it in queue order,
	// which is how a test knows every earlier record has landed on disk.
	barrier chan struct{}
}

// record queues one capture. Every failure path is silent-and-continue by
// design: this runs on the request path, and a diagnostic that can fail or slow
// a user's request is worse than no diagnostic at all. Hashing, encoding, and
// the disk write all happen on the writer goroutine.
func (c *bodyCapture) record(meta captureMeta, client, upstream captureBody) {
	if c == nil {
		return
	}
	size := int64(len(client.bytes) + len(upstream.bytes))
	if c.queued.Add(size) > captureQueueBytes {
		c.queued.Add(-size)
		c.drop()
		return
	}
	job := captureJob{seq: c.seq.Add(1), meta: meta, client: client, upstream: upstream, size: size}
	select {
	case c.jobs <- job:
	default:
		c.queued.Add(-size)
		c.drop()
	}
}

func (c *bodyCapture) drop() {
	n := c.dropped.Add(1)
	if c.logger != nil && (n == 1 || n%captureDropLogEvery == 0) {
		c.logger.Warn("body capture dropped records; capture is lossy under load", "dropped_total", n, "dir", c.dir)
	}
}

// flush blocks until every record queued before the call has been written. It
// exists so tests can assert against the files; the request path never calls it.
func (c *bodyCapture) flush() {
	if c == nil {
		return
	}
	barrier := make(chan struct{})
	c.jobs <- captureJob{barrier: barrier}
	<-barrier
}

func (c *bodyCapture) run() {
	for job := range c.jobs {
		if job.barrier != nil {
			close(job.barrier)
			continue
		}
		c.write(job)
		c.queued.Add(-job.size)
	}
}

func (c *bodyCapture) write(job captureJob) {
	client := job.client.resolve()
	upstream := job.upstream.resolve()
	// An empty hash means the caller could not state one; it must never read as a
	// match, because "identical" is a claim.
	identical := client.sum != "" && client.sum == upstream.sum

	entry := capturedRequest{
		Seq:                 job.seq,
		RequestID:           job.meta.RequestID,
		Provider:            job.meta.Provider,
		Endpoint:            job.meta.Endpoint,
		RuntimeMode:         job.meta.RuntimeMode,
		Optimizers:          job.meta.Optimizers,
		RetryOriginal:       job.meta.RetryOriginal,
		BodyEncoding:        "base64",
		ClientBytes:         client.total,
		UpstreamBytes:       upstream.total,
		ClientSHA256:        client.sum,
		UpstreamSHA256:      upstream.sum,
		Transformed:         !identical,
		ClientBody:          client.bytes,
		ClientOmittedReason: client.omitted,
		UpstreamOmitted:     identical,
	}
	// An untransformed request would otherwise store the same payload twice, and
	// these files are large. The hashes still prove the two sides matched.
	if !identical {
		entry.UpstreamBody = upstream.bytes
		entry.UpstreamOmittedReason = upstream.omitted
	}

	encoded, err := json.Marshal(entry)
	if err != nil {
		return
	}
	name := strconv.FormatUint(job.seq, 10) + "-" + sanitizeCaptureID(job.meta.RequestID) + ".json"
	_ = os.WriteFile(filepath.Join(c.dir, name), encoded, 0o600)
}

// resolvedBody is one side after the writer has hashed it and applied the size
// cap: bytes are present or they are not, and the hash and length always cover
// the whole body either way.
type resolvedBody struct {
	bytes   []byte
	total   int
	sum     string
	omitted string
}

func (b captureBody) resolve() resolvedBody {
	out := resolvedBody{total: b.total, sum: b.sum}
	held := b.bytes != nil || b.total == 0
	if out.sum == "" && held {
		sum := sha256.Sum256(b.bytes)
		out.sum = hex.EncodeToString(sum[:])
	}
	switch {
	case !held:
		out.omitted = "streamed"
	case len(b.bytes) > captureBodyLimit:
		out.omitted = "oversize"
	default:
		out.bytes = b.bytes
	}
	return out
}

// sanitizeCaptureID keeps a request id usable as a filename. An id is
// proxy-generated, but it reaches this function as a string and a path
// separator in a filename is a directory traversal, so it is filtered rather
// than trusted.
func sanitizeCaptureID(id string) string {
	if id == "" {
		return "unknown"
	}
	out := make([]byte, 0, len(id))
	for i := 0; i < len(id) && i < 64; i++ {
		ch := id[i]
		switch {
		case ch >= 'a' && ch <= 'z', ch >= 'A' && ch <= 'Z', ch >= '0' && ch <= '9', ch == '-', ch == '_':
			out = append(out, ch)
		default:
			out = append(out, '_')
		}
	}
	return string(out)
}

package gateway

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/openai"
)

// readCaptures reads every capture in dir, sorted by seq, and verifies each
// stored body against the hash the file itself recorded. A capture that cannot
// prove its own bytes is worthless as evidence, so every test that reads
// captures enforces it.
func readCaptures(t *testing.T, dir string) []capturedRequest {
	t.Helper()
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatalf("read capture dir: %v", err)
	}
	var out []capturedRequest
	for _, e := range entries {
		raw, err := os.ReadFile(filepath.Join(dir, e.Name()))
		if err != nil {
			t.Fatalf("read capture %s: %v", e.Name(), err)
		}
		var c capturedRequest
		if err := json.Unmarshal(raw, &c); err != nil {
			t.Fatalf("decode capture %s: %v", e.Name(), err)
		}
		if c.BodyEncoding != "base64" {
			t.Errorf("capture %s: body_encoding = %q, want base64", e.Name(), c.BodyEncoding)
		}
		verifyCaptureBody(t, e.Name(), "client", c.ClientBody, c.ClientBytes, c.ClientSHA256)
		verifyCaptureBody(t, e.Name(), "upstream", c.UpstreamBody, c.UpstreamBytes, c.UpstreamSHA256)
		out = append(out, c)
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Seq < out[j].Seq })
	return out
}

func verifyCaptureBody(t *testing.T, name, side string, body []byte, size int, sum string) {
	t.Helper()
	if body == nil {
		return
	}
	if len(body) != size {
		t.Errorf("capture %s: %s body is %d bytes, record says %d", name, side, len(body), size)
	}
	got := sha256.Sum256(body)
	if hex.EncodeToString(got[:]) != sum {
		t.Errorf("capture %s: %s body fails its own sha256 (got %s, record says %s)",
			name, side, hex.EncodeToString(got[:]), sum)
	}
}

// captureProxyServer is the standard proxy wiring these tests drive through the
// real handler: one adapter, a socket-free upstream, no compressor.
func captureProxyServer(mode string, rt *captureTransport) *Server {
	return New(Config{
		Adapters:   []providers.Adapter{openai.New("https://upstream.test")},
		Auth:       stubAuth{rc: RequestContext{Label: "local", RuntimeMode: mode}},
		Creds:      stubCreds{key: "sk-byok"},
		Sink:       &captureSink{},
		HTTPClient: &http.Client{Transport: rt},
	})
}

func serveCaptureRequest(t *testing.T, srv *Server, path, body string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodPost, path, strings.NewReader(body))
	rec := httptest.NewRecorder()
	srv.Handler().ServeHTTP(rec, req)
	srv.capture.flush()
	return rec
}

// Capture is off by default. A nil capture must be safe to call — the proxy path
// calls it unconditionally.
func TestBodyCaptureDisabledIsNilAndSafe(t *testing.T) {
	c := newBodyCapture("", nil)
	if c != nil {
		t.Fatal("empty dir must disable capture")
	}
	c.record(captureMeta{RequestID: "req", Provider: "anthropic"}, wholeBody([]byte("a")), wholeBody([]byte("b")))
	c.flush()
}

// A transformed request is the case the instrument exists for: both sides must
// be recoverable, byte for byte, from the capture alone.
func TestBodyCaptureRecordsBothSidesWhenTransformed(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	if c == nil {
		t.Fatal("capture must be enabled for a writable dir")
	}
	client := []byte(`{"messages":[{"role":"user","content":"original bytes"}]}`)
	upstream := []byte(`{"messages":[{"role":"user","content":"elided"}]}`)
	c.record(captureMeta{
		RequestID:   "req-1",
		Provider:    "anthropic",
		Endpoint:    "/v1/messages",
		RuntimeMode: "compress",
		Optimizers:  "caveman.compress.v1",
	}, wholeBody(client), wholeBody(upstream))
	c.flush()

	got := readCaptures(t, dir)
	if len(got) != 1 {
		t.Fatalf("want 1 capture, got %d", len(got))
	}
	entry := got[0]
	if !bytes.Equal(entry.ClientBody, client) {
		t.Errorf("client body not preserved: %q", entry.ClientBody)
	}
	if !bytes.Equal(entry.UpstreamBody, upstream) {
		t.Errorf("upstream body not preserved: %q", entry.UpstreamBody)
	}
	if !entry.Transformed {
		t.Error("differing bodies must be marked transformed")
	}
	if entry.ClientBytes != len(client) || entry.UpstreamBytes != len(upstream) {
		t.Errorf("sizes wrong: %d/%d", entry.ClientBytes, entry.UpstreamBytes)
	}
	if entry.ClientSHA256 == entry.UpstreamSHA256 {
		t.Error("differing bodies must hash differently")
	}
	if entry.Optimizers != "caveman.compress.v1" {
		t.Errorf("optimizers = %q", entry.Optimizers)
	}
}

// The bodies this instrument diagnoses are arbitrary bytes: a truncating
// compressor cuts mid-rune, and a JSON string would swap the invalid sequence
// for U+FFFD and quietly break the record's own hash. Base64 keeps it exact.
func TestBodyCaptureRoundTripsInvalidUTF8(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	client := []byte{'{', '"', 'a', '"', ':', '"', 0xff, 0xfe, 0x80, '"', '}'}
	upstream := []byte{0xff, 0xfe, 'c', 'u', 't'}
	c.record(captureMeta{RequestID: "req-utf8"}, wholeBody(client), wholeBody(upstream))
	c.flush()

	got := readCaptures(t, dir) // verifies both hashes against the decoded bytes
	if len(got) != 1 {
		t.Fatalf("want 1 capture, got %d", len(got))
	}
	if !bytes.Equal(got[0].ClientBody, client) {
		t.Errorf("client bytes mangled: % x", got[0].ClientBody)
	}
	if !bytes.Equal(got[0].UpstreamBody, upstream) {
		t.Errorf("upstream bytes mangled: % x", got[0].UpstreamBody)
	}
	if got[0].ClientBytes != len(client) {
		t.Errorf("client_bytes = %d, want %d", got[0].ClientBytes, len(client))
	}
}

// A pass-through would otherwise write the same payload twice. The hashes still
// have to prove the two sides matched, because "identical" is a claim.
func TestBodyCaptureOmitsDuplicateUpstreamButProvesEquality(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	same := []byte(`{"messages":[]}`)
	c.record(captureMeta{RequestID: "req-2", Provider: "anthropic", RuntimeMode: "record"}, wholeBody(same), wholeBody(same))
	c.flush()

	got := readCaptures(t, dir)
	if len(got) != 1 {
		t.Fatalf("want 1 capture, got %d", len(got))
	}
	entry := got[0]
	if entry.UpstreamBody != nil || !entry.UpstreamOmitted {
		t.Error("identical upstream body must be omitted and flagged")
	}
	if entry.Transformed {
		t.Error("identical bodies must not be marked transformed")
	}
	if entry.ClientSHA256 != entry.UpstreamSHA256 {
		t.Error("identical bodies must carry equal hashes")
	}
}

// Over the per-side cap the bytes are dropped entirely rather than stored as a
// prefix that would fail the record's own hash. The hash and length still
// describe the WHOLE body, which is what makes the record usable.
func TestBodyCaptureOversizeBodyOmitsBytesButHashesWholeBody(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	big := bytes.Repeat([]byte("x"), captureBodyLimit+1024)
	sum := sha256.Sum256(big)
	c.record(captureMeta{RequestID: "req-big"}, wholeBody(big), wholeBody(big))
	c.flush()

	got := readCaptures(t, dir)
	if len(got) != 1 {
		t.Fatalf("want 1 capture, got %d", len(got))
	}
	entry := got[0]
	if entry.ClientBody != nil {
		t.Errorf("over-cap body must not be stored, got %d bytes", len(entry.ClientBody))
	}
	if entry.ClientOmittedReason != "oversize" {
		t.Errorf("client_body_omitted = %q, want oversize", entry.ClientOmittedReason)
	}
	if entry.ClientBytes != len(big) || entry.ClientSHA256 != hex.EncodeToString(sum[:]) {
		t.Errorf("over-cap record must describe the whole body: %d bytes, %s", entry.ClientBytes, entry.ClientSHA256)
	}
}

// A caller that streamed the body through without ever holding it whole (the
// ChatGPT over-limit path) can still state the length and hash truthfully. It
// must never store bytes it does not have.
func TestBodyCaptureStreamedBodyRecordsHashWithoutBytes(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	sum := sha256.Sum256([]byte("streamed"))
	body := streamedBody(9_000_000, hex.EncodeToString(sum[:]))
	c.record(captureMeta{RequestID: "req-stream"}, body, body)
	c.flush()

	got := readCaptures(t, dir)
	if len(got) != 1 {
		t.Fatalf("want 1 capture, got %d", len(got))
	}
	entry := got[0]
	if entry.ClientBody != nil || entry.ClientOmittedReason != "streamed" {
		t.Errorf("streamed body must be omitted and flagged: %q", entry.ClientOmittedReason)
	}
	if entry.ClientBytes != 9_000_000 || entry.ClientSHA256 != hex.EncodeToString(sum[:]) {
		t.Errorf("streamed record must carry the caller's length and hash: %d %s", entry.ClientBytes, entry.ClientSHA256)
	}
	if entry.Transformed {
		t.Error("same body on both sides must not read as transformed")
	}
}

// Each request gets its own file, and the sequence is what puts a session's
// requests back in order — the whole point is reading prefix growth turn by turn.
func TestBodyCaptureSequencesEachRequest(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	for i := 0; i < 3; i++ {
		c.record(captureMeta{RequestID: "req"}, wholeBody([]byte("x")), wholeBody([]byte("y")))
	}
	c.flush()
	got := readCaptures(t, dir)
	if len(got) != 3 {
		t.Fatalf("want 3 captures, got %d", len(got))
	}
	seen := map[uint64]bool{}
	for _, e := range got {
		if seen[e.Seq] {
			t.Fatalf("duplicate seq %d", e.Seq)
		}
		seen[e.Seq] = true
	}
	for _, want := range []uint64{1, 2, 3} {
		if !seen[want] {
			t.Errorf("missing seq %d", want)
		}
	}
}

// The writer is a single goroutine behind a bounded queue: concurrent records
// must be race-free, and every record must be either written or counted as
// dropped — never silently lost.
func TestBodyCaptureConcurrentRecordsAreRaceFree(t *testing.T) {
	dir := t.TempDir()
	c := newBodyCapture(dir, nil)
	const n = 64
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			payload := []byte(strings.Repeat("c", i+1))
			c.record(captureMeta{RequestID: "req-concurrent"}, wholeBody(payload), wholeBody(payload))
		}(i)
	}
	wg.Wait()
	c.flush()

	got := readCaptures(t, dir)
	dropped := int(c.dropped.Load())
	if len(got)+dropped != n {
		t.Fatalf("written %d + dropped %d != %d records", len(got), dropped, n)
	}
	if c.queued.Load() != 0 {
		t.Errorf("queued byte budget leaked: %d", c.queued.Load())
	}
}

// A request id reaches the filename as a string; a separator in it would be a
// traversal. Filter rather than trust.
func TestSanitizeCaptureIDRejectsPathSeparators(t *testing.T) {
	for _, tc := range []struct{ in, want string }{
		{"", "unknown"},
		{"abc-123_XYZ", "abc-123_XYZ"},
		{"../../etc/passwd", "______etc_passwd"},
		{"a/b", "a_b"},
	} {
		if got := sanitizeCaptureID(tc.in); got != tc.want {
			t.Errorf("sanitizeCaptureID(%q) = %q, want %q", tc.in, got, tc.want)
		}
	}
}

// Default-off, through the real handler: an operator who never set the env var
// gets no instrument at all, and the bytes on the wire are untouched.
func TestCaptureDisabledByDefaultWritesNothing(t *testing.T) {
	t.Setenv("CAVE_CAPTURE_DIR", "")
	dir := t.TempDir()
	rt := &captureTransport{}
	srv := captureProxyServer("record", rt)
	if srv.capture != nil {
		t.Fatal("unset CAVE_CAPTURE_DIR must leave capture nil")
	}
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"hello"}]}`
	if rec := serveCaptureRequest(t, srv, "/v1/chat/completions", body); rec.Code != http.StatusOK {
		t.Fatalf("status = %d", rec.Code)
	}
	if len(rt.bodies) != 1 || string(rt.bodies[0]) != body {
		t.Fatalf("upstream body altered with capture off: %q", rt.bodies)
	}
	entries, err := os.ReadDir(dir)
	if err != nil || len(entries) != 0 {
		t.Fatalf("capture files written while disabled: %v %v", entries, err)
	}
}

// Enabling the instrument may not change one byte of what the upstream receives.
func TestCaptureEnabledLeavesUpstreamBytesIdentical(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"hello"}]}`

	t.Setenv("CAVE_CAPTURE_DIR", "")
	offRT := &captureTransport{}
	serveCaptureRequest(t, captureProxyServer("record", offRT), "/v1/chat/completions", body)

	t.Setenv("CAVE_CAPTURE_DIR", t.TempDir())
	onRT := &captureTransport{}
	srv := captureProxyServer("record", onRT)
	if srv.capture == nil {
		t.Fatal("CAVE_CAPTURE_DIR must enable capture")
	}
	serveCaptureRequest(t, srv, "/v1/chat/completions", body)

	if len(offRT.bodies) != 1 || len(onRT.bodies) != 1 {
		t.Fatalf("upstream calls = %d/%d, want 1/1", len(offRT.bodies), len(onRT.bodies))
	}
	if !bytes.Equal(offRT.bodies[0], onRT.bodies[0]) {
		t.Fatalf("capture changed the upstream bytes:\n off %q\n  on %q", offRT.bodies[0], onRT.bodies[0])
	}
}

// End to end through the handler on a body carrying invalid UTF-8: the capture
// must reproduce exactly the bytes the upstream received.
func TestCaptureThroughHandlerPreservesInvalidUTF8Bytes(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("CAVE_CAPTURE_DIR", dir)
	rt := &captureTransport{}
	srv := captureProxyServer("record", rt)

	body := "{\"model\":\"gpt-5.5\",\"messages\":[{\"role\":\"user\",\"content\":\"\xff\xfe cut\"}]}"
	if rec := serveCaptureRequest(t, srv, "/v1/chat/completions", body); rec.Code != http.StatusOK {
		t.Fatalf("status = %d", rec.Code)
	}
	if string(rt.bodies[0]) != body {
		t.Fatalf("upstream body altered: %q", rt.bodies[0])
	}
	got := readCaptures(t, dir)
	if len(got) != 1 {
		t.Fatalf("want 1 capture, got %d", len(got))
	}
	if !bytes.Equal(got[0].ClientBody, []byte(body)) {
		t.Fatalf("capture is not byte-exact:\n got % x\nwant % x", got[0].ClientBody, body)
	}
}

// The 4xx fail-open retry sends the ORIGINAL bytes. Without a second record the
// file on disk would claim the transformed bytes served the request — confident
// wrong evidence, which is the failure this instrument exists to remove.
func TestCaptureRecordsRetryWithOriginalBytes(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("CAVE_CAPTURE_DIR", dir)
	comp := &stubCompressor{out: []byte("X"), before: 100, after: 40, handle: "ccr_capture", recovered: []byte(chatReqStream)}
	rt := &captureTransport{
		statuses:  []int{http.StatusTooManyRequests, http.StatusOK},
		responses: []string{`{"type":"error","error":{"type":"rate_limit_error"}}`, chatRespBody},
	}
	srv := New(Config{
		Adapters:       []providers.Adapter{openai.New("https://upstream.test")},
		Auth:           stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "compress"}},
		Creds:          stubCreds{key: "sk-byok"},
		Sink:           &captureSink{},
		Compressor:     comp,
		RecoveryViaMCP: true,
		HTTPClient:     &http.Client{Transport: rt},
	})

	if rec := serveCaptureRequest(t, srv, "/v1/chat/completions", chatReqStream); rec.Code != http.StatusOK {
		t.Fatalf("status = %d", rec.Code)
	}
	if len(rt.bodies) != 2 {
		t.Fatalf("upstream calls = %d, want 2 (rejected transform, then original)", len(rt.bodies))
	}
	got := readCaptures(t, dir)
	if len(got) != 2 {
		t.Fatalf("want 2 captures (attempt + retry), got %d", len(got))
	}
	first, retry := got[0], got[1]
	if first.RetryOriginal || !first.Transformed {
		t.Errorf("first record must be the transformed attempt: retry=%v transformed=%v", first.RetryOriginal, first.Transformed)
	}
	if !bytes.Equal(first.UpstreamBody, rt.bodies[0]) {
		t.Errorf("first record must hold the rejected bytes:\n got %q\nwant %q", first.UpstreamBody, rt.bodies[0])
	}
	if !retry.RetryOriginal {
		t.Error("second record must be flagged retry_original")
	}
	if retry.RequestID != first.RequestID {
		t.Errorf("retry record must share the request id: %q vs %q", retry.RequestID, first.RequestID)
	}
	if !bytes.Equal(retry.ClientBody, []byte(chatReqStream)) || retry.Transformed {
		t.Errorf("retry record must hold the original bytes, untransformed: transformed=%v", retry.Transformed)
	}
	if !bytes.Equal(retry.ClientBody, rt.bodies[1]) {
		t.Error("retry record must match what the upstream actually received")
	}
}

// An operator who sets CAVE_CAPTURE_DIR and runs Codex must not get an empty
// directory: the ChatGPT route captures the same two sides.
func TestCaptureRecordsChatGPTRoute(t *testing.T) {
	dir := t.TempDir()
	t.Setenv("CAVE_CAPTURE_DIR", dir)
	rt := &captureTransport{responses: []string{`{"id":"resp"}`}}
	srv := New(Config{
		Auth:            stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "record"}},
		Sink:            &captureSink{},
		ChatGPTUpstream: "https://chatgpt.test/backend-api/codex",
		HTTPClient:      &http.Client{Transport: rt},
	})

	body := `{"model":"gpt-5.5","input":"codex turn"}`
	req := httptest.NewRequest(http.MethodPost, "/chatgpt/responses", strings.NewReader(body))
	req.Header.Set("Authorization", "Bearer codex-oauth-secret")
	rec := httptest.NewRecorder()
	srv.Handler().ServeHTTP(rec, req)
	srv.capture.flush()

	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d", rec.Code)
	}
	got := readCaptures(t, dir)
	if len(got) != 1 {
		t.Fatalf("want 1 capture on the chatgpt route, got %d", len(got))
	}
	entry := got[0]
	if entry.Provider != "chatgpt-subscription" || entry.Endpoint != "/responses" {
		t.Errorf("chatgpt capture identity wrong: %s %s", entry.Provider, entry.Endpoint)
	}
	if !bytes.Equal(entry.ClientBody, []byte(body)) {
		t.Errorf("chatgpt capture is not byte-exact: %q", entry.ClientBody)
	}
	if entry.Transformed {
		t.Error("a pass-through chatgpt request must not read as transformed")
	}
}

// The capture directory can disappear under a running proxy. Traffic must not
// notice — the instrument fails open on every error.
func TestCaptureDirDeletedAtRecordTimeLeavesTrafficUnaffected(t *testing.T) {
	dir := filepath.Join(t.TempDir(), "captures")
	t.Setenv("CAVE_CAPTURE_DIR", dir)
	rt := &captureTransport{}
	srv := captureProxyServer("record", rt)
	if srv.capture == nil {
		t.Fatal("capture must be enabled")
	}
	if err := os.RemoveAll(dir); err != nil {
		t.Fatalf("remove capture dir: %v", err)
	}

	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"hello"}]}`
	rec := serveCaptureRequest(t, srv, "/v1/chat/completions", body)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d after the capture dir vanished", rec.Code)
	}
	if len(rt.bodies) != 1 || string(rt.bodies[0]) != body {
		t.Fatalf("upstream body altered: %q", rt.bodies)
	}
	if _, err := os.Stat(dir); !os.IsNotExist(err) {
		t.Errorf("capture must not recreate the directory it was given: %v", err)
	}
}

package gateway

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/openai"
	"github.com/JuliusBrussee/caveman/shared/platform/httpx"
	"github.com/JuliusBrussee/caveman/shared/platform/id"
)

// DefaultChatGPTUpstream is the ChatGPT-subscription Codex backend. A wrapped
// Codex CLI on a ChatGPT login reaches it through this proxy via a custom
// model_provider with requires_openai_auth=true and base_url .../chatgpt.
const DefaultChatGPTUpstream = "https://chatgpt.com/backend-api/codex"

// chatGPTCaptureLimit caps request transformation and opportunistic response
// parsing. Bigger bodies stream through byte-exact and record no invented counts.
const chatGPTCaptureLimit = 4 << 20

// chatgpt is the ChatGPT-subscription Codex route. It preserves the agent's OAuth
// headers and streams responses unchanged. An entitled local compress run with
// agent-owned MCP recovery may apply the same schema-aware, deterministic live-zone
// compression as the OpenAI Responses adapter; every other case is pass-through.
// Invariants:
//   - no credential resolution, no env fallback — the agent's own OAuth
//     Authorization + ChatGPT-Account-ID headers ride through untouched, and
//     they are never logged, cached, or substituted. A missing credential is
//     the upstream's 401, not ours.
//   - only /responses request content may be transformed, only through the
//     account+MCP+prefix-stability gate. Any parse/store/shrink failure forwards
//     original bytes; a transformed 4xx retries once with original bytes.
//   - response bodies remain byte-identical and SSE streams stay unbuffered.
//   - metering is opportunistic and honest: parseable usage records token
//     counts with TotalCostUSD 0 — subscription traffic has no per-token
//     price, and pricing it at API rates would be a fake number.
func (s *Server) chatgpt(w http.ResponseWriter, r *http.Request) {
	start := time.Now()
	requestID := id.NewUUIDv7()
	traceID := traceIDFrom(r)
	w.Header().Set("x-cave-request-id", requestID)
	w.Header().Set("x-cave-trace-id", traceID)

	rc, err := s.auth.Authenticate(r.Context(), r)
	if err != nil {
		httpx.Error(w, r, http.StatusUnauthorized, "cave_unauthorized", "Request rejected by the proxy authenticator.")
		return
	}
	rc.AgentSlug = labelOrDefault(r.Header.Get("x-cave-agent"), "unlabeled-agent")
	evidence := requestEvidenceFromHeaders(r.Header)
	lockedRoutes, compiledPlanAllowed := compiledPlanRoutes(r.Header)

	suffix := strings.TrimPrefix(r.URL.Path, "/chatgpt")
	if suffix == "" {
		suffix = "/"
	}
	upstreamURL := s.chatGPTUpstream + suffix
	if r.URL.RawQuery != "" {
		upstreamURL += "?" + r.URL.RawQuery
	}

	// Compression needs a complete request. Keep the existing bounded behavior:
	// over-limit bodies stream through unchanged rather than being rejected or held
	// unbounded in memory.
	reqCapture := &cappedBuffer{limit: chatGPTCaptureLimit}
	reqHash := sha256.New()
	var reqBody io.Reader
	var originalBody []byte
	var requestBodyFullyRead bool
	var requestBodyTracker *eofTrackingReader
	transform := providers.TransformResult{OptimizerIDs: []string{}}
	var comp *compressionOutcome
	adapter := openai.New(s.chatGPTUpstream)
	compressEligible := r.Method == http.MethodPost && rc.RuntimeMode == "compress" && suffix == "/responses" &&
		s.compressor != nil && s.liveZoneCompressionAllowed(adapter) && compiledPlanAllowed
	if compressEligible {
		captured, readErr := io.ReadAll(io.LimitReader(r.Body, chatGPTCaptureLimit+1))
		if readErr == nil && len(captured) <= chatGPTCaptureLimit {
			requestBodyFullyRead = true
			originalBody = captured
			_, _ = reqHash.Write(originalBody)
			_, _ = reqCapture.Write(originalBody)
			transform.Body = originalBody
			headersForInspect := r.Header.Clone()
			headersForInspect.Set("x-cave-route-path", suffix)
			meta, inspectErr := adapter.InspectRequest(r.Context(), bytes.NewReader(originalBody), headersForInspect)
			if inspectErr == nil {
				meta.Endpoint = suffix
				meta.SessionID = evidence.SessionID
				if s.cacheEpochAllows(r, adapter, meta, originalBody, evidence.SessionID) {
					comp = s.compressRequest(adapter, originalBody, meta, &transform, requestID, lockedRoutes)
				}
			}
			reqBody = bytes.NewReader(transform.Body)
		} else {
			// Reconstruct the consumed prefix and continue the old streaming path.
			source := io.MultiReader(bytes.NewReader(captured), r.Body)
			requestBodyTracker = &eofTrackingReader{reader: source}
			reqBody = io.TeeReader(io.TeeReader(requestBodyTracker, reqHash), reqCapture)
			transform.Body = nil
		}
	} else {
		requestBodyTracker = &eofTrackingReader{reader: r.Body}
		reqBody = io.TeeReader(io.TeeReader(requestBodyTracker, reqHash), reqCapture)
	}
	if r.ContentLength == 0 && (r.Method == http.MethodGet || r.Method == http.MethodHead || r.Method == http.MethodDelete) {
		// A bodyless method with a non-nil reader would go out chunked; keep
		// the wire shape identical to what the agent sent.
		reqBody = nil
	}

	upReq, err := http.NewRequestWithContext(r.Context(), r.Method, upstreamURL, reqBody)
	if err != nil {
		httpx.Error(w, r, http.StatusBadRequest, "cave_provider_request_invalid", "ChatGPT route could not build the upstream request.")
		return
	}
	if transform.Body != nil {
		upReq.ContentLength = int64(len(transform.Body))
	} else {
		upReq.ContentLength = r.ContentLength
	}
	// Preserve OAuth/account/application headers, but never forward proxy-private
	// metadata or hop-by-hop fields to the subscription backend.
	upReq.Header = chatGPTRequestHeaders(r.Header)
	if comp != nil {
		upReq.Header.Del("Content-Length")
	}

	// Capture both sides of the transform before the send (see capture.go), off
	// unless CAVE_CAPTURE_DIR is set. Only the fully-read path can do it here; the
	// streaming path has no complete bytes or hash until the body has been
	// forwarded, so it captures after the response instead.
	if originalBody != nil {
		s.capture.record(captureMeta{
			RequestID:   requestID,
			Provider:    "chatgpt-subscription",
			Endpoint:    suffix,
			RuntimeMode: rc.RuntimeMode,
			Optimizers:  strings.Join(transform.OptimizerIDs, ","),
		}, wholeBody(originalBody), wholeBody(transform.Body))
	}

	resp, err := s.httpClient.Do(upReq)
	if err != nil {
		httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unreachable", "ChatGPT upstream is unreachable.")
		requestHashComplete := chatGPTRequestHashComplete(requestBodyFullyRead, r.ContentLength, reqCapture, requestBodyTracker)
		s.recordChatGPT(rc, r, requestID, traceID, suffix, start, 0, "cave_upstream_unreachable", reqCapture, reqHash.Sum(nil), transformedChatGPTHash(reqHash.Sum(nil), transform.Body), requestHashComplete, nil, 0, false, transform.OptimizerIDs, comp)
		return
	}
	// OAuth backends can reject byte-modified requests for undocumented reasons.
	// Retry once with exact original bytes, then disclose/record no optimization.
	if resp.StatusCode >= 400 && resp.StatusCode < 500 && comp != nil && originalBody != nil {
		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<20))
		_ = resp.Body.Close()
		retryReq, retryErr := http.NewRequestWithContext(r.Context(), r.Method, upstreamURL, bytes.NewReader(originalBody))
		if retryErr == nil {
			retryReq.Header = chatGPTRequestHeaders(r.Header)
			retryReq.Header.Del("Content-Length")
			retryResp, doErr := s.httpClient.Do(retryReq)
			if doErr == nil {
				resp = retryResp
				transform = providers.TransformResult{Body: originalBody, OptimizerIDs: []string{}}
				comp = nil
				// The original bytes served the request; the capture written before
				// the first attempt describes bytes the upstream rejected. Both
				// attempts stay on disk, and this one says which served.
				s.capture.record(captureMeta{
					RequestID:     requestID,
					Provider:      "chatgpt-subscription",
					Endpoint:      suffix,
					RuntimeMode:   rc.RuntimeMode,
					RetryOriginal: true,
				}, wholeBody(originalBody), wholeBody(originalBody))
			} else {
				httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unreachable", "ChatGPT upstream is unreachable.")
				s.recordChatGPT(rc, r, requestID, traceID, suffix, start, 0, "cave_upstream_unreachable", reqCapture, reqHash.Sum(nil), reqHash.Sum(nil), true, nil, 0, false, nil, nil)
				return
			}
		}
	}
	defer resp.Body.Close()

	copySafeResponseHeaders(w.Header(), resp.Header)
	if comp != nil {
		w.Header().Set("x-cave-mode", rc.RuntimeMode)
		w.Header().Set("x-cave-optimization", strings.Join(transform.OptimizerIDs, ","))
		w.Header().Set("x-caveman-compression-ratio", strconv.FormatFloat(comp.ratio, 'f', 4, 64))
		w.Header().Set("x-caveman-recovery-handle", comp.handle)
		w.Header().Set("x-caveman-tokens-before", strconv.Itoa(comp.before))
		w.Header().Set("x-caveman-tokens-after", strconv.Itoa(comp.after))
		w.Header().Set("x-caveman-token-count-basis", "estimated_engine_o200k")
	}
	w.WriteHeader(resp.StatusCode)

	respCapture := &cappedBuffer{limit: chatGPTCaptureLimit}
	respBytes, stream := s.streamThrough(w, io.TeeReader(resp.Body, respCapture))

	// The streaming path forwarded the request without ever holding it whole, so it
	// captures only what it can state truthfully: the whole body's length and hash,
	// plus the bytes themselves when the bounded buffer happened to hold all of
	// them. This path never transforms, so both sides are the same body.
	if s.capture != nil && originalBody == nil {
		sent := streamedBody(reqCapture.total, hex.EncodeToString(reqHash.Sum(nil)))
		if !reqCapture.truncated {
			sent = wholeBody(append([]byte(nil), reqCapture.buf.Bytes()...))
		}
		s.capture.record(captureMeta{
			RequestID:   requestID,
			Provider:    "chatgpt-subscription",
			Endpoint:    suffix,
			RuntimeMode: rc.RuntimeMode,
		}, sent, sent)
	}

	requestHashComplete := chatGPTRequestHashComplete(requestBodyFullyRead, r.ContentLength, reqCapture, requestBodyTracker)
	s.recordChatGPT(rc, r, requestID, traceID, suffix, start, resp.StatusCode, "", reqCapture, reqHash.Sum(nil), transformedChatGPTHash(reqHash.Sum(nil), transform.Body), requestHashComplete, respCapture, respBytes, stream, transform.OptimizerIDs, comp)

	// Path, status, and timing only — request headers carry the operator's
	// OAuth credential and are never logged on this route.
	if s.logger != nil {
		s.logger.Info("chatgpt_proxy",
			"path", suffix, "status", resp.StatusCode,
			"latency_ms", time.Since(start).Milliseconds(), "stream", stream, "compressed", comp != nil)
	}
}

func transformedChatGPTHash(raw []byte, transformed []byte) []byte {
	if transformed == nil {
		return raw
	}
	sum := sha256.Sum256(transformed)
	return sum[:]
}

// streamThrough copies upstream bytes to the client, flushing per chunk so SSE
// arrives unbuffered. It returns the byte count and whether flushing happened
// mid-stream (a streaming response).
func (s *Server) streamThrough(w http.ResponseWriter, body io.Reader) (int64, bool) {
	flusher, canFlush := w.(http.Flusher)
	var total int64
	chunks := 0
	buf := make([]byte, 32*1024)
	for {
		n, err := body.Read(buf)
		if n > 0 {
			if _, werr := w.Write(buf[:n]); werr != nil {
				return total, chunks > 1
			}
			total += int64(n)
			chunks++
			if canFlush {
				flusher.Flush()
			}
		}
		if err != nil {
			return total, chunks > 1
		}
	}
}

func (s *Server) recordChatGPT(rc RequestContext, r *http.Request, requestID, traceID, endpoint string, start time.Time, status int, errCode string, reqCapture *cappedBuffer, reqHash, transformedHash []byte, requestHashComplete bool, respCapture *cappedBuffer, respBytes int64, stream bool, optimizers []string, comp *compressionOutcome) {
	if s.sink == nil {
		return
	}
	var usage providers.UsageObservation
	// Opportunistic and honest: a truncated capture is never parsed — partial
	// SSE could yield partial counters, and no number beats a wrong number.
	if respCapture != nil && !respCapture.truncated {
		providers.ParseUsageBytes("openai", respCapture.buf.Bytes(), &usage)
	}
	model := "unknown"
	if reqCapture != nil && !reqCapture.truncated {
		var body struct {
			Model string `json:"model"`
		}
		if json.Unmarshal(reqCapture.buf.Bytes(), &body) == nil && body.Model != "" {
			model = body.Model
		}
	}
	rawHash, transformedHashHex := "", ""
	if requestHashComplete {
		rawHash = hex.EncodeToString(reqHash)
		transformedHashHex = hex.EncodeToString(transformedHash)
	}
	var compRatio float64
	var compBefore, compAfter int
	var compHandle, compBasis string
	if comp != nil {
		compRatio, compBefore, compAfter, compHandle = comp.ratio, comp.before, comp.after, comp.handle
		if comp.before > comp.after {
			compBasis = "estimated_engine_o200k"
		}
	}
	s.sink.Record(RequestRecord{
		Timestamp:                start.UTC().Format(time.RFC3339Nano),
		RequestID:                requestID,
		TraceID:                  traceID,
		Label:                    labelOrDefault(rc.Label, "local"),
		AgentSlug:                rc.AgentSlug,
		Provider:                 "chatgpt-subscription",
		Model:                    model,
		RouteFrom:                r.URL.Path,
		RouteTo:                  s.chatGPTUpstream + endpoint,
		Endpoint:                 endpoint,
		Stream:                   stream,
		StatusCode:               status,
		ErrorCode:                errCode,
		LatencyMS:                time.Since(start).Milliseconds(),
		RequestBytes:             reqCapture.total,
		ResponseBytes:            respBytes,
		InputTokens:              usage.InputTokens,
		OutputTokens:             usage.OutputTokens,
		CachedInputTokens:        usage.CachedInputTokens,
		CacheCreationInputTokens: usage.CacheCreationInputTokens,
		ReasoningTokens:          usage.ReasoningTokens,
		// Subscription traffic is unpriced: zero dollars, never an API-rate
		// guess (no-fake-savings). Token counts above are the honest meter.
		TotalCostUSD:               0,
		SavingsUSD:                 0,
		Basis:                      "inferred",
		TokenUsageBasis:            standaloneUsageBasis(usage),
		AuthMode:                   string(AuthModeSubscription),
		RuntimeMode:                rc.RuntimeMode,
		OptimizationIDs:            optimizers,
		RawRequestSHA256:           rawHash,
		TransformedRequestSHA256:   transformedHashHex,
		RequestHashComplete:        requestHashComplete,
		CompressionRatio:           compRatio,
		CompressionTokensBefore:    compBefore,
		CompressionTokensAfter:     compAfter,
		CompressionTokenCountBasis: compBasis,
		RecoveryHandle:             compHandle,
	})
}

type eofTrackingReader struct {
	reader io.Reader
	sawEOF bool
}

func (r *eofTrackingReader) Read(p []byte) (int, error) {
	n, err := r.reader.Read(p)
	if err == io.EOF {
		r.sawEOF = true
	}
	return n, err
}

func chatGPTRequestHashComplete(fullyRead bool, contentLength int64, capture *cappedBuffer, tracker *eofTrackingReader) bool {
	if fullyRead {
		return true
	}
	if capture != nil && contentLength >= 0 && int64(capture.total) == contentLength {
		return true
	}
	return tracker != nil && tracker.sawEOF
}

// cappedBuffer retains up to limit bytes and records the true total; past the
// limit it flags truncation instead of growing (bounded memory, no partial
// parses downstream).
type cappedBuffer struct {
	buf       bytes.Buffer
	limit     int
	total     int
	truncated bool
}

func (c *cappedBuffer) Write(p []byte) (int, error) {
	c.total += len(p)
	if c.truncated {
		return len(p), nil
	}
	room := c.limit - c.buf.Len()
	if room <= 0 {
		c.truncated = true
		return len(p), nil
	}
	if len(p) > room {
		c.buf.Write(p[:room])
		c.truncated = true
		return len(p), nil
	}
	c.buf.Write(p)
	return len(p), nil
}

