			provider: "openai",
			endpoint: "/v1/chat/completions",
			body:     `{`,
			want:     "",
		},
	}

	for _, tt := range tests {
		tt := tt
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := extractCompressionQuery(tt.provider, tt.endpoint, []byte(tt.body)); got != tt.want {
