}

func TestExtractCompressionQueryBoundsWorkWithoutBreakingUTF8(t *testing.T) {
	query := strings.Repeat("a", maxCompressionQueryBytes-1) + "€" + strings.Repeat("z", 32)
	body := `{"messages":[{"role":"user","content":` + quoteJSON(query) + `}]}`
