package gateway

import (
	"container/list"
	"sync"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// lever names one optimization the session ledger can account for and freeze.
// A lever is anything that rewrites bytes (or provider-native metadata) in a way
// that could move the provider cache prefix — the class of change whose harm
// shows up as cache-creation growth rather than as an error.
type lever string

const (
	// leverToolSchemaStrip is the tool-schema annotation strip (toolschema_strip.go).
	leverToolSchemaStrip lever = toolSchemaStripOptimizerID
	// leverBreakpointPlan is the cache-breakpoint planner (breakpoint_plan.go).
	leverBreakpointPlan lever = breakpointPlanOptimizerID
)

// ledgerMaxSessions bounds the ledger. A wrap session is a long-lived agent run,
// so a few thousand entries is far more than one operator produces; the cap
// exists so a client that mints a fresh x-cave-session per request cannot grow
// the map without bound. Eviction is least-recently-used.
const ledgerMaxSessions = 1024

// The tripwire thresholds. A lever trips when the request AFTER it ran paid a
// cache-creation bill that is both large in absolute terms and far above what
// this session normally pays — the signature of a rewrite that failed to
// stabilize into a reusable prefix (spec §6: Δturns / Δcache-reads rising while
// quality holds).
//
// These three numbers are deliberately conservative rather than measured: they
// are set so that only an unmistakable regression trips them, which means the
// tripwire under-fires rather than disabling a lever that was working.
// Follow-up: replace them with values derived from the replay grid's repo-scale
// corpus, where the normal cache-creation distribution per agent is known.
const (
	// tripwireCacheCreationFloorTokens is the absolute floor. Below it, a spike is
	// not worth acting on no matter how large the ratio (a session whose baseline
	// mean is 50 tokens hits 3x constantly and means nothing).
	tripwireCacheCreationFloorTokens = 50_000
	// tripwireCacheCreationMultiple is how far above the session's own baseline
	// mean cache-creation a call must land to count as anomalous.
	tripwireCacheCreationMultiple = 3
	// tripwireStrikesToFreeze is how many anomalous calls freeze the lever. One
	// spike is a cold cache or a genuinely new prefix; three is a pattern.
	tripwireStrikesToFreeze = 3
)

// sessionLedger is the per-session accounting the harm tripwire reasons over.
//
// It is keyed by the caller-supplied x-cave-session value and holds nothing but
// counters: no bodies, no headers, no content. A request with no session header
// gets no entry at all, and every method is then inert — a caller that does not
// identify its session simply never trips and never freezes.
//
// Freezing is one-way within a session. A frozen lever stays frozen until the
// session id changes (a new agent run), because the alternative — thawing on a
// quiet stretch — reintroduces exactly the oscillation the freeze exists to stop.
type sessionLedger struct {
	mu      sync.Mutex
	entries map[string]*list.Element
	// order is most-recently-used at the front; the back is the eviction target.
	order *list.List
}

// ledgerEntry is one session's running account. cumulative* fields include every
// observed call; last* fields are the most recent call's values.
type ledgerEntry struct {
	sessionID string

	calls                   int
	cumulativeInput         int64
	cumulativeCacheRead     int64
	cumulativeCacheCreation int64
	lastInputTokens         int
	lastCacheReadTokens     int
	lastCacheCreationTokens int
	// baselineCalls/baselineCacheCreation are the session's NORMAL cache-creation,
	// which is what the tripwire compares against — spec §6's "the wrap's own
	// baseline window". Calls the tripwire already judged anomalous are excluded
	// from it. A plain running mean over every call would fold each spike into the
	// very number the next spike is measured against, so a persistent regression
	// would raise its own bar out of reach after one or two calls and never reach
	// a freeze — the detector would be blind to exactly the failure it exists for.
	baselineCalls         int
	baselineCacheCreation int64
	strikes               map[lever]int
	frozen                map[lever]bool
	// activePrev is the set of levers that ran on the PREVIOUS request of this
	// session. The tripwire reads it rather than the current request's set: a
	// lever that rewrote turn N is judged by what turn N+1 had to pay to re-cache
	// the prefix it produced.
	activePrev map[lever]bool
}

func newSessionLedger() *sessionLedger {
	return &sessionLedger{entries: map[string]*list.Element{}, order: list.New()}
}

// LeverAllowed reports whether a lever may run for this session. An empty session
// id, a nil ledger, and an unknown session all allow it — the tripwire only ever
// takes capability away, and only from a session it has watched trip.
func (l *sessionLedger) LeverAllowed(sessionID string, lv lever) bool {
	if l == nil || sessionID == "" {
		return true
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	element, ok := l.entries[sessionID]
	if !ok {
		return true
	}
	l.order.MoveToFront(element)
	return !element.Value.(*ledgerEntry).frozen[lv]
}

// FrozenLevers returns this session's frozen levers in a stable order, for the
// x-caveman-tripwire disclosure header.
func (l *sessionLedger) FrozenLevers(sessionID string) []lever {
	if l == nil || sessionID == "" {
		return nil
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	element, ok := l.entries[sessionID]
	if !ok {
		return nil
	}
	entry := element.Value.(*ledgerEntry)
	var out []lever
	// Iterate the declared lever order, not the map, so the header is stable.
	for _, lv := range []lever{leverToolSchemaStrip, leverBreakpointPlan} {
		if entry.frozen[lv] {
			out = append(out, lv)
		}
	}
	return out
}

// Observe records one completed call against a session and evaluates the harm
// tripwire. active is the set of levers that ran on THIS request; the returned
// slice is the levers this call newly froze (empty in the normal case), so the
// caller can log the transition exactly once.
//
// The tripwire fires when a lever was active on the previous request AND this
// call's cache-creation exceeds BOTH the absolute floor AND the multiple of the
// session's baseline mean. The baseline is built from the calls before this one,
// so the very first call of a session can never strike.
func (l *sessionLedger) Observe(sessionID string, active []lever, usage providers.UsageObservation) []lever {
	if l == nil || sessionID == "" {
		return nil
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	entry := l.entryLocked(sessionID)

	creation := usage.CacheCreationInputTokens
	anomalous := false
	if entry.baselineCalls > 0 {
		baselineMean := float64(entry.baselineCacheCreation) / float64(entry.baselineCalls)
		anomalous = creation > tripwireCacheCreationFloorTokens &&
			float64(creation) > tripwireCacheCreationMultiple*baselineMean
	}

	var froze []lever
	if anomalous {
		for _, lv := range []lever{leverToolSchemaStrip, leverBreakpointPlan} {
			if !entry.activePrev[lv] || entry.frozen[lv] {
				continue
			}
			entry.strikes[lv]++
			if entry.strikes[lv] >= tripwireStrikesToFreeze {
				entry.frozen[lv] = true
				froze = append(froze, lv)
			}
		}
	} else {
		entry.baselineCalls++
		entry.baselineCacheCreation += int64(creation)
	}

	entry.calls++
	entry.cumulativeInput += int64(usage.InputTokens)
	entry.cumulativeCacheRead += int64(usage.CachedInputTokens)
	entry.cumulativeCacheCreation += int64(creation)
	entry.lastInputTokens = usage.InputTokens
	entry.lastCacheReadTokens = usage.CachedInputTokens
	entry.lastCacheCreationTokens = creation

	// activePrev is a single slot, so concurrent requests on ONE session are
	// last-writer-wins: two calls in flight together can overwrite each other's
	// lever set before the next call reads it. The consequence is bounded and
	// points the safe way. A lost write can only DROP a lever from the set the
	// next call is judged against, which loses a strike (under-fires); a stale
	// write can only carry a lever the immediately preceding call also ran, which
	// at worst mis-attributes one strike inside a three-strike budget. Neither can
	// freeze a lever that was never active in the session, and neither can
	// un-freeze one. Ordering a session's calls to fix this would mean serializing
	// them, which is a far worse trade than an occasionally missed strike.
	entry.activePrev = map[lever]bool{}
	for _, lv := range active {
		entry.activePrev[lv] = true
	}
	return froze
}

// entryLocked returns the session's entry, creating it (and evicting the
// least-recently-used session when the ledger is full) as needed.
func (l *sessionLedger) entryLocked(sessionID string) *ledgerEntry {
	if element, ok := l.entries[sessionID]; ok {
		l.order.MoveToFront(element)
		return element.Value.(*ledgerEntry)
	}
	for l.order.Len() >= ledgerMaxSessions {
		oldest := l.order.Back()
		if oldest == nil {
			break
		}
		l.order.Remove(oldest)
		delete(l.entries, oldest.Value.(*ledgerEntry).sessionID)
	}
	entry := &ledgerEntry{
		sessionID:  sessionID,
		strikes:    map[lever]int{},
		frozen:     map[lever]bool{},
		activePrev: map[lever]bool{},
	}
	l.entries[sessionID] = l.order.PushFront(entry)
	return entry
}

package gateway

import (
	"strconv"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// The session ledger is the accounting the harm tripwire reads, and the freeze
// registry every lever consults. Its contract: bounded, session-scoped,
// one-way, and completely inert for a caller that sends no session id.

func creation(tokens int) providers.UsageObservation {
	return providers.UsageObservation{InputTokens: tokens, CacheCreationInputTokens: tokens}
}

// warm gives a session a baseline the tripwire can measure against, with
// the lever recorded as active throughout.
func warm(l *sessionLedger, session string, lv lever, calls, tokens int) {
	for i := 0; i < calls; i++ {
		l.Observe(session, []lever{lv}, creation(tokens))
	}
}

func TestLedgerIsInertWithoutASessionID(t *testing.T) {
	l := newSessionLedger()
	for i := 0; i < tripwireStrikesToFreeze+2; i++ {
		if froze := l.Observe("", []lever{leverToolSchemaStrip}, creation(10_000_000)); froze != nil {
			t.Fatalf("an unidentified session was accounted for: %v", froze)
		}
	}
	if !l.LeverAllowed("", leverToolSchemaStrip) {
		t.Fatal("an unidentified session lost a lever")
	}
	if l.FrozenLevers("") != nil {
		t.Fatal("an unidentified session reported frozen levers")
	}
	if len(l.entries) != 0 {
		t.Fatalf("the ledger created %d entries for sessionless traffic", len(l.entries))
	}
}

// TestLedgerFreezesAfterThreeStrikes walks the whole tripwire: a quiet baseline,
// three anomalous calls, the freeze, and the fail-open consequence.
func TestLedgerFreezesAfterThreeStrikes(t *testing.T) {
	l := newSessionLedger()
	warm(l, "s1", leverToolSchemaStrip, 4, 1_000)

	spike := creation(10 * tripwireCacheCreationFloorTokens)
	for i := 1; i < tripwireStrikesToFreeze; i++ {
		if froze := l.Observe("s1", []lever{leverToolSchemaStrip}, spike); len(froze) != 0 {
			t.Fatalf("froze on strike %d, want %d strikes", i, tripwireStrikesToFreeze)
		}
		if !l.LeverAllowed("s1", leverToolSchemaStrip) {
			t.Fatalf("lever taken away on strike %d", i)
		}
	}
	froze := l.Observe("s1", []lever{leverToolSchemaStrip}, spike)
	if len(froze) != 1 || froze[0] != leverToolSchemaStrip {
		t.Fatalf("third strike froze %v, want [%s]", froze, leverToolSchemaStrip)
	}
	if l.LeverAllowed("s1", leverToolSchemaStrip) {
		t.Fatal("a frozen lever is still allowed")
	}
	// Only the lever that was active is taken; the other keeps running.
	if !l.LeverAllowed("s1", leverBreakpointPlan) {
		t.Fatal("an inactive lever was frozen by another lever's strikes")
	}
	if got := l.FrozenLevers("s1"); len(got) != 1 || got[0] != leverToolSchemaStrip {
		t.Fatalf("FrozenLevers = %v", got)
	}
	// The freeze is one-way. A long quiet stretch must not thaw it: thawing
	// reintroduces exactly the oscillation the freeze exists to stop.
	for i := 0; i < 50; i++ {
		l.Observe("s1", nil, creation(10))
	}
	if l.LeverAllowed("s1", leverToolSchemaStrip) {
		t.Fatal("a quiet stretch un-froze a lever")
	}
	// Freezing is scoped to one session; a new agent run starts clean.
	if !l.LeverAllowed("s2", leverToolSchemaStrip) {
		t.Fatal("freezing one session took the lever from another")
	}
}

// TestLedgerRequiresBothThresholds pins that neither half of the rule fires
// alone: a huge ratio under the floor is noise, and a huge absolute number that
// matches the session's own normal is just how this session bills.
func TestLedgerRequiresBothThresholds(t *testing.T) {
	t.Run("under the absolute floor", func(t *testing.T) {
		l := newSessionLedger()
		warm(l, "s", leverBreakpointPlan, 4, 10)
		for i := 0; i < tripwireStrikesToFreeze+1; i++ {
			l.Observe("s", []lever{leverBreakpointPlan}, creation(tripwireCacheCreationFloorTokens))
		}
		if !l.LeverAllowed("s", leverBreakpointPlan) {
			t.Fatal("a spike at the floor tripped the wire")
		}
	})
	t.Run("large but within the session's own normal", func(t *testing.T) {
		l := newSessionLedger()
		warm(l, "s", leverBreakpointPlan, 4, 400_000)
		for i := 0; i < tripwireStrikesToFreeze+1; i++ {
			l.Observe("s", []lever{leverBreakpointPlan}, creation(800_000))
		}
		if !l.LeverAllowed("s", leverBreakpointPlan) {
			t.Fatal("a call inside 3x the baseline mean tripped the wire")
		}
	})
}

// TestLedgerJudgesThePreviousRequestsLevers: a lever is judged by what the NEXT
// request had to pay to re-cache the prefix it produced. A spike on a request
// whose predecessor ran no lever belongs to the traffic, not to us.
func TestLedgerJudgesThePreviousRequestsLevers(t *testing.T) {
	l := newSessionLedger()
	warm(l, "s", leverToolSchemaStrip, 4, 1_000)
	// Every spike is preceded by a request with no lever active.
	spike := creation(10 * tripwireCacheCreationFloorTokens)
	for i := 0; i < tripwireStrikesToFreeze+2; i++ {
		l.Observe("s", nil, creation(1_000))
		l.Observe("s", nil, spike)
	}
	if !l.LeverAllowed("s", leverToolSchemaStrip) {
		t.Fatal("a lever was blamed for spikes it did not precede")
	}
	// The first call of a session can never strike: there is no baseline yet.
	fresh := newSessionLedger()
	if froze := fresh.Observe("new", []lever{leverToolSchemaStrip}, spike); len(froze) != 0 {
		t.Fatalf("the first call of a session struck: %v", froze)
	}
}

// TestLedgerEvictsLeastRecentlyUsed: the ledger is bounded, so a client that
// mints a fresh session per request cannot grow it without limit — and the
// session still in use survives the churn.
func TestLedgerEvictsLeastRecentlyUsed(t *testing.T) {
	l := newSessionLedger()
	l.Observe("keeper", []lever{leverBreakpointPlan}, creation(1_000))

	for i := 0; i < ledgerMaxSessions; i++ {
		id := "churn-" + strconv.Itoa(i)
		l.Observe(id, nil, creation(1))
		// Touching the keeper keeps it at the front of the LRU order.
		l.LeverAllowed("keeper", leverBreakpointPlan)
	}

	if len(l.entries) != ledgerMaxSessions || l.order.Len() != ledgerMaxSessions {
		t.Fatalf("ledger holds %d entries (order %d), want the %d cap",
			len(l.entries), l.order.Len(), ledgerMaxSessions)
	}
	if _, ok := l.entries["keeper"]; !ok {
		t.Fatal("the recently-used session was evicted while cold sessions survived")
	}
	if _, ok := l.entries["churn-0"]; ok {
		t.Fatal("the least-recently-used session was not evicted")
	}
}

// TestLedgerEvictionForgetsAFreeze is the honest consequence of a bounded
// ledger: eviction is a loss of memory, so an evicted session's lever comes back.
// It is the fail-open direction, and it is bounded by the cap being far larger
// than any real operator's concurrent session count.
func TestLedgerEvictionForgetsAFreeze(t *testing.T) {
	l := newSessionLedger()
	warm(l, "victim", leverBreakpointPlan, 4, 1_000)
	spike := creation(10 * tripwireCacheCreationFloorTokens)
	for i := 0; i < tripwireStrikesToFreeze; i++ {
		l.Observe("victim", []lever{leverBreakpointPlan}, spike)
	}
	if l.LeverAllowed("victim", leverBreakpointPlan) {
		t.Fatal("setup failed: the lever was not frozen")
	}
	for i := 0; i < ledgerMaxSessions+1; i++ {
		l.Observe("churn-"+strconv.Itoa(i), nil, creation(1))
	}
	if _, ok := l.entries["victim"]; ok {
		t.Fatal("setup failed: the frozen session was not evicted")
	}
	if !l.LeverAllowed("victim", leverBreakpointPlan) {
		t.Fatal("an evicted session must be indistinguishable from an unknown one")
	}
}

func TestLedgerTracksSessionTotals(t *testing.T) {
	l := newSessionLedger()
	l.Observe("s", nil, providers.UsageObservation{InputTokens: 100, CachedInputTokens: 60, CacheCreationInputTokens: 10})
	l.Observe("s", nil, providers.UsageObservation{InputTokens: 200, CachedInputTokens: 150, CacheCreationInputTokens: 20})

	entry := l.entries["s"].Value.(*ledgerEntry)
	if entry.calls != 2 || entry.cumulativeInput != 300 ||
		entry.cumulativeCacheRead != 210 || entry.cumulativeCacheCreation != 30 {
		t.Fatalf("cumulative totals wrong: %+v", entry)
	}
	if entry.lastInputTokens != 200 || entry.lastCacheReadTokens != 150 || entry.lastCacheCreationTokens != 20 {
		t.Fatalf("last-call values wrong: %+v", entry)
	}
}

// TestLedgerNilReceiverIsPermissive: a Server built without a ledger must not
// take a lever away or panic. The tripwire only ever subtracts capability.
func TestLedgerNilReceiverIsPermissive(t *testing.T) {
	var l *sessionLedger
	if !l.LeverAllowed("s", leverBreakpointPlan) {
		t.Fatal("a nil ledger denied a lever")
	}
	if l.FrozenLevers("s") != nil || l.Observe("s", []lever{leverBreakpointPlan}, creation(1)) != nil {
		t.Fatal("a nil ledger reported state")
	}
}

package gateway

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/anthropic"
	"github.com/JuliusBrussee/caveman/proxy/providers/openai"
)

type captureTransport struct {
	mu        sync.Mutex
	bodies    [][]byte
	headers   []http.Header
	responses []string
	statuses  []int
}

func (t *captureTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	body, _ := io.ReadAll(r.Body)
	t.mu.Lock()
	t.bodies = append(t.bodies, append([]byte(nil), body...))
	t.headers = append(t.headers, r.Header.Clone())
	idx := len(t.bodies) - 1
	t.mu.Unlock()

	status := http.StatusOK
	if idx < len(t.statuses) && t.statuses[idx] != 0 {
		status = t.statuses[idx]
	}
	respBody := chatRespBody
	if idx < len(t.responses) && t.responses[idx] != "" {
		respBody = t.responses[idx]
	}
	return &http.Response{
		StatusCode: status,
		Status:     http.StatusText(status),
		Header:     http.Header{"Content-Type": {"application/json"}, "X-Request-Id": {"up-live"}},
		Body:       io.NopCloser(strings.NewReader(respBody)),
		Request:    r,
	}, nil
}

type liveZoneCompressor struct {
	mu       sync.Mutex
	calls    int
	outputs  [][]byte
	before   []int
	after    []int
	stored   [][]byte
	recovery map[string][]byte
}

func (c *liveZoneCompressor) CompressSegment(seg []byte) ([]byte, int, int) {
	c.mu.Lock()
	defer c.mu.Unlock()
	i := c.calls
	c.calls++
	out := []byte("Z")
	if i < len(c.outputs) && c.outputs[i] != nil {
		out = c.outputs[i]
	}
	before := 100
	if i < len(c.before) && c.before[i] != 0 {
		before = c.before[i]
	}
	after := 40
	if i < len(c.after) && c.after[i] != 0 {
		after = c.after[i]
	}
	return out, before, after
}

func (c *liveZoneCompressor) StoreOriginal(body []byte) (string, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.stored = append(c.stored, append([]byte(nil), body...))
	sum := sha256.Sum256(body)
	handle := "ccr_" + hex.EncodeToString(sum[:16])
	if c.recovery == nil {
		c.recovery = map[string][]byte{}
	}
	c.recovery[handle] = append([]byte(nil), body...)
	return handle, nil
}

func (c *liveZoneCompressor) RetrieveOriginal(handle, query string) ([]byte, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	return append([]byte(nil), c.recovery[handle]...), nil
}

func newSocketFreeCompressServer(adapter providers.Adapter, comp Compressor, rt *captureTransport, creds CredentialResolver) *Server {
	return newSocketFreeCompressServerWithConfig(adapter, comp, rt, creds, Config{})
}

func newSocketFreeCompressServerWithConfig(adapter providers.Adapter, comp Compressor, rt *captureTransport, creds CredentialResolver, cfg Config) *Server {
	if creds == nil {
		creds = stubCreds{key: "sk-byok"}
	}
	cfg.Adapters = []providers.Adapter{adapter}
	cfg.Auth = stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "compress"}}
	cfg.Creds = creds
	cfg.Sink = &captureSink{}
	cfg.Compressor = comp
	cfg.HTTPClient = &http.Client{Transport: rt}
	return New(cfg)
}

func serveBody(t *testing.T, srv *Server, path, body string, headers map[string]string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodPost, path, strings.NewReader(body))
	for k, v := range headers {
		req.Header.Set(k, v)
	}
	rec := httptest.NewRecorder()
	srv.Handler().ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200 (body %s)", rec.Code, rec.Body.String())
	}
	return rec
}

func TestLiveZoneDeterminismAndMarkerContentAddressing(t *testing.T) {
	live := strings.Repeat("deterministic live block ", 40)
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"` + live + `"}]}`
	rt := &captureTransport{responses: []string{chatRespBody, chatRespBody}}
	comp := &liveZoneCompressor{}
	srv := newSocketFreeCompressServer(openai.New("https://upstream.test"), comp, rt, nil)

	serveBody(t, srv, "/v1/chat/completions", body, nil)
	serveBody(t, srv, "/v1/chat/completions", body, nil)

	if len(rt.bodies) != 2 {
		t.Fatalf("upstream calls = %d, want 2", len(rt.bodies))
	}
	if !bytes.Equal(rt.bodies[0], rt.bodies[1]) {
		t.Fatalf("same input must produce byte-identical transformed body:\n%s\n%s", rt.bodies[0], rt.bodies[1])
	}
	handle := contentHandle([]byte(live))
	if !bytes.Contains(rt.bodies[0], []byte("<<ccr:"+handle+">>")) {
		t.Fatalf("body missing deterministic content-addressed marker %s: %s", handle, rt.bodies[0])
	}
	if len(comp.stored) != 2 || !bytes.Equal(comp.stored[0], []byte(live)) || !bytes.Equal(comp.stored[1], []byte(live)) {
		t.Fatalf("StoreOriginal must receive original block bytes each time: %q", comp.stored)
	}
}

func TestLiveZoneTokenAwarePerBlockRevert(t *testing.T) {
	keep := strings.Repeat("KEEP_BLOCK ", 70)
	shrink := strings.Repeat("SHRINK_BLOCK ", 70)
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":[{"type":"text","text":"` + keep + `"},{"type":"text","text":"` + shrink + `"}]}]}`
	rt := &captureTransport{}
	comp := &liveZoneCompressor{
		outputs: [][]byte{[]byte("NO_SHRINK"), []byte("YES_SHRINK")},
		before:  []int{100, 100},
		after:   []int{100, 40},
	}
	srv := newSocketFreeCompressServer(openai.New("https://upstream.test"), comp, rt, nil)

	rec := serveBody(t, srv, "/v1/chat/completions", body, nil)
	upstream := string(rt.bodies[0])
	if !strings.Contains(upstream, keep) {
		t.Fatalf("non-shrinking block must stay original: %s", upstream)
	}
	if strings.Contains(upstream, shrink) || !strings.Contains(upstream, "YES_SHRINK") || !strings.Contains(upstream, "<<ccr:") {
		t.Fatalf("shrinking block missing replacement/marker: %s", upstream)
	}
	if got := rec.Header().Get("x-caveman-tokens-before"); got != "100" {
		t.Fatalf("tokens-before = %q, want 100", got)
	}
	if len(comp.stored) != 1 || !bytes.Equal(comp.stored[0], []byte(shrink)) {
		t.Fatalf("only shrinking block should be stored, got %q", comp.stored)
	}
}

func TestSubscriptionDefaultPassesThroughWithoutMutation(t *testing.T) {
	live := strings.Repeat("subscription live block ", 40)
	body := `{"model":"claude-sonnet-4-6","system":"System fixed","tools":[{"name":"read","description":"Read fixed","input_schema":{"type":"object"}}],"messages":[{"role":"user","content":"` + live + `"}]}`
	rt := &captureTransport{responses: []string{`{"id":"msg","type":"message","model":"claude-sonnet-4-6","content":[{"type":"text","text":"ok"}],"usage":{"input_tokens":1000,"output_tokens":10}}`}}
	comp := &liveZoneCompressor{}
	srv := newSocketFreeCompressServer(anthropic.New("https://upstream.test"), comp, rt, passthroughTestCreds{})

	serveBody(t, srv, "/v1/messages", body, map[string]string{
		"user-agent":        "codex-cli/0.1",
		"authorization":     "Bearer sk-ant-oat-test",
		"anthropic-beta":    "oauth-2025-04-20",
		"accept-encoding":   "identity",
		"anthropic-version": "2023-06-01",
	})

	if len(rt.bodies) != 1 {
		t.Fatalf("upstream calls = %d, want 1", len(rt.bodies))
	}
	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("subscription default must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
	}
	upstream := string(rt.bodies[0])
	if strings.Contains(upstream, retrieveToolName) || strings.Contains(upstream, "<<ccr:") {
		t.Fatalf("subscription default must inject no tool and add no marker: %s", upstream)
	}
	if comp.calls != 0 || len(comp.stored) != 0 {
		t.Fatalf("subscription default must not invoke compression/store: compress=%d stored=%d", comp.calls, len(comp.stored))
	}
	headers := rt.headers[0]
	if got := headers.Get("authorization"); got != "Bearer sk-ant-oat-test" {
		t.Fatalf("authorization = %q", got)
	}
	if got := headers.Get("anthropic-beta"); got != "oauth-2025-04-20" {
		t.Fatalf("anthropic-beta = %q", got)
	}
	if got := headers.Get("accept-encoding"); got != "identity" {
		t.Fatalf("accept-encoding = %q", got)
	}
	if got := headers.Get("user-agent"); got != "codex-cli/0.1" {
		t.Fatalf("user-agent = %q", got)
	}
}

