func (s *Server) proxy(w http.ResponseWriter, r *http.Request) {
	if !normalizeAgentPath(r) {
		httpx.Error(w, r, http.StatusNotFound, "cave_route_not_found", "Proxy path is not recognized.")
		return
	}
	start := time.Now()
	requestID := id.NewUUIDv7()
	traceID := traceIDFrom(r)
	w.Header().Set("x-cave-request-id", requestID)
	w.Header().Set("x-cave-trace-id", traceID)

	adapter := s.matchAdapter(r)
	if adapter == nil {
		// fail-closed routing: an unrecognized path is a 404, never a blind pass-through.
		httpx.Error(w, r, http.StatusNotFound, "cave_route_not_found", "Proxy path is not recognized.")
		return
	}
	rc, err := s.auth.Authenticate(r.Context(), r)
	if err != nil {
		httpx.Error(w, r, http.StatusUnauthorized, "cave_unauthorized", "Request rejected by the proxy authenticator.")
		return
	}
	credential := s.creds.Resolve(adapter.Name(), r)
	authMode := ClassifyResolvedAuthMode(r.Header, credential)
	// Per ADR 0031 local compression is not account-gated, so both non-PAYG
	// classifications reach the live zone on the same purely technical conditions:
	// the operator off-switch, an adapter with cache-floor reasoning, and the MCP
	// recovery + byte-stable prefix machinery that makes the rewrite recoverable
	// and maintainable.
	nonPAYGLiveZone := (authMode == AuthModeSubscription || authMode == AuthModeOAuth) && s.liveZoneCompressionAllowed(adapter)
	subscriptionPassthrough := authMode == AuthModeSubscription && !nonPAYGLiveZone
	// Attribute the row to the wrapped agent (e.g. `caveman wrap opencode` sets
	// x-cave-agent: opencode). Default to "unlabeled-agent" so the dimension is
	// always present. Telemetry-only: it never gates routing or transforms.
	rc.AgentSlug = labelOrDefault(r.Header.Get("x-cave-agent"), "unlabeled-agent")

	maxBytes := int64(env.Int("CAVE_MAX_REQUEST_BYTES", 33554432))
	body, err := io.ReadAll(io.LimitReader(r.Body, maxBytes+1))
	_ = r.Body.Close()
	if err != nil || int64(len(body)) > maxBytes {
		httpx.Error(w, r, http.StatusRequestEntityTooLarge, "cave_request_too_large", "Request body exceeds the proxy limit.")
		return
	}
	body, correlatedSessionID, _ := nativeruntime.StripSessionMarkers(body, s.sessionMarkerKey)
	if strings.HasPrefix(labelOrDefault(rc.Label, "local"), "trial:") {
		if payloads, ok := s.sink.(PayloadSink); ok {
			payloads.RecordPayload(rc.Label, requestID, traceID, body)
		}
	}
	rawHash := sha256.Sum256(body)
	evidence := requestEvidenceFromHeaders(r.Header)
	if correlatedSessionID != "" {
		evidence.SessionID = correlatedSessionID
		evidence.SessionCorrelationBasis = "signed_marker"
	} else if evidence.SessionID != "" {
		evidence.SessionCorrelationBasis = "explicit_header"
	}

	headersForInspect := r.Header.Clone()
	headersForInspect.Set("x-cave-route-path", r.URL.Path)
	meta, err := adapter.InspectRequest(r.Context(), bytes.NewReader(body), headersForInspect)
	if err != nil {
		httpx.Error(w, r, http.StatusBadRequest, "cave_provider_request_invalid", "Provider request metadata could not be inspected.")
		return
	}
	meta.BillingTier = rc.ProviderBillingTiers[meta.Provider]
	if evidence.SessionID == "" && s.sessionFallback != nil {
		if sessionID, basis := s.sessionFallback(time.Now(), meta.Provider, meta.Model); sessionID != "" && (basis == "unique_recent_session" || basis == "unique_recent_time_model") {
			evidence.SessionID = sessionID
			evidence.SessionCorrelationBasis = basis
		}
	}
	// Record the real request path rather than the adapter's default provider tag.
	meta.Endpoint = r.URL.Path
	// The caller's session identity, already shape-bounded by requestEvidenceFromHeaders.
	// It reaches adapters as content-blind routing input only (see RequestMetadata).
	meta.SessionID = evidence.SessionID

	// byte-safe transform. record mode never transforms. On ANY transform error we
	// forward the ORIGINAL bytes unchanged (fail-open) rather than failing the
	// request — the operator's traffic must never break because an optimizer hint
	// could not be applied. compress mode (S4) is the one path that intentionally
	// reshapes model-visible bytes; it is opt-in, recoverable via CCR, and disclosed.
	transform := providers.TransformResult{Body: body, OptimizerIDs: []string{}}
	var comp *compressionOutcome
	// toolSchemaHandle is the CCR handle of the original tool catalog, set only
	// when the tool-schema annotation strip actually rewrote it.
	toolSchemaHandle := ""
	// breakpointPlanned records that the cache-breakpoint planner placed provider
	// cache metadata on this request. The session ledger needs it to know which
	// levers were active when it later evaluates the harm tripwire.
	breakpointPlanned := false
	var estimate *estimateOutcome
	var estimateWG sync.WaitGroup
	retrieveInjected := false
	compressionEligible := false
	effectiveRuntimeMode := rc.RuntimeMode
	if strings.TrimSpace(r.Header.Get("x-cave-transforms")) == "caveman.pass-through.v1" {
		// Framework callers use this request-wide opt-out when their result contract
		// cannot observe or recover transformed bytes. It suppresses compression,
		// pixel, and provider-native transforms while preserving configured mode in
		// response/telemetry. Record behavior may still simulate an estimate on copies.
		effectiveRuntimeMode = "record"
	}
	switch effectiveRuntimeMode {
	case "record":
		// always a pure pass-through. When observe-estimate is on, measure — on
		// COPIES, storing nothing — how many tokens compression WOULD have removed.
		// The forwarded body stays byte-identical; any estimate error is swallowed.
		//
		// Run the estimate CONCURRENTLY with the upstream round-trip so its
		// tokenizer+Simulate cost never lands on time-to-first-byte. This is race-free:
		// the goroutine only READS body (segments are copied before the engine touches
		// them) — the same body the upstream reader consumes read-only — and meta is
		// snapshotted by value here, before the main path reassigns it via
		// ApplyResolvedPricingRoute below. `estimate` is written by exactly one
		// goroutine and read only after estimateWG.Wait() (which establishes the
		// happens-before), so every record() consumer sees a fully-computed value.
		if s.observeEstimate {
			estimateWG.Add(1)
			go func(m providers.RequestMetadata) {
				defer estimateWG.Done()
				estimate = s.estimateRequest(adapter, body, m)
			}(meta)
		}
	case "compress":
		if s.compressor == nil {
			break
		}
		lockedRoutes, compiledPlanAllowed := compiledPlanRoutes(r.Header)
		if !compiledPlanAllowed {
			break
		}
		// Subscription-classified traffic falls back to S0 passthrough whenever the
		// live-zone conditions do not hold (operator off-switch, no schema-aware
		// prefix stabilizer, no MCP recovery, no durable prefix cache) — the path
		// prior Claude Code sessions proved safe after byte-modified requests drew
		// opaque 429s. When they DO hold it takes the very same live-zone path PAYG
		// traffic uses — marker-only, cache-floor aware — and its row is recorded
		// tokens-only, never in dollars.
		if subscriptionPassthrough {
			break
		}
		serverRetrieveAllowed := authMode == AuthModePAYG && !s.recoveryViaMCP && !meta.Stream && !hasRetrieveTool(body) && serverRetrieveSupported(meta.Provider, meta.Endpoint)
		if serverRetrieveAllowed {
			if _, canRetrieve := s.compressor.(Retriever); !canRetrieve {
				serverRetrieveAllowed = false
			}
		}
		// Marker-only compression needs a recovery path the caller can actually reach.
		// PAYG keeps its pre-existing MCP-recovery rule; subscription and OAuth go
		// exclusively through the live-zone predicate above (which itself requires MCP
		// recovery), so neither can ever compress with no way back to the elided bytes.
		markerOnlyAllowed := (s.recoveryViaMCP && authMode != AuthModeOAuth && authMode != AuthModeSubscription) || nonPAYGLiveZone
		if (markerOnlyAllowed || serverRetrieveAllowed) && s.cacheEpochAllows(r, adapter, meta, body, evidence.SessionID) {
			// The request reached the compression path as a candidate. It is eligible
			// whether or not compressRequest ultimately shrinks any bytes — the
			// requests_eligible_for_compression denominator counts candidates, not wins.
			compressionEligible = true
			comp = s.compressRequest(adapter, body, meta, &transform, requestID, lockedRoutes)
		}
		if serverRetrieveAllowed {
			if injected, ok := injectRetrieveTool(meta.Provider, meta.Endpoint, transform.Body); ok {
				transform.Body = injected
				retrieveInjected = true
				if comp != nil {
					comp.bookSavings = true
				}
			} else {
				if comp != nil {
					comp = nil
					transform = providers.TransformResult{Body: body, OptimizerIDs: []string{}}
				}
			}
		}
		// The tool-schema annotation strip is its own path, not a rewritable block:
		// the tool catalog is frozen prefix that extractRewritable deliberately
		// never yields, and compressRequest's `!block.live` guard must keep
		// protecting that prefix from the general rewrite loop. See
		// stripToolSchema for the determinism invariant that makes a frozen-prefix
		// rewrite admissible here. It runs last so its byte offsets are computed on
		// the bytes actually going upstream, and it is skipped under a compiled
		// Cave Build, whose transform set is locked to what evals approved.
		if len(lockedRoutes) == 0 && s.toolSchemaStripAllowed(adapter, evidence.SessionID) && s.cacheEpochAllows(r, adapter, meta, transform.Body, evidence.SessionID) {
			if stripped, handle, ok := s.stripToolSchema(transform.Body, meta, requestID); ok {
				transform.Body = stripped
				transform.OptimizerIDs = append(transform.OptimizerIDs, toolSchemaStripOptimizerID)
				toolSchemaHandle = handle
			}
		}
	case "pixel":
		if s.compressor == nil {
			break
		}
		if authMode == AuthModeSubscription {
			break
		}
		comp = s.pixelRequest(adapter, body, meta, &transform, requestID)
	default:
		if authMode != AuthModeSubscription {
			t, terr := adapter.ApplyProviderNativeTransforms(r.Context(), bytes.NewReader(body), meta, providers.TransformPolicy{
				RuntimeMode: rc.RuntimeMode,
				AuthMode:    string(authMode),
				Optimizers:  rc.Optimizers,
				EvalGates:   rc.EvalGates,
			})
			if terr != nil {
				if s.logger != nil {
					s.logger.Warn("transform failed; forwarding original bytes unchanged", "error", redact.Error(terr), "request_id", requestID)
				}
			} else {
				transform = t
			}
		}
		// The cache-breakpoint planner runs on the bytes actually going upstream, so
		// its placement is computed after any provider-native transform above.
		//
		// Unlike that transform it is NOT skipped for subscription traffic, because it
		// adds provider metadata rather than model-visible bytes. Both of its live
		// arms are payg-gated today, so subscription traffic gets nothing from it; the
		// reach is kept for the reworked lookback guard, whose entire purpose is
		// harnesses that already place cache_control. record mode never reaches this
		// branch at all, so a pass-through request is untouched by construction.
		if s.breakpointPlanAllowed(evidence.SessionID) {
			if planned, ok := s.planBreakpoints(adapter, transform.Body, meta, authMode == AuthModePAYG); ok {
				transform.Body = planned
				transform.OptimizerIDs = append(transform.OptimizerIDs, breakpointPlanOptimizerID)
				breakpointPlanned = true
			}
		}
	}
	transformedHash := sha256.Sum256(transform.Body)
	providerCachePrefixSHA256, providerCacheComponentSHA256, cacheBoundaryKnown := providerPrefixEvidence(adapter, transform.Body, meta)

	// Observe-only prefix-monotonicity check (issue #133): compare this request's
	// frozen-prefix component hashes against the previous request in the same
	// session and flag cache_bust if the new prefix does not extend the prior one.
	// It never blocks or modifies traffic — the flag is persisted and a Warn names
	// the first diverging component index. Evaluated once here on the bytes we send
	// upstream; the byte-safe retry below keeps this verdict rather than re-running
	// the stateful monitor for the same request.
	cacheBust, divergingComponentIndex := s.prefixMonitor.observe(evidence.SessionID, providerCacheComponentSHA256)
	if cacheBust && s.logger != nil {
		s.logger.Warn("session frozen-cache prefix did not extend prior request; possible cache bust",
			"request_id", requestID, "session_id", evidence.SessionID,
			"diverging_component_index", divergingComponentIndex)
	}

	upstreamURL, err := adapter.ResolveUpstreamURL(r.Context(), r, providers.RouteContext{})
	if err != nil {
		httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unavailable", "Upstream route could not be resolved.")
		return
	}
	meta = providers.ApplyResolvedPricingRoute(meta, upstreamURL)
	authContext := providers.WithRequestPayloadHash(r.Context(), transform.Body)
	upstreamHeaders, err := adapter.SanitizeAndMapHeaders(authContext, r, credential, upstreamURL)
	if err != nil {
		httpx.Error(w, r, http.StatusBadRequest, "cave_header_mapping_failed", "Headers could not be mapped safely.")
		return
	}
	if authMode != AuthModePAYG && r.UserAgent() != "" {
		upstreamHeaders.Set("user-agent", r.UserAgent())
	}
	s.applyUpstreamAuthFallback(adapter.Name(), credential, upstreamHeaders)
	req, err := http.NewRequestWithContext(r.Context(), r.Method, upstreamURL.String(), bytes.NewReader(transform.Body))
	if err != nil {
		httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unavailable", "Upstream request could not be created.")
		return
	}
	req.Header = upstreamHeaders

	s.inflight.Add(1)
	// Capture both sides of the transform before the send (see capture.go). Off
	// unless CAVE_CAPTURE_DIR is set; nil-guarded inside record, and queued rather
	// than written here so the inflight window carries no disk write.
	s.capture.record(captureMeta{
		RequestID:   requestID,
		Provider:    meta.Provider,
		Endpoint:    meta.Endpoint,
		RuntimeMode: effectiveRuntimeMode,
		Optimizers:  strings.Join(transform.OptimizerIDs, ","),
	}, wholeBody(body), wholeBody(transform.Body))

	resp, err := s.httpClient.Do(req)
	s.inflight.Add(-1)
	if err != nil {
		httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unavailable", "Upstream provider unavailable.")
		estimateWG.Wait() // join the observe estimate before record() reads it
		s.record(start, 0, requestID, traceID, rc, meta, authMode, http.StatusBadGateway, 0, len(body), rawHash, transformedHash, "cave_upstream_unavailable", transform.OptimizerIDs, providers.UsageObservation{CacheStatus: "unknown"}, comp, toolSchemaHandle, false, estimate, evidence, providerCachePrefixSHA256, providerCacheComponentSHA256, cacheBoundaryKnown, cacheBust, compressionEligible)
		return
	}
	// byte-safe fail-open: if the upstream rejects a request whose bytes we
	// modified, retry ONCE with the original bytes before surfacing the error —
	// a transform must never break traffic that would have succeeded untouched.
	// (Measured 2026-07-07: Anthropic answers subscription-OAuth requests whose
	// first system block changed with an opaque 429; any future fingerprint check
	// lands here too.) The retry claims no optimization and books no savings.
	if resp.StatusCode >= 400 && resp.StatusCode < 500 && !bytes.Equal(transform.Body, body) {
		_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, 1<<20))
		_ = resp.Body.Close()
		if s.logger != nil {
			s.logger.Warn("upstream rejected transformed request; retrying with original bytes", "status", resp.StatusCode, "request_id", requestID)
		}
		retryReq, rerr := http.NewRequestWithContext(r.Context(), r.Method, upstreamURL.String(), bytes.NewReader(body))
		if rerr != nil {
			httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unavailable", "Upstream request could not be created.")
			return
		}
		retryAuthContext := providers.WithRequestPayloadHash(r.Context(), body)
		retryHeaders, rerr := adapter.SanitizeAndMapHeaders(retryAuthContext, r, credential, upstreamURL)
		if rerr != nil {
			httpx.Error(w, r, http.StatusBadRequest, "cave_header_mapping_failed", "Headers could not be mapped safely.")
			return
		}
		if authMode != AuthModePAYG && r.UserAgent() != "" {
			retryHeaders.Set("user-agent", r.UserAgent())
		}
		s.applyUpstreamAuthFallback(adapter.Name(), credential, retryHeaders)
		retryReq.Header = retryHeaders
		s.inflight.Add(1)
		retryResp, derr := s.httpClient.Do(retryReq)
		s.inflight.Add(-1)
		if derr != nil {
			httpx.Error(w, r, http.StatusBadGateway, "cave_upstream_unavailable", "Upstream provider unavailable.")
			estimateWG.Wait() // join the observe estimate; passed uniformly (zeroed at Record on this failed status)
			s.record(start, 0, requestID, traceID, rc, meta, authMode, http.StatusBadGateway, 0, len(body), rawHash, rawHash, "cave_upstream_unavailable", []string{}, providers.UsageObservation{CacheStatus: "unknown"}, nil, "", false, estimate, evidence, providerCachePrefixSHA256, providerCacheComponentSHA256, cacheBoundaryKnown, cacheBust, compressionEligible)
			return
		}
		resp = retryResp
		transform = providers.TransformResult{Body: body, OptimizerIDs: []string{}}
		transformedHash = rawHash
		providerCachePrefixSHA256, providerCacheComponentSHA256, cacheBoundaryKnown = providerPrefixEvidence(adapter, body, meta)
		comp = nil
		toolSchemaHandle = ""
		breakpointPlanned = false
		retrieveInjected = false
		// The ORIGINAL bytes served this request, so the capture written before the
		// first attempt describes bytes the upstream rejected. Write a second record
		// for the same request id rather than leaving the first one to be read as
		// what was answered — a capture that is confidently wrong is the exact
		// failure this instrument exists to remove.
		s.capture.record(captureMeta{
			RequestID:     requestID,
			Provider:      meta.Provider,
			Endpoint:      meta.Endpoint,
			RuntimeMode:   effectiveRuntimeMode,
			RetryOriginal: true,
		}, wholeBody(body), wholeBody(body))
	}
	var retrieveCalls []providers.UsageObservation
	var retrieved bool
	var replayedOriginal bool
	if retrieveInjected {
		resp, retrieveCalls, retrieved, replayedOriginal = s.runRetrieveLoop(r.Context(), s.httpClient, upstreamURL, upstreamHeaders, transform.Body, body, comp.recoveryHandles(), resp, adapter, meta.Provider, meta.Endpoint, requestID)
	}
	if replayedOriginal {
		transform = providers.TransformResult{Body: body, OptimizerIDs: []string{}}
		transformedHash = rawHash
		providerCachePrefixSHA256, providerCacheComponentSHA256, cacheBoundaryKnown = providerPrefixEvidence(adapter, body, meta)
		comp = nil
		toolSchemaHandle = ""
		breakpointPlanned = false
		retrieveInjected = false
		s.capture.record(captureMeta{
			RequestID:     requestID,
			Provider:      meta.Provider,
			Endpoint:      meta.Endpoint,
			RuntimeMode:   effectiveRuntimeMode,
			RetryOriginal: true,
		}, wholeBody(body), wholeBody(body))
	}
	defer resp.Body.Close()

	copySafeResponseHeaders(w.Header(), resp.Header)
	w.Header().Set("x-cave-project", rc.Label)
	w.Header().Set("x-cave-mode", rc.RuntimeMode)
	if len(transform.OptimizerIDs) == 0 {
		w.Header().Set("x-cave-optimization", "none")
	} else {
		w.Header().Set("x-cave-optimization", strings.Join(transform.OptimizerIDs, ","))
	}
	// per-request disclosure of S4 compression: ratio, the CCR recovery handle for
	// the original request, and the inferred token counts. Set only when compress
	// mode actually shrank the request.
	if comp != nil {
		w.Header().Set("x-caveman-compression-ratio", strconv.FormatFloat(comp.ratio, 'f', 4, 64))
		w.Header().Set("x-caveman-recovery-handle", comp.handle)
		w.Header().Set("x-caveman-tokens-before", strconv.Itoa(comp.before))
		w.Header().Set("x-caveman-tokens-after", strconv.Itoa(comp.after))
		w.Header().Set("x-caveman-token-count-basis", "estimated_engine_o200k")
	}
	// per-request disclosure of the tool-schema strip: which strip ran and the CCR
	// handle of the exact original catalog. It carries no token figure — the strip
	// claims no saving here; the replay grid prices it.
	if toolSchemaHandle != "" {
		w.Header().Set("x-caveman-toolschema-strip", toolSchemaStripMode)
		w.Header().Set("x-caveman-toolschema-recovery-handle", toolSchemaHandle)
	}
	// per-request disclosure of the harm tripwire: which levers this session has
	// lost. It appears from the request AFTER the one that tripped, because the
	// usage that trips it is only known once the response is already streaming.
	if tripwire := s.tripwireDisclosure(evidence.SessionID); tripwire != "" {
		w.Header().Set("x-caveman-tripwire", tripwire)
	}
	w.WriteHeader(resp.StatusCode)

	counter := &countingWriter{w: w}
	usageScanner := adapter.NewUsageScanner(resp.Header)
	_, copyErr := copyFlush(counter, io.TeeReader(resp.Body, usageScanner))
	ttfb := time.Since(start).Milliseconds()
	if !counter.firstByteAt.IsZero() {
		ttfb = counter.firstByteAt.Sub(start).Milliseconds()
	}
	if copyErr != nil && s.logger != nil {
		s.logger.Warn("client stream copy failed", "error", redact.Error(copyErr), "request_id", requestID)
	}
	errCode := ""
	if resp.StatusCode >= 400 {
		errCode = fmt.Sprintf("provider_%d", resp.StatusCode)
	}
	finalUsage := usageScanner.Usage()
	// The session ledger sees the provider's own numbers for the upstream call the
	// levers actually shaped — not the retrieve-loop total below, whose extra calls
	// carry their own prefixes and would blur the cache-creation signal the harm
	// tripwire reads.
	var activeLevers []lever
	if toolSchemaHandle != "" {
		activeLevers = append(activeLevers, leverToolSchemaStrip)
	}
	if breakpointPlanned {
		activeLevers = append(activeLevers, leverBreakpointPlan)
	}
	s.observeSession(evidence.SessionID, activeLevers, finalUsage, requestID)
	combinedUsage := finalUsage
	for _, callUsage := range retrieveCalls {
		combinedUsage = addUsage(combinedUsage, callUsage)
	}
	if len(retrieveCalls) > 0 {
		combinedUsage.CallObservations = append(append([]providers.UsageObservation{}, retrieveCalls...), finalUsage)
	}
	estimateWG.Wait() // join the observe estimate; overlapped the upstream round-trip + response stream
	s.record(start, ttfb, requestID, traceID, rc, meta, authMode, resp.StatusCode, counter.n, len(body), rawHash, transformedHash, errCode, transform.OptimizerIDs, combinedUsage, comp, toolSchemaHandle, retrieved, estimate, evidence, providerCachePrefixSHA256, providerCacheComponentSHA256, cacheBoundaryKnown, cacheBust, compressionEligible)
}

func providerPrefixEvidence(adapter providers.Adapter, body []byte, meta providers.RequestMetadata) (string, string, bool) {
	inspector, ok := adapter.(PrefixEvidenceInspector)
	if !ok {
		return "", "", false
	}
	components, ok := inspector.FrozenPrefixComponents(body, meta)
	if !ok || len(components) == 0 || len(components) > 1_024 {
		return "", "", false
	}
	whole := sha256.New()
	hashes := make([]string, 0, len(components))
	for _, component := range components {
		if len(component) > 32<<20 {
			return "", "", false
		}
		digest := sha256.Sum256(component)
		hashes = append(hashes, hex.EncodeToString(digest[:]))
		_, _ = whole.Write(component)
	}
	return hex.EncodeToString(whole.Sum(nil)), strings.Join(hashes, ","), true
}

type requestEvidence struct {
	SessionID               string
	SessionCorrelationBasis string
	AgentBuildSHA256        string
	EfficiencyPlanSHA256    string
	ContextBill             string
	TransformTrace          string
	TransformLocation       string
	CacheEpoch              string
	CachePrefixSHA256       string
}

func requestEvidenceFromHeaders(headers http.Header) requestEvidence {
	build := strings.TrimSpace(headers.Get("x-cave-agent-build"))
	plan := strings.TrimSpace(headers.Get("x-cave-efficiency-plan"))
	if !validGatewayDigest(build) || !validGatewayDigest(plan) {
		build, plan = "", ""
	}
	prefix := strings.TrimSpace(headers.Get("x-cave-cache-prefix-sha256"))
	if !validGatewayDigest(prefix) {
		prefix = ""
	}
	location := strings.TrimSpace(headers.Get("x-cave-transform-location"))
	if location != "local" && location != "gateway" {
		location = ""
	}
	return requestEvidence{
		SessionID:            boundedEvidenceToken(headers.Get("x-cave-session"), 256),
		AgentBuildSHA256:     build,
		EfficiencyPlanSHA256: plan,
		ContextBill:          boundedEvidenceValue(headers.Get("x-cave-context-bill"), 2_048),
		TransformTrace:       boundedEvidenceValue(headers.Get("x-cave-transform-trace"), 8_192),
		TransformLocation:    location,
		CacheEpoch:           boundedEvidenceToken(headers.Get("x-cave-cache-epoch"), 512),
		CachePrefixSHA256:    prefix,
	}
}

func boundedEvidenceToken(value string, limit int) string {
	value = strings.TrimSpace(value)
	if value == "" || len(value) > limit {
		return ""
	}
	for _, char := range value {
		if (char < 'a' || char > 'z') && (char < 'A' || char > 'Z') &&
			(char < '0' || char > '9') && !strings.ContainsRune("._:-", char) {
			return ""
		}
	}
	return value
}

func boundedEvidenceValue(value string, limit int) string {
	value = strings.TrimSpace(value)
	if value == "" || len(value) > limit {
		return ""
	}
	for _, char := range value {
		if char < 0x20 || char > 0x7e {
			return ""
		}
	}
	return value
}

// compiledPlanAllowsCompression keeps entitlement defaults from overriding an
// immutable Claude Cave Build. No build header means legacy/unlocked behavior.
// A locked baseline explicitly selects pass-through; unknown or partial lock
// identity also fails closed to original bytes.
func compiledPlanAllowsCompression(headers http.Header) bool {
	_, allowed := compiledPlanRoutes(headers)
	return allowed
}

func compiledPlanCompression(headers http.Header) (contentType, transformID string, allowed bool) {
	routes, allowed := compiledPlanRoutes(headers)
	if !allowed || len(routes) != 1 {
		return "", "", false
	}
	return routes[0].ContentType, routes[0].TransformID, true
}

type compiledRoute struct {
	SegmentID   string `json:"segment_id,omitempty"`
	SegmentKind string `json:"segment_kind"`
	TransformID string `json:"transform_id"`
	ContentType string `json:"-"`
}

func compiledPlanRoutes(headers http.Header) ([]compiledRoute, bool) {
	build := strings.TrimSpace(headers.Get("x-cave-agent-build"))
	plan := strings.TrimSpace(headers.Get("x-cave-efficiency-plan"))
	transforms := strings.TrimSpace(headers.Get("x-cave-transforms"))
	if strings.TrimSpace(headers.Get("x-cave-transform-location")) == "local" {
		// Pi runtime already applied plan bytes. Gateway is transport + metering;
		// a second entitlement-conditioned transform would invalidate baseline
		// and selected-plan evidence.
		return nil, false
	}
	// Unlocked framework callers may explicitly require byte-identical transport.
	// This opt-out carries no build claim and only removes capability from the
	// caller's own request, so it is safe without lock identity.
	if transforms == "caveman.pass-through.v1" {
		return nil, false
	}
	if build == "" && plan == "" {
		return nil, true
	}
	if !validGatewayDigest(build) || !validGatewayDigest(plan) || transforms == "" {
		return nil, false
	}
	parts := strings.Split(transforms, ",")
	var routes []compiledRoute
	encodedRoutes := strings.TrimSpace(headers.Get("x-cave-transform-routes"))
	if encodedRoutes == "" {
		if len(parts) != 1 {
			return nil, false
		}
		routes = []compiledRoute{{SegmentKind: "history", TransformID: strings.TrimSpace(parts[0])}}
	} else {
		raw, err := base64.RawURLEncoding.DecodeString(encodedRoutes)
		if err != nil || len(raw) > 16*1024 || json.Unmarshal(raw, &routes) != nil ||
			len(routes) == 0 || len(routes) > 32 || len(routes) != len(parts) {
			return nil, false
		}
	}
	for i := range routes {
		routes[i].TransformID = strings.TrimSpace(routes[i].TransformID)
		if routes[i].TransformID != strings.TrimSpace(parts[i]) ||
			!validCompiledSegmentKind(routes[i].SegmentKind) ||
			(routes[i].SegmentID != "" && len(routes[i].SegmentID) > 256) {
			return nil, false
		}
		contentType, ok := compiledContentType(routes[i].TransformID)
		if !ok {
			return nil, false
		}
		routes[i].ContentType = contentType
	}
	return routes, true
}

func compiledContentType(transformID string) (string, bool) {
	const prefix, suffix = "caveman.engine.", ".v1"
	if !strings.HasPrefix(transformID, prefix) || !strings.HasSuffix(transformID, suffix) {
		return "", false
	}
	contentType := strings.TrimSuffix(strings.TrimPrefix(transformID, prefix), suffix)
	switch contentType {
	case "a11y", "code", "config", "diff", "html", "json", "log", "repetition",
		"search-result", "tabular", "terminal", "text", "toolschema", "toon":
		return contentType, true
	default:
		return "", false
	}
}

func validCompiledSegmentKind(kind string) bool {
	switch kind {
	case "instruction", "user_intent", "tool_schema", "skill", "memory", "history",
		"tool_result", "artifact", "error", "output_contract":
		return true
	default:
		return false
	}
}

func validGatewayDigest(value string) bool {
	if len(value) != 64 {
		return false
	}
	for _, char := range value {
		if (char < '0' || char > '9') && (char < 'a' || char > 'f') {
			return false
		}
	}
	return true
}

// cacheEpochAllows binds framework-frozen prefix identity to gateway transform
// authorization without putting prompt bytes in headers or telemetry. Legacy
// callers that send neither header keep existing provider-adapter enforcement;
// a partial/invalid framework declaration fails closed to pass-through.
func (s *Server) cacheEpochAllows(r *http.Request, adapter providers.Adapter, meta providers.RequestMetadata, body []byte, sessionID string) bool {
	epoch := strings.TrimSpace(r.Header.Get("x-cave-cache-epoch"))
	digest := strings.TrimSpace(r.Header.Get("x-cave-cache-prefix-sha256"))
	if epoch == "" && digest == "" {
		// Header-less wrap clients (Claude Code, Codex, Gemini CLI) never declare a
		// cache epoch or prefix digest, so without a derived path the gate never runs
		// for the wrap's actual users (issue #133). It CANNOT reuse cacheguard.Inspect:
		// that compares whole-prefix digests for equality, but the Anthropic frozen
		// prefix grows every turn as the cache floor advances (content_compress.go), so
		// whole-prefix equality reads legitimate append-only growth as drift and would
		// skip compression from turn 2 onward — a coverage regression for the exact
		// clients this path serves. Instead gate on the SAME append-only component
		// check SLICE 1 uses (derivedEpochAllows).
		return s.derivedEpochAllows(adapter, meta, body, sessionID)
	}
	if epoch == "" || digest == "" || s.cacheGuard == nil {
		return false
	}
	result, err := s.cacheGuard.Inspect(cacheguard.Input{
		EpochID:       epoch + ":" + meta.Provider + ":" + meta.Endpoint,
		PrefixSHA256:  digest,
		BoundaryKnown: true,
		AdapterKnown:  s.prefixStabilized(adapter),
	})
	if err != nil || result.Decision == cacheguard.DecisionPassThrough {
		if s.logger != nil {
			s.logger.Warn("cache epoch rejected transformed request; forwarding original bytes",
				"warnings", result.Warnings)
		}
		return false
	}
	return true
}

// derivedEpochAllows is the compression gate for header-less wrap clients. It reuses
// SLICE 1's append-only component comparison (prefix_monitor) rather than
// cacheguard's whole-prefix equality, so it is extension-tolerant: a request whose
// frozen prefix APPEND-ONLY EXTENDS the stored one is allowed AND re-anchors the
// stored prefix to the new (longer) one, so a growing Claude Code session keeps
// compressing every turn instead of getting stuck on turn 1. Only a genuine
// divergence — a frozen component changed, dropped, or reordered (the same
// condition SLICE 1 flags as cache_bust) — is drift: compression is skipped and the
// ORIGINAL bytes are forwarded (byte-safe, blocks nothing, books nothing). The gate
// re-anchors on divergence too, so a real prefix change resyncs the next turn rather
// than stalling compression for the rest of the session.
//
// With no correlated session, or an adapter that exposes no frozen prefix, it keeps
// the legacy behavior of leaving provider-adapter enforcement in charge (allow).
func (s *Server) derivedEpochAllows(adapter providers.Adapter, meta providers.RequestMetadata, body []byte, sessionID string) bool {
	if sessionID == "" {
		return true
	}
	_, components, boundaryKnown := providerPrefixEvidence(adapter, body, meta)
	if components == "" || !boundaryKnown {
		return true
	}
	epochID := "wrap:" + sessionID + ":" + meta.Provider + ":" + meta.Endpoint
	bust, divergingIndex := s.cacheEpochGate.observe(epochID, components)
	if bust {
		if s.logger != nil {
			s.logger.Warn("derived cache epoch prefix diverged; forwarding original bytes",
				"provider", meta.Provider, "endpoint", meta.Endpoint,
				"diverging_component_index", divergingIndex)
		}
		return false
	}
	return true
}

// estimateOutcome carries a record-mode observe-only measurement: the engine's
// o200k token counts before/after the compression that WOULD have run. It never
// mutates the request and is never booked as a saving — only surfaced as
// would_save_tokens (and, for list-price-eligible rows, a would_save_usd figure).
type estimateOutcome struct {
	before int
	after  int
}

// estimateRequest measures how many tokens compression would have removed from the
// live-zone segments of a request, WITHOUT altering the forwarded bytes and WITHOUT
// storing any CCR original. It runs only through the Estimator (engine Simulate)
// seam — a compressor that cannot estimate without storing yields no estimate, so
// the observe path can never write a recovery row. Each segment is copied before it
// reaches the engine so the original request bytes are provably untouched.
func (s *Server) estimateRequest(adapter providers.Adapter, body []byte, meta providers.RequestMetadata) *estimateOutcome {
	est, ok := s.compressor.(Estimator)
	if !ok {
		return nil
	}
	segments, _, ok := adapter.ExtractCompressible(body, meta)
	if !ok || len(segments) == 0 {
		return nil
	}
	query := extractCompressionQuery(meta.Provider, meta.Endpoint, body)
	queryEst, queryAware := s.compressor.(QueryAwareEstimator)
	var before, after int
	for _, seg := range segments {
		cp := append([]byte(nil), seg...) // never let the estimator alias forwarded bytes
		tb, ta := 0, 0
		if queryAware && query != "" {
			tb, ta = queryEst.EstimateSegmentQuery(cp, query)
		} else {
			tb, ta = est.EstimateSegment(cp)
		}
		if tb <= 0 || ta >= tb {
			continue
		}
		before += tb
		after += ta
	}
	if before <= 0 || after >= before {
		return nil
	}
	return &estimateOutcome{before: before, after: after}
}

func normalizeAgentPath(r *http.Request) bool {
	if !strings.HasPrefix(r.URL.Path, "/w/") {
		return true
	}
	slug, rest, ok := providers.SplitAgentPath(r.URL.Path)
	if !ok {
		return false
	}
	rawPath := r.URL.RawPath
	if rawPath != "" {
		rawPrefix := "/w/" + slug
		if !strings.HasPrefix(rawPath, rawPrefix) {
			return false
		}
		rawPath = strings.TrimPrefix(rawPath, rawPrefix)
		if rawPath == "" {
			return false
		}
	}
	r.URL.Path = rest
	// Preserve the encoded spelling of the stripped route. Compatibility mounts
	// reject encoded separators/dot segments before adapter selection; clearing
	// RawPath here would otherwise let a named route claim
	// `/w/slug/compat/name%2F…`.
	if rawPath != "" {
		r.URL.RawPath = rawPath
	}
	r.Header.Set("x-cave-agent", slug)
	return true
}

// compressionOutcome carries the result of an applied S4 compression from the
// compress branch through to record(): the CCR handle for the original request and
// the inferred token reduction. It is nil whenever compress mode did not run or
// did not shrink the request.
type compressionOutcome struct {
	handle  string
	handles []string
	before  int
	after   int
	ratio   float64
	// bookSavings authorizes the inferred compression saving to be claimed for this
	// request. It is true only on the server-side recovery path, where the proxy can
	// observe whether a retrieve continuation happened. Under MCP recovery the proxy
	// cannot see the agent's off-proxy retrieves, so it stays false (handle and ratio
	// are still disclosed as telemetry, but no dollar saving is claimed).
	bookSavings bool
}

// recoveryHandles returns the per-block CCR handles, nil-safe so a caller that
// merges in another path's handle does not have to branch on a strip-only request.
func (c *compressionOutcome) recoveryHandles() []string {
	if c == nil {
		return nil
	}
	return c.handles
}

// rewritableBlock is one content block the compress path may rewrite plus the
// provider-cache zone it sits in. Adapters with no cache-floor reasoning yield
// live-only blocks, which is exactly the pre-existing live-zone behavior.
type rewritableBlock struct {
	content []byte
	live    bool
	kind    string
	id      string
}

// extractRewritable asks the adapter for the blocks compress mode may rewrite.
// With a durable prefix cache AND an adapter that exposes its frozen zone, that is
// the live zone PLUS the already-cached blocks (so a replacement emitted on an
// earlier turn can be re-substituted byte-identically). Otherwise it degrades to
// the live-zone-only extraction.
func (s *Server) extractRewritable(
	adapter providers.Adapter,
	body []byte,
	meta providers.RequestMetadata,
	requireSemantics bool,
) ([]rewritableBlock, func([][]byte) ([]byte, error), bool) {
	if s.prefixCache != nil || requireSemantics {
		if stabilizer, ok := adapter.(PrefixStabilizer); ok {
			raw, reassemble, ok := stabilizer.ExtractStabilizable(body, meta)
			if !ok || len(raw) == 0 {
				return nil, nil, false
			}
			blocks := make([]rewritableBlock, len(raw))
			for i, b := range raw {
				blocks[i] = rewritableBlock{
					content: b.Content,
					live:    b.Live,
					kind:    b.Kind,
					id:      b.ID,
				}
			}
			return blocks, reassemble, true
		}
	}
	segments, reassemble, ok := adapter.ExtractCompressible(body, meta)
	if !ok || len(segments) == 0 {
		return nil, nil, false
	}
	blocks := make([]rewritableBlock, len(segments))
	for i, seg := range segments {
		blocks[i] = rewritableBlock{content: seg, live: true}
	}
	return blocks, reassemble, true
}

// compressRequest applies S4 compression to live-zone content and re-applies the
// replacements it already emitted to frozen content. Each live segment is
// independently token-gated, stored in CCR, marked inside the replacement with
// <<ccr:handle>>, and memoised in the prefix cache; each block the cache already
// knows — live or frozen — is substituted with those exact stored bytes so the
// upstream prefix is identical on every turn of the conversation. Unchanged/failed
// blocks are left byte-identical by the adapter's splice reassembler. If nothing is
// rewritten, the original body is forwarded exactly.
//
// Token accounting is once-per-message: only a block compressed for the FIRST time
// contributes to before/after. A substituted block re-books nothing — the caller
// receives its reduction on every later turn, but claiming it again would inflate
// one message's delta into a per-turn saving that was never separately earned.
func (s *Server) compressRequest(
	adapter providers.Adapter,
	body []byte,
	meta providers.RequestMetadata,
	transform *providers.TransformResult,
	requestID string,
	lockedRoutes []compiledRoute,
) *compressionOutcome {
	if s.compressor == nil {
		return nil
	}
	blocks, reassemble, ok := s.extractRewritable(adapter, body, meta, len(lockedRoutes) > 0)
	if !ok {
		return nil
	}
	routeByBlock := make([]int, len(blocks))
	for i := range routeByBlock {
		routeByBlock[i] = -1
	}
	if len(lockedRoutes) > 0 {
		if _, ok := s.compressor.(TypedCompressor); !ok {
			return nil
		}
		for blockIndex, block := range blocks {
			for routeIndex, route := range lockedRoutes {
				if route.SegmentKind != block.kind ||
					(route.SegmentID != "" && route.SegmentID != block.id) {
					continue
				}
				if routeByBlock[blockIndex] >= 0 {
					return nil // ambiguous semantic ownership: original bytes win.
				}
				routeByBlock[blockIndex] = routeIndex
			}
		}
	}
	replacements := make([][]byte, len(blocks))
	var before, after int
	var handles []string
	query := extractCompressionQuery(meta.Provider, meta.Endpoint, body)
	queryComp, queryAware := s.compressor.(QueryAwareCompressor)
	activeRoutes := make([]bool, len(lockedRoutes))
	for i, block := range blocks {
		if len(lockedRoutes) > 0 && routeByBlock[i] < 0 {
			continue // unmatched frozen history is never rewritten under this lock.
		}
		// The strip's version is part of the scope: it moves the tool catalog at the
		// head of the same provider prefix these replacements live under, so changing
		// it must retire the old entries rather than mix two prefix generations. The
		// suffix is empty while the lever is off, leaving every existing key untouched.
		cacheScope := "unlocked" + s.toolSchemaCacheScope()
		if len(lockedRoutes) > 0 {
			route := lockedRoutes[routeByBlock[i]]
			cacheScope = "locked:" + route.SegmentKind + ":" + route.SegmentID + ":" + route.TransformID + s.toolSchemaCacheScope()
		}
		if s.prefixCache != nil {
			if stored, handle, hit := s.prefixCache.LookupReplacement(cacheScope, block.content); hit {
				replacements[i] = stored
				handles = append(handles, handle)
				if len(lockedRoutes) > 0 {
					activeRoutes[routeByBlock[i]] = true
				}
				continue
			}
		}
		// A frozen block the cache does not know was never compressed by us (or its
		// entry was evicted): forward the client's original bytes. That is the
		// re-sync path — it costs one prefix rebuild and is stable from then on.
		if !block.live {
			continue
		}
		out, tb, ta := []byte(nil), 0, 0
		if len(lockedRoutes) > 0 {
			routeIndex := routeByBlock[i]
			if routeIndex < 0 {
				continue
			}
			route := lockedRoutes[routeIndex]
			typed := s.compressor.(TypedCompressor)
			out, tb, ta = typed.CompressSegmentType(block.content, route.ContentType)
			if out != nil && tb > 0 && ta < tb {
				activeRoutes[routeIndex] = true
			}
		} else if queryAware && query != "" {
			out, tb, ta = queryComp.CompressSegmentQuery(block.content, query)
		} else {
			out, tb, ta = s.compressor.CompressSegment(block.content)
		}
		if out == nil || tb <= 0 || ta >= tb {
			continue
		}
		handle, err := s.compressor.StoreOriginal(block.content)
		if err != nil || handle == "" {
			if s.logger != nil {
				if err != nil {
					s.logger.Warn("compress recovery store failed for block; keeping block original", "error", redact.Error(err), "request_id", requestID)
				} else {
					s.logger.Warn("compress recovery store returned empty handle; keeping block original", "request_id", requestID)
				}
			}
			continue
		}
		replacement := appendCCRMarker(out, handle)
		if s.prefixCache != nil {
			// A rewrite we cannot re-issue next turn must not go out at all: it would
			// diverge the prefix on the very next request. Fail open to the original.
			stored, err := s.prefixCache.RememberReplacement(cacheScope, block.content, replacement, handle)
			if err != nil || len(stored) == 0 {
				if s.logger != nil {
					s.logger.Warn("prefix replacement store failed for block; keeping block original", "error", redact.Error(err), "request_id", requestID)
				}
				continue
			}
			replacement = stored
		}
		replacements[i] = replacement
		before += tb
		after += ta
		handles = append(handles, handle)
	}
	if len(handles) == 0 {
		return nil // nothing rewritten — pass through, claim nothing.
	}
	newBody, err := reassemble(replacements)
	if err != nil {
		if s.logger != nil {
			s.logger.Warn("compress reassembly failed; forwarding original bytes unchanged", "error", redact.Error(err), "request_id", requestID)
		}
		return nil
	}
	if len(newBody) == 0 {
		return nil
	}
	if !json.Valid(newBody) {
		if s.logger != nil {
			s.logger.Warn("compress splice produced invalid JSON; forwarding original bytes unchanged", "request_id", requestID)
		}
		return nil
	}
	if bytes.Equal(newBody, body) {
		return nil
	}
	transform.Body = newBody
	if len(lockedRoutes) > 0 {
		appliedTransformIDs := make([]string, 0, len(lockedRoutes))
		for routeIndex, route := range lockedRoutes {
			if activeRoutes[routeIndex] {
				appliedTransformIDs = append(appliedTransformIDs, route.TransformID)
			}
		}
		transform.OptimizerIDs = append(transform.OptimizerIDs, appliedTransformIDs...)
	} else {
		transform.OptimizerIDs = append(transform.OptimizerIDs, compressionOptimizerID)
	}
	handleList := joinRecoveryHandles(handles)
	// A substitution-only turn rewrote bytes but earned no NEW reduction, so its
	// token fields stay at the honest zero rather than re-claiming an earlier turn's
	// delta. The handles are still disclosed — recovery must work on every turn.
	ratio := 0.0
	if before > after {
		ratio = float64(before-after) / float64(before)
	}
	return &compressionOutcome{handle: handleList, handles: handles, before: before, after: after, ratio: ratio}
}

// recoveryHandleListMax bounds the comma-joined handle list one telemetry row
// carries. The column is a debug/audit breadcrumb only — recovery itself runs off
// the `<<ccr:…>>` markers in the request body and the CCR store, never off this
// row — but every turn re-substitutes every earlier block, so an unbounded join
// puts one handle per conversation turn into EVERY row (a 40-turn session = 40
// handles a row). Duplicates collapse and the NEWEST handles are kept, because the
// block this turn actually compressed is the last one; a leading `+N` names how
// many older handles were elided, so the row is never a silent truncation.
const recoveryHandleListMax = 8

func joinRecoveryHandles(handles []string) string {
	seen := make(map[string]struct{}, len(handles))
	uniq := make([]string, 0, len(handles))
	for _, h := range handles {
		if _, dup := seen[h]; dup {
			continue
		}
		seen[h] = struct{}{}
		uniq = append(uniq, h)
	}
	if len(uniq) <= recoveryHandleListMax {
		return strings.Join(uniq, ",")
	}
	elided := len(uniq) - recoveryHandleListMax
	return "+" + strconv.Itoa(elided) + "," + strings.Join(uniq[len(uniq)-recoveryHandleListMax:], ",")
}

func appendCCRMarker(out []byte, handle string) []byte {
	marker := []byte("<<ccr:" + handle + ">>")
	withMarker := make([]byte, 0, len(out)+1+len(marker))
	withMarker = append(withMarker, out...)
	if len(out) == 0 || out[len(out)-1] != '\n' {
		withMarker = append(withMarker, '\n')
	}
	withMarker = append(withMarker, marker...)
	return withMarker
}

func (s *Server) matchAdapter(r *http.Request) providers.Adapter {
	if r == nil || r.URL == nil || openaicompat.ValidateRequestPath(r.URL) != nil {
		return nil
	}
	for _, adapter := range s.adapters {
		if adapter.MatchRoute(r.Method, r.URL.Path) {
			return adapter
		}
	}
	return nil
}

// record prices the request from the catalog and writes one truthful row to the
// sink. Standalone savings are always labeled "inferred".
func (s *Server) record(start time.Time, ttfb int64, requestID, traceID string, rc RequestContext, meta providers.RequestMetadata, authMode AuthMode, status int, responseBytes int64, requestBytes int, rawHash, transformedHash [32]byte, errorCode string, optimizers []string, usage providers.UsageObservation, comp *compressionOutcome, toolSchemaHandle string, retrieved bool, estimate *estimateOutcome, evidence requestEvidence, providerCachePrefixSHA256, providerCacheComponentSHA256 string, cacheBoundaryKnown, cacheBust, compressionEligible bool) {
	price := standalonePriceForUsage(meta, usage)
	if !providers.ListPriceEligible(meta.Provider, string(authMode)) || !usage.Complete() {
		price = cost.Price{}
	}
	inputCost, outputCost, cachedCost := costBreakdown(meta.Provider, price, usage)
	total := cost.RoundUSD(inputCost + outputCost + cachedCost)
	savings := 0.0
	if authMode == AuthModePAYG && status < 400 && usage.Complete() {
		savings = cacheSavingsUSD(price, usage, optimizers)
	}
	if len(usage.CallObservations) > 0 {
		var multiInput, multiOutput, multiCached, multiSavings float64
		complete := providers.ListPriceEligible(meta.Provider, string(authMode))
		for _, callUsage := range usage.CallObservations {
			callPrice := standalonePriceForUsage(meta, callUsage)
			if !callUsage.Complete() || callPrice == (cost.Price{}) {
				complete = false
				continue
			}
			oneInput, oneOutput, oneCached := costBreakdown(meta.Provider, callPrice, callUsage)
			multiInput += oneInput
			multiOutput += oneOutput
			multiCached += oneCached
			if authMode == AuthModePAYG && status < 400 {
				multiSavings += cacheSavingsUSD(callPrice, callUsage, optimizers)
			}
		}
		if complete {
			inputCost = cost.RoundUSD(multiInput)
			outputCost = cost.RoundUSD(multiOutput)
			cachedCost = cost.RoundUSD(multiCached)
			total = cost.RoundUSD(inputCost + outputCost + cachedCost)
			savings = cost.RoundUSD(multiSavings)
		} else {
			inputCost, outputCost, cachedCost, total, savings = 0, 0, 0, 0, 0
		}
		// No single request tier describes all calls. Keep local compression's
		// dollar counterfactual at honest zero rather than misapply a tier.
		price = cost.Price{}
	}
	// Compression savings are attributed only on a successful upstream response —
	// the compressed bytes must have actually been processed for the saving to be real.
	var compRatio, compHandle = 0.0, ""
	var compBefore, compAfter int
	if comp != nil {
		compRatio, compBefore, compAfter, compHandle = comp.ratio, comp.before, comp.after, comp.handle
		if authMode == AuthModePAYG && comp.bookSavings && status < 400 && !retrieved {
			savings = cost.RoundUSD(savings + compressionSavingsUSD(price, comp.before, comp.after, optimizers, usage))
		}
	}
	// The tool-schema strip has its own CCR original. A strip-only request has no
	// compressionOutcome at all, so without this the row would name an optimizer
	// whose rewritten bytes it could not point anyone back from. It contributes a
	// handle and nothing else: the strip books no tokens and no dollars.
	if toolSchemaHandle != "" {
		handles := append([]string{}, comp.recoveryHandles()...)
		compHandle = joinRecoveryHandles(append(handles, toolSchemaHandle))
	}
	// Observe-only would-have-saved: the estimate is a pure measurement, never a
	// booked saving. would_save_tokens is the engine-counted reduction; would_save_usd
	// values it at the model's input rate ONLY when the row is list-price eligible
	// (price is empty otherwise), so an unpriced tier never fabricates a dollar figure.
	var wouldSaveTokens int
	var wouldSaveUSD *float64
	if estimate != nil && estimate.before > estimate.after {
		wouldSaveTokens = estimate.before - estimate.after
		if price != (cost.Price{}) {
			v := cost.RoundUSD(cost.EstimateUSD(
				cost.Price{InputPerMillion: price.InputPerMillion},
				cost.Usage{InputTokens: wouldSaveTokens},
			))
			wouldSaveUSD = &v
		}
	}
	cacheStatus := usage.CacheStatus
	if cacheStatus == "" {
		cacheStatus = "unknown"
	}
	s.sink.Record(RequestRecord{
		Timestamp:                    time.Now().UTC().Format("2006-01-02 15:04:05.000"),
		RequestID:                    requestID,
		TraceID:                      traceID,
		Label:                        labelOrDefault(rc.Label, "local"),
		SessionID:                    evidence.SessionID,
		SessionCorrelationBasis:      evidence.SessionCorrelationBasis,
		AgentBuildSHA256:             evidence.AgentBuildSHA256,
		EfficiencyPlanSHA256:         evidence.EfficiencyPlanSHA256,
		ContextBill:                  evidence.ContextBill,
		TransformTrace:               evidence.TransformTrace,
		TransformLocation:            evidence.TransformLocation,
		CacheEpoch:                   evidence.CacheEpoch,
		CachePrefixSHA256:            evidence.CachePrefixSHA256,
		ProviderCachePrefixSHA256:    providerCachePrefixSHA256,
		ProviderCacheComponentSHA256: providerCacheComponentSHA256,
		CacheBoundaryKnown:           cacheBoundaryKnown,
		CacheBust:                    cacheBust,
		CompressionEligible:          compressionEligible,
		AgentSlug:                    labelOrDefault(rc.AgentSlug, "unlabeled-agent"),
		Provider:                     meta.Provider,
		Model:                        meta.Model,
		RouteFrom:                    meta.Model,
		RouteTo:                      meta.Model,
		Endpoint:                     meta.Endpoint,
		Stream:                       meta.Stream,
		StatusCode:                   status,
		ErrorCode:                    errorCode,
		LatencyMS:                    time.Since(start).Milliseconds(),
		TTFBMS:                       ttfb,
		RequestBytes:                 requestBytes,
		ResponseBytes:                responseBytes,
		InputTokens:                  usage.InputTokens,
		OutputTokens:                 usage.OutputTokens,
		CachedInputTokens:            usage.CachedInputTokens,
		CacheCreationInputTokens:     usage.CacheCreationInputTokens,
		ReasoningTokens:              usage.ReasoningTokens,
		TotalCostUSD:                 total,
		SavingsUSD:                   savings,
		Basis:                        "inferred",
		TokenUsageBasis:              standaloneUsageBasis(usage),
		AuthMode:                     string(authMode),
		RuntimeMode:                  rc.RuntimeMode,
		OptimizationIDs:              optimizers,
		CacheStatus:                  cacheStatus,
		RawRequestSHA256:             hex.EncodeToString(rawHash[:]),
		TransformedRequestSHA256:     hex.EncodeToString(transformedHash[:]),
		RequestHashComplete:          true,
		CompressionRatio:             compRatio,
		CompressionTokensBefore:      compBefore,
		CompressionTokensAfter:       compAfter,
		CompressionTokenCountBasis:   standaloneCompressionBasis(comp),
		RecoveryHandle:               compHandle,
		WouldSaveTokens:              wouldSaveTokens,
		WouldSaveUSD:                 wouldSaveUSD,
	})
}

// costBreakdown prices normalized provider usage. Cache and reasoning fields are
// subsets of the inclusive input/output totals and are never added twice.
func costBreakdown(provider string, price cost.Price, usage providers.UsageObservation) (inputCost, outputCost, cachedCost float64) {
	if usage.Malformed || usage.InputTokens < 0 || usage.OutputTokens < 0 || usage.CachedInputTokens < 0 || usage.CacheCreationInputTokens < 0 || usage.CacheCreation1hTokens < 0 || usage.ReasoningTokens < 0 {
		return 0, 0, 0
	}
	price = cost.ForInputTokens(price, usage.InputTokens)
	billableInput := usage.InputTokens - usage.CachedInputTokens - usage.CacheCreationInputTokens
	if billableInput < 0 || usage.ReasoningTokens > usage.OutputTokens || usage.CacheCreation1hTokens > usage.CacheCreationInputTokens {
		return 0, 0, 0
	}
	cacheWrite5m := usage.CacheCreationInputTokens - usage.CacheCreation1hTokens
	inputCost = cost.EstimateUSD(cost.Price{InputPerMillion: price.InputPerMillion}, cost.Usage{InputTokens: billableInput})
	visibleOutput := usage.OutputTokens - usage.ReasoningTokens
	reasoningRate := price.ReasoningPerMillion
	if reasoningRate == 0 {
		reasoningRate = price.OutputPerMillion
	}
	outputCost = cost.EstimateUSD(
		cost.Price{OutputPerMillion: price.OutputPerMillion, ReasoningPerMillion: reasoningRate},
		cost.Usage{OutputTokens: visibleOutput, ReasoningTokens: usage.ReasoningTokens},
	)
	cachedCost = cost.EstimateUSD(
		cost.Price{CacheReadPerMillion: price.CacheReadPerMillion, CacheWritePerMillion: price.CacheWritePerMillion, CacheWrite1hPerMillion: price.CacheWrite1hPerMillion},
		cost.Usage{CachedInputTokens: usage.CachedInputTokens, CacheCreationTokens: cacheWrite5m, CacheCreation1hTokens: usage.CacheCreation1hTokens},
	)
	return inputCost, outputCost, cachedCost
}

func standalonePriceForUsage(meta providers.RequestMetadata, usage providers.UsageObservation) cost.Price {
	if meta.PricingUnsupportedReason != "" || usage.PricingUnsupportedReason != "" {
		return cost.Price{}
	}
	if meta.Provider == "gemini" && strings.ToLower(strings.TrimSpace(meta.BillingTier)) != "paid" {
		return cost.Price{}
	}
	tier := strings.ToLower(strings.TrimSpace(usage.ServiceTier))
	if tier == "" {
		tier = strings.ToLower(strings.TrimSpace(meta.ServiceTier))
	}
	switch tier {
	case "", "default", "standard", "standard_only", "unspecified":
	default:
		return cost.Price{}
	}
	var price cost.Price
	switch meta.Provider {
	case "bedrock":
		price, _ = catalog.PriceForRegion(meta.Provider, meta.Model, meta.Region)
	case "vertex":
		price, _ = catalog.PriceForRegionOrAgnostic(meta.Provider, meta.Model, meta.Region)
	default:
		price, _ = catalog.Price(meta.Provider, meta.Model)
	}
	if meta.Provider == "openai" && (meta.Region == "us" || meta.Region == "eu") {
		multiplier, ok := catalog.PricingMultiplier("openai", meta.Model, "global", "regional_processing_multiplier")
		if !ok {
			return cost.Price{}
		}
		price = scaleStandaloneTokenRates(price, multiplier)
	}
	geo := strings.ToLower(strings.TrimSpace(usage.InferenceGeo))
	if geo == "" {
		geo = strings.ToLower(strings.TrimSpace(meta.InferenceGeo))
	}
	if geo != "" && geo != "global" {
		if meta.Provider != "anthropic" || geo != "us" {
			return cost.Price{}
		}
		multiplier, ok := catalog.PricingMultiplier("anthropic", meta.Model, "global", "inference_geo_us_multiplier")
		if !ok {
			return cost.Price{}
		}
		price = scaleStandaloneTokenRates(price, multiplier)
	}
	return price
}

func scaleStandaloneTokenRates(price cost.Price, multiplier float64) cost.Price {
	price.InputPerMillion *= multiplier
	price.OutputPerMillion *= multiplier
	price.CacheReadPerMillion *= multiplier
	price.CacheWritePerMillion *= multiplier
	price.CacheWrite1hPerMillion *= multiplier
	price.ReasoningPerMillion *= multiplier
	return price
}

func standaloneUsageBasis(usage providers.UsageObservation) string {
	if usage.Malformed {
		return "provider_malformed"
	}
	if usage.InputTokensReported && usage.OutputTokensReported {
		return "provider_complete"
	}
	if usage.InputTokensReported || usage.OutputTokensReported {
		return "provider_partial"
	}
	return "unavailable"
}

func standaloneCompressionBasis(comp *compressionOutcome) string {
	if comp == nil {
		return ""
	}
	return "estimated_engine_o200k"
}

// cacheSavingsUSD is the baseline-vs-optimized delta for a request whose caching
// was caused by a Caveman cache optimizer. It is gated on a CACHE optimizer
// having been applied so cache hits the caller produced themselves are not
// attributed to us. In standalone the result is recorded as `inferred` — never
// `verified` — because there is no cloud eval gate behind it.
func cacheSavingsUSD(price cost.Price, usage providers.UsageObservation, optimizers []string) float64 {
	if !hasCacheOptimizer(optimizers) {
		return 0
	}
	if usage.CachedInputTokens == 0 && usage.CacheCreationInputTokens == 0 {
		return 0
	}
	price = cost.ForInputTokens(price, usage.InputTokens)
	if usage.CachedInputTokens < 0 || usage.CacheCreationInputTokens < 0 || usage.CacheCreation1hTokens < 0 || usage.CacheCreation1hTokens > usage.CacheCreationInputTokens || usage.CachedInputTokens+usage.CacheCreationInputTokens > usage.InputTokens {
		return 0
	}
	baselineCached := cost.EstimateUSD(
		cost.Price{InputPerMillion: price.InputPerMillion},
		cost.Usage{InputTokens: usage.CachedInputTokens + usage.CacheCreationInputTokens},
	)
	actualCached := cost.EstimateUSD(
		cost.Price{CacheReadPerMillion: price.CacheReadPerMillion, CacheWritePerMillion: price.CacheWritePerMillion, CacheWrite1hPerMillion: price.CacheWrite1hPerMillion},
		cost.Usage{CachedInputTokens: usage.CachedInputTokens, CacheCreationTokens: usage.CacheCreationInputTokens - usage.CacheCreation1hTokens, CacheCreation1hTokens: usage.CacheCreation1hTokens},
	)
	return cost.RoundUSD(baselineCached - actualCached)
}

// cacheOptimizerIDs is the set of optimizers that actually cause provider-native
// caching. Only these may attribute cache savings; behavioral/affinity hints must
// not. OpenAI prompt_cache_key is deliberately absent: OpenAI caching is already
// automatic and the affinity hint alone cannot prove an incremental cache hit.
// The historical gemini-explicit-cache scaffold is permanently absent: it never
// created a provider cache and is retired from policy and practice surfaces.
var cacheOptimizerIDs = map[string]bool{
	"anthropic-cache-breakpoints": true,
}

func hasCacheOptimizer(optimizers []string) bool {
	for _, oid := range optimizers {
		if cacheOptimizerIDs[oid] {
			return true
		}
	}
	return false
}

// compressionOptimizerID is the policy/telemetry id attributed when S4 content
// compression shrank a request. It is the gate for compression savings — a request
// the proxy did not compress can never carry it.
const compressionOptimizerID = "caveman-compression"

// compressionOptimizerIDs is the set of optimizer ids that may attribute
// compression savings. Mirrors cacheOptimizerIDs so the two savings paths share one
// discipline: a saving is only ever attributed to an optimizer we actually ran.
var compressionOptimizerIDs = map[string]bool{compressionOptimizerID: true}

func hasCompressionOptimizer(optimizers []string) bool {
	for _, oid := range optimizers {
		if compressionOptimizerIDs[oid] ||
			(strings.HasPrefix(oid, "caveman.engine.") && strings.HasSuffix(oid, ".v1")) {
			return true
		}
	}
	return false
}

// compressionSavingsUSD is the inferred dollar value of the input tokens that S4
// content compression removed before the request reached the provider. It is gated
// on the compression optimizer id so a request we did not compress can never
// attribute a saving, and it returns 0 unless the result was actually smaller. In
// standalone the figure is recorded as `inferred` — never `verified`; this mirrors
// the cloud gateway's verifiedCacheSavings gating discipline (the gate is the
// point, not the label).
//
// The removed tokens are valued at the model's FULL input rate only when the
// request was not predominantly served from cache. On cache-heavy traffic, valuing
// them at the full input rate overstates the saving ~10x — the tokens compression
// displaced would have been billed at the far cheaper cache-read rate. So, mirroring
// cacheSavingsUSD's honest counterfactual and the honesty-culture "under-claim,
// never blend" rule, when cache reads dominated the billed input the removed tokens
// are valued at the cache-read rate instead (issue #133).
func compressionSavingsUSD(price cost.Price, before, after int, optimizers []string, usage providers.UsageObservation) float64 {
	if !hasCompressionOptimizer(optimizers) {
		return 0
	}
	if before <= after {
		return 0
	}
	rate := price.InputPerMillion
	if usage.CachedInputTokens >= 0 && usage.CacheCreationInputTokens >= 0 {
		billableFresh := usage.InputTokens - usage.CachedInputTokens - usage.CacheCreationInputTokens
		if usage.CachedInputTokens > 0 && usage.CachedInputTokens >= billableFresh && price.CacheReadPerMillion > 0 {
			rate = price.CacheReadPerMillion
		}
	}
	return cost.RoundUSD(cost.EstimateUSD(
		cost.Price{InputPerMillion: rate},
		cost.Usage{InputTokens: before - after},
	))
}

func labelOrDefault(v, fallback string) string {
	if v == "" {
		return fallback
	}
	return v
}

type countingWriter struct {
	w           http.ResponseWriter
	n           int64
	firstByteAt time.Time
}

func (c *countingWriter) Write(p []byte) (int, error) {
	if c.firstByteAt.IsZero() && len(p) > 0 {
		c.firstByteAt = time.Now()
	}
	n, err := c.w.Write(p)
	c.n += int64(n)
	return n, err
}

func copyFlush(dst *countingWriter, src io.Reader) (int64, error) {
	buf := make([]byte, 32*1024)
	var written int64
	for {
		nr, er := src.Read(buf)
		if nr > 0 {
			nw, ew := dst.Write(buf[:nr])
			if f, ok := dst.w.(http.Flusher); ok {
				f.Flush()
			}
			written += int64(nw)
			if ew != nil {
				return written, ew
			}
			if nr != nw {
				return written, io.ErrShortWrite
			}
		}
		if er != nil {
			if er != io.EOF {
				return written, er
			}
			break
		}
	}
	return written, nil
}

func traceIDFrom(r *http.Request) string {
	if v := r.Header.Get("x-cave-trace-id"); len(v) == 32 {
		return v
	}
	if tp := r.Header.Get("traceparent"); len(tp) >= 55 {
		return tp[3:35]
	}
	return id.NewTraceID()
}

package gateway

import (
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers/anthropic"
)

// recoveredBlock is the payload an agent reads, has elided, and then asks back
// through its own caveman_retrieve MCP tool.
var recoveredBlock = strings.Repeat("bibliography entry that the agent must enumerate exhaustively ", 40)

func anthropicReadTurn(marked bool) string {
	cc := ""
	if marked {
		cc = `,"cache_control":{"type":"ephemeral"}`
	}
	return `{"role":"assistant","content":[{"type":"tool_use","id":"toolu_read","name":"Read","input":{"file_path":"./test.bib"}}]},` +
		`{"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_read","content":[{"type":"text","text":"` + recoveredBlock + `"` + cc + `}]}]}`
}

func anthropicRetrieveTurn() string {
	return `{"role":"assistant","content":[{"type":"tool_use","id":"toolu_ret","name":"mcp__caveman__caveman_retrieve","input":{"recovery_handle":"ccr_x"}}]},` +
		`{"role":"user","content":[{"type":"tool_result","tool_use_id":"toolu_ret","content":[{"type":"text","text":"` + recoveredBlock + `"}]}]}`
}

// TestRecoveryResultIsNeverRecompressed is the citation-check regression.
//
// Measured on 2026-08-06: the agent read a file, saw it elided, called its own
// mcp__caveman__caveman_retrieve, and reported "Same truncation" — because the
// recovered bytes came back through the proxy as an ordinary live tool_result,
// hit the prefix cache under the SAME content key that produced the elision, and
// were substituted with the identical compressed replacement. Recovery was
// structurally impossible, so the agent re-read the file seven times.
//
// A retrieve result must reach the provider byte-for-byte.
func TestRecoveryResultIsNeverRecompressed(t *testing.T) {
	rt := &captureTransport{responses: []string{subMessageRespBody, subMessageRespBody}}
	comp := &liveZoneCompressor{outputs: [][]byte{[]byte("ELIDED"), []byte("ELIDED")}}
	srv := newSocketFreeCompressServerWithConfig(
		anthropic.New("https://upstream.test"),
		comp,
		rt,
		passthroughTestCreds{},
		Config{SubscriptionCompress: "live_zone", RecoveryViaMCP: true, PrefixCache: newTestPrefixCache()},
	)
	headers := map[string]string{
		"user-agent":        "claude-cli/2.1",
		"authorization":     "Bearer sk-ant-oat-test",
		"anthropic-beta":    "oauth-2025-04-20",
		"anthropic-version": "2023-06-01",
	}

	turn1 := `{"model":"claude-sonnet-4-6","messages":[` + anthropicReadTurn(true) + `]}`
	serveBody(t, srv, "/v1/messages", turn1, headers)
	if !strings.Contains(string(rt.bodies[0]), "ELIDED") {
		t.Fatalf("precondition: first read should have been compressed: %s", rt.bodies[0])
	}

	turn2 := `{"model":"claude-sonnet-4-6","messages":[` + anthropicReadTurn(true) + `,` + anthropicRetrieveTurn() + `]}`
	serveBody(t, srv, "/v1/messages", turn2, headers)

	upstream := string(rt.bodies[1])
	retrieveIdx := strings.Index(upstream, "toolu_ret")
	if retrieveIdx < 0 {
		t.Fatalf("retrieve turn missing upstream: %s", upstream)
	}
	tail := upstream[retrieveIdx:]
	if !strings.Contains(tail, recoveredBlock) {
		t.Fatalf("recovered bytes must reach the provider intact; the agent has no other way back.\nretrieve tail: %s", tail)
	}
}

package gateway

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/url"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/shared/platform/env"
	"github.com/JuliusBrussee/caveman/shared/platform/redact"
)

const retrieveToolName = "caveman_retrieve"
const maxRetrieves = 3
const defaultMaxRetrieveResponseBytes = 8 << 20

var retrieveToolSchema = json.RawMessage(`{"type":"object","properties":{"handle":{"type":"string","description":"recovery handle from a <<ccr:...>> marker in compressed content"},"query":{"type":"string","description":"optional: describe the detail you need; the proxy returns only the elided sections most relevant to it instead of the entire original block"}},"required":["handle"]}`)

type retrieveTool struct {
	Name        string          `json:"name"`
	Description string          `json:"description"`
	InputSchema json.RawMessage `json:"input_schema,omitempty"`
	Parameters  json.RawMessage `json:"parameters,omitempty"`
}

const retrieveToolDescription = "Recover original content for a compressed block. Use the handle shown in a <<ccr:...>> marker inside the content. Pass query only when a narrower recovery is enough."

// serverRetrieveSupported is the positive allowlist for wire grammars fully
// implemented by inject/parse/append/strip below. Unsupported routes must keep
// original bytes: sending compressed content with an unusable recovery tool is
// a correctness failure, not a graceful degradation.
func serverRetrieveSupported(provider, routePath string) bool {
	provider = strings.ToLower(strings.TrimSpace(provider))
	routePath = strings.ToLower(strings.TrimSpace(routePath))
	switch provider {
	case "openai", "azure_openai", "openai_compatible":
		return strings.HasSuffix(routePath, "/chat/completions") || strings.HasSuffix(routePath, "/responses")
	case "anthropic":
		return strings.HasSuffix(routePath, "/messages")
	case "gemini", "vertex":
		return strings.HasSuffix(routePath, ":generatecontent")
	default:
		return false
	}
}

func injectRetrieveTool(provider, routePath string, body []byte) ([]byte, bool) {
	if hasRetrieveTool(body) {
		return body, false
	}
	tool := retrieveTool{
		Name:        retrieveToolName,
		Description: retrieveToolDescription,
		InputSchema: retrieveToolSchema,
		Parameters:  retrieveToolSchema,
	}
	toolBytes, err := json.Marshal(providerToolSchema(provider, routePath, tool))
	if err != nil || !json.Valid(toolBytes) {
		return body, false
	}
	root, ok := gatewayRootObjectSpan(body)
	if !ok {
		return body, false
	}
	toolsSpan, hasTools := gatewayFindObjectField(body, root, "tools")
	if hasTools {
		if toolsSpan.start >= len(body) || body[toolsSpan.start] != '[' {
			return body, false
		}
		elements, ok := gatewayArrayElements(body, toolsSpan)
		if !ok {
			return body, false
		}
		insertAt := toolsSpan.end - 1
		prefix := []byte(nil)
		if len(elements) > 0 {
			prefix = []byte(",")
		}
		out := make([]byte, 0, len(body)+len(prefix)+len(toolBytes))
		out = append(out, body[:insertAt]...)
		out = append(out, prefix...)
		out = append(out, toolBytes...)
		out = append(out, body[insertAt:]...)
		return out, json.Valid(out)
	}

	insertAt := root.end - 1
	prefix := []byte(`,"tools":[`)
	if gatewayObjectEmpty(body, root) {
		prefix = []byte(`"tools":[`)
	}
	out := make([]byte, 0, len(body)+len(prefix)+len(toolBytes)+1)
	out = append(out, body[:insertAt]...)
	out = append(out, prefix...)
	out = append(out, toolBytes...)
	out = append(out, ']')
	out = append(out, body[insertAt:]...)
	if !json.Valid(out) {
		return body, false
	}
	return out, true
}

func hasRetrieveTool(body []byte) bool {
	var root map[string]any
	if json.Unmarshal(body, &root) != nil {
		return false
	}
	tools, _ := root["tools"].([]any)
	return toolNameInList(tools, retrieveToolName)
}

type gatewayJSONSpan struct {
	start int
	end   int
}

func gatewayRootObjectSpan(body []byte) (gatewayJSONSpan, bool) {
	start := gatewaySkipJSONSpace(body, 0)
	if start >= len(body) || body[start] != '{' {
		return gatewayJSONSpan{}, false
	}
	end, ok := gatewayScanJSONValue(body, start)
	if !ok {
		return gatewayJSONSpan{}, false
	}
	if gatewaySkipJSONSpace(body, end) != len(body) {
		return gatewayJSONSpan{}, false
	}
	return gatewayJSONSpan{start: start, end: end}, true
}

func gatewayObjectEmpty(body []byte, obj gatewayJSONSpan) bool {
	i := gatewaySkipJSONSpace(body, obj.start+1)
	return i < obj.end && body[i] == '}'
}

func gatewayFindObjectField(body []byte, obj gatewayJSONSpan, field string) (gatewayJSONSpan, bool) {
	if obj.start < 0 || obj.end > len(body) || obj.start >= obj.end || body[obj.start] != '{' {
		return gatewayJSONSpan{}, false
	}
	i := gatewaySkipJSONSpace(body, obj.start+1)
	for i < obj.end {
		if body[i] == '}' {
			return gatewayJSONSpan{}, false
		}
		if body[i] != '"' {
			return gatewayJSONSpan{}, false
		}
		keyStart := i
		keyEnd, ok := gatewayScanJSONString(body, keyStart)
		if !ok {
			return gatewayJSONSpan{}, false
		}
		var key string
		if json.Unmarshal(body[keyStart:keyEnd], &key) != nil {
			return gatewayJSONSpan{}, false
		}
		i = gatewaySkipJSONSpace(body, keyEnd)
		if i >= obj.end || body[i] != ':' {
			return gatewayJSONSpan{}, false
		}
		valueStart := gatewaySkipJSONSpace(body, i+1)
		valueEnd, ok := gatewayScanJSONValue(body, valueStart)
		if !ok {
			return gatewayJSONSpan{}, false
		}
		if key == field {
			return gatewayJSONSpan{start: valueStart, end: valueEnd}, true
		}
		i = gatewaySkipJSONSpace(body, valueEnd)
		if i < obj.end && body[i] == ',' {
			i = gatewaySkipJSONSpace(body, i+1)
			continue
		}
	}
	return gatewayJSONSpan{}, false
}

func gatewayArrayElements(body []byte, arr gatewayJSONSpan) ([]gatewayJSONSpan, bool) {
	if arr.start < 0 || arr.end > len(body) || arr.start >= arr.end || body[arr.start] != '[' {
		return nil, false
	}
	var out []gatewayJSONSpan
	i := gatewaySkipJSONSpace(body, arr.start+1)
	for i < arr.end {
		if body[i] == ']' {
			return out, true
		}
		valueEnd, ok := gatewayScanJSONValue(body, i)
		if !ok {
			return nil, false
		}
		out = append(out, gatewayJSONSpan{start: i, end: valueEnd})
		i = gatewaySkipJSONSpace(body, valueEnd)
		if i < arr.end && body[i] == ',' {
			i = gatewaySkipJSONSpace(body, i+1)
			continue
		}
	}
	return nil, false
}

func gatewayScanJSONValue(body []byte, start int) (int, bool) {
	i := gatewaySkipJSONSpace(body, start)
	if i >= len(body) {
		return 0, false
	}
	switch body[i] {
	case '"':
		return gatewayScanJSONString(body, i)
	case '{', '[':
		depth := 0
		for j := i; j < len(body); j++ {
			switch body[j] {
			case '"':
				end, ok := gatewayScanJSONString(body, j)
				if !ok {
					return 0, false
				}
				j = end - 1
			case '{', '[':
				depth++
			case '}', ']':
				depth--
				if depth == 0 {
					return j + 1, true
				}
				if depth < 0 {
					return 0, false
				}
			}
		}
		return 0, false
	default:
		j := i
		for j < len(body) {
			switch body[j] {
			case ',', '}', ']', ' ', '\n', '\r', '\t':
				if j == i {
					return 0, false
				}
				return j, true
			default:
				j++
			}
		}
		return j, j > i
	}
}

func gatewayScanJSONString(body []byte, start int) (int, bool) {
	if start >= len(body) || body[start] != '"' {
		return 0, false
	}
	for i := start + 1; i < len(body); i++ {
		switch body[i] {
		case '\\':
			i++
		case '"':
			return i + 1, true
		}
	}
	return 0, false
}

func gatewaySkipJSONSpace(body []byte, i int) int {
	for i < len(body) {
		switch body[i] {
		case ' ', '\n', '\r', '\t':
			i++
		default:
			return i
		}
	}
	return i
}

func providerToolSchema(provider, routePath string, tool retrieveTool) any {
	if providerUsesGeminiTools(provider, routePath) {
		return map[string]any{
			"functionDeclarations": []any{map[string]any{
				"name":        tool.Name,
				"description": tool.Description,
				"parameters":  tool.Parameters,
			}},
		}
	}
	if providerUsesResponsesTools(provider, routePath) {
		return map[string]any{
			"type":        "function",
			"name":        tool.Name,
			"description": tool.Description,
			"parameters":  tool.Parameters,
		}
	}
	if providerUsesOpenAITools(provider) {
		return map[string]any{
			"type": "function",
			"function": map[string]any{
				"name":        tool.Name,
				"description": tool.Description,
				"parameters":  tool.Parameters,
			},
		}
	}
	return map[string]any{
		"name":         tool.Name,
		"description":  tool.Description,
		"input_schema": tool.InputSchema,
	}
}

func providerUsesResponsesTools(provider, routePath string) bool {
	return providerUsesOpenAITools(provider) && strings.HasSuffix(strings.ToLower(strings.TrimSpace(routePath)), "/responses")
}

func providerUsesGeminiTools(provider, routePath string) bool {
	provider = strings.ToLower(strings.TrimSpace(provider))
	return (provider == "gemini" || provider == "vertex") && strings.HasSuffix(strings.ToLower(strings.TrimSpace(routePath)), ":generatecontent")
}

func providerUsesOpenAITools(provider string) bool {
	switch provider {
	case "openai", "azure_openai", "openai_compatible":
		return true
	default:
		return false
	}
}

func toolNameInList(tools []any, name string) bool {
	for _, t := range tools {
		tm, _ := t.(map[string]any)
		if tm == nil {
			continue
		}
		if n, _ := tm["name"].(string); n == name {
			return true
		}
		if fn, _ := tm["function"].(map[string]any); fn != nil {
			if n, _ := fn["name"].(string); n == name {
				return true
			}
		}
		declarations, _ := tm["functionDeclarations"].([]any)
		for _, declaration := range declarations {
			declarationMap, _ := declaration.(map[string]any)
			if n, _ := declarationMap["name"].(string); n == name {
				return true
			}
		}
	}
	return false
}

func parseRetrieveCall(provider, routePath string, respBody []byte) (callID, handle, query string, ok bool) {
	var root map[string]any
	if json.Unmarshal(respBody, &root) != nil {
		return "", "", "", false
	}
	if providerUsesGeminiTools(provider, routePath) {
		candidates, _ := root["candidates"].([]any)
		var functionCalls []map[string]any
		for _, candidate := range candidates {
			candidateMap, _ := candidate.(map[string]any)
			content, _ := candidateMap["content"].(map[string]any)
			parts, _ := content["parts"].([]any)
			for _, part := range parts {
				partMap, _ := part.(map[string]any)
				if call, _ := partMap["functionCall"].(map[string]any); call != nil {
					functionCalls = append(functionCalls, call)
				}
			}
		}
		if len(functionCalls) != 1 {
			return "", "", "", false
		}
		call := functionCalls[0]
		if name, _ := call["name"].(string); name != retrieveToolName {
			return "", "", "", false
		}
		id, _ := call["id"].(string)
		args, _ := call["args"].(map[string]any)
		handle, _ = args["handle"].(string)
		if handle == "" {
			handle, _ = args["recovery_handle"].(string)
		}
		query, _ = args["query"].(string)
		return id, handle, query, true
	}
	if providerUsesResponsesTools(provider, routePath) {
		output, _ := root["output"].([]any)
		var functionCalls []map[string]any
		for _, item := range output {
			itemMap, _ := item.(map[string]any)
			if typ, _ := itemMap["type"].(string); typ == "function_call" {
				functionCalls = append(functionCalls, itemMap)
			}
		}
		if len(functionCalls) != 1 {
			return "", "", "", false
		}
		call := functionCalls[0]
		if name, _ := call["name"].(string); name != retrieveToolName {
			return "", "", "", false
		}
		id, _ := call["call_id"].(string)
		argStr, _ := call["arguments"].(string)
		handle, query = retrieveArgs([]byte(argStr))
		return id, handle, query, id != ""
	}
	if providerUsesOpenAITools(provider) {
		choices, _ := root["choices"].([]any)
		if len(choices) == 0 {
			return "", "", "", false
		}
		first, _ := choices[0].(map[string]any)
		msg, _ := first["message"].(map[string]any)
		calls, _ := msg["tool_calls"].([]any)
		if len(calls) != 1 {
			return "", "", "", false
		}
		c, _ := calls[0].(map[string]any)
		fn, _ := c["function"].(map[string]any)
		if name, _ := fn["name"].(string); name != retrieveToolName {
			return "", "", "", false
		}
		id, _ := c["id"].(string)
		// OpenAI tool-call arguments arrive as a JSON-encoded string.
		argStr, _ := fn["arguments"].(string)
		handle, query = retrieveArgs([]byte(argStr))
		return id, handle, query, id != ""
	}
	content, _ := root["content"].([]any)
	var toolUses []map[string]any
	for _, blk := range content {
		bm, _ := blk.(map[string]any)
		if t, _ := bm["type"].(string); t == "tool_use" {
			toolUses = append(toolUses, bm)
		}
	}
	if len(toolUses) != 1 {
		return "", "", "", false
	}
	if name, _ := toolUses[0]["name"].(string); name != retrieveToolName {
		return "", "", "", false
	}
	id, _ := toolUses[0]["id"].(string)
	// Anthropic tool_use carries arguments as a parsed object under "input".
	if input, _ := toolUses[0]["input"].(map[string]any); input != nil {
		handle, _ = input["handle"].(string)
		if handle == "" {
			handle, _ = input["recovery_handle"].(string)
		}
		query, _ = input["query"].(string)
	}
	return id, handle, query, id != ""
}

// retrieveArgs pulls handle/query out of an OpenAI tool-call's JSON-string
// arguments. It is best-effort: missing fields yield empty strings.
func retrieveArgs(argBytes []byte) (handle, query string) {
	if len(argBytes) == 0 {
		return "", ""
	}
	var args map[string]any
	if json.Unmarshal(argBytes, &args) != nil {
		return "", ""
	}
	handle, _ = args["handle"].(string)
	if handle == "" {
		handle, _ = args["recovery_handle"].(string)
	}
	q, _ := args["query"].(string)
	return handle, q
}

func appendRetrieveResult(provider, routePath string, reqBody, respBody []byte, callID, recovered string) ([]byte, bool) {
	var req map[string]any
	if json.Unmarshal(reqBody, &req) != nil {
		return nil, false
	}
	var resp map[string]any
	if json.Unmarshal(respBody, &resp) != nil {
		return nil, false
	}
	if providerUsesGeminiTools(provider, routePath) {
		contents, _ := req["contents"].([]any)
		if contents == nil {
			return nil, false
		}
		candidates, _ := resp["candidates"].([]any)
		if len(candidates) == 0 {
			return nil, false
		}
		candidate, _ := candidates[0].(map[string]any)
		modelContent, _ := candidate["content"].(map[string]any)
		if modelContent == nil {
			return nil, false
		}
		contents = append(contents, modelContent)
		functionResponse := map[string]any{
			"name":     retrieveToolName,
			"response": map[string]any{"output": recovered},
		}
		if callID != "" {
			functionResponse["id"] = callID
		}
		contents = append(contents, map[string]any{
			"role":  "user",
			"parts": []any{map[string]any{"functionResponse": functionResponse}},
		})
		req["contents"] = contents
	} else if providerUsesResponsesTools(provider, routePath) {
		var input []any
		switch existing := req["input"].(type) {
		case []any:
			input = append(input, existing...)
		case string:
			input = append(input, map[string]any{"role": "user", "content": existing})
		default:
			return nil, false
		}
		output, _ := resp["output"].([]any)
		if len(output) == 0 {
			return nil, false
		}
		input = append(input, output...)
		input = append(input, map[string]any{
			"type":    "function_call_output",
			"call_id": callID,
			"output":  recovered,
		})
		req["input"] = input
	} else {
		msgs, _ := req["messages"].([]any)
		if msgs == nil {
			return nil, false
		}
		if providerUsesOpenAITools(provider) {
			choices, _ := resp["choices"].([]any)
			if len(choices) == 0 {
				return nil, false
			}
			first, _ := choices[0].(map[string]any)
			assistant := first["message"]
			if am, ok := assistant.(map[string]any); ok && am["content"] == nil {
				am["content"] = ""
			}
			msgs = append(msgs, assistant)
			msgs = append(msgs, map[string]any{"role": "tool", "tool_call_id": callID, "content": recovered})
		} else {
			msgs = append(msgs, map[string]any{"role": "assistant", "content": resp["content"]})
			msgs = append(msgs, map[string]any{"role": "user", "content": []any{
				map[string]any{"type": "tool_result", "tool_use_id": callID, "content": recovered},
			}})
		}
		req["messages"] = msgs
	}
	out, err := json.Marshal(req)
	if err != nil || !json.Valid(out) {
		return nil, false
	}
	return out, true
}

func addUsage(a, b providers.UsageObservation) providers.UsageObservation {
	aCount, bCount := a.ObservationCount, b.ObservationCount
	for _, pair := range []struct {
		dst *int
		add int
	}{
		{&a.InputTokens, b.InputTokens}, {&a.OutputTokens, b.OutputTokens},
		{&a.CachedInputTokens, b.CachedInputTokens}, {&a.CacheCreationInputTokens, b.CacheCreationInputTokens},
		{&a.CacheCreation5mTokens, b.CacheCreation5mTokens}, {&a.CacheCreation1hTokens, b.CacheCreation1hTokens},
		{&a.ReasoningTokens, b.ReasoningTokens},
	} {
		if sum, ok := checkedUsageAdd(*pair.dst, pair.add); ok {
			*pair.dst = sum
		} else {
			*pair.dst = 0
			a.Malformed = true
		}
	}
	if aCount == 0 {
		a.InputTokensReported = b.InputTokensReported
		a.OutputTokensReported = b.OutputTokensReported
	} else if bCount > 0 {
		a.InputTokensReported = a.InputTokensReported && b.InputTokensReported
		a.OutputTokensReported = a.OutputTokensReported && b.OutputTokensReported
	}
	if count, ok := checkedUsageAdd(aCount, bCount); ok {
		a.ObservationCount = count
	} else {
		a.ObservationCount = 0
		a.Malformed = true
	}
	a.Malformed = a.Malformed || b.Malformed
	a.CacheObserved = a.CacheObserved || b.CacheObserved
	a.CacheStatus = aggregateCacheStatus(a)
	if a.PricingUnsupportedReason == "" {
		a.PricingUnsupportedReason = b.PricingUnsupportedReason
	}
	mergeUsageQualifier(&a.ServiceTier, b.ServiceTier, "mixed_service_tier", &a.PricingUnsupportedReason)
	mergeUsageQualifier(&a.InferenceGeo, b.InferenceGeo, "mixed_inference_geo", &a.PricingUnsupportedReason)
	return a
}

func checkedUsageAdd(a, b int) (int, bool) {
	if a < 0 || b < 0 || a > int(^uint(0)>>1)-b {
		return 0, false
	}
	return a + b, true
}

func aggregateCacheStatus(usage providers.UsageObservation) string {
	if !usage.CacheObserved || usage.Malformed {
		return "unknown"
	}
	if usage.CachedInputTokens > 0 {
		return "hit"
	}
	if usage.CacheCreationInputTokens > 0 {
		return "write"
	}
	return "miss"
}

func mergeUsageQualifier(current *string, next, reason string, unsupported *string) {
	if *current == "" {
		*current = next
		return
	}
	if next != "" && next != *current && *unsupported == "" {
		*unsupported = reason
	}
}

func bufferedBody(resp *http.Response, body []byte) *http.Response {
	resp.Body = io.NopCloser(bytes.NewReader(body))
	return resp
}

func stripRetrieveCall(provider, routePath string, respBody []byte) ([]byte, bool) {
	var root map[string]any
	if json.Unmarshal(respBody, &root) != nil {
		return respBody, false
	}
	changed := false
	if providerUsesGeminiTools(provider, routePath) {
		candidates, _ := root["candidates"].([]any)
		for _, candidate := range candidates {
			candidateMap, _ := candidate.(map[string]any)
			content, _ := candidateMap["content"].(map[string]any)
			parts, _ := content["parts"].([]any)
			kept := make([]any, 0, len(parts))
			for _, part := range parts {
				partMap, _ := part.(map[string]any)
				call, _ := partMap["functionCall"].(map[string]any)
				if name, _ := call["name"].(string); name == retrieveToolName {
					changed = true
					continue
				}
				kept = append(kept, part)
			}
			if len(kept) != len(parts) {
				if len(kept) == 0 {
					kept = append(kept, map[string]any{"text": ""})
				}
				content["parts"] = kept
			}
		}
	} else if providerUsesResponsesTools(provider, routePath) {
		output, _ := root["output"].([]any)
		kept := make([]any, 0, len(output))
		for _, item := range output {
			itemMap, _ := item.(map[string]any)
			if typ, _ := itemMap["type"].(string); typ == "function_call" {
				if name, _ := itemMap["name"].(string); name == retrieveToolName {
					changed = true
					continue
				}
			}
			kept = append(kept, item)
		}
		if changed {
			root["output"] = kept
		}
	} else if providerUsesOpenAITools(provider) {
		choices, _ := root["choices"].([]any)
		for _, ch := range choices {
			chm, _ := ch.(map[string]any)
			msg, _ := chm["message"].(map[string]any)
			if msg == nil {
				continue
			}
			calls, _ := msg["tool_calls"].([]any)
			if len(calls) == 0 {
				continue
			}
			kept := make([]any, 0, len(calls))
			for _, c := range calls {
				cm, _ := c.(map[string]any)
				fn, _ := cm["function"].(map[string]any)
				if name, _ := fn["name"].(string); name == retrieveToolName {
					changed = true
					continue
				}
				kept = append(kept, c)
			}
			if len(kept) == len(calls) {
				continue
			}
			if len(kept) == 0 {
				delete(msg, "tool_calls")
				if msg["content"] == nil {
					msg["content"] = ""
				}
				if _, ok := chm["finish_reason"]; ok {
					chm["finish_reason"] = "stop"
				}
			} else {
				msg["tool_calls"] = kept
			}
		}
	} else {
		content, _ := root["content"].([]any)
		kept := make([]any, 0, len(content))
		for _, blk := range content {
			bm, _ := blk.(map[string]any)
			if t, _ := bm["type"].(string); t == "tool_use" {
				if name, _ := bm["name"].(string); name == retrieveToolName {
					changed = true
					continue
				}
			}
			kept = append(kept, blk)
		}
		if changed {
			root["content"] = kept
			if sr, _ := root["stop_reason"].(string); sr == "tool_use" {
				root["stop_reason"] = "end_turn"
			}
		}
	}
	if !changed {
		return respBody, false
	}
	out, err := json.Marshal(root)
	if err != nil || !json.Valid(out) {
		return respBody, false
	}
	return out, true
}

func (s *Server) forwardCleaned(provider, routePath string, cur *http.Response, respBody []byte, requestID string) *http.Response {
	if cleaned, ok := stripRetrieveCall(provider, routePath, respBody); ok {
		if s.logger != nil {
			s.logger.Warn("retrieve loop ended with unresolved caveman_retrieve call; stripped it from client response", "request_id", requestID)
		}
		cur.Header.Del("Content-Length")
		return bufferedBody(cur, cleaned)
	}
	return bufferedBody(cur, respBody)
}

func retrieveFailureResponse(kind, message string) *http.Response {
	body, _ := json.Marshal(map[string]any{
		"error": map[string]any{
			"type":    kind,
			"message": message,
		},
	})
	resp := &http.Response{
		StatusCode: http.StatusBadGateway,
		Status:     "502 Bad Gateway",
		Header:     make(http.Header),
		Body:       io.NopCloser(bytes.NewReader(body)),
	}
	resp.Header.Set("Content-Type", "application/json")
	return resp
}

func retrieveResponseTooLarge() *http.Response {
	return retrieveFailureResponse("cave_retrieve_response_too_large", "Upstream response exceeded the local retrieve limit.")
}

func retrieveResponseReadFailed() *http.Response {
	return retrieveFailureResponse("cave_retrieve_response_read_failed", "Upstream response could not be read during local retrieval.")
}

func maxRetrieveResponseBytes() int64 {
	return int64(env.Int("CAVE_MAX_RETRIEVE_RESPONSE_BYTES", defaultMaxRetrieveResponseBytes))
}

func readRetrieveResponseBody(resp *http.Response) ([]byte, bool, error) {
	maxBytes := maxRetrieveResponseBytes()
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBytes+1))
	if err != nil {
		return body, false, err
	}
	tooLarge := int64(len(body)) > maxBytes
	if tooLarge {
		// Inspection is bounded, but a large valid provider response must still
		// reach caller byte-for-byte. Prepend consumed prefix and retain original
		// closer; caller owns restored body from here.
		resp.Body = &prependReadCloser{
			Reader: io.MultiReader(bytes.NewReader(body), resp.Body),
			Closer: resp.Body,
		}
	}
	return body, tooLarge, nil
}

type prependReadCloser struct {
	io.Reader
	io.Closer
}

func allowedRetrieveHandles(handles []string) map[string]struct{} {
	allowed := make(map[string]struct{}, len(handles))
	for _, handle := range handles {
		if handle != "" {
			allowed[handle] = struct{}{}
		}
	}
	return allowed
}

func replayOriginalResponse(ctx context.Context, upstream *http.Client, reqURL *url.URL, headers http.Header, originalBody []byte, oversized *http.Response) (*http.Response, bool) {
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, reqURL.String(), bytes.NewReader(originalBody))
	if err != nil {
		_ = oversized.Body.Close()
		return retrieveResponseTooLarge(), false
	}
	req.Header = headers.Clone()
	req.Header.Del("Content-Length")
	resp, err := upstream.Do(req)
	if err != nil {
		_ = oversized.Body.Close()
		return retrieveResponseTooLarge(), false
	}
	_ = oversized.Body.Close()
	return resp, true
}

func (s *Server) runRetrieveLoop(ctx context.Context, upstream *http.Client, reqURL *url.URL, headers http.Header, reqBody, originalBody []byte, handles []string, resp *http.Response, adapter providers.Adapter, provider, routePath, requestID string) (*http.Response, []providers.UsageObservation, bool, bool) {
	var calls []providers.UsageObservation
	retrieved := false
	allowedHandles := allowedRetrieveHandles(handles)
	retriever, ok := s.compressor.(Retriever)
	if !ok {
		respBody, tooLarge, err := readRetrieveResponseBody(resp)
		if tooLarge {
			if s.logger != nil {
				s.logger.Warn("retrieve loop bypassed inspection for large upstream response", "request_id", requestID, "max_bytes", maxRetrieveResponseBytes())
			}
			replayed, ok := replayOriginalResponse(ctx, upstream, reqURL, headers, originalBody, resp)
			return replayed, calls, false, ok
		}
		_ = resp.Body.Close()
		if err != nil {
			return retrieveResponseReadFailed(), calls, retrieved, false
		}
		_, _, _, retrieved = parseRetrieveCall(provider, routePath, respBody)
		return s.forwardCleaned(provider, routePath, resp, respBody, requestID), calls, retrieved, false
	}
	cur := resp
	curReq := reqBody
	for i := 0; i < maxRetrieves; i++ {
		respBody, tooLarge, err := readRetrieveResponseBody(cur)
		if tooLarge {
			if s.logger != nil {
				s.logger.Warn("retrieve loop bypassed inspection for large upstream response", "request_id", requestID, "max_bytes", maxRetrieveResponseBytes())
			}
			replayed, ok := replayOriginalResponse(ctx, upstream, reqURL, headers, originalBody, cur)
			return replayed, calls, retrieved, ok
		}
		_ = cur.Body.Close()
		if err != nil {
			return retrieveResponseReadFailed(), calls, retrieved, false
		}
		callID, handle, query, ok := parseRetrieveCall(provider, routePath, respBody)
		if !ok {
			return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
		}
		retrieved = true
		if _, allowed := allowedHandles[handle]; !allowed {
			if s.logger != nil {
				s.logger.Warn("ccr retrieve handle was not created for current request; stripping call", "request_id", requestID)
			}
			return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
		}
		// Intercepted response is a real provider call. Capture its usage before
		// any recovery/build/continuation step can fail.
		sc := adapter.NewUsageScanner(cur.Header)
		_, _ = sc.Write(respBody)
		calls = append(calls, sc.Usage())
		recovered, err := retriever.RetrieveOriginal(handle, query)
		if err != nil {
			if s.logger != nil {
				s.logger.Warn("ccr retrieve failed; forwarding cleaned response", "error", redact.Error(err), "request_id", requestID)
			}
			return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
		}
		nextReqBody, ok := appendRetrieveResult(provider, routePath, curReq, respBody, callID, string(recovered))
		if !ok {
			return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
		}
		nextReq, err := http.NewRequestWithContext(ctx, http.MethodPost, reqURL.String(), bytes.NewReader(nextReqBody))
		if err != nil {
			return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
		}
		nextReq.Header = headers.Clone()
		nextResp, err := upstream.Do(nextReq)
		if err != nil {
			if s.logger != nil {
				s.logger.Warn("ccr retrieve continuation upstream failed", "error", redact.Error(err), "request_id", requestID)
			}
			return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
		}
		cur = nextResp
		curReq = nextReqBody
	}
	respBody, tooLarge, err := readRetrieveResponseBody(cur)
	if tooLarge {
		if s.logger != nil {
			s.logger.Warn("retrieve loop bypassed final inspection for large upstream response", "request_id", requestID, "max_bytes", maxRetrieveResponseBytes())
		}
		replayed, ok := replayOriginalResponse(ctx, upstream, reqURL, headers, originalBody, cur)
		return replayed, calls, retrieved, ok
	}
	_ = cur.Body.Close()
	if err != nil {
		return retrieveResponseReadFailed(), calls, retrieved, false
	}
	return s.forwardCleaned(provider, routePath, cur, respBody, requestID), calls, retrieved, false
}

package gateway

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"
)

func TestServerRetrieveSupportedOnlyForImplementedWireGrammars(t *testing.T) {
	tests := []struct {
		provider string
		path     string
		want     bool
	}{
		{"openai", "/openai/v1/chat/completions", true},
		{"openai", "/openai/v1/responses", true},
		{"openai_compatible", "/compat/groq/v1/chat/completions", true},
		{"anthropic", "/anthropic/v1/messages", true},
		{"gemini", "/gemini/v1beta/models/gemini-2.5-pro:generateContent", true},
		{"vertex", "/vertex/v1/projects/p/locations/global/publishers/google/models/gemini-2.5-pro:generateContent", true},
		{"bedrock", "/bedrock/model/anthropic.claude-sonnet-4-6/converse", false},
	}
	for _, tc := range tests {
		if got := serverRetrieveSupported(tc.provider, tc.path); got != tc.want {
			t.Errorf("serverRetrieveSupported(%q, %q)=%v, want %v", tc.provider, tc.path, got, tc.want)
		}
	}
}

func TestInjectRetrieveToolStaticOpenAIPreservesMessageBytes(t *testing.T) {
	body := []byte(`{"model":"gpt-5.5","messages":[{"role":"system","content":"sys"},{"role":"user","content":"hello"}]}`)
	out1, ok := injectRetrieveTool("openai", "/v1/chat/completions", body)
	if !ok {
		t.Fatal("injectRetrieveTool ok=false")
	}
	out2, ok := injectRetrieveTool("openai", "/v1/chat/completions", body)
	if !ok {
		t.Fatal("second injectRetrieveTool ok=false")
	}
	if !bytes.Equal(out1, out2) {
		t.Fatalf("static injection must be deterministic:\n%s\n%s", out1, out2)
	}
	if !bytes.Contains(out1, []byte(retrieveToolName)) || bytes.Contains(out1, []byte("ccr_abc")) {
		t.Fatalf("tool must be static and handle-free: %s", out1)
	}
	if !bytes.Contains(out1, []byte(`"messages":[{"role":"system","content":"sys"},{"role":"user","content":"hello"}]`)) {
		t.Fatalf("messages bytes were not preserved: %s", out1)
	}
}

func TestInjectRetrieveToolAppendsToExistingAnthropicTools(t *testing.T) {
	body := []byte(`{"model":"claude","tools":[{"name":"read","description":"existing","input_schema":{"type":"object"}}],"messages":[{"role":"user","content":"hi"}]}`)
	out, ok := injectRetrieveTool("anthropic", "/v1/messages", body)
	if !ok {
		t.Fatal("injectRetrieveTool ok=false")
	}
	if !bytes.Contains(out, []byte(`{"name":"read","description":"existing","input_schema":{"type":"object"}}`)) {
		t.Fatalf("existing tool bytes changed: %s", out)
	}
	if strings.Count(string(out), retrieveToolName) != 1 {
		t.Fatalf("retrieve tool count = %d, want 1: %s", strings.Count(string(out), retrieveToolName), out)
	}
	if _, ok := injectRetrieveTool("anthropic", "/v1/messages", out); ok {
		t.Fatal("second injection should refuse duplicate caveman_retrieve")
	}
}

func TestParseRetrieveCallReadsHandleAndQuery(t *testing.T) {
	openAI := []byte(`{"choices":[{"message":{"tool_calls":[{"id":"call_1","type":"function","function":{"name":"caveman_retrieve","arguments":"{\"handle\":\"ccr_block\",\"query\":\"postgres\"}"}}]}}]}`)
	id, handle, query, ok := parseRetrieveCall("openai", "/v1/chat/completions", openAI)
	if !ok || id != "call_1" || handle != "ccr_block" || query != "postgres" {
		t.Fatalf("openai parse = id=%q handle=%q query=%q ok=%v", id, handle, query, ok)
	}

	anthropic := []byte(`{"content":[{"type":"tool_use","id":"toolu_1","name":"caveman_retrieve","input":{"handle":"ccr_anthropic","query":"schema"}}]}`)
	id, handle, query, ok = parseRetrieveCall("anthropic", "/v1/messages", anthropic)
	if !ok || id != "toolu_1" || handle != "ccr_anthropic" || query != "schema" {
		t.Fatalf("anthropic parse = id=%q handle=%q query=%q ok=%v", id, handle, query, ok)
	}
}

func TestResponsesRetrieveWireRoundTrip(t *testing.T) {
	reqBody := []byte(`{"model":"gpt-5.5","input":[{"role":"user","content":[{"type":"input_text","text":"compressed <<ccr:ccr_responses>>"}]}]}`)
	injected, ok := injectRetrieveTool("openai", "/v1/responses", reqBody)
	if !ok {
		t.Fatal("injectRetrieveTool ok=false")
	}
	var injectedRoot map[string]any
	if err := json.Unmarshal(injected, &injectedRoot); err != nil {
		t.Fatal(err)
	}
	tools, _ := injectedRoot["tools"].([]any)
	if len(tools) != 1 {
		t.Fatalf("tools = %#v", tools)
	}
	tool, _ := tools[0].(map[string]any)
	if tool["type"] != "function" || tool["name"] != retrieveToolName || tool["function"] != nil {
		t.Fatalf("Responses tool must use flat wire shape: %#v", tool)
	}

	respBody := []byte(`{"id":"resp_1","status":"completed","output":[{"type":"reasoning","id":"rs_1","summary":[]},{"type":"function_call","id":"fc_1","call_id":"call_1","name":"caveman_retrieve","arguments":"{\"handle\":\"ccr_responses\",\"query\":\"schema\"}"}]}`)
	id, handle, query, ok := parseRetrieveCall("openai", "/v1/responses", respBody)
	if !ok || id != "call_1" || handle != "ccr_responses" || query != "schema" {
		t.Fatalf("parse = id=%q handle=%q query=%q ok=%v", id, handle, query, ok)
	}

	continued, ok := appendRetrieveResult("openai", "/v1/responses", injected, respBody, id, "original bytes")
	if !ok {
		t.Fatal("appendRetrieveResult ok=false")
	}
	var continuedRoot map[string]any
	if err := json.Unmarshal(continued, &continuedRoot); err != nil {
		t.Fatal(err)
	}
	input, _ := continuedRoot["input"].([]any)
	if len(input) != 4 {
		t.Fatalf("continued input = %#v", input)
	}
	result, _ := input[3].(map[string]any)
	if result["type"] != "function_call_output" || result["call_id"] != "call_1" || result["output"] != "original bytes" {
		t.Fatalf("function result = %#v", result)
	}

	cleaned, ok := stripRetrieveCall("openai", "/v1/responses", respBody)
	if !ok || strings.Contains(string(cleaned), retrieveToolName) || !strings.Contains(string(cleaned), `"type":"reasoning"`) {
		t.Fatalf("cleaned Responses body = %s, ok=%v", cleaned, ok)
	}
}

func TestGeminiRetrieveWireRoundTrip(t *testing.T) {
	const route = "/v1beta/models/gemini-2.5-flash:generateContent"
	reqBody := []byte(`{"contents":[{"role":"user","parts":[{"text":"compressed <<ccr:ccr_gemini>>"}]}]}`)
	injected, ok := injectRetrieveTool("gemini", route, reqBody)
	if !ok {
		t.Fatal("injectRetrieveTool ok=false")
	}
	var injectedRoot map[string]any
	if err := json.Unmarshal(injected, &injectedRoot); err != nil {
		t.Fatal(err)
	}
	tools, _ := injectedRoot["tools"].([]any)
	tool, _ := tools[0].(map[string]any)
	declarations, _ := tool["functionDeclarations"].([]any)
	declaration, _ := declarations[0].(map[string]any)
	if len(tools) != 1 || len(declarations) != 1 || declaration["name"] != retrieveToolName {
		t.Fatalf("Gemini tool wire shape = %#v", tools)
	}
	if _, ok := injectRetrieveTool("gemini", route, injected); ok {
		t.Fatal("second injection should reject duplicate nested declaration")
	}

	respBody := []byte(`{"candidates":[{"content":{"role":"model","parts":[{"thoughtSignature":"sig"},{"functionCall":{"id":"call_g","name":"caveman_retrieve","args":{"handle":"ccr_gemini","query":"schema"}}}]},"finishReason":"STOP"}]}`)
	id, handle, query, ok := parseRetrieveCall("gemini", route, respBody)
	if !ok || id != "call_g" || handle != "ccr_gemini" || query != "schema" {
		t.Fatalf("parse = id=%q handle=%q query=%q ok=%v", id, handle, query, ok)
	}

	continued, ok := appendRetrieveResult("gemini", route, injected, respBody, id, "original bytes")
	if !ok {
		t.Fatal("appendRetrieveResult ok=false")
	}
	var continuedRoot map[string]any
	if err := json.Unmarshal(continued, &continuedRoot); err != nil {
		t.Fatal(err)
	}
	contents, _ := continuedRoot["contents"].([]any)
	if len(contents) != 3 {
		t.Fatalf("continued contents = %#v", contents)
	}
	resultContent, _ := contents[2].(map[string]any)
	parts, _ := resultContent["parts"].([]any)
	part, _ := parts[0].(map[string]any)
	result, _ := part["functionResponse"].(map[string]any)
	if result["name"] != retrieveToolName || result["id"] != "call_g" {
		t.Fatalf("function response = %#v", result)
	}

	cleaned, ok := stripRetrieveCall("gemini", route, respBody)
	if !ok || strings.Contains(string(cleaned), retrieveToolName) || !strings.Contains(string(cleaned), `"thoughtSignature":"sig"`) {
		t.Fatalf("cleaned Gemini body = %s, ok=%v", cleaned, ok)
	}
}

func TestRetrieveToolSchemaValid(t *testing.T) {
	var schema map[string]any
	if err := json.Unmarshal(retrieveToolSchema, &schema); err != nil {
		t.Fatalf("schema invalid: %v", err)
	}
	if !strings.Contains(retrieveToolDescription, "<<ccr:") {
		t.Fatalf("description must direct model to in-block markers: %q", retrieveToolDescription)
	}
}

// Package gateway is the byte-safe request lifecycle of the public standalone
// proxy: match → authenticate → inspect → byte-safe transform → upstream →
// meter. It is the same shape as the managed gateway loop but with the
// multi-tenant control plane replaced by three injected seams, so the loop
// carries no cloud coupling:
//
//   - Authenticator    accepts a request and returns its RuntimeMode + optimizer policy
//   - CredentialResolver resolves the upstream provider key (BYOK env or passthrough)
//   - TelemetrySink     records one truthful per-request spend row
//
// record mode is always a pass-through; on any transform problem the original
// bytes are forwarded unchanged. Standalone never claims `verified` savings — the
// sink labels every row `inferred`.
package gateway

import (
	"context"
	"log/slog"
	"net/http"
	"os"
	"strings"
	"sync/atomic"
	"time"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/shared/platform/cacheguard"
	"github.com/JuliusBrussee/caveman/shared/platform/env"
	"github.com/JuliusBrussee/caveman/shared/platform/httpx"
)

// RequestContext is the per-request policy the lifecycle needs. It is the slim,
// single-operator analog of the managed control plane's ProjectContext.
type RequestContext struct {
	// Label tags telemetry rows (e.g. the agent/workflow name); "local" by default.
	Label string
	// AgentSlug attributes the row to the wrapped agent that produced it (from the
	// inbound x-cave-agent header; "unlabeled-agent" when absent). It mirrors the
	// managed gateway's field so the two proxies share one attribution axis. It is a
	// telemetry tag, not policy — the lifecycle sets it after Authenticate.
	AgentSlug string
	// RuntimeMode gates transforms. "record" is always a pass-through.
	RuntimeMode string
	// Optimizers gates which provider-native optimizers may run, keyed by id.
	Optimizers map[string]bool
	// EvalGates records which behavioral optimizers have cleared their eval gate.
	EvalGates map[string]bool
	// ProviderBillingTiers is trusted local config (not a request header). The
	// Gemini Developer API is list-priced only when explicitly set to "paid".
	ProviderBillingTiers map[string]string
}

// Authenticator accepts or rejects an inbound request and returns its context.
// Standalone returns a static single-operator context; a connected build would
// consult its key cache.
type Authenticator interface {
	Authenticate(ctx context.Context, r *http.Request) (RequestContext, error)
}

// CredentialResolver resolves the upstream provider credential for a request.
// Standalone resolves a BYOK env key by provider, falling back to the inbound
// auth header; the managed gateway reads its ephemeral upstream-key header.
type CredentialResolver interface {
	Resolve(provider string, r *http.Request) providers.Credential
}

// TelemetrySink records one truthful per-request spend row. Standalone writes to
// a local SQLite store; every row's Basis is "inferred".
type TelemetrySink interface {
	Record(RequestRecord)
}

// PayloadSink optionally records raw local trial payloads. It is deliberately
// separate from TelemetrySink so ordinary embedders do not see request bodies.
type PayloadSink interface {
	RecordPayload(label, requestID, traceID string, body []byte)
}

// Compressor is the optional S4 content-compression seam. CompressSegment runs the
// engine on one extracted live-zone content block (byte-safe: returns the original
// bytes with a zero delta on any problem); StoreOriginal records that exact
// original block for CCR recovery and returns its deterministic content-addressed
// handle. Pixel mode still uses StoreOriginal for its full-request recovery record.
// It is defined in primitive terms so the gateway core carries no engine import. A
// nil Compressor means compress mode falls back to a record-mode pass-through —
// embedders wire the real engine or a cloud-backed equivalent.
type Compressor interface {
	CompressSegment(segment []byte) (out []byte, tokensBefore, tokensAfter int)
	StoreOriginal(body []byte) (handle string, err error)
}

// TypedCompressor executes an immutable Cave Build's exact engine transform.
// Locked wrappers must not auto-detect a different compressor than evals approved.
type TypedCompressor interface {
	CompressSegmentType(segment []byte, contentType string) (out []byte, tokensBefore, tokensAfter int)
}

// QueryAwareCompressor is an optional Compressor capability. The gateway passes
// the latest human query from the provider request so structural compressors can
// retain query-relevant rows instead of selecting only by position/statistics.
// Tool results are never used as the query. Implementations remain pure and
// deterministic; empty query must match CompressSegment behavior.
type QueryAwareCompressor interface {
	CompressSegmentQuery(segment []byte, query string) (out []byte, tokensBefore, tokensAfter int)
}

// ToolSchemaStripper is the optional Compressor capability that removes the
// documentation-only JSON-Schema annotation keywords
// ($schema/title/examples/deprecated) from inside a serialized tool catalog's
// schemas. It is a pure byte transform: same input bytes always produce the same
// output bytes, and ok=false means the caller forwards the catalog unchanged. A
// Compressor that does not implement it leaves the tool-schema strip closed no
// matter what the operator configured.
type ToolSchemaStripper interface {
	StripToolSchema(tools []byte) (out []byte, ok bool)
}

// Estimator is the optional observe-only half of Compressor. It measures the
// token reduction a real CompressSegment would achieve WITHOUT storing any CCR
// recovery original (it runs the engine's network-free Simulate path). Record-mode
// observe-estimate uses it so the forwarded bytes stay byte-identical and no
// recovery row is ever written — the estimate is a pure measurement of what
// compression would have cut, recorded as `inferred` and never booked as a saving.
type Estimator interface {
	EstimateSegment(segment []byte) (tokensBefore, tokensAfter int)
}

// QueryAwareEstimator keeps observe-only estimates aligned with live compression.
// Without it, an Estimator retains historical query-agnostic behavior.
type QueryAwareEstimator interface {
	EstimateSegmentQuery(segment []byte, query string) (tokensBefore, tokensAfter int)
}

// Retriever is the optional recovery half of Compressor. Standalone uses it to
// resolve caveman_retrieve calls server-side after S4 compression. Embedders that
// cannot retrieve simply omit it; the proxy then does not advertise its internal
// retrieve tool to the model.
//
// query is the model's optional, plain-language description of the detail it
// needs. handle comes from a <<ccr:...>> marker inside compressed content. When
// query is empty, RetrieveOriginal returns the byte-exact original block. When set,
// the implementation may return only the elided sections most relevant to the
// query (a cheaper, targeted recovery) — but must fall back to the full original
// rather than ever lose detail it cannot rank.
type Retriever interface {
	RetrieveOriginal(handle, query string) ([]byte, error)
}

// PrefixCache is the durable original→replacement map that keeps the upstream
// cache prefix BYTE-STABLE across turns. Live-zone compression rewrites the newest
// message; on the next turn the agent re-sends that same message as its ORIGINAL
// bytes, now below the provider cache floor. Forwarding the original there would
// flip the prefix back to a form the provider never cached and miss the entry the
// previous turn paid to create — at ~60% compression the caller pays more than the
// row claims to have saved. Substituting the stored replacement byte-identically
// removes that divergence entirely.
//
// It is keyed by the content hash of the original block, so it is deterministic
// (same input → same output bytes) and survives process restarts. Every method
// fails OPEN: a miss, an unavailable store, or a write error means the original
// bytes are forwarded and no new replacement is created — the proxy never emits a
// rewrite it could not reproduce on the next turn.
type PrefixCache interface {
	// LookupReplacement returns the exact replacement bytes previously emitted for
	// these original bytes plus the CCR handle they disclose. An evicted or absent
	// entry is a plain miss: the caller forwards the original, which re-syncs the
	// prefix at a one-time cost and stays stable from then on.
	LookupReplacement(scope string, original []byte) (replacement []byte, handle string, ok bool)
	// RememberReplacement durably records original→replacement and returns the
	// AUTHORITATIVE bytes for that original — the caller must forward what comes
	// back, not what it passed in. Storage is first-write-wins so two requests that
	// compressed the same block can never put two different prefixes on the wire.
	RememberReplacement(scope string, original, replacement []byte, handle string) (stored []byte, err error)
}

// PrefixStabilizer is the optional adapter capability that exposes the frozen
// (already-cached) blocks alongside the live zone, so the proxy can substitute a
// replacement it previously emitted for them. Anthropic, OpenAI (and the
// Azure/OpenAI-compatible adapters that reuse its grammar) and Gemini implement it;
// bedrock and vertex do not extract compressible content at all, so they have
// nothing to stabilize and keep the byte-identical passthrough.
type PrefixStabilizer interface {
	ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool)
}

// PrefixEvidenceInspector returns ordered exact provider-wire JSON components
// that form frozen prefix. Gateway stores only component hashes and aggregate
// hash. Ordered component hashes prove append-only extension without content.
type PrefixEvidenceInspector interface {
	FrozenPrefixComponents(body []byte, meta providers.RequestMetadata) ([][]byte, bool)
}

// RequestRecord is one proxied call's truthful spend + byte-safety audit row.
type RequestRecord struct {
	Timestamp string
	RequestID string
	TraceID   string
	Label     string
	// Agent framework evidence is caller-supplied content-blind metadata. Gateway
	// validates shape and bounds before recording; local store validates again.
	// These fields join a provider request to one strict Cave Build but never make
	// standalone evidence verified.
	SessionID                    string
	SessionCorrelationBasis      string
	AgentBuildSHA256             string
	EfficiencyPlanSHA256         string
	ContextBill                  string
	TransformTrace               string
	TransformLocation            string
	CacheEpoch                   string
	CachePrefixSHA256            string
	ProviderCachePrefixSHA256    string
	ProviderCacheComponentSHA256 string
	CacheBoundaryKnown           bool
	// CacheBust is set by the observe-only prefix-monotonicity check when this
	// request's frozen prefix did not extend the previous request in the same
	// session (see prefix_monitor.go). It is a diagnostic flag only — it never
	// blocks or modifies traffic and never affects any savings figure.
	CacheBust bool
	// CompressionEligible marks that this request reached the compression path as a
	// candidate (compress mode, recovery-reachable, cache-epoch allowed) regardless
	// of whether any bytes were ultimately saved. It is the denominator behind the
	// requests_eligible_for_compression stats field.
	CompressionEligible bool
	// AgentSlug is the wrapped agent that produced the call (from x-cave-agent;
	// "unlabeled-agent" when absent) — the per-agent attribution dimension.
	AgentSlug                string
	Provider                 string
	Model                    string
	RouteFrom                string
	RouteTo                  string
	Endpoint                 string
	Stream                   bool
	StatusCode               int
	ErrorCode                string
	LatencyMS                int64
	TTFBMS                   int64
	RequestBytes             int
	ResponseBytes            int64
	InputTokens              int
	OutputTokens             int
	CachedInputTokens        int
	CacheCreationInputTokens int
	ReasoningTokens          int
	TotalCostUSD             float64
	SavingsUSD               float64
	// Basis is the savings provenance. Standalone is single-tenant and self-proving,
	// so it is always "inferred" — never "verified" (which the cloud's eval-gated
	// active-mode rollout alone may claim).
	Basis string
	// TokenUsageBasis is independent of savings provenance: provider_complete,
	// provider_partial, provider_malformed, or unavailable.
	TokenUsageBasis          string
	AuthMode                 string
	RuntimeMode              string
	OptimizationIDs          []string
	CacheStatus              string
	RawRequestSHA256         string
	TransformedRequestSHA256 string
	// RequestHashComplete is true only when both hashes cover the complete body
	// accepted by the upstream transport. Streaming transport failures can leave
	// only a prefix; those rows keep hashes empty and mark this false.
	RequestHashComplete bool
	// Compression fields are populated only when compress mode actually shrank the
	// request (zero/empty otherwise). RecoveryHandle contains the CCR block handle
	// list disclosed in in-block <<ccr:...>> markers; CompressionRatio is the
	// inferred live-zone token-reduction fraction (0..1).
	CompressionRatio           float64
	CompressionTokensBefore    int
	CompressionTokensAfter     int
	CompressionTokenCountBasis string
	RecoveryHandle             string
	// WouldSaveTokens is the observe-only estimate: the engine-counted tokens
	// (o200k) that compression WOULD have removed from this request in record mode.
	// It is populated only when observe-estimate is on; it is a measurement, never a
	// booked saving, and never affects SavingsUSD. WouldSaveUSD is the inferred
	// dollar value of those tokens at the model's input rate, non-nil only when the
	// row is list-price eligible (nil otherwise — never a guessed price).
	WouldSaveTokens int
	WouldSaveUSD    *float64
}

// Server is the standalone proxy lifecycle.
type Server struct {
	adapters   []providers.Adapter
	auth       Authenticator
	creds      CredentialResolver
	sink       TelemetrySink
	compressor Compressor
	// prefixCache keeps a compressed message byte-stable on every later turn (see
	// PrefixCache). A nil cache means the proxy cannot maintain a rewrite across
	// turns, which is what the non-PAYG live-zone paths fail closed on.
	prefixCache PrefixCache
	cacheGuard  *cacheguard.Guard
	// prefixMonitor runs the observe-only per-session prefix-monotonicity check
	// (see prefix_monitor.go). It flags cache_bust when a request's frozen prefix
	// does not extend the prior request in the same session.
	prefixMonitor *prefixMonitor
	// cacheEpochGate is the compression GATE for header-less wrap clients: a second,
	// independent prefix monitor keyed on the derived cache epoch. It cannot share
	// prefixMonitor's state (that one is consulted on every request; this one only
	// on compress candidates), and unlike cacheguard it tolerates append-only
	// frozen-prefix growth — see derivedEpochAllows.
	cacheEpochGate *prefixMonitor
	// recoveryViaMCP records that the wrapped agent fulfills caveman_retrieve itself
	// (via the caveman MCP server, sharing the CCR store) — set by `caveman wrap`
	// when it installed that tool. When true, compress mode reshapes streaming and
	// non-streaming requests alike, embeds the recovery handle as a content marker
	// instead of injecting (and never running) the server-side retrieve loop, and
	// claims no savings (retrieves happen off-proxy, so it cannot prove none did).
	recoveryViaMCP bool
	// observeEstimate runs record mode as an observe-only would-have-saved measurement:
	// each live-zone segment is compressed on a COPY to count the tokens compression
	// would remove, the forwarded request stays byte-identical, and no saving is booked.
	observeEstimate bool
	// chatGPTUpstream is the Codex subscription target (test-injectable;
	// DefaultChatGPTUpstream in production). Eligible /responses calls may take
	// live-zone compression before forwarding.
	chatGPTUpstream      string
	subscriptionCompress string
	// toolSchemaStrip selects the tool-schema annotation strip. Only "annotations"
	// enables it; every other value (including the empty default) is off.
	toolSchemaStrip string
	// breakpointPlan selects the cache-breakpoint planner. Only "frontier" enables
	// it; every other value (including the empty default) is off.
	breakpointPlan string
	// ledger is the per-session token account the harm tripwire reasons over, and
	// the freeze registry every lever consults through LeverAllowed. Sessions are
	// identified by the caller's x-cave-session value; a request without one gets
	// no entry and the whole mechanism is inert for it.
	ledger           *sessionLedger
	httpClient       *http.Client
	sessionMarkerKey []byte
	sessionFallback  func(time.Time, string, string) (string, string)
	logger           *slog.Logger
	inflight         atomic.Int64
	// capture is the local body-capture instrument (see capture.go). It is nil
	// unless CAVE_CAPTURE_DIR names a writable directory, and it never affects
	// what is sent, recorded, or claimed.
	capture *bodyCapture
}

// liveZoneCompressionAllowed reports whether subscription- or OAuth-classified
// traffic may take the SAME live-zone compression path PAYG traffic uses. Per
// ADR 0031 local compression is NOT account-gated: no login, no entitlement, and
// no seat is required, because compression is the free adoption surface. It is on
// by default and the operator turns it off with `subscription_compress: off`; any
// unrecognized value fails closed to off here as well as in the config loader.
//
// Three conditions fail closed, because each one is a way to hand the
// caller a request it cannot recover from or cannot keep paying for:
//
//   - the adapter must expose schema-aware frozen/live zones through
//     PrefixStabilizer. Anthropic uses explicit cache_control breakpoints; OpenAI
//     and Gemini expose only latest-user/latest-tool blocks as live and treat prior
//     matching blocks as substitute-only. Adapters without that contract remain
//     byte-identical passthrough.
//   - recovery must run through the agent's own caveman_retrieve MCP tool. These
//     paths are marker-only — the proxy never injects its server-side retrieve
//     tool into them — so without MCP recovery the elided detail is unreachable.
//   - the proxy must be able to keep the rewrite byte-stable on later turns
//     (prefixStabilized), or turn N+1 flips the prefix back and busts the cache
//     turn N created.
//
// This is a LOCAL-wrap-only capability. The managed gateway's lossless+stealth
// rule for non-PAYG traffic is unchanged. Subscription rows it produces are
// tokens-only: the row's dollar fields stay zero (see record()).
func (s *Server) liveZoneCompressionAllowed(adapter providers.Adapter) bool {
	switch s.subscriptionCompress {
	case "", "live_zone":
	default:
		return false
	}
	if adapter == nil {
		return false
	}
	if !s.recoveryViaMCP {
		return false
	}
	return s.prefixStabilized(adapter)
}

// prefixStabilized reports whether this server + adapter pair can keep a
// compressed message byte-stable on every later turn: the adapter must expose its
// frozen (already-cached) blocks and the server must hold a durable replacement
// cache to substitute them from. Without both, compressing the live zone would
// bust the provider cache on the very next turn, so the non-PAYG paths fail
// closed to passthrough rather than book a saving the caller never receives.
func (s *Server) prefixStabilized(adapter providers.Adapter) bool {
	if s.prefixCache == nil {
		return false
	}
	_, ok := adapter.(PrefixStabilizer)
	return ok
}

// Config injects the three seams plus the upstream HTTP client. A nil HTTPClient
// defaults to a plain client with the standard upstream timeout; the standalone
// binary passes an SSRF-guarded client (see StandaloneHTTPClient).
type Config struct {
	Adapters   []providers.Adapter
	Auth       Authenticator
	Creds      CredentialResolver
	Sink       TelemetrySink
	Compressor Compressor
	// PrefixCache is the durable original→replacement map that keeps a compressed
	// message byte-stable across turns (see PrefixCache). The standalone binary
	// passes its local SQLite store; a nil cache leaves the non-PAYG live-zone
	// paths closed.
	PrefixCache PrefixCache
	// RecoveryViaMCP routes S4 recovery through the agent's own caveman_retrieve MCP
	// tool instead of the proxy's server-side loop (see Server.recoveryViaMCP).
	RecoveryViaMCP bool
	// ObserveEstimate enables record-mode observe-only estimation (see
	// Server.observeEstimate). It requires a Compressor that implements Estimator;
	// without one the record path stays a plain byte-safe pass-through.
	ObserveEstimate bool
	// ChatGPTUpstream overrides the /chatgpt passthrough target (tests only);
	// empty means DefaultChatGPTUpstream.
	ChatGPTUpstream string
	// SubscriptionCompress is the operator off-switch for subscription live-zone
	// compression: empty/"live_zone" allow it, "off" (and any unknown value) fail
	// closed to S0 passthrough. It is the ONLY policy input — there is no account
	// gate (ADR 0031).
	SubscriptionCompress string
	// ToolSchemaStrip enables the tool-schema annotation strip when it is exactly
	// "annotations". It is default OFF and additionally requires the same
	// local-wrap conditions live-zone compression requires (see
	// toolSchemaStripAllowed).
	ToolSchemaStrip string
	// BreakpointPlan enables the cache-breakpoint planner when it is exactly
	// "frontier". It is default OFF (see breakpointPlanAllowed).
	BreakpointPlan string
	HTTPClient     *http.Client
	// SessionMarkerKey validates local native-hook correlation markers. Valid
	// markers are stripped before provider inspection and forwarding.
	SessionMarkerKey []byte
	// SessionFallback may return one conservative native-session candidate when
	// host removed signed marker. Returned basis must remain distinct from exact
	// marker correlation; ambiguous cases return empty.
	SessionFallback func(time.Time, string, string) (string, string)
	Logger          *slog.Logger
}

// New constructs a standalone proxy Server.
func New(cfg Config) *Server {
	client := cfg.HTTPClient
	if client == nil {
		timeout := time.Duration(env.Int("CAVE_GATEWAY_UPSTREAM_TIMEOUT_MS", 900000)) * time.Millisecond
		client = &http.Client{Timeout: timeout}
	}
	upstream := cfg.ChatGPTUpstream
	if upstream == "" {
		upstream = DefaultChatGPTUpstream
	}
	if cfg.ToolSchemaStrip == toolSchemaStripMode && cfg.Logger != nil {
		// One startup line, because this lever rewrites the head of the provider
		// cache prefix: the operator should be able to date the one-time cold write
		// to a config change rather than to the provider.
		cfg.Logger.Info("tool-schema annotation strip enabled",
			"mode", toolSchemaStripMode, "strip_version", toolSchemaStripVersion)
	}
	if cfg.BreakpointPlan == breakpointPlanModeFrontier && cfg.Logger != nil {
		// One startup line, for the same reason the strip has one: the planner moves
		// where the provider cache boundary sits, so the operator should be able to
		// date that change to a config change rather than to the provider.
		cfg.Logger.Info("cache-breakpoint planner enabled", "mode", breakpointPlanModeFrontier)
	}
	return &Server{
		adapters:             cfg.Adapters,
		auth:                 cfg.Auth,
		creds:                cfg.Creds,
		sink:                 cfg.Sink,
		compressor:           cfg.Compressor,
		prefixCache:          cfg.PrefixCache,
		cacheGuard:           cacheguard.New(),
		prefixMonitor:        newPrefixMonitor(),
		cacheEpochGate:       newPrefixMonitor(),
		recoveryViaMCP:       cfg.RecoveryViaMCP,
		observeEstimate:      cfg.ObserveEstimate,
		chatGPTUpstream:      strings.TrimSuffix(upstream, "/"),
		subscriptionCompress: cfg.SubscriptionCompress,
		toolSchemaStrip:      cfg.ToolSchemaStrip,
		breakpointPlan:       cfg.BreakpointPlan,
		ledger:               newSessionLedger(),
		httpClient:           client,
		sessionMarkerKey:     append([]byte(nil), cfg.SessionMarkerKey...),
		sessionFallback:      cfg.SessionFallback,
		logger:               cfg.Logger,
		capture:              newBodyCapture(os.Getenv("CAVE_CAPTURE_DIR"), cfg.Logger),
	}
}

// Handler returns the standalone HTTP handler: health, metrics, and the proxy
// catch-all. Unlike the managed gateway it serves no SDK/OTLP endpoints — the
// standalone proxy is a pure base-URL swap.
func (s *Server) Handler() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /health/live", s.health)
	mux.HandleFunc("GET /health/ready", s.health)
	mux.HandleFunc("GET /metrics", s.metrics)
	// ChatGPT-login Codex: OAuth-preserving forward with OpenAI Responses
	// live-zone compression and exact-original fallback.
	mux.HandleFunc("/chatgpt/", s.chatgpt)
	mux.HandleFunc("/", s.proxy)
	return mux
}

func (s *Server) health(w http.ResponseWriter, r *http.Request) {
	httpx.JSON(w, http.StatusOK, map[string]any{
		"ok":       true,
		"service":  "caveman-proxy",
		"schema":   "caveman.proxy.health.v1",
		"billing":  "byok",
		"adapters": len(s.adapters),
	})
}

func (s *Server) metrics(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("content-type", "text/plain; version=0.0.4")
	_, _ = w.Write([]byte("cave_proxy_inflight_requests "))
	_, _ = w.Write([]byte(itoa(s.inflight.Load())))
	_, _ = w.Write([]byte("\n"))
}

func itoa(n int64) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var buf [20]byte
	i := len(buf)
	for n > 0 {
		i--
		buf[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return string(buf[i:])
}

