package gateway

import (
	"bytes"
	"crypto/sha256"
	"net/http"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/anthropic"
	"github.com/JuliusBrussee/caveman/proxy/providers/gemini"
	"github.com/JuliusBrussee/caveman/proxy/providers/openai"
)

// Subscription live-zone compression: the local wrap MAY compress
// subscription/OAuth-authenticated coding-agent traffic with NO Caveman account
// (ADR 0031), but only through the SAME live-zone path PAYG uses, only when the
// three technical conditions hold, and only ever as a tokens-only measurement —
// a subscription row must never carry a dollar.

const subMessageRespBody = `{"id":"msg","type":"message","model":"claude-sonnet-4-6","content":[{"type":"text","text":"ok"}],"usage":{"input_tokens":1000,"output_tokens":10}}`

// subscriptionAgentHeaders is a Claude Code subscription session: a subscription
// user-agent plus an OAuth session token.
var subscriptionAgentHeaders = map[string]string{
	"user-agent":        "claude-cli/1.0.0",
	"authorization":     "Bearer sk-ant-oat-test",
	"anthropic-beta":    "oauth-2025-04-20",
	"anthropic-version": "2023-06-01",
}

func newSubscriptionCompressServer(comp Compressor, rt *captureTransport, cfg Config) (*Server, *captureSink) {
	sink := &captureSink{}
	// Production always has the durable replacement cache (the local SQLite spend
	// store); tests that pin its ABSENCE set their own.
	if cfg.PrefixCache == nil {
		cfg.PrefixCache = newTestPrefixCache()
	}
	cfg.Adapters = []providers.Adapter{anthropic.New("https://upstream.test")}
	cfg.Auth = stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "compress"}}
	cfg.Creds = passthroughTestCreds{}
	cfg.Sink = sink
	cfg.Compressor = comp
	cfg.HTTPClient = &http.Client{Transport: rt}
	return New(cfg), sink
}

func subBlock(text string) string {
	return `{"type":"text","text":"` + text + `"}`
}

func subCachedBlock(text string) string {
	return `{"type":"text","text":"` + text + `","cache_control":{"type":"ephemeral"}}`
}

// claudeCodeConversation is a multi-turn Claude Code shaped request: a stable
// system field, static tools, cache_control breakpoints planted mid-conversation,
// and a just-arrived trailing user turn. liveText is the only content the live
// zone may touch.
func claudeCodeConversation(liveText string) string {
	turn1 := strings.Repeat("turn one project context ", 30)
	turn2 := strings.Repeat("turn two file contents ", 30)
	return `{"model":"claude-sonnet-4-6","max_tokens":1024,` +
		`"system":[{"type":"text","text":"You are Claude Code.","cache_control":{"type":"ephemeral"}}],` +
		`"tools":[{"name":"Read","description":"Read a file","input_schema":{"type":"object"}}],` +
		`"messages":[` +
		`{"role":"user","content":[` + subCachedBlock(turn1) + `]},` +
		`{"role":"assistant","content":[` + subBlock("assistant one") + `]},` +
		`{"role":"user","content":[` + subCachedBlock(turn2) + `]},` +
		`{"role":"assistant","content":[` + subBlock("assistant two") + `]},` +
		`{"role":"user","content":[` + subBlock(liveText) + `]}` +
		`]}`
}

// TestSubscriptionLiveZoneNeedsNoAccount pins ADR 0031: local compression is NOT
// account-gated. A bare server with no entitlement signal of any kind compresses
// the live zone exactly like a signed-in one, because the only remaining policy
// input is the operator off-switch.
func TestSubscriptionLiveZoneNeedsNoAccount(t *testing.T) {
	live := strings.Repeat("newest live turn bytes ", 40)
	body := claudeCodeConversation(live)
	for _, cfg := range []Config{
		{RecoveryViaMCP: true}, // signed out, no config at all
		{SubscriptionCompress: "live_zone", RecoveryViaMCP: true}, // explicit operator opt-in
	} {
		rt := &captureTransport{responses: []string{subMessageRespBody}}
		comp := &liveZoneCompressor{}
		srv, sink := newSubscriptionCompressServer(comp, rt, cfg)

		serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

		upstream := string(rt.bodies[0])
		if strings.Contains(upstream, live) {
			t.Fatalf("cfg %+v: an account-less wrap must still compress the live zone: %s", cfg, upstream)
		}
		if !strings.Contains(upstream, "<<ccr:") {
			t.Fatalf("cfg %+v: compression must disclose an in-block CCR marker: %s", cfg, upstream)
		}
		if comp.calls == 0 {
			t.Fatalf("cfg %+v: compressor was never called", cfg)
		}
		if row := sink.last(t); row.CompressionTokensBefore <= 0 {
			t.Fatalf("cfg %+v: row must record the token reduction: %+v", cfg, row)
		}
	}
}

// TestSubscriptionLiveZoneUnknownOffSwitchFailsClosed keeps the operator opt-out
// fail-closed: an unrecognized subscription_compress value means passthrough, not
// "probably on".
func TestSubscriptionLiveZoneUnknownOffSwitchFailsClosed(t *testing.T) {
	body := claudeCodeConversation(strings.Repeat("newest live turn bytes ", 40))
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &liveZoneCompressor{}
	srv, sink := newSubscriptionCompressServer(comp, rt, Config{SubscriptionCompress: "not_a_mode", RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("an unknown off-switch value must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.calls != 0 || len(comp.stored) != 0 {
		t.Fatalf("an unknown off-switch value must not compress or store: compress=%d stored=%d", comp.calls, len(comp.stored))
	}
	if row := sink.last(t); row.CompressionTokensBefore != 0 || row.RecoveryHandle != "" {
		t.Fatalf("passthrough row must claim no compression: %+v", row)
	}
}

// TestSubscriptionWithoutMCPRecoveryPassesThrough pins recoverability.
// Subscription compression is marker-only — the proxy never injects its
// server-side retrieve tool into these requests — so without the agent's own
// caveman_retrieve MCP tool the elided detail would be unreachable by anyone. A
// wrap that could not install MCP recovery therefore compresses nothing.
func TestSubscriptionWithoutMCPRecoveryPassesThrough(t *testing.T) {
	body := claudeCodeConversation(strings.Repeat("newest live turn bytes ", 40))
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &liveZoneCompressor{}
	srv, sink := newSubscriptionCompressServer(comp, rt, Config{})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("no MCP recovery must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if strings.Contains(string(rt.bodies[0]), "<<ccr:") {
		t.Fatalf("an unrecoverable marker must never be emitted: %s", rt.bodies[0])
	}
	if comp.calls != 0 || len(comp.stored) != 0 {
		t.Fatalf("no MCP recovery must not compress or store: compress=%d stored=%d", comp.calls, len(comp.stored))
	}
	if row := sink.last(t); row.CompressionTokensBefore != 0 || row.RecoveryHandle != "" {
		t.Fatalf("row must claim no compression: %+v", row)
	}
}

// TestSubscriptionWithoutPrefixCachePassesThrough pins the maintainability
// half of the same rule: a rewrite the proxy cannot re-issue on the next turn would
// flip the upstream prefix back to the client's originals and bust the cache entry
// this turn just paid to create. With no durable replacement cache, nothing is
// compressed at all.
func TestSubscriptionWithoutPrefixCachePassesThrough(t *testing.T) {
	body := claudeCodeConversation(strings.Repeat("newest live turn bytes ", 40))
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &liveZoneCompressor{}
	sink := &captureSink{}
	srv := New(Config{
		Adapters:       []providers.Adapter{anthropic.New("https://upstream.test")},
		Auth:           stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "compress"}},
		Creds:          passthroughTestCreds{},
		Sink:           sink,
		Compressor:     comp,
		HTTPClient:     &http.Client{Transport: rt},
		RecoveryViaMCP: true,
	})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("no prefix cache must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.calls != 0 {
		t.Fatalf("no prefix cache must not compress (calls=%d)", comp.calls)
	}
}

// TestSubscriptionCompressesLiveZoneByDefault pins the product decision:
// subscription compression is on by default — no account and no extra config
// value required.
func TestSubscriptionCompressesLiveZoneByDefault(t *testing.T) {
	live := strings.Repeat("newest live turn bytes ", 40)
	body := claudeCodeConversation(live)
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &liveZoneCompressor{}
	srv, _ := newSubscriptionCompressServer(comp, rt, Config{RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	upstream := string(rt.bodies[0])
	if strings.Contains(upstream, live) {
		t.Fatalf("subscription live zone should have been compressed: %s", upstream)
	}
	if !strings.Contains(upstream, "<<ccr:") {
		t.Fatalf("subscription compression must disclose an in-block CCR marker: %s", upstream)
	}
	// Marker-only recovery: the proxy must never inject its server-side retrieve
	// tool into a subscription request (that would add a model-visible tool).
	if strings.Contains(upstream, retrieveToolName) {
		t.Fatalf("subscription must not inject the server-side retrieve tool: %s", upstream)
	}
}

// OAuth compression is an adapter capability, not an Anthropic special case.
// OpenAI Responses and Gemini both expose schema-aware frozen/live zones, so an
// local wrap with MCP recovery can compress their latest user/tool data
// while preserving every prior block byte-for-byte.
func TestOAuthLiveZoneCompressesAcrossPrefixStableAdapters(t *testing.T) {
	cases := []struct {
		name    string
		adapter providers.Adapter
		path    string
		body    string
		frozen  string
		live    string
	}{
		{
			name:    "openai responses",
			adapter: openai.New("https://upstream.test"),
			path:    "/v1/responses",
			frozen:  strings.Repeat("oauth codex frozen prior turn ", 30),
			live:    strings.Repeat("oauth codex live tool output ", 40),
		},
		{
			name:    "gemini generate content",
			adapter: gemini.New("https://upstream.test"),
			path:    "/v1beta/models/gemini-3-pro:generateContent",
			frozen:  strings.Repeat("oauth gemini frozen prior turn ", 30),
			live:    strings.Repeat("oauth gemini live tool output ", 40),
		},
	}
	for i := range cases {
		tc := &cases[i]
		if tc.name == "openai responses" {
			tc.body = `{"model":"gpt-5.5","input":[` +
				`{"type":"message","role":"user","content":[{"type":"input_text","text":"` + tc.frozen + `"}]},` +
				`{"type":"message","role":"assistant","content":[{"type":"output_text","text":"done"}]},` +
				`{"type":"message","role":"user","content":[{"type":"input_text","text":"` + tc.live + `"}]}]}`
		} else {
			tc.body = `{"contents":[` +
				`{"role":"user","parts":[{"text":"` + tc.frozen + `"}]},` +
				`{"role":"model","parts":[{"text":"done"}]},` +
				`{"role":"user","parts":[{"text":"` + tc.live + `"}]}]}`
		}
		t.Run(tc.name, func(t *testing.T) {
			rt := &captureTransport{}
			comp := &liveZoneCompressor{}
			srv := newSocketFreeCompressServerWithConfig(tc.adapter, comp, rt, passthroughTestCreds{}, Config{
				RecoveryViaMCP: true,
				PrefixCache:    newTestPrefixCache(),
			})

			headers := map[string]string{"authorization": "Bearer opaque-oauth-token"}
			if tc.name == "gemini generate content" {
				// Gemini user OAuth requires caller-owned quota attribution. Never
				// guess it in production or omit it from an OAuth conformance test.
				headers["x-goog-user-project"] = "caveman-test-project"
			}
			serveBody(t, srv, tc.path, tc.body, headers)

			if len(rt.bodies) != 1 {
				t.Fatalf("upstream calls = %d, want 1", len(rt.bodies))
			}
			upstream := string(rt.bodies[0])
			if strings.Contains(upstream, tc.live) || !strings.Contains(upstream, "<<ccr:") {
				t.Fatalf("OAuth live zone was not compressed: %s", upstream)
			}
			if !strings.Contains(upstream, tc.frozen) {
				t.Fatalf("OAuth frozen prefix changed on first sight: %s", upstream)
			}
			if got := rt.headers[0].Get("authorization"); got != "Bearer opaque-oauth-token" {
				t.Fatalf("OAuth authorization changed: %q", got)
			}
			if tc.name == "gemini generate content" && rt.headers[0].Get("x-goog-user-project") != "caveman-test-project" {
				t.Fatalf("Gemini OAuth quota project was not preserved: %q", rt.headers[0].Get("x-goog-user-project"))
			}
		})
	}
}

// TestSubscriptionOffSwitchPassesThrough pins the off-switch: the operator can
// still turn the capability off through the existing subscription_compress
// config key. It is the ONLY policy input left.
func TestSubscriptionOffSwitchPassesThrough(t *testing.T) {
	body := claudeCodeConversation(strings.Repeat("newest live turn bytes ", 40))
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &liveZoneCompressor{}
	srv, _ := newSubscriptionCompressServer(comp, rt, Config{RecoveryViaMCP: true, SubscriptionCompress: "off"})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("subscription_compress: off must be byte-identical passthrough:\n got %s", rt.bodies[0])
	}
	if comp.calls != 0 {
		t.Fatalf("subscription_compress: off must not compress (calls=%d)", comp.calls)
	}
}

// TestSubscriptionLiveZoneKeepsCacheBreakpointPrefixByteEqual is the cache-safety
// invariant: every byte at or before the last mid-conversation cache_control
// breakpoint — plus the system field and the tools array Claude Code caches
// against — is forwarded byte-identical. Only the just-arrived trailing turn,
// which no provider cache can hold yet, is reshaped.
func TestSubscriptionLiveZoneKeepsCacheBreakpointPrefixByteEqual(t *testing.T) {
	live := strings.Repeat("newest live turn bytes ", 40)
	body := claudeCodeConversation(live)
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	srv, _ := newSubscriptionCompressServer(&liveZoneCompressor{}, rt, Config{RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)
	upstream := string(rt.bodies[0])

	// Everything the client sent before the live content must be byte-equal, not
	// merely present: that span carries system, tools, both cache_control
	// breakpoints and every frozen turn.
	assertFrozenPrefixByteEqual(t, body, upstream, live)

	cut := strings.Index(body, live)
	prefix := body[:cut]
	if strings.Count(prefix, `"cache_control"`) != 3 {
		t.Fatalf("test fixture lost its breakpoints; prefix = %s", prefix)
	}
	if strings.Count(upstream, `"cache_control"`) != 3 {
		t.Fatalf("cache_control breakpoints must survive verbatim: %s", upstream)
	}
	if !strings.Contains(upstream, `"system":[{"type":"text","text":"You are Claude Code.","cache_control":{"type":"ephemeral"}}]`) {
		t.Fatalf("system field must not be touched: %s", upstream)
	}
	if !strings.Contains(upstream, `"tools":[{"name":"Read","description":"Read a file","input_schema":{"type":"object"}}]`) {
		t.Fatalf("tools must not be touched: %s", upstream)
	}
	if !strings.Contains(upstream, `{"role":"assistant","content":[{"type":"text","text":"assistant two"}]}`) {
		t.Fatalf("assistant turns must not be touched: %s", upstream)
	}
}

// TestSubscriptionLiveZoneClampCompressesNewestMarkedTurn documents the one case
// where the live zone reaches a message that itself carries cache_control: agents
// like Claude Code mark the just-arrived turn, and ComputeFrozenCount deliberately
// clamps the floor to len(messages)-1 so the live zone is not permanently empty.
// The clamped turn cannot be in any provider cache yet, so compressing it busts
// nothing at send time — but everything before it, including the previous
// breakpoint, still has to be byte-identical. This test pins that boundary.
func TestSubscriptionLiveZoneClampCompressesNewestMarkedTurn(t *testing.T) {
	live := strings.Repeat("newest marked turn bytes ", 40)
	prior := strings.Repeat("prior cached turn bytes ", 30)
	body := `{"model":"claude-sonnet-4-6","max_tokens":1024,` +
		`"system":[{"type":"text","text":"You are Claude Code.","cache_control":{"type":"ephemeral"}}],` +
		`"messages":[` +
		`{"role":"user","content":[` + subCachedBlock(prior) + `]},` +
		`{"role":"assistant","content":[` + subBlock("assistant one") + `]},` +
		`{"role":"user","content":[` + subCachedBlock(live) + `]}` +
		`]}`
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	srv, _ := newSubscriptionCompressServer(&liveZoneCompressor{}, rt, Config{RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)
	upstream := string(rt.bodies[0])

	assertFrozenPrefixByteEqual(t, body, upstream, live)
	if !strings.Contains(upstream, prior) {
		t.Fatalf("the previous breakpoint's turn must stay original: %s", upstream)
	}
	if strings.Contains(upstream, live) || !strings.Contains(upstream, "<<ccr:") {
		t.Fatalf("the clamped trailing turn should be compressed: %s", upstream)
	}
	// The breakpoint itself is a sibling key of "text"; only the string value is
	// spliced, so the marker survives and the request still declares the same
	// number of cache breakpoints it arrived with.
	if strings.Count(upstream, `"cache_control"`) != 3 {
		t.Fatalf("cache_control markers must survive the splice: %s", upstream)
	}
}

// TestSubscriptionLiveZoneDeterministicDoubleRun pins determinism: the same client
// bytes must always produce the same upstream bytes, so a replayed prefix never
// diverges from what the agent previously sent.
func TestSubscriptionLiveZoneDeterministicDoubleRun(t *testing.T) {
	body := claudeCodeConversation(strings.Repeat("newest live turn bytes ", 40))
	rt := &captureTransport{responses: []string{subMessageRespBody, subMessageRespBody}}
	srv, _ := newSubscriptionCompressServer(&liveZoneCompressor{}, rt, Config{RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)
	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if len(rt.bodies) != 2 {
		t.Fatalf("upstream calls = %d, want 2", len(rt.bodies))
	}
	if !bytes.Equal(rt.bodies[0], rt.bodies[1]) {
		t.Fatalf("subscription compression must be deterministic:\n%s\n%s", rt.bodies[0], rt.bodies[1])
	}
}

// TestSubscriptionLiveZoneUncompressibleBodyPassesThrough pins the fail-open rule:
// a request whose live zone cannot be extracted (here: no user message to work on)
// is forwarded byte-identical, even when entitled.
func TestSubscriptionLiveZoneUncompressibleBodyPassesThrough(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","max_tokens":1024,"messages":[{"role":"assistant","content":[` +
		subBlock(strings.Repeat("assistant only content ", 40)) + `]}]}`
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &liveZoneCompressor{}
	srv, _ := newSubscriptionCompressServer(comp, rt, Config{RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("unextractable body must pass through unchanged:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.calls != 0 {
		t.Fatalf("unextractable body must not reach the compressor (calls=%d)", comp.calls)
	}
}

// TestSubscriptionLiveZoneRecordsTokensNeverDollars is the no-fake-savings pin:
// a compressed subscription row carries the local o200k token estimate with its
// basis label and NOTHING in dollars — no spend, no savings, no would-have-saved
// figure. Subscription traffic has no list price, so a dollar here would be a lie.
func TestSubscriptionLiveZoneRecordsTokensNeverDollars(t *testing.T) {
	body := claudeCodeConversation(strings.Repeat("newest live turn bytes ", 40))
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	srv, sink := newSubscriptionCompressServer(&liveZoneCompressor{}, rt, Config{RecoveryViaMCP: true})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	row := sink.last(t)
	if row.AuthMode != "subscription" {
		t.Fatalf("auth_mode = %q, want subscription", row.AuthMode)
	}
	if row.CompressionTokensBefore <= 0 || row.CompressionTokensAfter >= row.CompressionTokensBefore {
		t.Fatalf("subscription row must record a token reduction: before=%d after=%d", row.CompressionTokensBefore, row.CompressionTokensAfter)
	}
	if row.CompressionTokenCountBasis != "estimated_engine_o200k" {
		t.Fatalf("compression_token_count_basis = %q, want estimated_engine_o200k", row.CompressionTokenCountBasis)
	}
	if row.RecoveryHandle == "" {
		t.Fatal("subscription row must disclose its CCR recovery handle")
	}
	if row.Basis != "inferred" {
		t.Fatalf("basis = %q, want inferred", row.Basis)
	}
	if row.TotalCostUSD != 0 {
		t.Fatalf("total_cost_usd = %v, want 0 — subscription traffic has no list price", row.TotalCostUSD)
	}
	if row.SavingsUSD != 0 {
		t.Fatalf("savings_usd = %v, want 0 — subscription savings are tokens-only", row.SavingsUSD)
	}
	if row.WouldSaveUSD != nil {
		t.Fatalf("would_save_usd = %v, want nil for subscription", *row.WouldSaveUSD)
	}
}

package gateway

import (
	"encoding/json"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/shared/platform/redact"
)

// toolSchemaStripOptimizerID labels the tool-schema annotation strip in
// x-cave-optimization and in the telemetry row's optimization list, so a request
// whose catalog was rewritten is never indistinguishable from one that was not.
const toolSchemaStripOptimizerID = "toolschema-annotation-strip"

// toolSchemaStripMode is the one value that enables the lever. It names what is
// removed — JSON-Schema annotation keywords — rather than claiming losslessness.
const toolSchemaStripMode = "annotations"

// toolSchemaStripVersion pins the strip's SEMANTICS into the prefix-cache scope
// key. Turning the lever on, off, or changing which keywords it removes moves the
// tool catalog, which is the head of the provider cache prefix; message
// replacements memoised against the old catalog would then be re-substituted
// under a prefix that no longer matches. Folding this into the scope makes such a
// change a deliberate, one-time epoch rollover instead of a silent partial cold
// write. Bump it whenever annotationDropKeys or the descent allowlist changes.
const toolSchemaStripVersion = "v1"

// toolSchemaStripAllowed reports whether the tool-schema annotation strip may run.
//
// The strip changes model-visible bytes, so ADR 0024 §2 lets it default on only
// under the local-wrap clause (recovery + CCR) — and it does not even do that: it
// is default OFF and an operator turns it on explicitly with
// `toolschema_strip: annotations` / CAVEMAN_TOOLSCHEMA_STRIP=annotations. On top
// of the flag it reuses liveZoneCompressionAllowed rather than restating its
// conditions, so it inherits the same three fail-closed local-wrap requirements —
// the operator off-switch, MCP recovery through the agent's own caveman_retrieve,
// and a durable prefix cache behind a schema-aware adapter. A Compressor that
// cannot strip, or cannot store the original for recovery, keeps the catalog
// unchanged.
//
// On top of all of that it consults the session ledger's freeze registry — it is
// the first lever to do so. A session whose measured cache-creation blew up after
// this strip ran loses the strip for the rest of that session, and falls open to
// forwarding the catalog unchanged.
func (s *Server) toolSchemaStripAllowed(adapter providers.Adapter, sessionID string) bool {
	if s.toolSchemaStrip != toolSchemaStripMode || s.compressor == nil {
		return false
	}
	if _, ok := s.compressor.(ToolSchemaStripper); !ok {
		return false
	}
	if !s.ledger.LeverAllowed(sessionID, leverToolSchemaStrip) {
		return false
	}
	return s.liveZoneCompressionAllowed(adapter)
}

// toolSchemaCacheScope returns the suffix the strip contributes to a prefix-cache
// scope key. It is empty when the lever is off, so every pre-existing scope key
// is byte-identical to what it was before this lever existed.
func (s *Server) toolSchemaCacheScope() string {
	if s.toolSchemaStrip != toolSchemaStripMode {
		return ""
	}
	return "|tss:" + toolSchemaStripVersion
}

// stripToolSchema removes the documentation-only JSON-Schema annotations from the
// request's tool catalog and returns the rewritten body plus the CCR handle of the
// exact original catalog bytes.
//
// The tool catalog is the very front of the provider cache prefix, which the
// general compress path deliberately never touches: no adapter exposes it through
// ExtractStabilizable, and compressRequest's `!block.live` guard exists to keep
// frozen bytes out of the rewrite loop. This is a separate path with a separate
// invariant. The strip is admissible in the frozen prefix ONLY because it is a
// deterministic pure function of the catalog bytes: identical tools produce
// identical stripped bytes on every turn, every session, and every restart, so the
// prefix the first request paid to cache is the exact prefix every later request
// re-sends. Nothing here may become input-dependent on turn number, time, or
// process state without breaking that.
//
// Every failure keeps the original catalog: a shape we cannot extract, a strip
// that removed nothing, an unstorable original, a failed splice, or output that is
// not valid JSON.
func (s *Server) stripToolSchema(body []byte, meta providers.RequestMetadata, requestID string) ([]byte, string, bool) {
	stripper, ok := s.compressor.(ToolSchemaStripper)
	if !ok {
		return nil, "", false
	}
	raw, reassemble, ok := providers.ExtractToolCatalog(body, meta)
	if !ok {
		return nil, "", false
	}
	stripped, ok := stripper.StripToolSchema(raw)
	if !ok || len(stripped) >= len(raw) {
		return nil, "", false
	}
	handle, err := s.compressor.StoreOriginal(raw)
	if err != nil || handle == "" {
		if s.logger != nil {
			s.logger.Warn("tool-schema recovery store failed; keeping the original catalog",
				"error", redact.Error(err), "request_id", requestID)
		}
		return nil, "", false
	}
	out, err := reassemble(stripped)
	if err != nil || len(out) == 0 || !json.Valid(out) {
		if s.logger != nil {
			s.logger.Warn("tool-schema splice failed; forwarding original bytes unchanged",
				"error", redact.Error(err), "request_id", requestID)
		}
		return nil, "", false
	}
	return out, handle, true
}

package gateway

import (
	"bytes"
	"crypto/sha256"
	"net/http"
	"strings"
	"sync"
	"testing"

	"github.com/JuliusBrussee/caveman/engine/compressors"
	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/anthropic"
)

// The tool-schema annotation strip removes documentation-only JSON-Schema
// annotation keywords from inside a tool catalog's schemas — the very front of
// the provider cache prefix. It changes model-visible bytes, so it is default
// OFF, opt-in per operator, gated on the same local-wrap conditions live-zone
// compression needs, and every rewritten catalog has its exact original in CCR
// first (ADR 0024 §2, local wrap: recovery + CCR).

// toolCatalog is a Claude-Code-shaped catalog: schema annotations worth removing,
// an MCP annotations block whose "title" is the tool's display NAME, a property
// legitimately named "title", descriptions that must survive, and a cache_control
// breakpoint riding the last tool.
const toolCatalog = `[` +
	`{"name":"Read","description":"Read a file from disk.","annotations":{"title":"Read a file","readOnlyHint":true},` +
	`"input_schema":{"$schema":"https://json-schema.org/draft/2020-12/schema","title":"Read args","examples":[{"path":"main.go"}],"type":"object",` +
	`"properties":{"title":{"type":"string","title":"Document title"},"path":{"type":"string","deprecated":false}},"required":["path"]}},` +
	`{"name":"Write","description":"Write a file to disk.",` +
	`"input_schema":{"type":"object","title":"Write args","properties":{"path":{"type":"string"}}},` +
	`"cache_control":{"type":"ephemeral"}}` +
	`]`

func toolCatalogRequest(live string) string {
	return `{"model":"claude-sonnet-4-6","max_tokens":1024,` +
		`"system":[{"type":"text","text":"You are Claude Code."}],` +
		`"tools":` + toolCatalog + `,` +
		`"messages":[{"role":"user","content":[{"type":"text","text":"` + live + `"}]}]}`
}

func strippedToolCatalog(t *testing.T) string {
	t.Helper()
	out, ok := compressors.StripToolSchemaAnnotations([]byte(toolCatalog))
	if !ok {
		t.Fatal("fixture catalog is not strippable")
	}
	return string(out)
}

// toolSchemaStripCompressor is a Compressor that never rewrites message content,
// so a test exercises the tool-schema path alone. It strips through the engine's
// canonical function — the same one the binary wires.
type toolSchemaStripCompressor struct {
	mu     sync.Mutex
	stored [][]byte
	strips int
}

func (c *toolSchemaStripCompressor) CompressSegment(seg []byte) ([]byte, int, int) {
	return seg, 0, 0
}

func (c *toolSchemaStripCompressor) StoreOriginal(body []byte) (string, error) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.stored = append(c.stored, append([]byte(nil), body...))
	return contentHandle(body), nil
}

func (c *toolSchemaStripCompressor) StripToolSchema(tools []byte) ([]byte, bool) {
	c.mu.Lock()
	c.strips++
	c.mu.Unlock()
	return compressors.StripToolSchemaAnnotations(tools)
}

// noStripCompressor implements Compressor but not ToolSchemaStripper.
type noStripCompressor struct{ stored int }

func (c *noStripCompressor) CompressSegment(seg []byte) ([]byte, int, int) { return seg, 0, 0 }

func (c *noStripCompressor) StoreOriginal(body []byte) (string, error) {
	c.stored++
	return contentHandle(body), nil
}

func newToolSchemaStripServer(t *testing.T, comp Compressor, rt *captureTransport, cfg Config) (*Server, *captureSink) {
	t.Helper()
	sink := &captureSink{}
	if cfg.PrefixCache == nil {
		cfg.PrefixCache = newTestPrefixCache()
	}
	if cfg.Auth == nil {
		cfg.Auth = stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "compress"}}
	}
	cfg.Adapters = []providers.Adapter{anthropic.New("https://upstream.test")}
	cfg.Creds = passthroughTestCreds{}
	cfg.Sink = sink
	cfg.Compressor = comp
	cfg.HTTPClient = &http.Client{Transport: rt}
	return New(cfg), sink
}

// TestToolSchemaStripIsOffByDefault is the default-off pin: a wrap with every
// technical condition satisfied and no strip configured forwards the catalog
// byte-identically and writes no recovery record.
func TestToolSchemaStripIsOffByDefault(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &toolSchemaStripCompressor{}
	srv, sink := newToolSchemaStripServer(t, comp, rt, Config{RecoveryViaMCP: true})

	rec := serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("default must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.strips != 0 || len(comp.stored) != 0 {
		t.Fatalf("default must not strip or store: strips=%d stored=%d", comp.strips, len(comp.stored))
	}
	if got := rec.Header().Get("x-caveman-toolschema-strip"); got != "" {
		t.Fatalf("default disclosed a strip: %q", got)
	}
	if row := sink.last(t); len(row.OptimizationIDs) != 0 {
		t.Fatalf("default row claimed an optimization: %+v", row.OptimizationIDs)
	}
}

// TestToolSchemaStripRemovesAnnotationsAndDisclosesRecovery pins the whole
// contract of an enabled strip: the four annotations leave, everything that
// selects a tool stays, cache_control survives byte-for-byte, the exact original
// catalog is in CCR before the rewritten bytes ship, and the response discloses
// both the strip and its recovery handle.
func TestToolSchemaStripRemovesAnnotationsAndDisclosesRecovery(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &toolSchemaStripCompressor{}
	srv, sink := newToolSchemaStripServer(t, comp, rt, Config{
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	rec := serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	upstream := string(rt.bodies[0])
	if !strings.Contains(upstream, `"tools":`+strippedToolCatalog(t)+`,`) {
		t.Fatalf("upstream catalog is not the canonical strip: %s", upstream)
	}
	for _, gone := range []string{
		`"$schema"`, `"examples"`, `"deprecated"`,
		`"title":"Read args"`, `"title":"Write args"`, `"title":"Document title"`,
	} {
		if strings.Contains(upstream, gone) {
			t.Fatalf("annotation %s survived: %s", gone, upstream)
		}
	}
	for _, kept := range []string{
		`"cache_control":{"type":"ephemeral"}`,
		`"description":"Read a file from disk."`,
		`"description":"Write a file to disk."`,
		// MCP's annotations.title is the tool's human-readable NAME — model-visible
		// and selection-relevant. The strip must never reach inside a non-schema
		// container to take it.
		`"annotations":{"title":"Read a file","readOnlyHint":true}`,
		`"properties":{"title":{"type":"string"},"path":{"type":"string"}}`,
		`"required":["path"]`,
	} {
		if !strings.Contains(upstream, kept) {
			t.Fatalf("selection-relevant bytes %s were lost: %s", kept, upstream)
		}
	}
	if strings.Index(upstream, `"name":"Read"`) > strings.Index(upstream, `"name":"Write"`) {
		t.Fatalf("tool order changed: %s", upstream)
	}
	if len(comp.stored) != 1 || string(comp.stored[0]) != toolCatalog {
		t.Fatalf("CCR must hold the exact original catalog, got %d records: %s", len(comp.stored), comp.stored)
	}
	if rec.Header().Get("x-caveman-toolschema-strip") != toolSchemaStripMode ||
		rec.Header().Get("x-caveman-toolschema-recovery-handle") != contentHandle([]byte(toolCatalog)) {
		t.Fatalf("strip disclosure missing: %v", rec.Header())
	}
	if !strings.Contains(rec.Header().Get("x-cave-optimization"), toolSchemaStripOptimizerID) {
		t.Fatalf("optimization header = %q", rec.Header().Get("x-cave-optimization"))
	}
	row := sink.last(t)
	if strings.Join(row.OptimizationIDs, ",") != toolSchemaStripOptimizerID {
		t.Fatalf("row optimizations = %v", row.OptimizationIDs)
	}
	// A row that names an optimizer must also name where the original bytes live,
	// or the audit trail claims a rewrite nobody can undo.
	if row.RecoveryHandle != contentHandle([]byte(toolCatalog)) {
		t.Fatalf("row recovery handle = %q, want the stored catalog handle", row.RecoveryHandle)
	}
	if row.CompressionTokensBefore != 0 || row.CompressionRatio != 0 || row.SavingsUSD != 0 {
		t.Fatalf("the strip must claim no token or dollar saving: %+v", row)
	}
}

// TestToolSchemaStripIsCacheStable is the reason a frozen-prefix rewrite is
// admissible at all: two consecutive requests carrying the same catalog must
// produce byte-identical upstream bodies, so the second turn hits the prefix the
// first turn paid to cache.
func TestToolSchemaStripIsCacheStable(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	rt := &captureTransport{responses: []string{subMessageRespBody, subMessageRespBody}}
	comp := &toolSchemaStripCompressor{}
	srv, _ := newToolSchemaStripServer(t, comp, rt, Config{
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)
	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if len(rt.bodies) != 2 {
		t.Fatalf("want 2 upstream requests, got %d", len(rt.bodies))
	}
	if !bytes.Equal(rt.bodies[0], rt.bodies[1]) {
		t.Fatalf("turn 2 diverged from turn 1:\n%s\n%s", rt.bodies[0], rt.bodies[1])
	}
	if bytes.Equal(rt.bodies[0], []byte(body)) {
		t.Fatal("neither turn was stripped, so stability proves nothing")
	}
	// A different live turn must leave the catalog span identical too — the prefix
	// is what the provider cached, and it may not move when the tail grows.
	stripped := strippedToolCatalog(t)
	serveBody(t, srv, "/v1/messages", toolCatalogRequest("a later, longer turn"), subscriptionAgentHeaders)
	if !strings.Contains(string(rt.bodies[2]), `"tools":`+stripped+`,`) {
		t.Fatalf("catalog moved when the conversation grew: %s", rt.bodies[2])
	}
}

// TestToolSchemaStripRecordModeIsPassThrough keeps record mode what it has always
// been: a byte-safe pass-through, whatever the operator configured.
func TestToolSchemaStripRecordModeIsPassThrough(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &toolSchemaStripCompressor{}
	srv, sink := newToolSchemaStripServer(t, comp, rt, Config{
		Auth:            stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "record"}},
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	rec := serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("record mode transformed the request:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.strips != 0 || len(comp.stored) != 0 {
		t.Fatalf("record mode stripped or stored: strips=%d stored=%d", comp.strips, len(comp.stored))
	}
	if rec.Header().Get("x-caveman-toolschema-strip") != "" {
		t.Fatal("record mode disclosed a strip")
	}
	if row := sink.last(t); row.RawRequestSHA256 != row.TransformedRequestSHA256 {
		t.Fatalf("record row is not byte-identical: %+v", row)
	}
}

// TestToolSchemaStripFailsClosed covers every way the lever must decline: an
// unrecognized flag value, the explicit request-wide opt-out, a missing recovery
// path, a compressor that cannot strip, and a catalog we cannot extract.
func TestToolSchemaStripFailsClosed(t *testing.T) {
	tests := []struct {
		name    string
		cfg     Config
		body    string
		headers map[string]string
	}{
		{
			name: "unrecognized flag value",
			cfg:  Config{RecoveryViaMCP: true, ToolSchemaStrip: "aggressive"},
		},
		{
			name: "no MCP recovery",
			cfg:  Config{ToolSchemaStrip: toolSchemaStripMode},
		},
		{
			name: "operator off-switch",
			cfg:  Config{RecoveryViaMCP: true, ToolSchemaStrip: toolSchemaStripMode, SubscriptionCompress: "off"},
		},
		{
			name:    "request-wide pass-through opt-out",
			cfg:     Config{RecoveryViaMCP: true, ToolSchemaStrip: toolSchemaStripMode},
			headers: map[string]string{"x-cave-transforms": "caveman.pass-through.v1"},
		},
		{
			name: "tools field is not an array",
			cfg:  Config{RecoveryViaMCP: true, ToolSchemaStrip: toolSchemaStripMode},
			body: `{"model":"claude-sonnet-4-6","max_tokens":1,"tools":{"name":"Read","title":"Read"},"messages":[{"role":"user","content":"hi"}]}`,
		},
		{
			name: "no tools field at all",
			cfg:  Config{RecoveryViaMCP: true, ToolSchemaStrip: toolSchemaStripMode},
			body: `{"model":"claude-sonnet-4-6","max_tokens":1,"messages":[{"role":"user","content":"hi"}]}`,
		},
		{
			name: "catalog has nothing to strip",
			cfg:  Config{RecoveryViaMCP: true, ToolSchemaStrip: toolSchemaStripMode},
			body: `{"model":"claude-sonnet-4-6","max_tokens":1,"tools":[{"name":"Read","description":"Read a file."}],"messages":[{"role":"user","content":"hi"}]}`,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			body := tc.body
			if body == "" {
				body = toolCatalogRequest("newest turn")
			}
			headers := map[string]string{}
			for k, v := range subscriptionAgentHeaders {
				headers[k] = v
			}
			for k, v := range tc.headers {
				headers[k] = v
			}
			rt := &captureTransport{responses: []string{subMessageRespBody}}
			comp := &toolSchemaStripCompressor{}
			srv, _ := newToolSchemaStripServer(t, comp, rt, tc.cfg)

			rec := serveBody(t, srv, "/v1/messages", body, headers)

			if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
				t.Fatalf("must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
			}
			if len(comp.stored) != 0 {
				t.Fatalf("declined strip still wrote %d recovery records", len(comp.stored))
			}
			if rec.Header().Get("x-caveman-toolschema-strip") != "" {
				t.Fatal("declined strip was disclosed as applied")
			}
		})
	}
}

// TestToolSchemaStripWithoutStripperCapabilityPassesThrough pins the seam: an
// embedder whose Compressor cannot strip keeps the catalog, whatever the operator
// configured.
func TestToolSchemaStripWithoutStripperCapabilityPassesThrough(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &noStripCompressor{}
	srv, _ := newToolSchemaStripServer(t, comp, rt, Config{
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("a compressor that cannot strip must pass through:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.stored != 0 {
		t.Fatalf("a compressor that cannot strip wrote %d recovery records", comp.stored)
	}
}

// TestToolSchemaStripWithoutPrefixCachePassesThrough pins the maintainability
// half of the gate. Without a durable replacement cache the proxy cannot keep
// message rewrites byte-stable across turns, and the strip inherits that same
// fail-closed condition rather than restating a looser one of its own.
func TestToolSchemaStripWithoutPrefixCachePassesThrough(t *testing.T) {
	body := toolCatalogRequest("newest turn")
	rt := &captureTransport{responses: []string{subMessageRespBody}}
	comp := &toolSchemaStripCompressor{}
	srv := New(Config{
		Adapters:        []providers.Adapter{anthropic.New("https://upstream.test")},
		Auth:            stubAuth{rc: RequestContext{Label: "local", RuntimeMode: "compress"}},
		Creds:           passthroughTestCreds{},
		Sink:            &captureSink{},
		Compressor:      comp,
		HTTPClient:      &http.Client{Transport: rt},
		RecoveryViaMCP:  true,
		ToolSchemaStrip: toolSchemaStripMode,
	})

	serveBody(t, srv, "/v1/messages", body, subscriptionAgentHeaders)

	if sha256.Sum256(rt.bodies[0]) != sha256.Sum256([]byte(body)) {
		t.Fatalf("no prefix cache must be byte-identical passthrough:\n got %s\nwant %s", rt.bodies[0], body)
	}
	if comp.strips != 0 || len(comp.stored) != 0 {
		t.Fatalf("no prefix cache still stripped: strips=%d stored=%d", comp.strips, len(comp.stored))
	}
}

