func TestSocketPathWindowsIsPerInstall(t *testing.T) {
	one := SocketPath(`C:\Users\Alice\.caveman`)
	two := SocketPath(`C:\Users\Bob\.caveman`)
	if !strings.HasPrefix(one, `\\.\pipe\caveman-native-`) {
		t.Fatalf("SocketPath() = %q", one)
