)

// config_scan.go measures the local agent config that loads into context every
// turn — the "config tax". It reads only local files (CLAUDE.md / AGENTS.md, skill
// descriptions, hooks, plugins) and never writes them. Token counts are an
// `inferred` estimate. See docs/CAVEMAN_LEARN_SPEC.md §4–§5.

type skillInfo struct {
	Name       string
	Path       string
	DescTokens int
}

// configScan is the measured config-tax picture used by the detectors.
type configScan struct {
	Snapshots       []ConfigSnapshot
	ClaudeMDUser    *ConfigSnapshot
	ClaudeMDProject *ConfigSnapshot
	CodexAgents     *ConfigSnapshot
	Skills          []skillInfo
	SkillDescTokens int // per-turn skill catalog tax (name+description only)
	HookCount       int
	PluginCount     int
}

// claudeRoot / codexRoot resolve the agent config dirs, env-overridable for tests.
func claudeRoot() string {
	if r := os.Getenv("CAVEMAN_CLAUDE_ROOT"); r != "" {
		return r
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".claude")
}

func codexRoot() string {
	if r := os.Getenv("CAVEMAN_CODEX_ROOT"); r != "" {
		return r
	}
	home, err := os.UserHomeDir()
	if err != nil {
		return ""
	}
	return filepath.Join(home, ".codex")
}

// estimateTokens is the project's inferred token heuristic (bytes/4), matching the
// usage importer's roughJSONSize/4 convention. Conservative, deterministic, no deps.
func estimateTokens(text string) int {
	n := len(text)
	if n == 0 {
		return 0
	}
	return (n + 3) / 4
}

// scanConfig reads every config-tax source for the current working directory and
// the user's global agent config. cwd is where `caveman learn` was invoked.
func scanConfig(cwd string) configScan {
	now := time.Now().UTC().Format(time.RFC3339)
	var sc configScan
	add := func(snap *ConfigSnapshot) {
		if snap == nil {
			return
		}
		snap.ObservedAt = now
		sc.Snapshots = append(sc.Snapshots, *snap)
	}

	croot := claudeRoot()
	if croot != "" {
		sc.ClaudeMDUser = readMarkdownConfig("user", filepath.Join(croot, "CLAUDE.md"), "claude_md")
		add(sc.ClaudeMDUser)
		sc.Skills = scanSkills(filepath.Join(croot, "skills"))
		for _, sk := range sc.Skills {
			sc.SkillDescTokens += sk.DescTokens
		}
		if len(sc.Skills) > 0 {
			add(&ConfigSnapshot{Scope: "skills", Path: filepath.Join(croot, "skills"), Kind: "skill_desc",
				Lines: len(sc.Skills), Tokens: sc.SkillDescTokens,
				MetadataJSON: compactMeta(map[string]any{"skill_count": len(sc.Skills)})})
		}
		sc.HookCount = countHooks(filepath.Join(croot, "settings.json"))
		if sc.HookCount > 0 {
			add(&ConfigSnapshot{Scope: "hooks", Path: filepath.Join(croot, "settings.json"), Kind: "hooks",
				Lines: sc.HookCount, Tokens: 0,
				MetadataJSON: compactMeta(map[string]any{"hook_count": sc.HookCount})})
		}
		sc.PluginCount = countPlugins(filepath.Join(croot, "plugins", "installed_plugins.json"))
		if sc.PluginCount > 0 {
			add(&ConfigSnapshot{Scope: "plugins", Path: filepath.Join(croot, "plugins", "installed_plugins.json"), Kind: "plugins",
				Lines: sc.PluginCount, Tokens: 0,
				MetadataJSON: compactMeta(map[string]any{"plugin_count": sc.PluginCount})})
		}
	}

	if cwd != "" {
		sc.ClaudeMDProject = readMarkdownConfig("project", filepath.Join(cwd, "CLAUDE.md"), "claude_md")
		add(sc.ClaudeMDProject)
	}

	croot2 := codexRoot()
	if croot2 != "" {
		sc.CodexAgents = readMarkdownConfig("user", filepath.Join(croot2, "AGENTS.md"), "agents_md")
		add(sc.CodexAgents)
	}
	if cwd != "" {
		if proj := readMarkdownConfig("project", filepath.Join(cwd, "AGENTS.md"), "agents_md"); proj != nil {
			add(proj)
		}
	}
	return sc
}

// configTaxPerTurn is the token tax loaded on every turn: CLAUDE.md (user +
// project) + the skill catalog. Hooks/plugins are reported as counts, not folded
// into the token figure, because their context cost can't be measured statically.
func (sc configScan) configTaxPerTurn() int {
	total := sc.SkillDescTokens
	if sc.ClaudeMDUser != nil {
		total += sc.ClaudeMDUser.Tokens
	}
	if sc.ClaudeMDProject != nil {
		total += sc.ClaudeMDProject.Tokens
	}
	return total
}

func readMarkdownConfig(scope, path, kind string) *ConfigSnapshot {
	raw, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	text := string(raw)
	return &ConfigSnapshot{
		Scope:  scope,
		Path:   path,
		Kind:   kind,
		Lines:  strings.Count(text, "\n") + 1,
		Tokens: estimateTokens(text),
	}
}

// scanSkills reads <root>/*/SKILL.md and estimates each skill's per-turn catalog
// tax (its name + description frontmatter, which loads at session start — the body
// loads only on invocation).
func scanSkills(skillsDir string) []skillInfo {
	entries, err := os.ReadDir(skillsDir)
	if err != nil {
		return nil
	}
	var out []skillInfo
	for _, e := range entries {
		if !e.IsDir() {
			continue
		}
		path := filepath.Join(skillsDir, e.Name(), "SKILL.md")
		name, desc := readSkillFrontmatter(path)
		if name == "" {
			name = e.Name()
		}
		out = append(out, skillInfo{
			Name:       name,
			Path:       path,
			DescTokens: estimateTokens(name + " " + desc),
		})
	}
	return out
}

func readSkillFrontmatter(path string) (name, desc string) {
	f, err := os.Open(path)
	if err != nil {
		return "", ""
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 1<<20)
	inFront := false
	started := false
	for sc.Scan() {
		line := sc.Text()
		trimmed := strings.TrimSpace(line)
		if trimmed == "---" {
			if !started {
				started = true
				inFront = true
				continue
			}
			break // end of frontmatter
		}
		if !inFront {
			if !started {
				// No frontmatter fence on the first non-empty line; bail.
				if trimmed != "" {
					return "", ""
				}
				continue
			}
			continue
		}
		if strings.HasPrefix(trimmed, "name:") {
			name = strings.TrimSpace(strings.TrimPrefix(trimmed, "name:"))
		} else if strings.HasPrefix(trimmed, "description:") {
			desc = strings.TrimSpace(strings.TrimPrefix(trimmed, "description:"))
		}
	}
	return strings.Trim(name, `"'`), strings.Trim(desc, `"'`)
}

func countHooks(settingsPath string) int {
	raw, err := os.ReadFile(settingsPath)
	if err != nil {
		return 0
	}
	var obj map[string]any
	if json.Unmarshal(raw, &obj) != nil {
		return 0
	}
	hooks, ok := obj["hooks"].(map[string]any)
	if !ok {
		return 0
	}
	count := 0
	for _, v := range hooks {
		switch x := v.(type) {
		case []any:
			count += len(x)
		case map[string]any:
			count += len(x)
		}
	}
	return count
}

func countPlugins(pluginsPath string) int {
	raw, err := os.ReadFile(pluginsPath)
	if err != nil {
		return 0
	}
	var v any
	if json.Unmarshal(raw, &v) != nil {
		return 0
	}
	switch x := v.(type) {
	case []any:
		return len(x)
	case map[string]any:
		// Common shape: { "<marketplace>": ["plugin@ver", ...] } or { plugins: [...] }
		if arr, ok := x["plugins"].([]any); ok {
			return len(arr)
		}
		total := 0
		counted := false
		for _, child := range x {
			if arr, ok := child.([]any); ok {
				total += len(arr)
				counted = true
			}
		}
		if counted {
			return total
		}
		return len(x)
	}
	return 0
}

// InsertConfigSnapshots persists the measured config sources (evidence/export).
func (s *Store) InsertConfigSnapshots(snaps []ConfigSnapshot) (int, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()
	stmt, err := tx.Prepare(
		`INSERT INTO config_snapshots (scope, path, kind, lines, tokens, observed_at, metadata_json)
		  VALUES (?, ?, ?, ?, ?, ?, ?)
		  ON CONFLICT(scope, path, kind) DO UPDATE SET
		    lines = excluded.lines,
		    tokens = excluded.tokens,
		    observed_at = excluded.observed_at,
		    metadata_json = excluded.metadata_json`,
	)
	if err != nil {
		return 0, err
	}
	defer stmt.Close()
	n := 0
	for _, snap := range snaps {
		if snap.Path == "" {
			continue
		}
		if snap.ObservedAt == "" {
			snap.ObservedAt = time.Now().UTC().Format(time.RFC3339)
		}
		if _, err := stmt.Exec(snap.Scope, snap.Path, snap.Kind, snap.Lines, snap.Tokens, snap.ObservedAt, snap.MetadataJSON); err != nil {
			return n, err
		}
		n++
	}
	if err := tx.Commit(); err != nil {
		return n, err
	}
	return n, nil
}

package store

import (
	"bufio"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/JuliusBrussee/caveman/mem"
)

func hashText(text string) string {
	sum := sha256.Sum256([]byte(text))
	return hex.EncodeToString(sum[:8])
}

// learn.go is the local setup profiler. It turns config files and real session
// history into a Cave Score + a ranked list of token sinks (the `caveman.learn.v1`
// contract). Class A sinks are asserted as facts; Class B sinks are softened with
// their evidence attached. Everything is `inferred`. See docs/CAVEMAN_LEARN_SPEC.md.

// Cave Score weights + caps (documented in one place; mirror the cloud "start at
// 100, subtract capped penalties" mechanic). Higher = leaner.
const (
	wConfigTax   = 50.0
	capConfigTax = 35
	wDumbzone    = 50.0
	capDumbzone  = 25
	wDeadLoad    = 40.0
	capDeadLoad  = 20
	wSubagent    = 20.0
	capSubagent  = 20

	dumbzoneFraction    = 0.5  // a turn over 50% of the window is in the dumbzone
	claudeMDLineBudget  = 150  // CLAUDE.md trim target
	claudeMDTokenAlarm  = 2000 // CLAUDE.md token tax that warrants a reducible sink
	dumbzonePctFloor    = 10.0 // only surface a dumbzone sink above this share
	maxLearnScanWorkers = 16   // bound file descriptors and per-parser buffers on large machines
)

// behaviorScan is the at-the-time picture extracted from real session transcripts.
type behaviorScan struct {
	Turns             int
	DumbzoneTurns     int
	Contexts          []int
	TaskSpawns        int
	SessionsScanned   int
	SessionsBySource  map[string]int
	SessionsWithTasks int
	SkillUse          map[string]int
	LearningLoops     []learningLoop
	From, To          string
}

func (b *behaviorScan) recordSession(source string) {
	b.SessionsScanned++
	if b.SessionsBySource == nil {
		b.SessionsBySource = map[string]int{}
	}
	b.SessionsBySource[source]++
}

func (b behaviorScan) medianContext() int {
	if len(b.Contexts) == 0 {
		return 0
	}
	sorted := append([]int(nil), b.Contexts...)
	sort.Ints(sorted)
	return sorted[len(sorted)/2]
}

// BuildLearnPlan is the front-door analyzer: scan config + real history, compute the
// detectors, the Cave Score, rank by tokens/day, and persist sinks. Read-only over
// user config — it never edits a config file.
func (s *Store) BuildLearnPlan(cwd string, sources []string, sinceExpr string) (LearnPlan, error) {
	return s.BuildLearnPlanWithRetro(cwd, sources, sinceExpr, RetroOptions{})
}

// BuildLearnPlanWithRetro is BuildLearnPlan plus the opt-in retrospective pass.
// With retro disabled the two are the same code path and the same output bytes.
func (s *Store) BuildLearnPlanWithRetro(cwd string, sources []string, sinceExpr string, retro RetroOptions) (LearnPlan, error) {
	sourceSet := normalizeSources(sources)
	since := parseSince(sinceExpr)

	cfg := scanConfig(cwd)
	if _, err := s.InsertConfigSnapshots(cfg.Snapshots); err != nil {
		logStoreWarning(s.logger, "config snapshot persist failed", err)
	}

	beh, rec := behaviorScan{}, recurringResult{}
	behaviorTimeBoxed := false
	if retro.Enabled {
		budgetMS := retro.BehaviorBudgetMS
		if budgetMS <= 0 {
			budgetMS = behaviorDefaultBudgetMS
		}
		beh, rec, behaviorTimeBoxed = s.scanBehaviorWithBudget(sourceSet, since, cfg, time.Duration(budgetMS)*time.Millisecond)
	} else {
		beh, rec = s.scanBehavior(sourceSet, since, cfg)
	}

	days := windowDays(sinceExpr, beh.From, beh.To)
	turnsPerDay := 0.0
	if beh.Turns > 0 && days > 0 {
		turnsPerDay = float64(beh.Turns) / days
	}

	plan := LearnPlan{
		Schema:           learnSchema,
		Basis:            learnBasis,
		Window:           LearnWindow{From: beh.From, To: beh.To, Since: sinceExpr},
		SessionsScanned:  beh.SessionsScanned,
		SessionsBySource: beh.SessionsBySource,
		Sinks:            []Sink{},
		Caveats: []string{
			"Local learn results are inferred. No local number is promoted to verified; Cloud additionally requires supported provider-causal, provider-complete, catalog-priced active evidence.",
			"Config tax is reported as a forward rate from your current setup, never as tokens already wasted. Context window sizes are assumed per-provider defaults.",
		},
	}

	deadTokens, deadSkills := deadLoadSkills(cfg, beh)

	recurPerTurn := 0
	for _, e := range rec.Repaste {
		recurPerTurn += recurringPerTurn(e, beh.Turns)
	}

	plan.Sinks = append(plan.Sinks, configSinks(cfg, turnsPerDay)...)
	plan.Sinks = append(plan.Sinks, recurringSinks(rec, beh, turnsPerDay)...)
	plan.Sinks = append(plan.Sinks, learningLoopSinks(beh.LearningLoops)...)
	plan.Sinks = append(plan.Sinks, dumbzoneSink(beh)...)
	plan.Sinks = append(plan.Sinks, deadLoadSink(deadTokens, deadSkills, beh, turnsPerDay)...)
	plan.Sinks = append(plan.Sinks, subagentSink(beh)...)
	plan.Sinks = append(plan.Sinks, surfaceSink(cfg)...)
	for i := range plan.Sinks {
		plan.Sinks[i].PracticeID = practiceIDForSink(plan.Sinks[i].SinkID)
	}

	// Rank by forward tokens/day rate (reducible movers first); behavioral sinks
	// (rate 0) keep their relative order after.
	sort.SliceStable(plan.Sinks, func(i, j int) bool {
		return plan.Sinks[i].TokensPerDayRate > plan.Sinks[j].TokensPerDayRate
	})

	plan.CaveScore = caveScore(cfg, beh, deadTokens, recurPerTurn)

	if len(plan.Sinks) == 0 {
		plan.Caveats = appendUnique(plan.Caveats, "No config-tax or behavioral sink found yet. Run caveman learn after some Claude/Codex sessions exist on disk, or from a repo with a CLAUDE.md.")
	}
	if beh.SessionsScanned == 0 {
		plan.Caveats = appendUnique(plan.Caveats, "No local session transcripts were scanned, so behavioral findings (dumbzone, subagents, dead-skill use) are not measured.")
	}
	if behaviorTimeBoxed {
		plan.Caveats = appendUnique(plan.Caveats, "The base behavioral scan hit its time budget, so Cave Score and behavioral findings cover partial history. The independent retro totals still name only sessions they measured.")
	}

	// The retro pass is a second, budget-bounded walk so the base scan above keeps
	// its exact timing and its exact output when --retro is absent.
	if retro.Enabled {
		plan.Retro = s.buildLearnRetro(sourceSet, since, sinceExpr, cfg.configTaxPerTurn(), retro)
	}

	if err := s.upsertSinks(plan.Sinks); err != nil {
		logStoreWarning(s.logger, "learn sink persist failed", err)
	}
	return plan, nil
}

// LearnScan builds the plan and writes concise cavemem learnings from the reducible
// sinks (so the durable memory + trial report stay populated). Returns the plan.
func (s *Store) LearnScan(sources []string, sinceExpr string) (LearnPlan, error) {
	return s.LearnScanWithRetro(sources, sinceExpr, RetroOptions{})
}

// LearnScanWithRetro is LearnScan plus the opt-in retrospective pass.
func (s *Store) LearnScanWithRetro(sources []string, sinceExpr string, retro RetroOptions) (LearnPlan, error) {
	cwd, _ := os.Getwd()
	plan, err := s.BuildLearnPlanWithRetro(cwd, sources, sinceExpr, retro)
	if err != nil {
		return plan, err
	}
	s.writeCavememLearnings(plan)
	return plan, nil
}

func (s *Store) writeCavememLearnings(plan LearnPlan) {
	var texts []string
	for _, sink := range plan.Sinks {
		if sink.Class != classReducible {
			continue
		}
		text := sink.Title
		if sink.Suggestion != "" {
			text += " — " + sink.Suggestion
		}
		texts = append(texts, text)
	}
	if len(texts) == 0 {
		return
	}
	memStore, err := mem.Open(mem.Options{})
	if err != nil {
		logStoreWarning(s.logger, "open cavemem failed", err)
		return
	}
	defer memStore.Close()
	for _, text := range texts {
		l := Learning{Text: text, SourceKind: "caveman_learn", Confidence: "medium"}
		if memory, err := memStore.Remember(text); err == nil {
			l.ID = memory.ID
			l.StoredInCavemem = true
		} else {
			l.ID = "mem_" + hashText(text)
		}
		if err := s.insertLearning(l); err != nil {
			logStoreWarning(s.logger, "learning insert failed", err)
		}
	}
}

// --- detectors -------------------------------------------------------------

func configSinks(cfg configScan, turnsPerDay float64) []Sink {
	tax := cfg.configTaxPerTurn()
	var sinks []Sink
	if tax > 0 {
		userTokens, projectTokens := 0, 0
		if cfg.ClaudeMDUser != nil {
			userTokens = cfg.ClaudeMDUser.Tokens
		}
		if cfg.ClaudeMDProject != nil {
			projectTokens = cfg.ClaudeMDProject.Tokens
		}
		sinks = append(sinks, Sink{
			SinkID:           "config_tax:baseline",
			Title:            fmt.Sprintf("Your agent config loads ~%d tokens into every turn", tax),
			Class:            classLoadBearing,
			Basis:            observedLocal,
			TokensPerTurn:    int64(tax),
			TokensPerDayRate: rate(tax, turnsPerDay),
			Framing:          framingForward,
			Suggestion:       "Some of this is load-bearing. The reducible parts are broken out as their own sinks below.",
			Evidence: map[string]any{
				"claude_md_user_tokens":    userTokens,
				"claude_md_project_tokens": projectTokens,
				"skill_desc_tokens":        cfg.SkillDescTokens,
				"skill_count":              len(cfg.Skills),
				"hook_count":               cfg.HookCount,
				"plugin_count":             cfg.PluginCount,
			},
		})
	}
	sinks = append(sinks, claudeMDSink(cfg.ClaudeMDUser, "user", turnsPerDay)...)
	sinks = append(sinks, claudeMDSink(cfg.ClaudeMDProject, "project", turnsPerDay)...)
	if cfg.CodexAgents != nil {
		sinks = append(sinks, claudeMDSink(cfg.CodexAgents, "codex", turnsPerDay)...)
	}
	return sinks
}

func claudeMDSink(snap *ConfigSnapshot, scope string, turnsPerDay float64) []Sink {
	if snap == nil {
		return nil
	}
	if snap.Lines <= claudeMDLineBudget && snap.Tokens <= claudeMDTokenAlarm {
		return nil
	}
	label := map[string]string{"user": "User", "project": "Project", "codex": "Codex AGENTS.md"}[scope]
	kind := "CLAUDE.md"
	if snap.Kind == "agents_md" {
		kind = "AGENTS.md"
	}
	title := fmt.Sprintf("%s %s is %d lines (~%d tokens) loaded every turn", label, kind, snap.Lines, snap.Tokens)
	if scope == "codex" {
		title = fmt.Sprintf("%s is %d lines (~%d tokens) loaded every turn", label, snap.Lines, snap.Tokens)
	}
	return []Sink{{
		SinkID:           "claude_md_weight:" + scope,
		Title:            title,
		Class:            classReducible,
		Basis:            observedLocal,
		TokensPerTurn:    int64(snap.Tokens),
		TokensPerDayRate: rate(snap.Tokens, turnsPerDay),
		Framing:          framingForward,
		Suggestion:       fmt.Sprintf("Trim to the sections actually used; target < %d lines.", claudeMDLineBudget),
		Evidence:         map[string]any{"lines": snap.Lines, "tokens": snap.Tokens, "path": snap.Path},
	}}
}

func dumbzoneSink(beh behaviorScan) []Sink {
	if beh.Turns == 0 {
		return nil
	}
	pct := float64(beh.DumbzoneTurns) / float64(beh.Turns) * 100
	if pct < dumbzonePctFloor {
		return nil
	}
	return []Sink{{
		SinkID:        "context_dumbzone",
		Title:         fmt.Sprintf("%.0f%% of turns ran over %.0f%% of the model window", pct, dumbzoneFraction*100),
		Class:         classBehavioral,
		Basis:         observedLocal,
		TokensPerTurn: 0, TokensPerDayRate: 0,
		Framing:    framingHistorical,
		Suggestion: "Compact or split long sessions before the dumbzone; large context degrades quality well before the window limit.",
		Evidence: map[string]any{
			"turns_over_50pct": beh.DumbzoneTurns,
			"total_turns":      beh.Turns,
			"pct":              int(pct + 0.5),
			"median_context":   beh.medianContext(),
		},
	}}
}

// deadLoadSkills returns the total per-turn token tax of skills with no detected
// use, and the slug list (Class B: numbers asserted, "unused" softened to
// "no use detected in the scanned window").
func deadLoadSkills(cfg configScan, beh behaviorScan) (int, []string) {
	if beh.SessionsScanned == 0 {
		return 0, nil
	}
	tokens := 0
	var slugs []string
	for _, sk := range cfg.Skills {
		slug := strings.ToLower(filepath.Base(filepath.Dir(sk.Path)))
		if beh.SkillUse[slug] > 0 {
			continue
		}
		tokens += sk.DescTokens
		slugs = append(slugs, slug)
	}
	sort.Strings(slugs)
	return tokens, slugs
}

func deadLoadSink(deadTokens int, deadSkills []string, beh behaviorScan, turnsPerDay float64) []Sink {
	if len(deadSkills) == 0 || deadTokens == 0 {
		return nil
	}
	sample := deadSkills
	if len(sample) > 12 {
		sample = sample[:12]
	}
	return []Sink{{
		SinkID:           "dead_load:skills",
		Title:            fmt.Sprintf("%d skills load ~%d tokens/turn with no use detected in %d sessions", len(deadSkills), deadTokens, beh.SessionsScanned),
		Class:            classReducible,
		Basis:            observedLocal,
		TokensPerTurn:    int64(deadTokens),
		TokensPerDayRate: rate(deadTokens, turnsPerDay),
		Framing:          framingForward,
		Suggestion:       "Consider gating skills with no detected use; their descriptions load every turn. (No use detected is window-bounded, not proof a skill is unneeded.)",
		Evidence: map[string]any{
			"skill_count":      len(deadSkills),
			"sessions_scanned": beh.SessionsScanned,
			"skills":           sample,
		},
	}}
}

func subagentSink(beh behaviorScan) []Sink {
	if beh.TaskSpawns == 0 {
		return nil
	}
	median := 0
	if beh.SessionsWithTasks > 0 {
		median = beh.TaskSpawns / beh.SessionsWithTasks
	}
	return []Sink{{
		SinkID:        "subagent_overuse",
		Title:         fmt.Sprintf("You spawned %d subagents across %d sessions (≈%d per session that used them)", beh.TaskSpawns, beh.SessionsWithTasks, median),
		Class:         classBehavioral,
		Basis:         observedLocal,
		TokensPerTurn: 0, TokensPerDayRate: 0,
		Framing:    framingHistorical,
		Suggestion: "Subagents each carry their own context; for one-file lookups a direct read is cheaper. (Counts only — Caveman never asserts a spawn was unnecessary.)",
		Evidence: map[string]any{
			"task_spawns":         beh.TaskSpawns,
			"sessions_with_tasks": beh.SessionsWithTasks,
			"sessions_scanned":    beh.SessionsScanned,
		},
	}}
}

func surfaceSink(cfg configScan) []Sink {
	combined := cfg.HookCount + cfg.PluginCount
	if combined < 10 {
		return nil
	}
	return []Sink{{
		SinkID:        "config_surface",
		Title:         fmt.Sprintf("Your setup loads %d skills, %d hooks, and %d plugins", len(cfg.Skills), cfg.HookCount, cfg.PluginCount),
		Class:         classBehavioral,
		Basis:         observedLocal,
		TokensPerTurn: 0, TokensPerDayRate: 0,
		Framing:    framingHistorical,
		Suggestion: "SessionStart/UserPromptSubmit hooks inject their output into context each session; trimming the surface you don't use reduces per-turn overhead.",
		Evidence: map[string]any{
			"skill_count":  len(cfg.Skills),
			"hook_count":   cfg.HookCount,
			"plugin_count": cfg.PluginCount,
		},
	}}
}

// --- Cave Score ------------------------------------------------------------

func caveScore(cfg configScan, beh behaviorScan, deadTokens, recurPerTurn int) CaveScore {
	tax := cfg.configTaxPerTurn()
	median := beh.medianContext()

	components := []ScoreComponent{}
	score := 100

	// config_tax: per-turn tokens you pay to re-establish context every turn —
	// config that loads each turn plus recurring re-pasted blocks — as a share of a
	// median turn. Recurring re-paste folds in here (it's the same value family:
	// tokens cavemem could replace), so the score stays four components.
	cTax := ScoreComponent{Key: scoreKeyConfigTax}
	numerator := tax + recurPerTurn
	if numerator > 0 && median > 0 {
		cTax.Measured = true
		ratio := float64(numerator) / float64(median)
		cTax.Penalty = capped(wConfigTax*ratio, capConfigTax)
		if recurPerTurn > 0 {
			cTax.Detail = fmt.Sprintf("config %d + recurring re-paste %d tok/turn vs median context %d", tax, recurPerTurn, median)
		} else {
			cTax.Detail = fmt.Sprintf("config %d tok/turn vs median context %d", tax, median)
		}
	} else {
		cTax.Detail = "not measured (need config tax and session transcripts)"
	}
	components = append(components, cTax)
	score -= cTax.Penalty

	// dumbzone: share of turns over the window fraction.
	cDz := ScoreComponent{Key: scoreKeyDumbzone}
	if beh.Turns > 0 {
		cDz.Measured = true
		dzRate := float64(beh.DumbzoneTurns) / float64(beh.Turns)
		cDz.Penalty = capped(wDumbzone*dzRate, capDumbzone)
		cDz.Detail = fmt.Sprintf("%d/%d turns over %.0f%% window", beh.DumbzoneTurns, beh.Turns, dumbzoneFraction*100)
	} else {
		cDz.Detail = "not measured (no session transcripts)"
	}
	components = append(components, cDz)
	score -= cDz.Penalty

	// dead_load: dead-skill tokens as a share of the config tax.
	cDead := ScoreComponent{Key: scoreKeyDeadLoad}
	if beh.SessionsScanned > 0 && tax > 0 {
		cDead.Measured = true
		deadRatio := float64(deadTokens) / float64(tax)
		cDead.Penalty = capped(wDeadLoad*deadRatio, capDeadLoad)
		cDead.Detail = fmt.Sprintf("%d dead-skill tok of %d config tok", deadTokens, tax)
	} else {
		cDead.Detail = "not measured (need skills and session transcripts)"
	}
	components = append(components, cDead)
	score -= cDead.Penalty

	// subagent pressure: average task spawns per scanned session.
	cSub := ScoreComponent{Key: scoreKeySubagent}
	if beh.SessionsScanned > 0 {
		cSub.Measured = true
		pressure := float64(beh.TaskSpawns) / float64(beh.SessionsScanned) / 5.0
		if pressure > 1 {
			pressure = 1
		}
		cSub.Penalty = capped(wSubagent*pressure, capSubagent)
		cSub.Detail = fmt.Sprintf("%d spawns over %d sessions", beh.TaskSpawns, beh.SessionsScanned)
	} else {
		cSub.Detail = "not measured (no session transcripts)"
	}
	components = append(components, cSub)
	score -= cSub.Penalty

	if score < 0 {
		score = 0
	}
	if score > 100 {
		score = 100
	}
	return CaveScore{Score: score, Basis: learnBasis, Scope: "local_setup", Components: components}
}

// --- behavioral transcript scan -------------------------------------------

var behaviorClock = time.Now

type behaviorDeadline struct {
	at time.Time
}

func (d *behaviorDeadline) expired() bool {
	return d != nil && !behaviorClock().Before(d.at)
}

func (s *Store) scanBehavior(sourceSet map[string]bool, since time.Time, cfg configScan) (behaviorScan, recurringResult) {
	beh, rec, _ := s.scanBehaviorUntil(sourceSet, since, cfg, nil)
	return beh, rec
}

func (s *Store) scanBehaviorWithBudget(sourceSet map[string]bool, since time.Time, cfg configScan, budget time.Duration) (behaviorScan, recurringResult, bool) {
	deadline := &behaviorDeadline{at: behaviorClock().Add(budget)}
	return s.scanBehaviorUntil(sourceSet, since, cfg, deadline)
}

func (s *Store) scanBehaviorUntil(sourceSet map[string]bool, since time.Time, cfg configScan, deadline *behaviorDeadline) (behaviorScan, recurringResult, bool) {
	beh := behaviorScan{SkillUse: map[string]int{}, SessionsBySource: map[string]int{}}
	miner := newRecurringMiner()
	timeBoxed := false
	slugs := make([]string, 0, len(cfg.Skills))
	for _, sk := range cfg.Skills {
		slugs = append(slugs, strings.ToLower(filepath.Base(filepath.Dir(sk.Path))))
	}
	if sourceSet["claude"] {
		timeBoxed = scanClaudeSessionsUntil(claudeRoot(), since, slugs, &beh, miner, deadline) || timeBoxed
	}
	if sourceSet["codex"] && (deadline == nil || !deadline.expired()) {
		// Codex repaste mining is deferred (its payload content shape differs);
		// behavioral counts are still scanned below.
		timeBoxed = scanCodexSessionsUntil(codexRoot(), since, &beh, deadline) || timeBoxed
	} else if sourceSet["codex"] {
		timeBoxed = true
	}
	return beh, miner.result(), timeBoxed
}

func scanClaudeSessionsUntil(root string, since time.Time, slugs []string, beh *behaviorScan, miner *recurringMiner, deadline *behaviorDeadline) bool {
	if root == "" {
		return false
	}
	projects := filepath.Join(root, "projects")
	var paths []string
	timeBoxed := false
	_ = filepath.WalkDir(projects, func(path string, d os.DirEntry, err error) error {
		if deadline != nil && deadline.expired() {
			timeBoxed = true
			return fs.SkipAll
		}
		if err != nil || d.IsDir() || !strings.HasSuffix(path, ".jsonl") {
			return nil
		}
		paths = append(paths, path)
		return nil
	})
	sort.Strings(paths)

	type result struct {
		behavior  behaviorScan
		miner     *recurringMiner
		timeBoxed bool
	}
	results := make([]result, len(paths))
	parallelSessionScan(len(paths), func(i int) {
		if deadline != nil && deadline.expired() {
			results[i].timeBoxed = true
			return
		}
		path := paths[i]
		relPath, relErr := filepath.Rel(root, path)
		if relErr != nil {
			relPath = filepath.Base(path)
		}
		localBehavior := behaviorScan{SkillUse: map[string]int{}, SessionsBySource: map[string]int{}}
		localMiner := newRecurringMiner()
		truncated := scanClaudeTranscriptBehaviorUntil(path, relPath, since, slugs, &localBehavior, localMiner, deadline)
		results[i] = result{behavior: localBehavior, miner: localMiner, timeBoxed: truncated}
	})
	for i := range results {
		mergeBehaviorScan(beh, &results[i].behavior)
		miner.merge(results[i].miner)
		timeBoxed = results[i].timeBoxed || timeBoxed
	}
	return timeBoxed
}

func scanClaudeTranscriptBehavior(path, relPath string, since time.Time, slugs []string, beh *behaviorScan, miner *recurringMiner) {
	_ = scanClaudeTranscriptBehaviorUntil(path, relPath, since, slugs, beh, miner, nil)
}

func scanClaudeTranscriptBehaviorUntil(path, relPath string, since time.Time, slugs []string, beh *behaviorScan, miner *recurringMiner, deadline *behaviorDeadline) bool {
	if deadline != nil && deadline.expired() {
		return true
	}
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 16<<20)
	beh.recordSession("claude")
	sessionTasks := 0
	seenSlugs := map[string]bool{}
	seenUsage := map[string]bool{}
	pendingTools := map[string]learnToolCall{}
	var sessionToolCalls []learnToolCall
	lineNo := 0
	for sc.Scan() {
		lineNo++
		if deadline != nil && deadline.expired() {
			return true
		}
		line := sc.Bytes()
		var obj map[string]any
		if json.Unmarshal(line, &obj) != nil {
			continue
		}
		ts := timestampFromObject(obj)
		if !since.IsZero() && !ts.IsZero() && ts.Before(since) {
			continue
		}
		tsStr := ""
		if !ts.IsZero() {
			tsStr = ts.UTC().Format(time.RFC3339)
			if beh.From == "" || tsStr < beh.From {
				beh.From = tsStr
			}
			if beh.To == "" || tsStr > beh.To {
				beh.To = tsStr
			}
		}
		miner.observeTurn("claude", relPath, lineNo, tsStr, obj)
		sessionToolCalls = append(sessionToolCalls, claudeToolCalls(obj, pendingTools, lineNo)...)
		if ctx, ok := claudeTurnContext(obj); ok {
			if id := claudeUsageMessageID(obj); id == "" || !seenUsage[id] {
				if id != "" {
					seenUsage[id] = true
				}
				beh.Turns++
				beh.Contexts = append(beh.Contexts, ctx)
				if ctx > int(dumbzoneFraction*float64(contextWindow("anthropic", claudeModel(obj)))) {
					beh.DumbzoneTurns++
				}
			}
		}
		lower := strings.ToLower(string(line))
		if strings.Contains(lower, `"name":"task"`) {
			sessionTasks += strings.Count(lower, `"name":"task"`)
		}
		for _, slug := range slugs {
			if slug != "" && !seenSlugs[slug] && strings.Contains(lower, slug) {
				seenSlugs[slug] = true
			}
		}
	}
	for slug := range seenSlugs {
		beh.SkillUse[slug]++
	}
	if sessionTasks > 0 {
		beh.TaskSpawns += sessionTasks
		beh.SessionsWithTasks++
	}
	sessionSum := sha256.Sum256([]byte(relPath))
	sessionRef := hex.EncodeToString(sessionSum[:8])
	beh.LearningLoops = append(beh.LearningLoops, detectLearningLoops(sessionToolCalls, sessionRef)...)
	return false
}

// claudeUsageMessageID identifies the API response a usage block belongs to.
// Claude Code writes one assistant turn as several JSONL lines — one per
// content block — and each line repeats the same message.usage verbatim, so
// counting per line double-counts every multi-block turn (measured ×2.03 on
// real 30-day logs). Lines carrying no id cannot be deduplicated and count
// individually.
func claudeUsageMessageID(obj map[string]any) string {
	msg := asMap(obj["message"])
	return firstString(msg["id"], obj["requestId"])
}

// claudeTurnContext returns the full context size the model saw on an assistant
// turn (input + cache read + cache creation), from the real usage block.
func claudeTurnContext(obj map[string]any) (int, bool) {
	msg := asMap(obj["message"])
	usage := asMap(msg["usage"])
	if len(usage) == 0 {
		usage = asMap(obj["usage"])
	}
	if len(usage) == 0 {
		return 0, false
	}
	total, ok := checkedNonNegativeSum(
		int64FromAny(usage["input_tokens"]),
		int64FromAny(usage["cache_read_input_tokens"]),
		int64FromAny(usage["cache_creation_input_tokens"]),
	)
	if !ok || total <= 0 || uint64(total) > uint64(^uint(0)>>1) {
		return 0, false
	}
	return int(total), true
}

func claudeModel(obj map[string]any) string {
	msg := asMap(obj["message"])
	return firstString(msg["model"], obj["model"])
}

func scanCodexSessionsUntil(root string, since time.Time, beh *behaviorScan, deadline *behaviorDeadline) bool {
	if root == "" {
		return false
	}
	paths, timeBoxed, _ := codexPathsUntil(root, func() bool { return deadline != nil && deadline.expired() })
	sort.Strings(paths)
	type result struct {
		behavior  behaviorScan
		timeBoxed bool
	}
	results := make([]result, len(paths))
	parallelSessionScan(len(paths), func(i int) {
		if deadline != nil && deadline.expired() {
			results[i].timeBoxed = true
			return
		}
		local := behaviorScan{SkillUse: map[string]int{}, SessionsBySource: map[string]int{}}
		truncated := scanCodexSessionBehaviorUntil(paths[i], since, &local, deadline)
		results[i] = result{behavior: local, timeBoxed: truncated}
	})
	for i := range results {
		mergeBehaviorScan(beh, &results[i].behavior)
		timeBoxed = results[i].timeBoxed || timeBoxed
	}
	return timeBoxed
}

func scanCodexSessionBehavior(path string, since time.Time, beh *behaviorScan) {
	_ = scanCodexSessionBehaviorUntil(path, since, beh, nil)
}

func scanCodexSessionBehaviorUntil(path string, since time.Time, beh *behaviorScan, deadline *behaviorDeadline) bool {
	if deadline != nil && deadline.expired() {
		return true
	}
	f, err := os.Open(path)
	if err != nil {
		return false
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 16<<20)
	beh.recordSession("codex")
	lineNo := 0
	for sc.Scan() {
		lineNo++
		if deadline != nil && deadline.expired() {
			return true
		}
		var obj map[string]any
		if json.Unmarshal(sc.Bytes(), &obj) != nil {
			continue
		}
		ts := timestampFromObject(obj)
		if !since.IsZero() && !ts.IsZero() && ts.Before(since) {
			continue
		}
		payload := asMap(obj["payload"])
		info := asMap(payload["info"])
		usage := asMap(info["last_token_usage"])
		if len(usage) == 0 {
			usage = asMap(payload["last_token_usage"])
		}
		if len(usage) == 0 {
			continue
		}
		// Codex mirrors OpenAI usage: input_tokens is already the total
		// effective prompt size and cached_input_tokens is a subset. Adding the
		// cache detail again inflates context and false-triggers the dumbzone.
		ctx64 := int64FromAny(usage["input_tokens"])
		if uint64(ctx64) > uint64(^uint(0)>>1) {
			continue
		}
		ctx := int(ctx64)
		if ctx <= 0 {
			continue
		}
		beh.Turns++
		beh.Contexts = append(beh.Contexts, ctx)
		model := firstString(payload["model"], info["model"], obj["model"])
		if ctx > int(dumbzoneFraction*float64(contextWindow("openai", model))) {
			beh.DumbzoneTurns++
		}
	}
	return false
}

// parallelSessionScan bounds file-level concurrency to available Go schedulers.
// Each worker owns its parser state; results merge later in sorted path order.
func parallelSessionScan(count int, scan func(int)) {
	if count <= 0 {
		return
	}
	workers := runtime.GOMAXPROCS(0)
	if workers > maxLearnScanWorkers {
		workers = maxLearnScanWorkers
	}
	if workers > count {
		workers = count
	}
	jobs := make(chan int)
	var wg sync.WaitGroup
	wg.Add(workers)
	for range workers {
		go func() {
			defer wg.Done()
			for i := range jobs {
				scan(i)
			}
		}()
	}
	for i := range count {
		jobs <- i
	}
	close(jobs)
	wg.Wait()
}

func mergeBehaviorScan(dst, src *behaviorScan) {
	if dst == nil || src == nil {
		return
	}
	dst.Turns += src.Turns
	dst.DumbzoneTurns += src.DumbzoneTurns
	dst.Contexts = append(dst.Contexts, src.Contexts...)
	dst.TaskSpawns += src.TaskSpawns
	dst.SessionsScanned += src.SessionsScanned
	dst.SessionsWithTasks += src.SessionsWithTasks
	dst.LearningLoops = append(dst.LearningLoops, src.LearningLoops...)
	if dst.SessionsBySource == nil {
		dst.SessionsBySource = map[string]int{}
	}
	for source, count := range src.SessionsBySource {
		dst.SessionsBySource[source] += count
	}
	if dst.SkillUse == nil {
		dst.SkillUse = map[string]int{}
	}
	for skill, count := range src.SkillUse {
		dst.SkillUse[skill] += count
	}
	if src.From != "" && (dst.From == "" || src.From < dst.From) {
		dst.From = src.From
	}
	if src.To > dst.To {
		dst.To = src.To
	}
}

// --- helpers ---------------------------------------------------------------

func (s *Store) upsertSinks(sinks []Sink) error {
	for _, sink := range sinks {
		evidence, _ := json.Marshal(sink.Evidence)
		if _, err := s.db.Exec(
			`INSERT INTO learn_sinks
			  (sink_id, title, class, basis, tokens_per_turn, tokens_per_day_rate, framing, evidence_json, suggestion, computed_at)
			  VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
			  ON CONFLICT(sink_id) DO UPDATE SET
			    title = excluded.title, class = excluded.class, basis = excluded.basis,
			    tokens_per_turn = excluded.tokens_per_turn, tokens_per_day_rate = excluded.tokens_per_day_rate,
			    framing = excluded.framing, evidence_json = excluded.evidence_json,
			    suggestion = excluded.suggestion, computed_at = excluded.computed_at`,
			sink.SinkID, sink.Title, sink.Class, sink.Basis, sink.TokensPerTurn, sink.TokensPerDayRate,
			sink.Framing, string(evidence), sink.Suggestion, time.Now().UTC().Format(time.RFC3339),
		); err != nil {
			return err
		}
	}
	return nil
}

func normalizeSources(sources []string) map[string]bool {
	set := map[string]bool{}
	for _, src := range sources {
		for _, part := range strings.Split(src, ",") {
			if part = strings.TrimSpace(part); part != "" {
				set[part] = true
			}
		}
	}
	if len(set) == 0 {
		set = map[string]bool{"codex": true, "claude": true, "caveman": true}
	}
	return set
}

func contextWindow(provider, model string) int {
	m := strings.ToLower(model)
	if strings.Contains(m, "1m") || strings.Contains(m, "[1m]") {
		return 1_000_000
	}
	switch provider {
	case "openai":
		return 400_000
	default:
		return 200_000
	}
}

func windowDays(sinceExpr, from, to string) float64 {
	sinceExpr = strings.TrimSpace(sinceExpr)
	if strings.HasSuffix(sinceExpr, "d") {
		var days int
		if _, err := fmt.Sscanf(sinceExpr, "%dd", &days); err == nil && days > 0 {
			return float64(days)
		}
	}
	if from != "" && to != "" {
		a, errA := time.Parse(time.RFC3339, from)
		b, errB := time.Parse(time.RFC3339, to)
		if errA == nil && errB == nil {
			d := b.Sub(a).Hours() / 24
			if d >= 1 {
				return d
			}
		}
	}
	return 1
}

func rate(tokensPerTurn int, turnsPerDay float64) int64 {
	if turnsPerDay <= 0 {
		return 0
	}
	return int64(float64(tokensPerTurn) * turnsPerDay)
}

func capped(v float64, max int) int {
	n := int(v + 0.5)
	if n < 0 {
		return 0
	}
	if n > max {
		return max
	}
	return n
}

package store

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"regexp"
	"sort"
	"strings"
)

const minLearningLoopCalls = 3

type learnToolCall struct {
	Name         string
	Input        string
	IsError      bool
	OutputTokens int
	Position     int
}

type learningLoop struct {
	Kind             string
	Tool             string
	SignatureHash    string
	SessionRef       string
	Calls            int
	Positions        []int
	OutputTokenFloor int
}

var (
	loopPagination = regexp.MustCompile(`(?i)(\|\s*(head|tail)\s+(-n\s*)?\d+|--max-count[= ]\d+|--lines[= ]\d+|\b(limit|offset)[= ]\d+)`)
	loopIntegers   = regexp.MustCompile(`\b\d+\b`)
	loopWhitespace = regexp.MustCompile(`\s+`)
)

func detectLearningLoops(calls []learnToolCall, sessionRef string) []learningLoop {
	groups := map[string][]learnToolCall{}
	for _, call := range calls {
		signature := canonicalToolSignature(call.Name, call.Input)
		if signature == "" {
			continue
		}
		groups[signature] = append(groups[signature], call)
	}
	var loops []learningLoop
	for signature, grouped := range groups {
		if len(grouped) < minLearningLoopCalls {
			continue
		}
		errors := 0
		variants := map[string]bool{}
		var positions, tokenCosts []int
		for _, call := range grouped {
			if call.IsError {
				errors++
			}
			variants[strings.TrimSpace(call.Input)] = true
			positions = append(positions, call.Position)
			tokenCosts = append(tokenCosts, call.OutputTokens)
		}
		kind := ""
		tokenFloor := 0
		if errors*2 >= len(grouped) {
			kind = "error_loop"
			for _, cost := range tokenCosts {
				tokenFloor += cost
			}
		} else if errors == 0 && len(variants) > 1 {
			// Successful repeats become a re-fetch loop only when pagination or
			// output-limit variants collapsed to one signature. Exact repeated
			// commands may be intentional test/build loops and stay silent.
			kind = "refetch_loop"
			sort.Sort(sort.Reverse(sort.IntSlice(tokenCosts)))
			for i := 1; i < len(tokenCosts); i++ {
				tokenFloor += tokenCosts[i]
			}
		}
		if kind == "" {
			continue
		}
		sum := sha256.Sum256([]byte(signature))
		loops = append(loops, learningLoop{
			Kind:             kind,
			Tool:             grouped[0].Name,
			SignatureHash:    hex.EncodeToString(sum[:8]),
			SessionRef:       sessionRef,
			Calls:            len(grouped),
			Positions:        positions,
			OutputTokenFloor: tokenFloor,
		})
	}
	sort.SliceStable(loops, func(i, j int) bool {
		if loops[i].OutputTokenFloor != loops[j].OutputTokenFloor {
			return loops[i].OutputTokenFloor > loops[j].OutputTokenFloor
		}
		return loops[i].SignatureHash < loops[j].SignatureHash
	})
	return loops
}

func canonicalToolSignature(name, input string) string {
	name = strings.ToLower(strings.TrimSpace(name))
	input = strings.ToLower(strings.TrimSpace(input))
	if name == "" || input == "" {
		return ""
	}
	switch name {
	case "bash", "shell", "run_command":
		input = loopPagination.ReplaceAllString(input, " ")
		input = loopIntegers.ReplaceAllString(input, "N")
	}
	input = loopWhitespace.ReplaceAllString(input, " ")
	return name + "::" + strings.TrimSpace(input)
}

func claudeToolCalls(obj map[string]any, pending map[string]learnToolCall, position int) []learnToolCall {
	message, _ := obj["message"].(map[string]any)
	content, _ := message["content"].([]any)
	var completed []learnToolCall
	for _, raw := range content {
		block, _ := raw.(map[string]any)
		switch block["type"] {
		case "tool_use":
			id, _ := block["id"].(string)
			name, _ := block["name"].(string)
			if id == "" || name == "" {
				continue
			}
			pending[id] = learnToolCall{
				Name:     name,
				Input:    toolInputSummary(block["input"]),
				Position: position,
			}
		case "tool_result":
			id, _ := block["tool_use_id"].(string)
			call, ok := pending[id]
			if !ok {
				continue
			}
			delete(pending, id)
			call.IsError, _ = block["is_error"].(bool)
			call.OutputTokens = estimateTokens(toolResultText(block["content"]))
			call.Position = position
			completed = append(completed, call)
		}
	}
	return completed
}

func toolInputSummary(value any) string {
	if input, ok := value.(map[string]any); ok {
		for _, key := range []string{"command", "path", "file_path", "query", "pattern"} {
			if text, ok := input[key].(string); ok && strings.TrimSpace(text) != "" {
				return text
			}
		}
	}
	raw, err := json.Marshal(value)
	if err != nil {
		return ""
	}
	return string(raw)
}

func toolResultText(value any) string {
	switch typed := value.(type) {
	case string:
		return typed
	case []any:
		var parts []string
		for _, raw := range typed {
			if block, ok := raw.(map[string]any); ok {
				if text, ok := block["text"].(string); ok {
					parts = append(parts, text)
				}
			}
		}
		return strings.Join(parts, "\n")
	default:
		raw, _ := json.Marshal(value)
		return string(raw)
	}
}

func learningLoopSinks(loops []learningLoop) []Sink {
	sinks := make([]Sink, 0, len(loops))
	for _, loop := range loops {
		label := "failed"
		suggestion := "Review the first failure before retrying the same call; record a project-local guardrail only after confirming the corrected command."
		if loop.Kind == "refetch_loop" {
			label = "re-fetched"
			suggestion = "Request enough output once, or narrow the query before repeating pagination variants. Treat this as a measured pattern, not proof that every repeat was waste."
		}
		sinks = append(sinks, Sink{
			SinkID: "learning_loop:" + loop.Kind + ":" + loop.SessionRef + ":" + loop.SignatureHash,
			Title:  loop.Tool + " " + label + " " + itoa(loop.Calls) + " times in one session",
			Class:  classBehavioral,
			Basis:  observedLocal,
			Evidence: map[string]any{
				"kind":                        loop.Kind,
				"tool":                        loop.Tool,
				"session_ref":                 loop.SessionRef,
				"signature_sha256_prefix":     loop.SignatureHash,
				"calls":                       loop.Calls,
				"positions":                   loop.Positions,
				"observed_output_token_floor": loop.OutputTokenFloor,
			},
			Suggestion: suggestion,
			Framing:    framingHistorical,
		})
	}
	return sinks
}

func itoa(value int) string {
	// JSON's integer rendering is deterministic and avoids a second formatting
	// dependency in finding titles.
	raw, _ := json.Marshal(value)
	return string(raw)
}

package store

import (
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func TestDetectLearningLoopsRequiresThreeCallsWithinOneSession(t *testing.T) {
	twoFailures := []learnToolCall{
		{Name: "Bash", Input: "cat missing.txt", IsError: true, OutputTokens: 10, Position: 2},
		{Name: "Bash", Input: "cat missing.txt", IsError: true, OutputTokens: 12, Position: 4},
	}
	if got := detectLearningLoops(twoFailures, "session-a"); len(got) != 0 {
		t.Fatalf("two calls must not become a loop: %+v", got)
	}
	// Calls from unrelated sessions are evaluated independently; two plus two
	// never become one cross-session loop.
	if got := detectLearningLoops(twoFailures, "session-b"); len(got) != 0 {
		t.Fatalf("cross-session recurrence must not become a loop: %+v", got)
	}

	threeFailures := append(append([]learnToolCall(nil), twoFailures...),
		learnToolCall{Name: "Bash", Input: "cat missing.txt", IsError: true, OutputTokens: 14, Position: 6})
	got := detectLearningLoops(threeFailures, "session-a")
	if len(got) != 1 || got[0].Kind != "error_loop" || got[0].OutputTokenFloor != 36 {
		t.Fatalf("error loop = %+v", got)
	}
}

func TestDetectLearningLoopsDistinguishesPaginationVariants(t *testing.T) {
	variants := []learnToolCall{
		{Name: "Bash", Input: "rg error build.log | head -50", OutputTokens: 30, Position: 1},
		{Name: "Bash", Input: "rg error build.log | head -100", OutputTokens: 50, Position: 2},
		{Name: "Bash", Input: "rg error build.log | head -200", OutputTokens: 70, Position: 3},
	}
	got := detectLearningLoops(variants, "session")
	if len(got) != 1 || got[0].Kind != "refetch_loop" || got[0].OutputTokenFloor != 80 {
		t.Fatalf("re-fetch loop = %+v", got)
	}

	exactRepeats := []learnToolCall{
		{Name: "Bash", Input: "go test ./...", OutputTokens: 10},
		{Name: "Bash", Input: "go test ./...", OutputTokens: 10},
		{Name: "Bash", Input: "go test ./...", OutputTokens: 10},
	}
	if got := detectLearningLoops(exactRepeats, "session"); len(got) != 0 {
		t.Fatalf("exact successful repeats may be intentional and must stay silent: %+v", got)
	}
}

func TestBuildLearnPlanSurfacesHashedFailureLoopEvidence(t *testing.T) {
	home := t.TempDir()
	claudeDir := t.TempDir()
	t.Setenv("CAVEMAN_HOME", home)
	t.Setenv("CAVEMAN_CLAUDE_ROOT", claudeDir)
	t.Setenv("CAVEMAN_CODEX_ROOT", t.TempDir())

	var lines []string
	for i := 1; i <= 3; i++ {
		id := fmt.Sprintf("tool-%d", i)
		lines = append(lines,
			fmt.Sprintf(`{"type":"assistant","timestamp":"2026-07-28T12:00:0%dZ","message":{"model":"claude","content":[{"type":"tool_use","id":"%s","name":"Bash","input":{"command":"cat missing-secret-path.txt"}}]}}`, i, id),
			fmt.Sprintf(`{"type":"user","timestamp":"2026-07-28T12:00:1%dZ","message":{"content":[{"type":"tool_result","tool_use_id":"%s","is_error":true,"content":"No such file or directory: missing-secret-path.txt"}]}}`, i, id),
		)
	}
	path := filepath.Join(claudeDir, "projects", "repo", "loop.jsonl")
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(strings.Join(lines, "\n")+"\n"), 0o600); err != nil {
		t.Fatal(err)
	}

	store, err := Open(filepath.Join(home, "caveman.db"), nil)
	if err != nil {
		t.Fatal(err)
	}
	defer store.Close()
	plan, err := store.BuildLearnPlan(t.TempDir(), []string{"claude"}, "30d")
	if err != nil {
		t.Fatal(err)
	}
	var loop *Sink
	for i := range plan.Sinks {
		if strings.HasPrefix(plan.Sinks[i].SinkID, "learning_loop:error_loop:") {
			loop = &plan.Sinks[i]
			break
		}
	}
	if loop == nil {
		t.Fatalf("learning loop sink missing: %v", sinkIDs(plan))
	}
	if loop.Class != classBehavioral || loop.Framing != framingHistorical {
		t.Fatalf("loop classification = %+v", loop)
	}
	serialized := fmt.Sprintf("%+v", loop)
	if strings.Contains(serialized, "missing-secret-path") {
		t.Fatalf("loop finding leaked raw tool input/output: %s", serialized)
	}
	if loop.Evidence["calls"] != 3 {
		t.Fatalf("loop evidence = %+v", loop.Evidence)
	}
}

package store

import (
	"bufio"
	"encoding/json"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	"github.com/JuliusBrussee/caveman/engine"
	"github.com/JuliusBrussee/caveman/engine/ccr"
)

// learn_retro.go is the opt-in retrospective pass behind `learn scan --retro`:
// over the same window the profiler already scans, it reports what the sessions
// actually sent and what the engine measures it would have cut. It is a second,
// budget-bounded walk so the base scan's timing and output stay byte-identical
// when `--retro` is absent.
//
// HONESTY (docs/SAVINGS_ACCOUNTING.md §1.2): everything here is `inferred` and
// sums only over sessions actually read. Provider usage is counted once per API
// response (message id), never once per transcript line. WouldCutTokens counts
// each unique tool-output once plus a conservative lower bound for observed
// re-pastes (sum of occurrence sizes minus the largest normalized variant);
// WouldCutStreamTokens re-weights tool-output and
// timestamp-ordered repeated-block cuts by later provider-counted turns of the
// same transcript — and because the
// transcript does not observe mid-session eviction, believed residency is
// CAPPED by each turn's own provider-counted size (oldest blocks evicted
// first) and cleared at compaction or end of session. Cross-file duplicates
// weight deterministically in the newest file that carries them. Never
// projected; token volume only — the price of a re-sent token depends on
// provider caching, so no dollar is ever derived here. Under-claim, never blend.

const (
	// behaviorDefaultBudgetMS caps the base behavioral pass when retro is enabled.
	// Together with retroDefaultBudgetMS it stays below the first-run child's
	// derived timeout, so a cold base scan cannot erase a partial retro result.
	behaviorDefaultBudgetMS = 20000
	// retroDefaultBudgetMS matches the CLI's first-run budget so the bare
	// `learn scan --retro` and the welcome reveal report the same coverage on
	// the same history.
	retroDefaultBudgetMS = 60000
	// retroSegmentFloorBytes: below this a tool result is not worth an engine
	// pass, and the engine's not-smaller check would pass it through anyway.
	retroSegmentFloorBytes = 512
)

// RetroOptions turns on the retrospective pass. Off by default: an existing
// `learn scan` caller must see zero behavior change.
type RetroOptions struct {
	Enabled bool
	// BudgetMS bounds the retro pass, including discovery and transcript parsing,
	// but never the base scan. <= 0 uses the default. Exceeding it truncates
	// coverage and sets TimeBoxed.
	BudgetMS int
	// BehaviorBudgetMS bounds the base behavioral pass that precedes retro.
	// <= 0 uses behaviorDefaultBudgetMS. Ignored when Enabled is false, preserving
	// existing `learn scan` timing and bytes.
	BehaviorBudgetMS int
}

// retroClock and retroEngineFactory are the pass's only injected seams. The
// deadline is what makes the pass bounded, and "the engine could not be built"
// is a fail-closed path that must stay reachable in tests.
var (
	retroClock          = time.Now
	retroDiscoveryClock = time.Now
	retroEngineFactory  = openRetroEngine
)

// openRetroEngine builds a counting-only engine. Simulate stores nothing, so the
// in-memory CCR store is never written; it exists so an S4 reduction is reported
// as realizable — which is what the local wrap path, where CCR is wired, would
// actually achieve. Without it the engine would report those reductions as
// unrecoverable and the retro block would silently under-count.
func openRetroEngine() (*engine.Engine, func(), error) {
	recovery, err := ccr.OpenMemory()
	if err != nil {
		return nil, nil, err
	}
	eng := engine.New(recovery, nil)
	// Warm the shared token counter on this goroutine before any worker touches
	// it: its regexp splitter lazily allocates a runner pool on first use and
	// that allocation is not itself synchronized. Warming here happens-before
	// the scan workers start, after which the pool is safe for concurrent use.
	eng.Simulate([]byte("warm"), engine.Options{Mode: engine.ModeCompress})
	return eng, func() { _ = recovery.Close() }, nil
}

// retroSessionPath is one discovered transcript, ordered newest-first so a
// truncated pass covers the freshest sessions rather than an arbitrary slice.
type retroSessionPath struct {
	path    string
	relPath string
	source  string
	modTime time.Time
}

// retroTurn is one deduplicated provider-counted API response: where it sits
// in the file, how many tokens the provider counted for it, and whether it
// belongs to an interleaved legacy sidechain.
type retroTurn struct {
	line int
	ctx  int64
	side bool
}

// retroCandidate is one tool-output segment (>= floor) a file carries. Whether
// it earned a cut lives in the collector, keyed by sha; size is the scanner's
// byte-based estimate of the WHOLE segment, used only to cap believed
// residency against each turn's provider-counted size.
type retroCandidate struct {
	sha  string
	line int
	size int64
	side bool
}

// retroFileResult is one transcript's contribution. A file counts toward
// SessionsScanned only when it carried provider usage — mixing counted and
// estimated sessions in one total is exactly the blend the accounting forbids.
// Stream weighting happens after the parallel scan, in deterministic
// newest-first file order, from turns/boundaries/candidates.
type retroFileResult struct {
	source      string
	relPath     string
	usageTokens int64
	usageTurns  int
	turns       []retroTurn
	boundaries  []int
	candidates  []retroCandidate
	parsed      bool // read before the deadline (as opposed to skipped entirely)
	usable      bool // carried provider-counted usage
	truncated   bool
	miner       *recurringMiner
}

// retroCollector measures unique tool-output segments exactly once per scan.
// savedBySha keeps each booked cut so the deterministic stream pass can weight
// a segment from whichever file wins the newest-first attribution, regardless
// of which goroutine ran the engine.
type retroCollector struct {
	mu         sync.Mutex
	seen       map[string]bool
	savedBySha map[string]int64
	cutTokens  int64
	segments   int
	eng        *engine.Engine
	deadline   time.Time
}

// claim reports whether this scan has not measured the segment yet. The claim is
// what makes the count first-send-only across the whole window.
func (c *retroCollector) claim(sha string) bool {
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.seen[sha] {
		return false
	}
	c.seen[sha] = true
	return true
}

// measure runs one segment through the engine exactly once per unique sha and
// books only a real reduction. A pass-through, a non-positive delta, or an
// unrecoverable result books zero. The result is deterministic per content, so
// whichever goroutine wins the claim records the same figure in savedBySha.
func (c *retroCollector) measure(sha, text string) {
	if c.eng == nil {
		return
	}
	if !c.claim(sha) {
		return
	}
	sim := c.eng.Simulate([]byte(text), engine.Options{Mode: engine.ModeCompress})
	if !sim.Recoverable || sim.TokensSaved <= 0 {
		return
	}
	c.mu.Lock()
	c.cutTokens += int64(sim.TokensSaved)
	c.segments++
	c.savedBySha[sha] = int64(sim.TokensSaved)
	c.mu.Unlock()
}

func (c *retroCollector) expired() bool { return !retroClock().Before(c.deadline) }

// buildLearnRetro runs the bounded retro pass. It returns nil rather than a
// block of zeros when there is nothing honest to report.
func (s *Store) buildLearnRetro(sourceSet map[string]bool, since time.Time, sinceExpr string, configPrefixPerTurn int, opts RetroOptions) *LearnRetro {
	budget := time.Duration(opts.BudgetMS) * time.Millisecond
	if opts.BudgetMS <= 0 {
		budget = retroDefaultBudgetMS * time.Millisecond
	}
	// Overall deadline starts before transcript discovery. Discovery gets at most
	// one quarter of the pass (capped at 10s), reserving time to parse and return
	// honest partial coverage before the CLI child deadline.
	col := &retroCollector{seen: map[string]bool{}, savedBySha: map[string]int64{}, deadline: retroClock().Add(budget)}
	discoveryBudget := budget / 4
	if discoveryBudget > 10*time.Second {
		discoveryBudget = 10 * time.Second
	}
	discoveryDeadline := retroDiscoveryClock().Add(discoveryBudget)
	paths, discoveryTimeBoxed := retroSessionPathsUntil(sourceSet, since, func() bool {
		return !retroDiscoveryClock().Before(discoveryDeadline)
	})
	if len(paths) == 0 {
		return nil
	}

	// Fail closed on the engine: without it the tool-output family is omitted
	// entirely rather than estimated, and engine_used records why.
	engineUsed := true
	engineErr := ""
	if eng, closeEngine, err := retroEngineFactory(); err == nil {
		col.eng = eng
		defer closeEngine()
	} else {
		engineUsed = false
		engineErr = err.Error()
	}

	results := make([]retroFileResult, len(paths))
	skipped := discoveryTimeBoxed
	var skippedMu sync.Mutex
	parallelSessionScan(len(paths), func(i int) {
		if col.expired() {
			skippedMu.Lock()
			skipped = true
			skippedMu.Unlock()
			return
		}
		switch paths[i].source {
		case "claude":
			results[i] = retroScanClaudeFile(paths[i], since, col)
		case "codex":
			results[i] = retroScanCodexFile(paths[i], since, col)
		}
	})

	miner := newRecurringStreamMiner()
	retro := LearnRetro{
		Basis:                     learnBasis,
		WindowDays:                int(windowDays(sinceExpr, "", "")),
		SessionsTotal:             len(paths),
		TokensObservedSource:      retroSourceSessionUsage,
		ConfigPrefixTokensPerTurn: configPrefixPerTurn,
		EngineUsed:                engineUsed,
		TimeBoxed:                 skipped,
		Families:                  []LearnRetroFamily{},
	}
	// Merge in newest-first path order so recurrence aggregation stays
	// deterministic even though parsing ran concurrently.
	unusable := 0
	for i := range results {
		if results[i].truncated {
			retro.TimeBoxed = true
		}
		if !results[i].usable {
			// Only a completed scan can establish that a session lacked usage.
			// A deadline-truncated file may carry usage below the stopping point.
			if results[i].parsed && !results[i].truncated {
				unusable++
			}
			continue
		}
		// Every family must be mined from exactly the session set that backs
		// TokensObserved. Folding a usage-free session's blocks in here would
		// book a cut against tokens no total ever counted — a blend, and one
		// that can push would_cut past observed.
		if results[i].miner != nil {
			miner.merge(results[i].miner)
		}
		retro.SessionsScanned++
		retro.TurnsObserved += results[i].usageTurns
		retro.TokensObserved += results[i].usageTokens
	}
	if retro.SessionsScanned == 0 || retro.TokensObserved <= 0 {
		return nil // nothing provider-counted was read; emit no block at all
	}

	if engineUsed && col.cutTokens > 0 {
		retro.Families = append(retro.Families, LearnRetroFamily{
			ID: retroFamilyToolOutputs, Label: "tool outputs (wrap compression)", Tokens: col.cutTokens,
		})
	}
	recurring := miner.result()
	if repeated := retroRepeatedBlockTokens(recurring); repeated > 0 {
		retro.Families = append(retro.Families, LearnRetroFamily{
			ID: retroFamilyRepeatedBlocks, Label: "re-pasted context (cavemem offload)", Tokens: repeated,
		})
	}
	repeatedByFile, undatedRepeated := retroRepeatedStreamCandidates(recurring)
	streamClaimed := map[string]bool{}
	for i := range results {
		if !results[i].usable {
			continue
		}
		key := retroStreamFileKey(results[i].source, results[i].relPath)
		retro.WouldCutStreamTokens += retroStreamCutTokens(
			&results[i], col.savedBySha, streamClaimed, repeatedByFile[key],
		)
	}
	for _, family := range retro.Families {
		retro.WouldCutTokens += family.Tokens
	}

	retro.Caveats = retroCaveats(retro, sourceSet, unusable, engineErr, undatedRepeated)
	return &retro
}

type retroStreamCandidate struct {
	line      int
	cut, size int64
	side      bool
}

func retroStreamFileKey(source, relPath string) string { return source + "\x00" + relPath }

// retroStreamCutTokens weights one file's tool-output and repeated-block cuts
// together by later provider-counted turns of the same transcript. Combining
// both families before the residency cap prevents each from independently
// claiming the same provider-counted context. Believed residency is
// CAPPED by each turn's own provider-counted size: the transcript cannot
// observe mid-session eviction, so when the byte-estimated sizes of the
// believed-resident segments exceed what the provider counted for a turn, the
// oldest segments are evicted first and never credit again. A compact boundary
// clears residency outright. Cross-file duplicates weight only in the first
// file the deterministic caller order reaches (streamClaimed). In a legacy
// MIXED file (interleaved sidechain lines) only main-thread cuts weigh,
// against main-thread turns — current Claude Code writes each subagent thread
// to its own file, where every turn is honestly the same thread.
func retroStreamCutTokens(r *retroFileResult, savedBySha map[string]int64, streamClaimed map[string]bool, repeated []retroStreamCandidate) int64 {
	if (len(r.candidates) == 0 && len(repeated) == 0) || len(r.turns) == 0 {
		return 0
	}
	sawMain, sawSide := false, false
	for _, t := range r.turns {
		if t.side {
			sawSide = true
		} else {
			sawMain = true
		}
	}
	mixed := sawMain && sawSide
	var segs []retroStreamCandidate
	for _, cand := range r.candidates {
		saved := savedBySha[cand.sha]
		if saved <= 0 || streamClaimed[cand.sha] {
			continue
		}
		streamClaimed[cand.sha] = true
		if mixed && cand.side {
			continue
		}
		segs = append(segs, retroStreamCandidate{line: cand.line, cut: saved, size: cand.size})
	}
	for _, cand := range repeated {
		if mixed && cand.side {
			continue
		}
		segs = append(segs, cand)
	}
	// Candidates from both families can share a transcript line. Evict the
	// largest cut first on a tie: transcript order is unavailable at that grain,
	// so the deterministic tie-break under-claims rather than favoring savings.
	sort.SliceStable(segs, func(i, j int) bool {
		if segs[i].line != segs[j].line {
			return segs[i].line < segs[j].line
		}
		return segs[i].cut > segs[j].cut
	})
	var total int64
	var active []retroStreamCandidate
	var activeSize int64
	si, bi := 0, 0
	for _, t := range r.turns {
		if mixed && t.side {
			continue
		}
		// Replay segment arrivals and compaction clears in line order up to
		// this turn.
		for {
			nextSeg, nextBound := t.line, t.line
			if si < len(segs) {
				nextSeg = segs[si].line
			}
			if bi < len(r.boundaries) {
				nextBound = r.boundaries[bi]
			}
			if nextSeg >= t.line && nextBound >= t.line {
				break
			}
			if nextSeg < nextBound {
				active = append(active, segs[si])
				activeSize += segs[si].size
				si++
			} else {
				active = active[:0]
				activeSize = 0
				bi++
			}
		}
		for len(active) > 0 && activeSize > t.ctx {
			activeSize -= active[0].size
			active = active[1:]
		}
		for _, s := range active {
			total += s.cut
		}
	}
	return total
}

// retroRepeatedBlockTokens counts historical duplication actually present in
// the transcripts. Normalization can group differently sized digit/whitespace
// variants, and chronology may be unavailable, so subtracting the largest
// observed occurrence is the conservative lower bound for "all but the first."
func retroRepeatedBlockTokens(rec recurringResult) int64 {
	var total int64
	for _, e := range rec.Repaste {
		if e.Occurrences <= 1 || len(e.Positions) != e.Occurrences {
			continue
		}
		var sum, largest int64
		complete := true
		for _, position := range e.Positions {
			if position.Tokens <= 0 {
				complete = false
				break
			}
			size := int64(position.Tokens)
			sum += size
			if size > largest {
				largest = size
			}
		}
		if complete {
			total += sum - largest
		}
	}
	return total
}

// retroRepeatedStreamCandidates turns every timestamp-ordered re-paste after
// the earliest occurrence group into a resident cut. Exact earliest ties stay
// necessary because separate files have no causal ordering. If any occurrence
// lacks a timestamp the whole fingerprint stays out of the stream figure:
// choosing a first paste from file/path order could inflate residency, so the
// base occurrence count remains the honest fallback.
func retroRepeatedStreamCandidates(rec recurringResult) (map[string][]retroStreamCandidate, bool) {
	byFile := map[string][]retroStreamCandidate{}
	undated := false
	for _, entry := range rec.Repaste {
		if entry.Occurrences <= 1 || entry.BlockTokens <= 0 {
			continue
		}
		if len(entry.Positions) != entry.Occurrences {
			undated = true
			continue
		}
		type timedOccurrence struct {
			recurringOccurrence
			at time.Time
		}
		positions := make([]timedOccurrence, 0, len(entry.Positions))
		complete := true
		for _, position := range entry.Positions {
			if position.Timestamp == "" || position.Tokens <= 0 {
				complete = false
				break
			}
			at, err := time.Parse(time.RFC3339Nano, position.Timestamp)
			if err != nil {
				complete = false
				break
			}
			positions = append(positions, timedOccurrence{recurringOccurrence: position, at: at})
		}
		if !complete {
			undated = true
			continue
		}
		sort.SliceStable(positions, func(i, j int) bool {
			if !positions[i].at.Equal(positions[j].at) {
				return positions[i].at.Before(positions[j].at)
			}
			if positions[i].RootKind != positions[j].RootKind {
				return positions[i].RootKind < positions[j].RootKind
			}
			if positions[i].RelPath != positions[j].RelPath {
				return positions[i].RelPath < positions[j].RelPath
			}
			return positions[i].JSONLLine < positions[j].JSONLLine
		})
		// Separate transcript files have no causal ordering at an identical
		// timestamp. Treat the whole earliest tied group as necessary context;
		// path order must never decide which one earns removable-repeat credit.
		firstRepeat := 1
		for firstRepeat < len(positions) && positions[firstRepeat].at.Equal(positions[0].at) {
			firstRepeat++
		}
		for _, position := range positions[firstRepeat:] {
			key := retroStreamFileKey(position.RootKind, position.RelPath)
			byFile[key] = append(byFile[key], retroStreamCandidate{
				line: position.JSONLLine, cut: int64(position.Tokens),
				size: int64(position.Tokens), side: position.Side,
			})
		}
	}
	return byFile, undated
}

func retroCaveats(retro LearnRetro, sourceSet map[string]bool, unusable int, engineErr string, undatedRepeated bool) []string {
	caveats := []string{
		"Provider usage is counted once per API response (message id), never once per transcript line.",
		"would_cut_tokens counts each unique tool-output cut once plus a conservative repeated-block lower bound: occurrence sizes summed minus the largest normalized variant; it carries no ratio against tokens_observed.",
		"would_cut_stream_tokens re-weights tool-output and timestamp-ordered repeated-block cuts by later provider-counted turns of the same session, with exact earliest timestamp ties kept as necessary context; both families share one residency cap per turn (oldest evicted first) and clear at compaction or end of session — same basis as tokens_observed, token volume only; the price of a re-sent token depends on provider caching.",
		"Totals are sums over the sessions actually read; nothing is extrapolated to unscanned sessions, to a month, or to a dollar.",
		"Config prefix is reported as a per-turn rate and is deliberately excluded from would_cut_tokens; trimming config is a different fix from wrap compression.",
	}
	if retro.EngineUsed {
		caveats = append(caveats, "Tool-output savings are engine-measured in o200k tokens; repeated-block savings use the scanner's byte-based estimate. The two are not the same estimator.")
	} else {
		msg := "The compression engine could not be started, so the tool-output family is omitted entirely rather than estimated."
		if engineErr != "" {
			msg += " (" + engineErr + ")"
		}
		caveats = append(caveats, msg)
	}
	if sourceSet["codex"] {
		caveats = append(caveats, "Codex sessions contribute observed tokens only; tool outputs and repeated blocks are scanned from Claude Code transcripts, whose payload shape exposes them.")
	}
	if undatedRepeated {
		caveats = append(caveats, "Repeated blocks without complete transcript timestamps remain in would_cut_tokens but are omitted from would_cut_stream_tokens rather than guessing which occurrence came first.")
	}
	if retro.TimeBoxed {
		caveats = append(caveats, "The retro pass hit its discovery or scan time budget, so coverage is partial and the figures under-count. Complete paths discovered before expiry were read newest-first.")
	}
	if unusable > 0 {
		caveats = appendUnique(caveats, "Sessions without provider-counted usage were excluded from every total rather than estimated.")
	}
	return caveats
}

// retroSessionPaths discovers the transcripts in the window and orders them
// newest-first, so a budget-truncated pass covers the freshest sessions.
func retroSessionPaths(sourceSet map[string]bool, since time.Time) []retroSessionPath {
	paths, _ := retroSessionPathsUntil(sourceSet, since, nil)
	return paths
}

// retroSessionPathsUntil makes discovery part of the pass budget. A truncated
// discovery returns every complete path found before expiry and marks the result
// partial; callers sort that known subset newest-first and never extrapolate it.
func retroSessionPathsUntil(sourceSet map[string]bool, since time.Time, expired func() bool) ([]retroSessionPath, bool) {
	var out []retroSessionPath
	timeBoxed := false
	stopped := func() bool {
		if expired == nil || !expired() {
			return false
		}
		timeBoxed = true
		return true
	}
	add := func(root, source, path string, info os.FileInfo) bool {
		if stopped() {
			return false
		}
		if info == nil {
			var err error
			info, err = os.Stat(path)
			if err != nil {
				return true
			}
		}
		if info.IsDir() || (!since.IsZero() && info.ModTime().Before(since)) {
			return true
		}
		rel, relErr := filepath.Rel(root, path)
		if relErr != nil {
			rel = filepath.Base(path)
		}
		out = append(out, retroSessionPath{path: path, relPath: rel, source: source, modTime: info.ModTime()})
		return true
	}
	if sourceSet["claude"] {
		if root := claudeRoot(); root != "" {
			_ = filepath.WalkDir(filepath.Join(root, "projects"), func(path string, d os.DirEntry, err error) error {
				if stopped() {
					return fs.SkipAll
				}
				if err != nil || d.IsDir() || !strings.HasSuffix(path, ".jsonl") {
					return nil
				}
				info, infoErr := d.Info()
				if infoErr == nil && !add(root, "claude", path, info) {
					return fs.SkipAll
				}
				return nil
			})
		}
	}
	if sourceSet["codex"] && !stopped() {
		if root := codexRoot(); root != "" {
			paths, pathsTimeBoxed, _ := codexPathsUntil(root, stopped)
			timeBoxed = pathsTimeBoxed || timeBoxed
			for _, path := range paths {
				if !add(root, "codex", path, nil) {
					break
				}
			}
		}
	} else if sourceSet["codex"] {
		timeBoxed = true
	}
	sort.SliceStable(out, func(i, j int) bool {
		if !out[i].modTime.Equal(out[j].modTime) {
			return out[i].modTime.After(out[j].modTime)
		}
		return out[i].path < out[j].path
	})
	return out, timeBoxed
}

// retroScanClaudeFile reads one Claude Code transcript: provider-counted usage,
// recurring blocks, and tool-result payloads for the engine.
func retroScanClaudeFile(p retroSessionPath, since time.Time, col *retroCollector) retroFileResult {
	res := retroFileResult{source: p.source, relPath: p.relPath, miner: newRecurringStreamMiner()}
	f, err := os.Open(p.path)
	if err != nil {
		return res
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 16<<20)
	// Record positions for the deterministic stream pass (retroStreamCutTokens):
	// deduplicated provider-counted turns with their counted sizes, compaction
	// clears, and every >= floor tool-output segment. All ascending by
	// construction. Sidechain flags matter only for legacy transcripts that
	// interleaved subagent lines into the session file — current Claude Code
	// writes each subagent thread to its own file.
	seenUsage := map[string]bool{}
	lineNo := 0
	for sc.Scan() {
		lineNo++
		if col.expired() {
			res.truncated = true
			break
		}
		res.parsed = true
		var obj map[string]any
		if json.Unmarshal(sc.Bytes(), &obj) != nil {
			continue
		}
		ts := timestampFromObject(obj)
		if !since.IsZero() && !ts.IsZero() && ts.Before(since) {
			continue
		}
		tsStr := ""
		if !ts.IsZero() {
			tsStr = ts.UTC().Format(time.RFC3339Nano)
		}
		if obj["type"] == "system" && obj["subtype"] == "compact_boundary" {
			res.boundaries = append(res.boundaries, lineNo)
		}
		sidechain := obj["isSidechain"] == true
		if ctx, ok := claudeTurnContext(obj); ok {
			res.usable = true
			// One API response is written as several transcript lines (one per
			// content block), each repeating the same usage — count it once.
			if id := claudeUsageMessageID(obj); id == "" || !seenUsage[id] {
				if id != "" {
					seenUsage[id] = true
				}
				res.usageTurns++
				res.usageTokens += int64(ctx)
				res.turns = append(res.turns, retroTurn{line: lineNo, ctx: int64(ctx), side: sidechain})
			}
		}
		res.miner.observeTurn("claude", p.relPath, lineNo, tsStr, obj)
		// Measure only once this session is known to carry provider usage, so
		// the cut total and the observed total cover exactly the same sessions.
		// In a Claude Code transcript the first tool_result always follows an
		// assistant turn, which is where usage lives, so nothing real is lost.
		if !res.usable {
			continue
		}
		for _, text := range claudeToolResultTexts(obj) {
			sha := contentSHA256(text)
			col.measure(sha, text)
			res.candidates = append(res.candidates, retroCandidate{
				sha: sha, line: lineNo, size: int64(estimateTokens(text)), side: sidechain,
			})
		}
	}
	return res
}

// claudeToolResultTexts pulls tool-result payload text out of one transcript
// turn. These are the bodies the wrap path compresses.
func claudeToolResultTexts(obj map[string]any) []string {
	msg := asMap(obj["message"])
	content, _ := msg["content"].([]any)
	var out []string
	for _, raw := range content {
		block := asMap(raw)
		if block == nil || block["type"] != "tool_result" {
			continue
		}
		if text := toolResultText(block["content"]); len(text) >= retroSegmentFloorBytes {
			out = append(out, text)
		}
	}
	return out
}

// retroScanCodexFile reads a Codex rollout for its provider-counted usage only.
// Codex's payload shape does not expose tool-result bodies the way the Claude
// transcript does, so it contributes to the observed total and to nothing else.
func retroScanCodexFile(p retroSessionPath, since time.Time, col *retroCollector) retroFileResult {
	res := retroFileResult{source: p.source, relPath: p.relPath}
	f, err := os.Open(p.path)
	if err != nil {
		return res
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 0, 64*1024), 16<<20)
	lineNo := 0
	for sc.Scan() {
		lineNo++
		if col.expired() {
			res.truncated = true
			break
		}
		res.parsed = true
		var obj map[string]any
		if json.Unmarshal(sc.Bytes(), &obj) != nil {
			continue
		}
		ts := timestampFromObject(obj)
		if !since.IsZero() && !ts.IsZero() && ts.Before(since) {
			continue
		}
		payload := asMap(obj["payload"])
		info := asMap(payload["info"])
		usage := asMap(info["last_token_usage"])
		if len(usage) == 0 {
			usage = asMap(payload["last_token_usage"])
		}
		if len(usage) == 0 {
			continue
		}
		// Codex mirrors OpenAI usage: input_tokens is already the total effective
		// prompt size and cached_input_tokens is a subset of it. Adding the cache
		// detail again would double-count context that was sent once.
		ctx := int64FromAny(usage["input_tokens"])
		if ctx <= 0 {
			continue
		}
		res.usable = true
		res.usageTurns++
		res.usageTokens += ctx
	}
	return res
}

