		retroUsageLineSized("msg_2", 9000), // once evicted it never comes back
	})
	s := openRetroTestStore(t)

	plan, err := s.BuildLearnPlanWithRetro(fx.cwd, []string{"claude"}, "30d", RetroOptions{Enabled: true})
	if err != nil {
		t.Fatal(err)
