package store

import (
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"errors"
	"fmt"
	"time"
)

// prefixCacheMaxEntries bounds the replacement cache. The store keeps the most
// recently used entries and drops the rest; an evicted entry is a plain lookup
// miss, so the gateway forwards that message's original bytes from then on. That
// costs one prompt-cache rebuild and is byte-stable afterwards — never a
// half-applied prefix. Live blocks average a few KB, so the cap is a soft ceiling
// of tens of MB in ~/.caveman/caveman.db.
const prefixCacheMaxEntries = 10000

// LookupReplacement returns the replacement bytes this proxy previously emitted
// for these exact original bytes, plus the CCR handle they disclose. It implements
// the read half of gateway.PrefixCache and fails open: any miss or SQL error is
// reported as ok=false so the caller forwards the client's original bytes.
func (s *Store) LookupReplacement(scope string, original []byte) ([]byte, string, bool) {
	key := prefixCacheKey(scope, original)
	replacement, handle, ok := s.readReplacement(key)
	if !ok {
		return nil, "", false
	}
	// Touch for LRU eviction only. A failed touch changes nothing the caller can
	// observe this turn, so it is logged and swallowed rather than turned into a miss.
	if _, err := s.db.Exec(`UPDATE prefix_replacements SET last_used_at = ? WHERE original_sha256 = ?`, prefixCacheNow(), key); err != nil && s.logger != nil {
		s.logger.Warn("prefix replacement touch failed", "error", err)
	}
	return replacement, handle, true
}

// RememberReplacement durably records original→replacement and returns the
// authoritative bytes for that original. Storage is first-write-wins: if another
// in-flight request already stored a replacement for the same block, that one is
// returned and the caller forwards it, so two requests can never put two different
// prefixes on the wire for one logical message.
func (s *Store) RememberReplacement(scope string, original, replacement []byte, handle string) ([]byte, error) {
	if scope == "" || len(original) == 0 || len(replacement) == 0 || handle == "" {
		return nil, errors.New("prefix replacement: incomplete entry")
	}
	key := prefixCacheKey(scope, original)
	now := prefixCacheNow()
	if _, err := s.db.Exec(
		`INSERT INTO prefix_replacements (original_sha256, handle, replacement, created_at, last_used_at)
		 VALUES (?,?,?,?,?)
		 ON CONFLICT(original_sha256) DO UPDATE SET last_used_at=excluded.last_used_at`,
		key, handle, replacement, now, now,
	); err != nil {
		return nil, fmt.Errorf("prefix replacement put: %w", err)
	}
	stored, _, ok := s.readReplacement(key)
	if !ok {
		return nil, errors.New("prefix replacement: entry unreadable after write")
	}
	s.evictPrefixReplacements()
	return stored, nil
}

func (s *Store) readReplacement(key string) ([]byte, string, bool) {
	var handle string
	var replacement []byte
	row := s.db.QueryRow(`SELECT handle, replacement FROM prefix_replacements WHERE original_sha256 = ?`, key)
	switch err := row.Scan(&handle, &replacement); {
	case errors.Is(err, sql.ErrNoRows):
		return nil, "", false
	case err != nil:
		// NOT a miss: the entry may well exist. The caller still has to fail safe and
		// forward the original bytes (there is nothing else it can send), so the real
		// guarantee comes from the store's WAL + busy_timeout DSN — log this distinctly
		// so contention that would flip an upstream prefix is visible, not silent.
		if s.logger != nil {
			s.logger.Warn("prefix replacement lookup errored (treated as a miss; upstream prefix may flip)", "error", err)
		}
		return nil, "", false
	}
	if handle == "" || len(replacement) == 0 {
		if s.logger != nil {
			s.logger.Warn("prefix replacement entry incomplete (treated as a miss)")
		}
		return nil, "", false
	}
	return replacement, handle, true
}

// evictPrefixReplacements keeps the table at prefixCacheMaxEntries, dropping the
// least recently used rows. Eviction failure is logged, never propagated: an
// oversized cache is a disk-space problem, not a correctness one.
func (s *Store) evictPrefixReplacements() {
	if _, err := s.db.Exec(
		`DELETE FROM prefix_replacements WHERE original_sha256 NOT IN (
		   SELECT original_sha256 FROM prefix_replacements ORDER BY last_used_at DESC, original_sha256 DESC LIMIT ?
		 )`, prefixCacheMaxEntries,
	); err != nil && s.logger != nil {
		s.logger.Warn("prefix replacement eviction failed", "error", err)
	}
}

// prefixCacheKey binds replacement to semantic plan/transform scope. Same bytes
// selected for a different locked transform must never replay an older winner.
func prefixCacheKey(scope string, original []byte) string {
	sum := sha256.Sum256(append(append([]byte(scope), 0), original...))
	return hex.EncodeToString(sum[:])
}

func prefixCacheNow() string { return time.Now().UTC().Format(storeTSLayout) }

package store

import (
	"bytes"
	"fmt"
	"path/filepath"
	"strings"
	"sync"
	"testing"
)

// TestPrefixReplacementRoundTripAndDurability pins the property the whole cross-turn
// cache-prefix fix rests on: the same original always resolves to the same stored
// replacement bytes, in this process and in the next one.
func TestPrefixReplacementRoundTripAndDurability(t *testing.T) {
	path := filepath.Join(t.TempDir(), "caveman.db")
	original := []byte("the original live-zone block bytes the agent sent")
	replacement := []byte("COMPRESSED\n<<ccr:ccr_deadbeef>>")

	first, err := Open(path, nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	if _, _, ok := first.LookupReplacement("unlocked", original); ok {
		t.Fatal("a fresh store must report a miss, not a guess")
	}
	stored, err := first.RememberReplacement("unlocked", original, replacement, "ccr_deadbeef")
	if err != nil {
		t.Fatalf("remember: %v", err)
	}
	if !bytes.Equal(stored, replacement) {
		t.Fatalf("stored = %q, want %q", stored, replacement)
	}
	if err := first.Close(); err != nil {
		t.Fatalf("close: %v", err)
	}

	// A restart is what the durability claim is about: the replacement must survive
	// the process that created it.
	second, err := Open(path, nil)
	if err != nil {
		t.Fatalf("reopen store: %v", err)
	}
	defer second.Close()
	got, handle, ok := second.LookupReplacement("unlocked", original)
	if !ok {
		t.Fatal("replacement did not survive the restart")
	}
	if !bytes.Equal(got, replacement) || handle != "ccr_deadbeef" {
		t.Fatalf("after restart got %q/%q, want %q/ccr_deadbeef", got, handle, replacement)
	}
	if _, _, ok := second.LookupReplacement("unlocked", []byte("some other block")); ok {
		t.Fatal("an unrelated block must miss")
	}
}

// TestPrefixReplacementFirstWriteWins pins the race rule: once a replacement exists
// for an original, a later writer gets the stored bytes back rather than replacing
// them, so two in-flight requests can never put two different prefixes on the wire.
func TestPrefixReplacementFirstWriteWins(t *testing.T) {
	s, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer s.Close()

	original := []byte("one logical message")
	if _, err := s.RememberReplacement("unlocked", original, []byte("FIRST"), "ccr_1"); err != nil {
		t.Fatalf("remember first: %v", err)
	}
	stored, err := s.RememberReplacement("unlocked", original, []byte("SECOND"), "ccr_1")
	if err != nil {
		t.Fatalf("remember second: %v", err)
	}
	if string(stored) != "FIRST" {
		t.Fatalf("stored = %q, want FIRST — the first write is authoritative", stored)
	}
	got, _, ok := s.LookupReplacement("unlocked", original)
	if !ok || string(got) != "FIRST" {
		t.Fatalf("lookup = %q (ok=%v), want FIRST", got, ok)
	}
}

func TestPrefixReplacementIsScopedByLockedTransform(t *testing.T) {
	s, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer s.Close()
	original := []byte("same provider-visible bytes")
	firstScope := "locked:history::caveman.engine.json.v1"
	secondScope := "locked:history::caveman.engine.text.v1"
	if _, err := s.RememberReplacement(firstScope, original, []byte("JSON"), "ccr_json"); err != nil {
		t.Fatalf("remember first transform: %v", err)
	}
	if _, _, ok := s.LookupReplacement(secondScope, original); ok {
		t.Fatal("different locked transform reused stale replacement")
	}
	stored, err := s.RememberReplacement(secondScope, original, []byte("TEXT"), "ccr_text")
	if err != nil {
		t.Fatalf("remember second transform: %v", err)
	}
	if string(stored) != "TEXT" {
		t.Fatalf("second transform stored %q", stored)
	}
}

// TestPrefixReplacementIncompleteEntryRejected pins fail-closed storage: an entry
// the store cannot honor later is refused now, so the gateway forwards the original
// instead of sending a rewrite it could not reproduce.
func TestPrefixReplacementIncompleteEntryRejected(t *testing.T) {
	s, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer s.Close()

	for _, tc := range []struct {
		name                 string
		original, replacment []byte
		handle               string
	}{
		{"no original", nil, []byte("R"), "ccr_1"},
		{"no replacement", []byte("O"), nil, "ccr_1"},
		{"no handle", []byte("O"), []byte("R"), ""},
	} {
		if _, err := s.RememberReplacement("unlocked", tc.original, tc.replacment, tc.handle); err == nil {
			t.Fatalf("%s: expected an error, got nil", tc.name)
		}
	}
}

// TestPrefixReplacementEviction pins bounded storage: the table never grows past
// prefixCacheMaxEntries. An evicted entry becomes a plain miss, which the gateway
// degrades to forwarding the client's original bytes.
func TestPrefixReplacementEviction(t *testing.T) {
	s, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer s.Close()

	// Seed past the cap directly so the test does not have to write 10k blobs.
	for i := 0; i < prefixCacheMaxEntries+5; i++ {
		key := prefixCacheKey("unlocked", []byte{byte(i / 256), byte(i % 256)})
		if _, err := s.db.Exec(
			`INSERT INTO prefix_replacements (original_sha256, handle, replacement, created_at, last_used_at) VALUES (?,?,?,?,?)`,
			key, "ccr_seed", []byte("R"), prefixCacheNow(), prefixCacheNow(),
		); err != nil {
			t.Fatalf("seed %d: %v", i, err)
		}
	}
	if _, err := s.RememberReplacement("unlocked", []byte("newest block"), []byte("NEW"), "ccr_new"); err != nil {
		t.Fatalf("remember: %v", err)
	}

	var count int
	if err := s.db.QueryRow(`SELECT COUNT(*) FROM prefix_replacements`).Scan(&count); err != nil {
		t.Fatalf("count: %v", err)
	}
	if count > prefixCacheMaxEntries {
		t.Fatalf("rows = %d, want <= %d", count, prefixCacheMaxEntries)
	}
	if _, _, ok := s.LookupReplacement("unlocked", []byte("newest block")); !ok {
		t.Fatal("eviction must keep the most recently used entry")
	}
}

// TestPrefixReplacementConcurrentWrites pins the write half under contention. The
// compress path calls RememberReplacement synchronously on the hot path while the
// same database is taking telemetry inserts, so a SQLITE_BUSY here would stop
// compression for that block. Without the DSN's WAL + busy_timeout pragmas this
// fails ~31/32.
func TestPrefixReplacementConcurrentWrites(t *testing.T) {
	s, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer s.Close()

	const n = 32
	var wg sync.WaitGroup
	errs := make([]error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			original := []byte(fmt.Sprintf("block-%d-%s", i, strings.Repeat("x", 512)))
			_, errs[i] = s.RememberReplacement("unlocked", original, []byte("R"), "ccr_c")
		}(i)
	}
	wg.Wait()
	for i, err := range errs {
		if err != nil {
			t.Fatalf("concurrent RememberReplacement %d failed: %v", i, err)
		}
	}
}

// TestPrefixReplacementLookupUnderWriteContention is the decisive one. A lookup
// that errors is reported as a miss, and the gateway then forwards the client's
// ORIGINAL bytes for a frozen block it already compressed — the upstream prefix
// flips, non-deterministically, per turn. Without the DSN pragmas this misses
// ~9/24.
func TestPrefixReplacementLookupUnderWriteContention(t *testing.T) {
	s, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer s.Close()

	frozen := []byte("a frozen block compressed on an earlier turn")
	if _, err := s.RememberReplacement("unlocked", frozen, []byte("STABLE-REPLACEMENT"), "ccr_hot"); err != nil {
		t.Fatalf("seed: %v", err)
	}

	const readers, writers = 24, 24
	var wg sync.WaitGroup
	var mu sync.Mutex
	misses := 0
	for i := 0; i < writers; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			_, _ = s.RememberReplacement("unlocked", []byte(fmt.Sprintf("churn-%d", i)), []byte("R"), "ccr_c")
		}(i)
	}
	for i := 0; i < readers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if _, _, ok := s.LookupReplacement("unlocked", frozen); !ok {
				mu.Lock()
				misses++
				mu.Unlock()
			}
		}()
	}
	wg.Wait()

	if misses > 0 {
		t.Fatalf("%d/%d lookups of a STORED replacement reported a miss under contention — each one flips the upstream prefix back to the client's originals", misses, readers)
	}
}

package store

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"path/filepath"
	"strings"
	"sync"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/internal/gateway"
	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/anthropic"
)

// End-to-end cross-turn stability wired to the REAL file-backed SQLite replacement
// cache the binary uses (cmd/caveman-proxy passes the spend store as
// gateway.PrefixCache), not the gateway package's in-memory test double. It answers
// the production question: does a message this proxy already compressed keep going
// upstream as the SAME bytes when the proxy is serving more than one request at a
// time? The store is also the telemetry sink, so a lookup always races a write.

type e2eTransport struct {
	mu     sync.Mutex
	bodies [][]byte
}

func (t *e2eTransport) RoundTrip(r *http.Request) (*http.Response, error) {
	body, _ := io.ReadAll(r.Body)
	t.mu.Lock()
	t.bodies = append(t.bodies, append([]byte(nil), body...))
	t.mu.Unlock()
	return &http.Response{
		StatusCode: 200,
		Header:     http.Header{"Content-Type": {"application/json"}},
		Body: io.NopCloser(strings.NewReader(
			`{"id":"msg","type":"message","model":"claude-sonnet-4-6","content":[{"type":"text","text":"ok"}],"usage":{"input_tokens":10,"output_tokens":2}}`)),
		Request: r,
	}, nil
}

type e2eAuth struct{}

func (e2eAuth) Authenticate(context.Context, *http.Request) (gateway.RequestContext, error) {
	return gateway.RequestContext{Label: "local", RuntimeMode: "compress"}, nil
}

type e2eCreds struct{}

func (e2eCreds) Resolve(string, *http.Request) providers.Credential {
	return providers.Credential{Key: "sk-ant-oat-test", Scheme: "bearer"}
}

type e2eSink struct{}

func (e2eSink) Record(gateway.RequestRecord) {}

// e2eCompressor is deterministic per content, so any byte difference upstream comes
// from the cache, never from the compressor.
type e2eCompressor struct{}

func e2eHandle(b []byte) string {
	sum := sha256.Sum256(b)
	return "ccr_" + hex.EncodeToString(sum[:16])
}

func (e2eCompressor) CompressSegment(seg []byte) ([]byte, int, int) {
	return []byte("CMP:" + e2eHandle(seg)), 100, 40
}

func (e2eCompressor) StoreOriginal(b []byte) (string, error) { return e2eHandle(b), nil }

func e2eConversation(userTexts ...string) string {
	msgs := make([]string, 0, len(userTexts)*2)
	for i, text := range userTexts {
		if i > 0 {
			msgs = append(msgs, `{"role":"assistant","content":[{"type":"text","text":"assistant reply"}]}`)
		}
		msgs = append(msgs, `{"role":"user","content":[{"type":"text","text":"`+text+`","cache_control":{"type":"ephemeral"}}]}`)
	}
	return `{"model":"claude-sonnet-4-6","max_tokens":1024,"messages":[` + strings.Join(msgs, ",") + `]}`
}

var e2eHeaders = map[string]string{
	"user-agent":        "claude-cli/1.0.0",
	"authorization":     "Bearer sk-ant-oat-test",
	"anthropic-beta":    "oauth-2025-04-20",
	"anthropic-version": "2023-06-01",
}

func e2eServe(srv *gateway.Server, body string) {
	req := httptest.NewRequest(http.MethodPost, "/v1/messages", strings.NewReader(body))
	for k, v := range e2eHeaders {
		req.Header.Set(k, v)
	}
	srv.Handler().ServeHTTP(httptest.NewRecorder(), req)
}

// TestE2EPrefixStabilityWithRealStore fires turn 1 serially (establishing a stored
// replacement for t1), then fires N concurrent turn-2 requests that all carry t1 as
// a FROZEN block. Every one of them must send t1's stored replacement. Any request
// that sends t1's original bytes is a cross-turn prefix divergence. Before the
// store's WAL + busy_timeout DSN pragmas this failed ~7/16.
func TestE2EPrefixStabilityWithRealStore(t *testing.T) {
	st, err := Open(filepath.Join(t.TempDir(), "caveman.db"), nil)
	if err != nil {
		t.Fatalf("open store: %v", err)
	}
	defer st.Close()

	rt := &e2eTransport{}
	srv := gateway.New(gateway.Config{
		Adapters:       []providers.Adapter{anthropic.New("https://upstream.test")},
		Auth:           e2eAuth{},
		Creds:          e2eCreds{},
		Sink:           e2eSink{},
		Compressor:     e2eCompressor{},
		PrefixCache:    st,
		HTTPClient:     &http.Client{Transport: rt},
		RecoveryViaMCP: true,
	})

	t1 := strings.Repeat("turn one client bytes ", 40)
	e2eServe(srv, e2eConversation(t1))
	want := "CMP:" + e2eHandle([]byte(t1))
	if len(rt.bodies) != 1 || !strings.Contains(string(rt.bodies[0]), want) {
		t.Fatalf("turn 1 did not compress the live zone:\n%s", rt.bodies[0])
	}
	rt.mu.Lock()
	rt.bodies = nil
	rt.mu.Unlock()

	const n = 16
	var wg sync.WaitGroup
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			e2eServe(srv, e2eConversation(t1, strings.Repeat(fmt.Sprintf("turn two variant %d ", i), 40)))
		}(i)
	}
	wg.Wait()

	rt.mu.Lock()
	defer rt.mu.Unlock()
	diverged := 0
	for _, b := range rt.bodies {
		if !strings.Contains(string(b), want) || strings.Contains(string(b), t1) {
			diverged++
		}
	}
	if diverged > 0 {
		t.Fatalf("%d/%d concurrent turn-2 requests flipped the frozen prefix back to the client's original bytes", diverged, len(rt.bodies))
	}
}

