package store

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"regexp"
	"sort"
	"strings"
)

// recurring.go mines heavy context blocks that recur across sessions — the
// "re-established context" a developer pastes or restates session after session.
// It is the detector behind the recurring_context sink class, whose fix is
// cavemem_offload: move the block into cavemem so it's recalled compactly instead
// of re-loaded every turn (see docs/CAVEMAN_LEARN_SPEC.md §5/§10).
//
// HONESTY: the miner is deterministic and read-only. It persists only
// fingerprints, counts, token weights, and content *locators* in sink evidence —
// never the raw block body. The body stays on disk; the consent-gated editing
// skill re-derives it locally from the locator (file + line + block index) and
// verifies it against content_sha256 before offloading.
const (
	// recurSegmenterVersion / recurNormalizationVer are a shared contract with the
	// editing skill: the skill re-segments a turn the same way to locate a block by
	// (jsonl_line, block_index) and verifies it by content_sha256. Bump on change.
	recurSegmenterVersion = "v1"
	recurNormalizationVer = "v1"

	minBlockTokens        = 180 // a block must weigh at least this to be a candidate
	minRecurrenceSessions = 3   // must appear in at least this many distinct sessions
	maxLocatorSamples     = 5   // cap locator samples per fingerprint (refs, never bodies)
)

var (
	reBlankLine  = regexp.MustCompile(`\n[ \t]*\n`)
	reWhitespace = regexp.MustCompile(`\s+`)
	reDigits     = regexp.MustCompile(`\d+`)
)

// blockLocator points at one occurrence of a block without carrying its body.
// For transcripts the address is (jsonl_line, block_index); the skill re-reads
// the line, re-segments it (segmenter v1), picks block_index, and verifies the
// raw block against ContentSHA before acting.
type blockLocator struct {
	RootKind   string `json:"root_kind"`
	RelPath    string `json:"rel_path"`
	JSONLLine  int    `json:"jsonl_line"`
	BlockIndex int    `json:"block_index"`
	ContentSHA string `json:"content_sha256"`
}

// recurringOccurrence is uncapped scan-local position data used only to weight
// repeated context against later provider-counted turns. Unlike Locators it is
// never emitted in sink evidence and carries no block body.
type recurringOccurrence struct {
	RootKind  string
	RelPath   string
	JSONLLine int
	Timestamp string
	Tokens    int
	Side      bool
}

type fpAgg struct {
	sessions    map[string]bool
	occurrences int
	blockTokens int
	totalTokens int
	blockLines  int
	locators    []blockLocator
	positions   []recurringOccurrence
	firstSeen   string
	lastSeen    string
}

type recurringEntry struct {
	Fingerprint string
	Sessions    int
	Occurrences int
	BlockTokens int
	TotalTokens int
	BlockLines  int
	Locators    []blockLocator
	Positions   []recurringOccurrence
	First, Last string
}

type recurringResult struct {
	Repaste []recurringEntry
}

type recurringMiner struct {
	byFP           map[string]*fpAgg
	trackPositions bool
}

func newRecurringMiner() *recurringMiner {
	return &recurringMiner{byFP: map[string]*fpAgg{}}
}

// newRecurringStreamMiner retains occurrence coordinates for retro stream
// weighting. The ordinary learn scan deliberately uses newRecurringMiner so
// its memory stays bounded by locator samples rather than transcript length.
func newRecurringStreamMiner() *recurringMiner {
	return &recurringMiner{byFP: map[string]*fpAgg{}, trackPositions: true}
}

// merge folds one session-local miner into the scan-wide miner. Callers merge
// sessions in path order so capped locator samples stay deterministic even when
// transcript parsing runs concurrently.
func (m *recurringMiner) merge(other *recurringMiner) {
	if m == nil || other == nil {
		return
	}
	for fp, src := range other.byFP {
		dst := m.byFP[fp]
		if dst == nil {
			dst = &fpAgg{sessions: map[string]bool{}}
			m.byFP[fp] = dst
		}
		for session := range src.sessions {
			dst.sessions[session] = true
		}
		dst.occurrences += src.occurrences
		dst.totalTokens += src.totalTokens
		if m.trackPositions {
			dst.positions = append(dst.positions, src.positions...)
		}
		if src.blockTokens > dst.blockTokens {
			dst.blockTokens = src.blockTokens
			dst.blockLines = src.blockLines
		}
		remaining := maxLocatorSamples - len(dst.locators)
		if remaining > len(src.locators) {
			remaining = len(src.locators)
		}
		if remaining > 0 {
			dst.locators = append(dst.locators, src.locators[:remaining]...)
		}
		if src.firstSeen != "" && (dst.firstSeen == "" || src.firstSeen < dst.firstSeen) {
			dst.firstSeen = src.firstSeen
		}
		if src.lastSeen > dst.lastSeen {
			dst.lastSeen = src.lastSeen
		}
	}
}

// segmentBlocks splits one text payload into candidate blocks on blank-line
// boundaries, preserving each block's internal bytes verbatim. The editing skill
// reproduces this exactly to locate a block by index.
func segmentBlocks(text string) []string {
	parts := reBlankLine.Split(text, -1)
	out := make([]string, 0, len(parts))
	for _, p := range parts {
		p = strings.Trim(p, "\n")
		if strings.TrimSpace(p) == "" {
			continue
		}
		out = append(out, p)
	}
	return out
}

// extractTurnBlocks pulls the human-readable text payloads out of one transcript
// turn (message.content as a string, or "text" blocks in a list) and segments
// them in document order. Tool inputs and tool results are excluded — the target
// is re-established narrative/context, not tool noise.
func extractTurnBlocks(obj map[string]any) []string {
	msg := asMap(obj["message"])
	content := msg["content"]
	if content == nil {
		content = obj["content"]
	}
	var payloads []string
	switch c := content.(type) {
	case string:
		payloads = append(payloads, c)
	case []any:
		for _, item := range c {
			block := asMap(item)
			if block == nil || block["type"] != "text" {
				continue
			}
			if t := firstString(block["text"]); t != "" {
				payloads = append(payloads, t)
			}
		}
	}
	var blocks []string
	for _, p := range payloads {
		blocks = append(blocks, segmentBlocks(p)...)
	}
	return blocks
}

// normalizeBlock is the internal grouping key (lowercase, digit-run masked,
// whitespace collapsed) so the same block with trivial numeric/whitespace drift
// still collides. It is the proxy's concern only — the skill never needs it.
func normalizeBlock(block string) string {
	s := strings.ToLower(block)
	s = reDigits.ReplaceAllString(s, "#")
	s = reWhitespace.ReplaceAllString(s, " ")
	return strings.TrimSpace(s)
}

func contentSHA256(raw string) string {
	sum := sha256.Sum256([]byte(raw))
	return hex.EncodeToString(sum[:])
}

// observeTurn segments one transcript turn and records each qualifying block's
// fingerprint, distinct session, and a capped locator sample. It never stores the
// block text.
func (m *recurringMiner) observeTurn(rootKind, relPath string, jsonlLine int, ts string, obj map[string]any) {
	if m == nil {
		return
	}
	for idx, raw := range extractTurnBlocks(obj) {
		tokens := estimateTokens(raw)
		if tokens < minBlockTokens {
			continue
		}
		fp := hashText(normalizeBlock(raw))
		agg := m.byFP[fp]
		if agg == nil {
			agg = &fpAgg{sessions: map[string]bool{}}
			m.byFP[fp] = agg
		}
		agg.sessions[relPath] = true
		agg.occurrences++
		agg.totalTokens += tokens
		if m.trackPositions {
			agg.positions = append(agg.positions, recurringOccurrence{
				RootKind: rootKind, RelPath: relPath, JSONLLine: jsonlLine,
				Timestamp: ts, Tokens: tokens, Side: obj["isSidechain"] == true,
			})
		}
		if tokens > agg.blockTokens {
			agg.blockTokens = tokens
			agg.blockLines = strings.Count(raw, "\n") + 1
		}
		if len(agg.locators) < maxLocatorSamples {
			agg.locators = append(agg.locators, blockLocator{
				RootKind: rootKind, RelPath: relPath, JSONLLine: jsonlLine,
				BlockIndex: idx, ContentSHA: contentSHA256(raw),
			})
		}
		if ts != "" {
			if agg.firstSeen == "" || ts < agg.firstSeen {
				agg.firstSeen = ts
			}
			if ts > agg.lastSeen {
				agg.lastSeen = ts
			}
		}
	}
}

// result applies the recurrence + weight thresholds and returns entries ordered
// deterministically (by total recurring weight, then fingerprint).
func (m *recurringMiner) result() recurringResult {
	var res recurringResult
	if m == nil {
		return res
	}
	for fp, agg := range m.byFP {
		if len(agg.sessions) < minRecurrenceSessions {
			continue
		}
		res.Repaste = append(res.Repaste, recurringEntry{
			Fingerprint: fp,
			Sessions:    len(agg.sessions),
			Occurrences: agg.occurrences,
			BlockTokens: agg.blockTokens,
			TotalTokens: agg.totalTokens,
			BlockLines:  agg.blockLines,
			Locators:    agg.locators,
			Positions:   append([]recurringOccurrence(nil), agg.positions...),
			First:       agg.firstSeen,
			Last:        agg.lastSeen,
		})
	}
	sort.SliceStable(res.Repaste, func(i, j int) bool {
		wi := res.Repaste[i].TotalTokens
		wj := res.Repaste[j].TotalTokens
		if wi != wj {
			return wi > wj
		}
		return res.Repaste[i].Fingerprint < res.Repaste[j].Fingerprint
	})
	return res
}

// recurringPerTurn amortizes actual observed occurrence sizes over scanned
// turns. Normalized variants can differ sharply in raw size, so multiplying the
// largest occurrence by count would overstate inferred headroom.
func recurringPerTurn(e recurringEntry, turns int) int {
	if turns <= 0 {
		return e.BlockTokens
	}
	return (e.TotalTokens + turns - 1) / turns
}

// recurringSinks turns mined cross-session re-paste into recurring_context sinks
// whose fix is cavemem_offload. Soft, currency-free, evidence carries no body.
func recurringSinks(rec recurringResult, beh behaviorScan, turnsPerDay float64) []Sink {
	var sinks []Sink
	for _, e := range rec.Repaste {
		perTurn := recurringPerTurn(e, beh.Turns)
		sinks = append(sinks, Sink{
			SinkID:           "recurring_context:repaste:" + e.Fingerprint,
			Title:            fmt.Sprintf("A recurring context pattern (up to ~%d tokens) was re-established across %d sessions", e.BlockTokens, e.Sessions),
			Class:            classRecurringContext,
			Basis:            observedLocal,
			TokensPerTurn:    int64(perTurn),
			TokensPerDayRate: rate(perTurn, turnsPerDay),
			Framing:          framingForward,
			Suggestion:       "Consider offloading this to cavemem so it's recalled compactly instead of re-established each session. (Recurrence is window-bounded, not proof the content is unneeded.)",
			Evidence: map[string]any{
				"fix_kind":                "cavemem_offload",
				"fingerprint":             e.Fingerprint,
				"recurrence_sessions":     e.Sessions,
				"occurrences_total":       e.Occurrences,
				"block_tokens":            e.BlockTokens,
				"occurrence_tokens_total": e.TotalTokens,
				"block_lines":             e.BlockLines,
				"first_seen":              e.First,
				"last_seen":               e.Last,
				"segmenter":               recurSegmenterVersion,
				"normalization":           recurNormalizationVer,
				"topic_label":             "recurring context block " + e.Fingerprint,
				"locators":                e.Locators,
			},
		})
	}
	return sinks
}

package store

import (
	"encoding/json"
	"fmt"
	"html/template"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

func DefaultReportPath(home, trialID string) string {
	if trialID == "" {
		trialID = "local"
	}
	return filepath.Join(home, "reports", "caveman-trial-"+trialID+".html")
}

func DefaultLearnReportPath(home string) string {
	return filepath.Join(home, "reports", "caveman-learn.html")
}

func DefaultLearnJSONPath(home string) string {
	return filepath.Join(home, "reports", "caveman-learn.json")
}

type LearnSnapshot struct {
	LearnPlan
	Moves       int    `json:"moves"`
	GeneratedAt string `json:"generated_at"`
	Generation  string `json:"generation,omitempty"`
}

// WriteLearnSidecars persists the current machine-readable plan plus a bounded
// dated history used by local learn diffs. Both states with and without moves
// are written; HTML existence is never used as plan-state evidence.
func (s *Store) WriteLearnSidecars(home string, plan LearnPlan, now time.Time, generation string) (string, error) {
	dir := filepath.Join(home, "reports")
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return "", err
	}
	snapshot := LearnSnapshot{
		LearnPlan:   plan,
		Moves:       len(plan.Sinks),
		GeneratedAt: now.UTC().Format(time.RFC3339),
		Generation:  generation,
	}
	raw, err := json.MarshalIndent(snapshot, "", "  ")
	if err != nil {
		return "", err
	}
	raw = append(raw, '\n')
	current := DefaultLearnJSONPath(home)
	if err := os.WriteFile(current, raw, 0o600); err != nil {
		return "", err
	}
	if err := os.Chmod(current, 0o600); err != nil {
		return "", err
	}
	history := filepath.Join(dir, "caveman-learn."+now.UTC().Format("2006-01-02")+".json")
	if err := os.WriteFile(history, raw, 0o600); err != nil {
		return "", err
	}
	if err := os.Chmod(history, 0o600); err != nil {
		return "", err
	}
	entries, _ := filepath.Glob(filepath.Join(dir, "caveman-learn.????-??-??.json"))
	sort.Strings(entries)
	for len(entries) > 8 {
		_ = os.Remove(entries[0])
		entries = entries[1:]
	}
	return current, nil
}

func (s *Store) WriteLearnHTML(plan LearnPlan, outPath string) error {
	if outPath == "" {
		return fmt.Errorf("report path is required")
	}
	if err := os.MkdirAll(filepath.Dir(outPath), 0o700); err != nil {
		return err
	}
	f, err := os.OpenFile(outPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	defer f.Close()
	return learnTemplate.Execute(f, struct {
		Plan      LearnPlan
		Generated string
	}{Plan: plan, Generated: time.Now().UTC().Format(time.RFC3339)})
}

func (s *Store) WriteTrialHTML(plan TrialPlan, outPath string) error {
	if outPath == "" {
		return fmt.Errorf("report path is required")
	}
	if err := os.MkdirAll(filepath.Dir(outPath), 0o700); err != nil {
		return err
	}
	f, err := os.OpenFile(outPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	defer f.Close()
	return trialTemplate.Execute(f, struct {
		Plan      TrialPlan
		Generated string
	}{Plan: plan, Generated: time.Now().UTC().Format(time.RFC3339)})
}

func (s *Store) ExportTrial(plan TrialPlan, outDir string) (map[string]string, error) {
	if outDir == "" {
		return nil, fmt.Errorf("export directory is required")
	}
	if err := os.MkdirAll(outDir, 0o700); err != nil {
		return nil, err
	}
	trialPath := filepath.Join(outDir, "trial.json")
	raw, _ := json.MarshalIndent(plan, "", "  ")
	if err := os.WriteFile(trialPath, append(raw, '\n'), 0o600); err != nil {
		return nil, err
	}
	spansPath := filepath.Join(outDir, "spans.jsonl")
	f, err := os.OpenFile(spansPath, os.O_CREATE|os.O_TRUNC|os.O_WRONLY, 0o600)
	if err != nil {
		return nil, err
	}
	if err := s.writeExportSpans(f, plan); err != nil {
		_ = f.Close()
		return nil, err
	}
	if err := f.Close(); err != nil {
		return nil, err
	}
	return map[string]string{"trial_json": trialPath, "spans_jsonl": spansPath}, nil
}

func (s *Store) writeExportSpans(f *os.File, plan TrialPlan) error {
	enc := json.NewEncoder(f)
	label := ""
	if plan.TrialID != "" {
		label = "trial:" + plan.TrialID
	}
	rows, err := s.db.Query(
		`SELECT request_id, COALESCE(trace_id, ''), ts, COALESCE(label, ''),
		        COALESCE(agent_slug, ''), COALESCE(provider, ''), COALESCE(model, ''),
		        COALESCE(endpoint, ''), COALESCE(runtime_mode, ''), COALESCE(optimization_ids, ''),
		        COALESCE(input_tokens, 0), COALESCE(output_tokens, 0),
		        COALESCE(cached_input_tokens, 0), COALESCE(cache_creation_input_tokens, 0),
		        COALESCE(reasoning_tokens, 0),
		        COALESCE(total_cost_usd, 0), basis
		   FROM requests
		  WHERE (? = '' OR label = ?)
		  ORDER BY ts, id`,
		label, label,
	)
	if err != nil {
		return err
	}
	for rows.Next() {
		var requestID, traceID, ts, rowLabel, agent, provider, model, endpoint, mode, optimizers, basis string
		var input, output, cached, cacheCreation, reasoning int64
		var totalCost float64
		if err := rows.Scan(&requestID, &traceID, &ts, &rowLabel, &agent, &provider, &model, &endpoint, &mode, &optimizers, &input, &output, &cached, &cacheCreation, &reasoning, &totalCost, &basis); err != nil {
			_ = rows.Close()
			return err
		}
		if err := enc.Encode(map[string]any{
			"span_kind":                   "request",
			"source_kind":                 sourceCaveProxy,
			"trial_id":                    plan.TrialID,
			"request_id":                  requestID,
			"trace_id":                    traceID,
			"ts":                          ts,
			"label":                       rowLabel,
			"agent_slug":                  agent,
			"provider":                    provider,
			"model":                       model,
			"endpoint":                    endpoint,
			"runtime_mode":                mode,
			"optimization_ids":            optimizers,
			"input_tokens":                input,
			"output_tokens":               output,
			"cached_input_tokens":         cached,
			"cache_creation_input_tokens": cacheCreation,
			"reasoning_tokens":            reasoning,
			"total_cost_usd":              roundUSD(totalCost),
			"basis":                       basis,
		}); err != nil {
			_ = rows.Close()
			return err
		}
	}
	if err := rows.Err(); err != nil {
		_ = rows.Close()
		return err
	}
	if err := rows.Close(); err != nil {
		return err
	}

	imported, err := s.db.Query(
		`SELECT source_kind, COALESCE(source_path, ''), event_id, ts,
		        COALESCE(agent_slug, ''), COALESCE(provider, ''), COALESCE(model, ''),
		        COALESCE(requests, 0), COALESCE(input_tokens, 0), COALESCE(output_tokens, 0),
		        COALESCE(cached_input_tokens, 0), COALESCE(cache_creation_input_tokens, 0),
		        COALESCE(reasoning_tokens, 0),
		        COALESCE(total_cost_usd, 0), basis
		   FROM usage_events
		  ORDER BY ts, id`,
	)
	if err != nil {
		return err
	}
	for imported.Next() {
		var sourceKind, sourcePath, eventID, ts, agent, provider, model, basis string
		var requests, input, output, cached, cacheCreation, reasoning int64
		var totalCost float64
		if err := imported.Scan(&sourceKind, &sourcePath, &eventID, &ts, &agent, &provider, &model, &requests, &input, &output, &cached, &cacheCreation, &reasoning, &totalCost, &basis); err != nil {
			_ = imported.Close()
			return err
		}
		if err := enc.Encode(map[string]any{
			"span_kind":                   "usage_event",
			"source_kind":                 sourceKind,
			"source_path":                 sourcePath,
			"event_id":                    eventID,
			"ts":                          ts,
			"agent_slug":                  agent,
			"provider":                    provider,
			"model":                       model,
			"requests":                    requests,
			"input_tokens":                input,
			"output_tokens":               output,
			"cached_input_tokens":         cached,
			"cache_creation_input_tokens": cacheCreation,
			"reasoning_tokens":            reasoning,
			"total_cost_usd":              roundUSD(totalCost),
			"basis":                       basis,
		}); err != nil {
			_ = imported.Close()
			return err
		}
	}
	if err := imported.Err(); err != nil {
		_ = imported.Close()
		return err
	}
	return imported.Close()
}

var learnTemplate = template.Must(template.New("learn").Funcs(template.FuncMap{
	"reducible": func(sinks []Sink) []Sink {
		out := []Sink{}
		for _, s := range sinks {
			if s.Class == classReducible {
				out = append(out, s)
			}
		}
		return out
	},
	"behavioral": func(sinks []Sink) []Sink {
		out := []Sink{}
		for _, s := range sinks {
			if s.Class == classBehavioral {
				out = append(out, s)
			}
		}
		return out
	},
	"recurring": func(sinks []Sink) []Sink {
		out := []Sink{}
		for _, s := range sinks {
			if s.Class == classRecurringContext {
				out = append(out, s)
			}
		}
		return out
	},
	"classClass": func(class string) string {
		switch class {
		case classReducible:
			return "tag reducible"
		case classBehavioral:
			return "tag behavioral"
		case classRecurringContext:
			return "tag recurring"
		default:
			return "tag loadbearing"
		}
	},
	"basisClass": func(basis string) string {
		if strings.EqualFold(basis, "verified") {
			return "bad"
		}
		return "basis"
	},
	"scoreBasis": func(basis string) string {
		if strings.EqualFold(basis, "verified") {
			return "inferred"
		}
		return basis
	},
	"comma": func(v int64) string {
		s := fmt.Sprintf("%d", v)
		n := len(s)
		if n <= 3 {
			return s
		}
		var b strings.Builder
		pre := n % 3
		if pre > 0 {
			b.WriteString(s[:pre])
			if n > pre {
				b.WriteString(",")
			}
		}
		for i := pre; i < n; i += 3 {
			b.WriteString(s[i : i+3])
			if i+3 < n {
				b.WriteString(",")
			}
		}
		return b.String()
	},
	"evidence": func(m map[string]any) string {
		if len(m) == 0 {
			return ""
		}
		keys := make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		parts := make([]string, 0, len(keys))
		for _, k := range keys {
			parts = append(parts, fmt.Sprintf("%s=%v", k, m[k]))
		}
		return strings.Join(parts, " · ")
	},
}).Parse(`<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Caveman Learn Report</title>
<style>
:root{color-scheme:light;--ink:#111;--muted:#666;--line:#ddd;--bg:#fafafa;--accent:#0f766e;--warn:#92400e}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
main{max-width:1040px;margin:0 auto;padding:32px 20px 56px}header{border-bottom:2px solid var(--ink);padding-bottom:18px;margin-bottom:24px}
h1{font-size:32px;line-height:1.1;margin:0 0 8px}h2{font-size:20px;margin:28px 0 10px}
p{margin:0 0 10px}.muted{color:var(--muted)}.basis,.bad,.tag{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 8px;font-size:12px;background:white}.bad{border-color:#f59e0b;color:var(--warn)}
.tag.reducible{border-color:#0f766e;color:#0f766e}.tag.behavioral{border-color:#6366f1;color:#4338ca}.tag.recurring{border-color:#b45309;color:#b45309}.tag.loadbearing{color:var(--muted)}
.score{display:flex;align-items:center;gap:18px;background:white;border:1px solid var(--line);border-radius:10px;padding:18px}
.score .num{font-size:46px;font-weight:800;line-height:1;color:var(--accent)}.score .of{font-size:16px;color:var(--muted)}
.components{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin:12px 0}.comp{background:white;border:1px solid var(--line);border-radius:8px;padding:10px}.comp .k{font-size:12px;color:var(--muted)}.comp .p{font-size:18px;font-weight:700;margin-top:3px}.comp .d{font-size:11px;color:var(--muted);margin-top:4px}
table{border-collapse:collapse;width:100%;background:white;border:1px solid var(--line);border-radius:8px;overflow:hidden}th,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;color:var(--muted);font-weight:600;background:#f3f4f6}tr:last-child td{border-bottom:0}
.section-note{color:var(--muted);margin-bottom:10px}.ev{font-size:12px;color:var(--muted);margin-top:4px}.caveats li{margin:6px 0}.empty{padding:12px;background:white;border:1px solid var(--line);border-radius:8px;color:var(--muted)}
@media(max-width:780px){.components{grid-template-columns:repeat(2,minmax(0,1fr))}table{font-size:12px}main{padding:22px 12px}}
</style>
</head>
<body>
<main>
<header>
  <h1>Caveman Learn Report</h1>
  <p class="muted">generated {{.Generated}} · <span class="{{basisClass .Plan.Basis}}">{{.Plan.Basis}}</span> · window {{.Plan.Window.Since}}</p>
</header>

<section>
  <h2>Cave Score</h2>
  <p class="section-note">Setup leanness, starting at 100 and subtracting capped penalties. Inferred, local-only, and distinct from the Cloud Cave Score. Not a savings or dollar figure.</p>
  <div class="score"><div><span class="num">{{.Plan.CaveScore.Score}}</span><span class="of"> / 100</span></div><div class="muted">basis: {{scoreBasis .Plan.CaveScore.Basis}}</div></div>
  <div class="components">
    {{range .Plan.CaveScore.Components}}
    <div class="comp"><div class="k">{{.Key}}</div><div class="p">{{if .Measured}}-{{.Penalty}}{{else}}n/a{{end}}</div><div class="d">{{if .Measured}}{{.Detail}}{{else}}not measured{{end}}</div></div>
    {{end}}
  </div>
</section>

<section>
  <h2>Biggest Token Sinks</h2>
  <p class="section-note">Ranked by forward tokens/day rate. Class A facts are asserted; Class B observations carry softened suggestions with their evidence.</p>
  {{if .Plan.Sinks}}
  <table>
    <thead><tr><th>Sink</th><th>Class</th><th>Tokens/turn</th><th>Tokens/day</th><th>Basis</th></tr></thead>
    <tbody>
      {{range .Plan.Sinks}}
      <tr><td>{{.Title}}<div class="muted">{{.SinkID}}</div>{{if .Suggestion}}<div class="ev">{{.Suggestion}}</div>{{end}}{{if .Evidence}}<div class="ev">{{evidence .Evidence}}</div>{{end}}</td><td><span class="{{classClass .Class}}">{{.Class}}</span></td><td>{{comma .TokensPerTurn}}</td><td>{{comma .TokensPerDayRate}}</td><td><span class="{{basisClass .Basis}}">{{.Basis}}</span></td></tr>
      {{end}}
    </tbody>
  </table>
  {{else}}<div class="empty">No token sinks found yet.</div>{{end}}
</section>

<section>
  <h2>What's Safely Reducible</h2>
  <p class="section-note">Config-bloat sinks with a mechanical, net-token-negative fix. The editing skill proposes a diff per item; you approve each one.</p>
  {{$red := reducible .Plan.Sinks}}
  {{if $red}}
  <table>
    <thead><tr><th>Move</th><th>Tokens/turn</th><th>Suggested fix</th></tr></thead>
    <tbody>
      {{range $red}}
      <tr><td>{{.Title}}</td><td>{{comma .TokensPerTurn}}</td><td>{{.Suggestion}}</td></tr>
      {{end}}
    </tbody>
  </table>
  {{else}}<div class="empty">No safely-reducible config sinks detected.</div>{{end}}
</section>

<section>
  <h2>Recurring Context (offload to cavemem)</h2>
  <p class="section-note">Heavy context re-established across sessions. The editing skill can offload each block to cavemem — recalled on demand instead of re-pasted every turn — only when that measurably reduces tokens/turn. Counts and locators only; no block content is stored.</p>
  {{$rec := recurring .Plan.Sinks}}
  {{if $rec}}
  <table>
