			body:   `{"usageMetadata":{"promptTokenCount":100,"toolUsePromptTokenCount":20,"candidatesTokenCount":30,"thoughtsTokenCount":40,"totalTokenCount":190}}`,
			wantIn: 120, wantOut: 70,
		},
		{
