			got := sc.Usage()
			want := "content_decode_failed/" + encoding
			if got.PricingUnsupportedReason != want || got.Complete() {
				t.Fatalf("corrupt %s usage = %+v, want reason %q", encoding, got, want)
			}
		})
	}
}

func TestUsageScanner_DecodedSideCopyHonorsScanLimit(t *testing.T) {
	const limit = 128
	wire := compressUsagePayload(t, "gzip", []byte(strings.Repeat("x", 4096)))
	if len(wire) >= limit {
		t.Fatalf("test requires compressed bytes below the scan limit, got %d", len(wire))
	}
	sc := (Base{Provider: "openai"}).NewUsageScanner(http.Header{"Content-Encoding": []string{"gzip"}})
	sc.SetLimit(limit)
	_, _ = sc.Write(wire)
	got := sc.Usage()
	if got.PricingUnsupportedReason != "response_scan_limit_exceeded" || got.Complete() {
		t.Fatalf("oversized decoded usage = %+v", got)
	}
}

func TestUsageScanner_StackedEncodingIsExplicitlyUnpriced(t *testing.T) {
	wire := compressUsagePayload(t, "gzip", []byte(`{"usage":{"input_tokens":10,"output_tokens":5}}`))
	sc := (Base{Provider: "openai"}).NewUsageScanner(http.Header{"Content-Encoding": []string{"gzip, br"}})
	_, _ = sc.Write(wire)
	got := sc.Usage()
	if got.PricingUnsupportedReason != "unsupported_content_encoding/stacked" || got.Complete() {
		t.Fatalf("stacked encoding usage = %+v", got)
	}
}

func compressUsagePayload(t *testing.T, encoding string, body []byte) []byte {
	t.Helper()
	var compressed bytes.Buffer
	var (
		writer interface {
			Write([]byte) (int, error)
			Close() error
		}
		err error
	)
	switch encoding {
	case "gzip":
		writer = gzip.NewWriter(&compressed)
	case "deflate":
		writer = zlib.NewWriter(&compressed)
	case "zstd":
		writer, err = zstd.NewWriter(&compressed)
		if err != nil {
			t.Fatal(err)
		}
	default:
		t.Fatalf("unsupported test encoding %q", encoding)
	}
	if _, err := writer.Write(body); err != nil {
		t.Fatal(err)
	}
	if err := writer.Close(); err != nil {
		t.Fatal(err)
	}
	return append([]byte(nil), compressed.Bytes()...)
}

func TestUsageScanner_UnsupportedEncodingIsExplicitlyUnpriced(t *testing.T) {
	sc := (Base{Provider: "openai"}).NewUsageScanner(http.Header{"Content-Encoding": []string{"br"}})
	_, _ = sc.Write([]byte("compressed"))
	got := sc.Usage()
	if got.PricingUnsupportedReason != "unsupported_content_encoding/br" || got.Complete() {
		t.Fatalf("unsupported encoding usage = %+v", got)
	}
}

func TestUsageScanner_RecoversCompleteTerminalUsageFromBoundedTail(t *testing.T) {
	sc := &UsageScanner{provider: "openai", limit: 256}
	_, _ = sc.Write([]byte(strings.Repeat("x", 1024)))
	_, _ = sc.Write([]byte("\ndata: {\"type\":\"response.completed\",\"usage\":{\"input_tokens\":20,\"output_tokens\":8,\"total_tokens\":28}}\n\n"))
	got := sc.Usage()
	if !got.Complete() || got.InputTokens != 20 || got.OutputTokens != 8 {
		t.Fatalf("tail usage = %+v, want complete 20/8", got)
	}
}

// A single SSE/JSONL line larger than the old 4MB cap must not silently drop usage.
func TestParseUsageBytes_LargeSingleLine(t *testing.T) {
	pad := strings.Repeat("x", 5*1024*1024)
	body := `data: {"type":"response.completed","usage":{"input_tokens":1000,"output_tokens":50},"padding":"` + pad + `"}` + "\n\n"
	var u UsageObservation
	ParseUsageBytes("openai", []byte(body), &u)
	if u.InputTokens != 1000 || u.OutputTokens != 50 {
		t.Errorf("large single line dropped usage: got input=%d output=%d, want 1000/50", u.InputTokens, u.OutputTokens)
	}
}

func assertUsage(t *testing.T, u UsageObservation, in, out, cached, cacheCreate, reasoning int) {
	t.Helper()
	if u.InputTokens != in {
		t.Errorf("input = %d, want %d", u.InputTokens, in)
	}
	if u.OutputTokens != out {
		t.Errorf("output = %d, want %d", u.OutputTokens, out)
	}
	if u.CachedInputTokens != cached {
		t.Errorf("cached = %d, want %d", u.CachedInputTokens, cached)
	}
	if u.CacheCreationInputTokens != cacheCreate {
		t.Errorf("cache_creation = %d, want %d", u.CacheCreationInputTokens, cacheCreate)
	}
	if u.ReasoningTokens != reasoning {
		t.Errorf("reasoning = %d, want %d", u.ReasoningTokens, reasoning)
	}
}

package providers

import "strings"

// SplitAgentPath splits a /w/<slug>/... attribution path.
func SplitAgentPath(path string) (slug, rest string, ok bool) {
	if !strings.HasPrefix(path, "/w/") {
		return "", "", false
	}
	trimmed := strings.TrimPrefix(path, "/w/")
	slash := strings.IndexByte(trimmed, '/')
	if slash <= 0 {
		return "", "", false
	}
	slug = trimmed[:slash]
	rest = trimmed[slash:]
	if rest == "/" || !validAgentSlug(slug) {
		return "", "", false
	}
	return slug, rest, true
}

func validAgentSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > 64 {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		if c >= 'a' && c <= 'z' || c >= '0' && c <= '9' {
			continue
		}
		if i > 0 && (c == '.' || c == '_' || c == '-') {
			continue
		}
		return false
	}
	return true
}

package providers

import (
	"strings"
	"testing"
)

func TestSplitAgentPath(t *testing.T) {
	longSlug := "a" + strings.Repeat("b", 64)
	cases := []struct {
		name     string
		path     string
		wantSlug string
		wantRest string
		wantOK   bool
	}{
		{
			name:     "valid prefixed openai route",
			path:     "/w/checkout-bot/openai/v1/chat/completions",
			wantSlug: "checkout-bot",
			wantRest: "/openai/v1/chat/completions",
			wantOK:   true,
		},
		{
			name:     "dots underscores dashes ok",
			path:     "/w/app.v2_worker-prod/v1/messages",
			wantSlug: "app.v2_worker-prod",
			wantRest: "/v1/messages",
			wantOK:   true,
		},
		{
			name:     "strip once",
			path:     "/w/openai/openai/v1/chat/completions",
			wantSlug: "openai",
			wantRest: "/openai/v1/chat/completions",
			wantOK:   true,
		},
		{name: "uppercase reject", path: "/w/Bad/v1/messages"},
		{name: "too long reject", path: "/w/" + longSlug + "/v1/messages"},
		{name: "leading dash reject", path: "/w/-bad/v1/messages"},
		{name: "empty rest reject", path: "/w/app"},
		{name: "slash rest reject", path: "/w/app/"},
		{name: "empty slug reject", path: "/w//v1/messages"},
		{name: "non w path passthrough", path: "/openai/v1/chat/completions"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			gotSlug, gotRest, gotOK := SplitAgentPath(tc.path)
			if gotOK != tc.wantOK || gotSlug != tc.wantSlug || gotRest != tc.wantRest {
				t.Fatalf("SplitAgentPath(%q) = (%q, %q, %v), want (%q, %q, %v)",
					tc.path, gotSlug, gotRest, gotOK, tc.wantSlug, tc.wantRest, tc.wantOK)
			}
		})
	}
}

package anthropic

import (
	"context"
	"net/http"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// Adapter embeds the shared Base and overrides ApplyProviderNativeTransforms for
// explicit breakpoints and the separate experimental automatic-cache marker.
type Adapter struct {
	providers.Base
}

func (a Adapter) InspectRequest(ctx context.Context, body providers.BodyReader, headers http.Header) (providers.RequestMetadata, error) {
	meta, err := a.Base.InspectRequest(ctx, body, headers)
	if path := headers.Get("x-cave-route-path"); path != "" {
		meta.Endpoint = path
	}
	return meta, err
}

func New(baseURL string) providers.Adapter {
	return Adapter{Base: providers.Base{
		Provider: "anthropic",
		BaseURL:  baseURL,
		// Both the gateway-prefixed routes and the bare Anthropic routes are
		// accepted, mirroring the OpenAI adapter. The bare routes let an agent
		// (e.g. Claude Code) point ANTHROPIC_BASE_URL straight at the standalone
		// proxy unprefixed; ResolveUpstreamURL has no /anthropic prefix to trim, so
		// it forwards to {base}/v1/messages unchanged.
		Routes: []string{"/anthropic/v1/messages", "/anthropic/v1/messages/count_tokens", "/v1/messages", "/v1/messages/count_tokens"},
	}}
}

package anthropic

import (
	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/jsonsplice"
)

// AutomaticPromptCacheOptimizerID is an experimental, default-off direct
// Anthropic Messages transform. Applying its marker is observable; whether the
// provider creates or reads a cache entry must be measured from provider usage
// and does not establish causal or verified savings.
const AutomaticPromptCacheOptimizerID = "anthropic-automatic-prompt-cache"

func automaticPromptCacheMessagesEndpoint(meta providers.RequestMetadata) bool {
	if meta.Provider != "anthropic" {
		return false
	}
	switch meta.Endpoint {
	case "/v1/messages", "/anthropic/v1/messages":
		return true
	default:
		return false
	}
}

func injectAutomaticPromptCacheRaw(data []byte) ([]byte, bool) {
	root, ok := jsonsplice.Root(data)
	if !ok {
		return nil, false
	}
	out, err := jsonsplice.AppendObjectFields(data, root,
		jsonsplice.FieldInsertion{Name: "cache_control", Value: []byte(`{"type":"ephemeral"}`)},
	)
	return out, err == nil
}

package anthropic

import (
	"context"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func automaticPolicy(ids ...string) providers.TransformPolicy {
	enabled := make(map[string]bool, len(ids))
	for _, id := range ids {
		enabled[id] = true
	}
	return providers.TransformPolicy{RuntimeMode: "active", Optimizers: enabled}
}

func applyAutomatic(t *testing.T, body string, meta providers.RequestMetadata, policy providers.TransformPolicy) providers.TransformResult {
	t.Helper()
	a := New("http://upstream").(Adapter)
	res, err := a.ApplyProviderNativeTransforms(context.Background(), strings.NewReader(body), meta, policy)
	if err != nil {
		t.Fatalf("transform error: %v", err)
	}
	return res
}

func TestAutomaticPromptCacheAddsOnlyTopLevelFiveMinuteMarker(t *testing.T) {
	body := "{\n \"model\" : \"claude-sonnet-4-6\", \"messages\" : [ {\"role\":\"user\",\"content\":\"hi\"} ]\n}"
	res := applyAutomatic(t, body, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}, automaticPolicy(AutomaticPromptCacheOptimizerID))
	want := "{\n \"model\" : \"claude-sonnet-4-6\", \"messages\" : [ {\"role\":\"user\",\"content\":\"hi\"} ],\"cache_control\":{\"type\":\"ephemeral\"}\n}"
	if string(res.Body) != want {
		t.Fatalf("automatic cache insertion changed unrelated bytes:\n got %s\nwant %s", res.Body, want)
	}
	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != AutomaticPromptCacheOptimizerID {
		t.Fatalf("optimizer ids = %v, want only %q", res.OptimizerIDs, AutomaticPromptCacheOptimizerID)
	}
}

func TestAutomaticPromptCacheConflictsPassThroughByteIdentically(t *testing.T) {
	base := `{"model":"claude-sonnet-4-6","messages":[{"role":"user","content":"hi"}]}`
	tests := []struct {
		name   string
		body   string
		meta   providers.RequestMetadata
		policy providers.TransformPolicy
	}{
		{"both Caveman cache strategies", base, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}, automaticPolicy(OptimizerID, AutomaticPromptCacheOptimizerID)},
		{"caller block marker", `{"system":[{"type":"text","text":"stable","cache_control":{"type":"ephemeral"}}],"messages":[{"role":"user","content":"hi"}]}`, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}, automaticPolicy(AutomaticPromptCacheOptimizerID)},
		{"caller escaped top-level marker", `{"cache\u005fcontrol":{"type":"ephemeral"},"messages":[{"role":"user","content":"hi"}]}`, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}, automaticPolicy(AutomaticPromptCacheOptimizerID)},
		{"count tokens endpoint", base, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages/count_tokens"}, automaticPolicy(AutomaticPromptCacheOptimizerID)},
		{"bedrock metadata", base, providers.RequestMetadata{Provider: "bedrock", Endpoint: "/v1/messages"}, automaticPolicy(AutomaticPromptCacheOptimizerID)},
		{"unknown endpoint", base, providers.RequestMetadata{Provider: "anthropic"}, automaticPolicy(AutomaticPromptCacheOptimizerID)},
		{"subscription", base, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}, func() providers.TransformPolicy {
			p := automaticPolicy(AutomaticPromptCacheOptimizerID)
			p.AuthMode = "subscription"
			return p
		}()},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			res := applyAutomatic(t, tc.body, tc.meta, tc.policy)
			if string(res.Body) != tc.body || len(res.OptimizerIDs) != 0 {
				t.Fatalf("unsafe/unsupported request changed: ids=%v body=%s", res.OptimizerIDs, res.Body)
			}
		})
	}
}

func TestAutomaticPromptCacheDoesNotGuessModelTokenThreshold(t *testing.T) {
	// Anthropic silently declines cache creation below the current model-specific
	// minimum. The adapter has no provider tokenizer and must not maintain a
	// drifting model threshold table or fabricate whether the provider cached it.
	body := `{"model":"future-active-claude","messages":[{"role":"user","content":"x"}]}`
	res := applyAutomatic(t, body, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/anthropic/v1/messages"}, automaticPolicy(AutomaticPromptCacheOptimizerID))
	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != AutomaticPromptCacheOptimizerID {
		t.Fatalf("provider-owned below-minimum decision was guessed locally: %v", res.OptimizerIDs)
	}
	if !strings.Contains(string(res.Body), `"cache_control":{"type":"ephemeral"}`) {
		t.Fatalf("top-level marker missing: %s", res.Body)
	}
}

func TestAnthropicCacheStrategiesRecordModeAreByteIdentical(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","system":"stable","messages":[{"role":"user","content":"hi"}]}`
	for _, optimizerID := range []string{OptimizerID, AutomaticPromptCacheOptimizerID} {
		t.Run(optimizerID, func(t *testing.T) {
			policy := automaticPolicy(optimizerID)
			policy.RuntimeMode = "record"
			res := applyAutomatic(t, body, providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}, policy)
			if string(res.Body) != body || len(res.OptimizerIDs) != 0 {
				t.Fatalf("record mode changed bytes or attributed an optimizer: ids=%v body=%s", res.OptimizerIDs, res.Body)
			}
		})
	}
}

package anthropic

import (
	"encoding/json"
	"sort"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/jsonsplice"
)

// BreakpointPlanID labels the cache-breakpoint planner in x-cave-optimization and
// on the telemetry row.
//
// It is deliberately NOT in the gateway's cacheOptimizerIDs set. Anthropic-direct
// breakpoints ARE the provider_causal_cache method, so adding this id there would
// start minting cache savings for planner-placed breakpoints. Minting requires the
// exact provider/method/optimizer tuple discipline in docs/SAVINGS_ACCOUNTING.md,
// and earning it is a deliberate later change with its own review. Until then the
// planner mints nothing: no tokens, no ratio, no dollars.
const BreakpointPlanID = "cache-breakpoint-plan"

// maxCacheBreakpoints is Anthropic's hard cap on cache_control markers per
// request. The planner counts what the caller already placed and never exceeds
// the cap; a request that already carries four is left alone entirely.
const maxCacheBreakpoints = 4

// breakpointLookbackBlocks is Anthropic's documented cache lookback: a cache read
// looks backward at most this many positions from a breakpoint, and it can only
// find entries PRIOR REQUESTS WROTE. See lookbackPlan for why that second half
// makes the lookback a cross-request property, and why the guard arm that
// modeled it inside a single body does not ship.
const breakpointLookbackBlocks = 20

// cacheControlField is the exact bytes every planned breakpoint inserts. One
// spelling, so a planned request is byte-identical on every later turn that
// carries the same content.
const cacheControlField = `"cache_control":{"type":"ephemeral"}`

// PlanCacheBreakpoints places Anthropic prompt-cache breakpoints on the upstream
// request. cache_control is provider metadata the model never sees, so this
// changes no model-visible bytes; on any parse anomaly the body is left unchanged.
//
// Two arms, and they never mix:
//
//   - No cache_control anywhere: the caller manages no caching at all (a custom
//     agent rather than a caching harness). The planner places its own
//     deterministic set — tools tail, system tail, and a frontier breakpoint on
//     the newest message — within the max-4 budget. This arm is payg-only, the
//     same restriction ApplyProviderNativeTransforms keeps, because a
//     subscription/OAuth session's caching is the harness's business.
//
//   - Existing cache_control present: the planner NEVER moves or removes what is
//     already there. The 20-block lookback guard that would add an intermediate
//     breakpoint is DISABLED (see lookbackPlan). The one thing this arm still
//     does is close the composition dead zone: when every existing breakpoint is
//     on the tool catalog and none is on a content block — the exact shape the
//     sibling anthropic-cache-breakpoints optimizer produces when it runs first —
//     the conversation itself is uncached, so the frontier breakpoint is placed as
//     it would have been in the cold arm, bounded by the same max-4 budget.
//
// payg carries the caller's classification; meta is unused today and is present
// so the planner reads the same way for every provider that has one.
func (a Adapter) PlanCacheBreakpoints(body []byte, meta providers.RequestMetadata, payg bool) ([]byte, bool) {
	return planCacheBreakpoints(body, payg)
}

func planCacheBreakpoints(data []byte, payg bool) ([]byte, bool) {
	// Decode once for the existence question: a valid request may spell the key
	// with an escape such as cache_control, and a raw byte search would then
	// read a caller-managed request as unmanaged and plant a competing plan.
	var root map[string]any
	if json.Unmarshal(data, &root) != nil {
		return nil, false
	}
	existing := countJSONKey(root, "cache_control")
	if existing >= maxCacheBreakpoints {
		return nil, false
	}
	object, ok := jsonsplice.Root(data)
	if !ok {
		return nil, false
	}

	var edits []spliceEdit
	if existing == 0 {
		if !payg {
			return nil, false
		}
		edits = coldStartPlan(data, object)
	} else {
		edits = managedPlan(data, object, maxCacheBreakpoints-existing, payg)
	}
	if len(edits) == 0 {
		return nil, false
	}
	out, ok := applySpliceEdits(data, edits)
	if !ok || !json.Valid(out) {
		return nil, false
	}
	return out, true
}

// coldStartPlan is the arm for requests that carry no cache_control at all. It
// places at most three breakpoints — well inside the max-4 budget — in a fixed
// order so the same conversation always produces the same upstream bytes.
func coldStartPlan(data []byte, root jsonsplice.Span) []spliceEdit {
	var edits []spliceEdit
	if edit, ok := toolsTailEdit(data, root); ok {
		edits = append(edits, edit)
	}
	if edit, ok := systemTailEdit(data, root); ok {
		edits = append(edits, edit)
	}
	if edit, ok := frontierEdit(data, root); ok {
		edits = append(edits, edit)
	}
	if len(edits) > maxCacheBreakpoints {
		edits = edits[:maxCacheBreakpoints]
	}
	return edits
}

// toolsTailEdit marks the last tool. Anthropic caches everything up to and
// including the marked block, so one marker on the last tool caches the whole
// tool catalog — the largest stable prefix in an agent request.
func toolsTailEdit(data []byte, root jsonsplice.Span) (spliceEdit, bool) {
	tools, ok := jsonsplice.Field(data, root, "tools")
	if !ok || !isJSONArray(data, tools) {
		return spliceEdit{}, false
	}
	elements, valid := jsonsplice.Elements(data, tools)
	if !valid {
		return spliceEdit{}, false
	}
	for i := len(elements) - 1; i >= 0; i-- {
		if isJSONObject(data, elements[i]) {
			return appendFieldEdit(data, elements[i])
		}
	}
	return spliceEdit{}, false
}

// systemTailEdit marks the tail of the system prompt. A string system prompt is
// rewritten into its equivalent single-text-block array form, which is the only
// shape that can carry a marker.
func systemTailEdit(data []byte, root jsonsplice.Span) (spliceEdit, bool) {
	system, ok := jsonsplice.Field(data, root, "system")
	if !ok || system.Start >= system.End {
		return spliceEdit{}, false
	}
	switch data[system.Start] {
	case '"':
		replacement := make([]byte, 0, system.End-system.Start+72)
		replacement = append(replacement, []byte(`[{"type":"text","text":`)...)
		replacement = append(replacement, data[system.Start:system.End]...)
		replacement = append(replacement, ',')
		replacement = append(replacement, []byte(cacheControlField)...)
		replacement = append(replacement, []byte(`}]`)...)
		return spliceEdit{start: system.Start, end: system.End, bytes: replacement}, true
	case '[':
		elements, valid := jsonsplice.Elements(data, system)
		if !valid {
			return spliceEdit{}, false
		}
		for i := len(elements) - 1; i >= 0; i-- {
			if isJSONObject(data, elements[i]) {
				return appendFieldEdit(data, elements[i])
			}
		}
	}
	return spliceEdit{}, false
}

// frontierEdit marks the last content block of the newest message — the rolling
// tail breakpoint. It bounds every later turn's rebuild to the tail rather than
// the whole conversation.
func frontierEdit(data []byte, root jsonsplice.Span) (spliceEdit, bool) {
	messages, ok := jsonsplice.Field(data, root, "messages")
	if !ok || !isJSONArray(data, messages) {
		return spliceEdit{}, false
	}
	elements, valid := jsonsplice.Elements(data, messages)
	if !valid || len(elements) == 0 {
		return spliceEdit{}, false
	}
	last := elements[len(elements)-1]
	if !isJSONObject(data, last) {
		return spliceEdit{}, false
	}
	content, ok := jsonsplice.Field(data, last, "content")
	if !ok || !isJSONArray(data, content) {
		// A string content block cannot carry a marker without reshaping the
		// message itself, which is model-visible. Leave it alone.
		return spliceEdit{}, false
	}
	blocks, valid := jsonsplice.Elements(data, content)
	if !valid {
		return spliceEdit{}, false
	}
	for i := len(blocks) - 1; i >= 0; i-- {
		if isJSONObject(data, blocks[i]) {
			return appendFieldEdit(data, blocks[i])
		}
	}
	return spliceEdit{}, false
}

// managedPlan is the arm for requests that already carry a breakpoint. The
// lookback guard is disabled, so the only thing it can still contribute is the
// composition dead-zone fall-through described on PlanCacheBreakpoints.
func managedPlan(data []byte, root jsonsplice.Span, budget int, payg bool) []spliceEdit {
	if budget <= 0 {
		return nil
	}
	if edits := lookbackPlan(); len(edits) > 0 {
		return edits
	}
	// The fall-through is a continuation of the cold arm — it places the frontier
	// breakpoint on a conversation nobody is caching — so it carries the cold
	// arm's payg restriction too.
	if !payg {
		return nil
	}
	marked, ok := contentBlocksCarryBreakpoint(data, root)
	if !ok || marked {
		// Either a shape we cannot walk exactly, or the caller IS caching the
		// conversation. Both mean: leave it alone.
		return nil
	}
	edit, ok := frontierEdit(data, root)
	if !ok {
		return nil
	}
	return []spliceEdit{edit}
}

// lookbackPlan is the 20-block lookback guard. It is DISABLED and returns no
// edits, because the version that shipped modeled the lookback as a property of
// one request body, and that is not what Anthropic documents.
//
// The documented semantics (platform.claude.com/docs/en/build-with-claude/prompt-caching):
// a cache read looks backward at most breakpointLookbackBlocks positions from a
// breakpoint, and it can only find entries PRIOR REQUESTS WROTE. So the gap that
// matters is never between two breakpoints inside the current body — it is
// between this request's breakpoint and the index the PREVIOUS request actually
// wrote. A breakpoint placed at a position computed relative to the current
// body's own markers moves forward as the conversation grows, so every turn lands
// it somewhere no earlier request ever wrote: it can never read, and it pays the
// 1.25x cache write every single turn. That is a pure cost, which is the exact
// failure mode the harm tripwire exists to catch.
//
// Follow-up: rebuild it as a CROSS-REQUEST anchor. The session ledger is already
// keyed on x-cave-session, so it can carry the last breakpoint index this session
// actually wrote; the guard then inserts at lastWrittenIndex+19 — an ABSOLUTE
// pinned position — and re-emits that same absolute index on every later turn, so
// the entry the first turn paid to write is the entry every later turn reads.
// Landing that needs three more things: a block view whose indices are stable
// across turns (append-only conversations are, compressed ones need the prefix
// cache), a placeability check on the target block, and the same max-4 budget cap.
func lookbackPlan() []spliceEdit {
	return nil
}

// contentBlocksCarryBreakpoint reports whether any CONTENT block carries a
// cache_control marker — the system blocks (when system is an array) plus every
// message's content blocks, in wire order. Tools are objects rather than content
// blocks and are deliberately excluded: a marker there says the tool catalog is
// cached, not the conversation.
//
// ok is false for any shape it cannot walk exactly, which the caller treats as
// "leave the body unchanged".
func contentBlocksCarryBreakpoint(data []byte, root jsonsplice.Span) (marked bool, ok bool) {
	if system, found := jsonsplice.Field(data, root, "system"); found && isJSONArray(data, system) {
		elements, valid := jsonsplice.Elements(data, system)
		if !valid {
			return false, false
		}
		for _, element := range elements {
			if blockIsMarked(data, element) {
				return true, true
			}
		}
	}

	messages, found := jsonsplice.Field(data, root, "messages")
	if !found || !isJSONArray(data, messages) {
		return false, false
	}
	elements, valid := jsonsplice.Elements(data, messages)
	if !valid {
		return false, false
	}
	for _, message := range elements {
		if !isJSONObject(data, message) {
			return false, false
		}
		content, found := jsonsplice.Field(data, message, "content")
		if !found {
			return false, false
		}
		if !isJSONArray(data, content) {
			// A string content is one block on the wire that cannot hold a marker.
			continue
		}
		blocks, valid := jsonsplice.Elements(data, content)
		if !valid {
			return false, false
		}
		for _, block := range blocks {
			if blockIsMarked(data, block) {
				return true, true
			}
		}
	}
	return false, true
}

func blockIsMarked(data []byte, span jsonsplice.Span) bool {
	if !isJSONObject(data, span) {
		return false
	}
	_, marked := jsonsplice.Field(data, span, "cache_control")
	return marked
}

// spliceEdit is one byte-range replacement. An insertion is the degenerate case
// where start == end.
type spliceEdit struct {
	start int
	end   int
	bytes []byte
}

// appendFieldEdit produces the insertion that adds cache_control immediately
// before an object's closing brace, leaving every other byte — whitespace, key
// order, escapes — exactly as the caller wrote it.
func appendFieldEdit(data []byte, object jsonsplice.Span) (spliceEdit, bool) {
	if !isJSONObject(data, object) {
		return spliceEdit{}, false
	}
	insertAt := object.End - 1
	for insertAt > object.Start+1 && isJSONSpaceByte(data[insertAt-1]) {
		insertAt--
	}
	addition := make([]byte, 0, len(cacheControlField)+1)
	if insertAt > object.Start+1 {
		addition = append(addition, ',')
	}
	addition = append(addition, []byte(cacheControlField)...)
	return spliceEdit{start: insertAt, end: insertAt, bytes: addition}, true
}

// applySpliceEdits rewrites data in one ascending pass. Edits must not overlap;
// an overlap is a planning bug and returns false so the caller forwards the
// original bytes.
func applySpliceEdits(data []byte, edits []spliceEdit) ([]byte, bool) {
	sorted := append([]spliceEdit(nil), edits...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].start < sorted[j].start })
	total := len(data)
	for _, edit := range sorted {
		total += len(edit.bytes)
	}
	out := make([]byte, 0, total)
	last := 0
	for _, edit := range sorted {
		if edit.start < last || edit.end < edit.start || edit.end > len(data) {
			return nil, false
		}
		out = append(out, data[last:edit.start]...)
		out = append(out, edit.bytes...)
		last = edit.end
	}
	return append(out, data[last:]...), true
}

func isJSONObject(data []byte, span jsonsplice.Span) bool {
	return span.Start >= 0 && span.Start < span.End && span.End <= len(data) &&
		data[span.Start] == '{' && data[span.End-1] == '}'
}

func isJSONArray(data []byte, span jsonsplice.Span) bool {
	return span.Start >= 0 && span.Start < span.End && span.End <= len(data) &&
		data[span.Start] == '[' && data[span.End-1] == ']'
}

func isJSONSpaceByte(b byte) bool {
	return b == ' ' || b == '\n' || b == '\r' || b == '\t'
}

// countJSONKey counts how many times a key appears anywhere in a decoded
// document. The planner uses it for the max-4 budget, so it must count every
// occurrence rather than stop at the first.
func countJSONKey(value any, key string) int {
	switch node := value.(type) {
	case map[string]any:
		count := 0
		for k, child := range node {
			if k == key {
				count++
			}
			count += countJSONKey(child, key)
		}
		return count
	case []any:
		count := 0
		for _, child := range node {
			count += countJSONKey(child, key)
		}
		return count
	}
	return 0
}

package anthropic

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// The breakpoint planner places Anthropic prompt-cache metadata on the upstream
// request. cache_control is not model-visible, so this is byte-safe under honesty
// rule #2 — but it is still bounded by two hard contracts: never exceed the
// provider's four-breakpoint budget, and never move or remove a breakpoint the
// harness placed.

// planBlocks builds a request whose single user message carries `blocks` content
// blocks, with cache_control on each index named in marked.
func planBlocks(blocks int, marked ...int) string {
	isMarked := map[int]bool{}
	for _, i := range marked {
		isMarked[i] = true
	}
	parts := make([]string, 0, blocks)
	for i := 0; i < blocks; i++ {
		block := `{"type":"text","text":"block ` + itoaTest(i) + `"`
		if isMarked[i] {
			block += `,` + cacheControlField
		}
		parts = append(parts, block+`}`)
	}
	return `{"model":"claude-sonnet-4-6","max_tokens":1024,` +
		`"system":"You are a helpful assistant.",` +
		`"messages":[{"role":"user","content":[` + strings.Join(parts, ",") + `]}]}`
}

func itoaTest(n int) string {
	if n == 0 {
		return "0"
	}
	var buf []byte
	for n > 0 {
		buf = append([]byte{byte('0' + n%10)}, buf...)
		n /= 10
	}
	return string(buf)
}

func countBreakpoints(t *testing.T, body []byte) int {
	t.Helper()
	var root map[string]any
	if err := json.Unmarshal(body, &root); err != nil {
		t.Fatalf("planner produced invalid JSON: %v", err)
	}
	return countJSONKey(root, "cache_control")
}

// TestBreakpointPlanColdStartIsDeterministic pins the arm for agents that manage
// no caching at all: the planner places its own set (tools tail, system tail,
// frontier), inside the budget, and byte-identically on every call — a plan that
// moved between turns would bust the very cache it created.
func TestBreakpointPlanColdStartIsDeterministic(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","max_tokens":1024,` +
		`"tools":[{"name":"read","input_schema":{}},{"name":"write","input_schema":{}}],` +
		`"system":[{"type":"text","text":"sys a"},{"type":"text","text":"sys b"}],` +
		`"messages":[{"role":"user","content":[{"type":"text","text":"one"}]},` +
		`{"role":"user","content":[{"type":"text","text":"two"},{"type":"text","text":"three"}]}]}`

	out, ok := planCacheBreakpoints([]byte(body), true)
	if !ok {
		t.Fatal("planner declined a request with no cache_control at all")
	}
	if got := countBreakpoints(t, out); got != 3 {
		t.Fatalf("placed %d breakpoints, want 3 (tools tail, system tail, frontier)", got)
	}

	var root map[string]any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatalf("invalid JSON: %v", err)
	}
	tools := root["tools"].([]any)
	if _, marked := tools[1].(map[string]any)["cache_control"]; !marked {
		t.Error("the last tool carries no breakpoint")
	}
	if _, marked := tools[0].(map[string]any)["cache_control"]; marked {
		t.Error("only the LAST tool should carry the tools breakpoint")
	}
	system := root["system"].([]any)
	if _, marked := system[1].(map[string]any)["cache_control"]; !marked {
		t.Error("the system tail carries no breakpoint")
	}
	messages := root["messages"].([]any)
	live := messages[1].(map[string]any)["content"].([]any)
	if _, marked := live[1].(map[string]any)["cache_control"]; !marked {
		t.Error("the frontier block (last block of the newest message) carries no breakpoint")
	}
	if _, marked := live[0].(map[string]any)["cache_control"]; marked {
		t.Error("only the LAST block of the newest message is the frontier")
	}

	again, ok := planCacheBreakpoints([]byte(body), true)
	if !ok || string(again) != string(out) {
		t.Fatalf("plan is not deterministic:\n first %s\nsecond %s", out, again)
	}
}

// TestBreakpointPlanColdStartConvertsStringSystem covers the one reshape the cold
// arm performs: a string system prompt has no block that can hold a marker, so it
// becomes its equivalent single-text-block array. The text itself is untouched.
func TestBreakpointPlanColdStartConvertsStringSystem(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","system":"You are Claude.","messages":[{"role":"user","content":[{"type":"text","text":"hi"}]}]}`

	out, ok := planCacheBreakpoints([]byte(body), true)
	if !ok {
		t.Fatal("planner declined")
	}
	var root map[string]any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatalf("invalid JSON: %v", err)
	}
	system, isArray := root["system"].([]any)
	if !isArray || len(system) != 1 {
		t.Fatalf("system was not converted to a one-block array: %v", root["system"])
	}
	block := system[0].(map[string]any)
	if block["text"] != "You are Claude." || block["type"] != "text" {
		t.Fatalf("system text was altered: %v", block)
	}
	if _, marked := block["cache_control"]; !marked {
		t.Fatalf("converted system block carries no breakpoint: %v", block)
	}
}

// TestBreakpointPlanColdStartIsPAYGOnly: a subscription/OAuth session's caching is
// its harness's business. With no cache_control to guard, the planner declines.
func TestBreakpointPlanColdStartIsPAYGOnly(t *testing.T) {
	body := planBlocks(3)
	if out, ok := planCacheBreakpoints([]byte(body), false); ok {
		t.Fatalf("non-payg request with no cache_control was rewritten: %s", out)
	}
}

// TestBreakpointPlanLookbackGuardIsDisabled pins the disablement, so a future
// change has to be deliberate rather than accidental.
//
// The guard that shipped in review computed its insertion position from the
// CURRENT body's markers. Anthropic's lookback only finds entries prior requests
// WROTE, so a position that moves as the conversation grows lands somewhere no
// earlier request ever wrote: it pays the 1.25x write every turn and never reads.
// The cases below are the reviewer's replayed doc example — consecutive turns of
// one growing conversation, each with a rolling tail breakpoint — and every one
// of them must produce no plan at all.
func TestBreakpointPlanLookbackGuardIsDisabled(t *testing.T) {
	for _, tc := range []struct {
		name   string
		blocks int
		mark   int
	}{
		{name: "turn2: 15 blocks, tail breakpoint at 14", blocks: 15, mark: 14},
		{name: "turn3: 35 blocks, tail breakpoint at 34", blocks: 35, mark: 34},
		{name: "gap of exactly the lookback", blocks: 21, mark: 0},
		{name: "gap one past the lookback", blocks: 22, mark: 0},
		{name: "gap far past the lookback", blocks: 61, mark: 0},
		{name: "two marks with a long trailing gap", blocks: 30, mark: 1},
	} {
		t.Run(tc.name, func(t *testing.T) {
			body := planBlocks(tc.blocks, tc.mark)
			if out, ok := planCacheBreakpoints([]byte(body), true); ok {
				t.Fatalf("the disabled lookback guard produced a plan: %s", out)
			}
		})
	}
}

// TestBreakpointPlanNeverMovesHarnessBreakpoints is the arm's core promise, and
// with the guard disabled it holds in its strongest form: a request whose
// conversation the caller is already caching goes upstream byte-identically.
func TestBreakpointPlanNeverMovesHarnessBreakpoints(t *testing.T) {
	for _, body := range []string{
		planBlocks(30, 0, 1),
		planBlocks(60, 0, 30),
		`{"model":"claude-sonnet-4-6",` +
			`"tools":[{"name":"read","input_schema":{},` + cacheControlField + `}],` +
			`"system":[{"type":"text","text":"sys",` + cacheControlField + `}],` +
			`"messages":[{"role":"user","content":[` + blocksWithMarks(40, 0) + `]}]}`,
	} {
		if out, ok := planCacheBreakpoints([]byte(body), true); ok {
			t.Fatalf("a caller-cached conversation was rewritten:\n got %s\nwant %s", out, body)
		}
	}
}

// TestBreakpointPlanRespectsTheFourBudget: a request already carrying the
// provider's maximum is left completely alone.
func TestBreakpointPlanRespectsTheFourBudget(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6",` +
		`"tools":[{"name":"read","input_schema":{},` + cacheControlField + `}],` +
		`"system":[{"type":"text","text":"sys",` + cacheControlField + `}],` +
		`"messages":[{"role":"user","content":[` + blocksWithMarks(60, 0, 1) + `]}]}`

	if got := countBreakpoints(t, []byte(body)); got != 4 {
		t.Fatalf("fixture carries %d breakpoints, want 4", got)
	}
	if out, ok := planCacheBreakpoints([]byte(body), true); ok {
		t.Fatalf("planner exceeded the four-breakpoint budget: %s", out)
	}
}

// TestBreakpointPlanClosesTheCompositionDeadZone is F5: when the sibling
// anthropic-cache-breakpoints optimizer has already put a breakpoint on the tool
// catalog, the conversation itself is still uncached. Returning nil there would
// leave the request strictly worse off than if the planner had run alone, so the
// frontier breakpoint is placed — without displacing the tools one.
func TestBreakpointPlanClosesTheCompositionDeadZone(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6",` +
		`"tools":[{"name":"read","input_schema":{},` + cacheControlField + `}],` +
		`"system":"You are an agent.",` +
		`"messages":[{"role":"user","content":[{"type":"text","text":"one"},{"type":"text","text":"two"}]}]}`

	out, ok := planCacheBreakpoints([]byte(body), true)
	if !ok {
		t.Fatal("the composition dead zone was not closed: a tools-only breakpoint left the conversation uncached")
	}
	if got := countBreakpoints(t, out); got != 2 {
		t.Fatalf("breakpoints = %d, want 2 (the tools one plus the frontier)", got)
	}
	var root map[string]any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatalf("invalid JSON: %v", err)
	}
	if _, marked := root["tools"].([]any)[0].(map[string]any)["cache_control"]; !marked {
		t.Fatal("the existing tools breakpoint was displaced")
	}
	blocks := root["messages"].([]any)[0].(map[string]any)["content"].([]any)
	if _, marked := blocks[1].(map[string]any)["cache_control"]; !marked {
		t.Fatalf("the frontier breakpoint was not placed: %s", out)
	}
	if _, marked := blocks[0].(map[string]any)["cache_control"]; marked {
		t.Fatal("only the last block of the newest message is the frontier")
	}
	// Nothing but the one insertion: the tools breakpoint keeps its exact bytes.
	marker := `,` + cacheControlField
	if got, want := strings.ReplaceAll(string(out), marker, ""), strings.ReplaceAll(body, marker, ""); got != want {
		t.Fatalf("the fall-through changed bytes outside its insertion:\n got %s\nwant %s", got, want)
	}

	// Same shape, but non-payg: the fall-through carries the cold arm's payg
	// restriction, because it IS the cold arm's placement.
	if out, ok := planCacheBreakpoints([]byte(body), false); ok {
		t.Fatalf("non-payg request took the fall-through: %s", out)
	}

	// One marked content block anywhere means the caller IS caching the
	// conversation, and the fall-through must not fire.
	managed := `{"model":"claude-sonnet-4-6",` +
		`"tools":[{"name":"read","input_schema":{},` + cacheControlField + `}],` +
		`"messages":[{"role":"user","content":[` + blocksWithMarks(3, 0) + `]}]}`
	if out, ok := planCacheBreakpoints([]byte(managed), true); ok {
		t.Fatalf("the fall-through fired on a caller-cached conversation: %s", out)
	}
}

// TestBreakpointPlanLeavesShapesItCannotWalk covers the byte-safe rule: anything
// the planner cannot parse exactly forwards unchanged.
func TestBreakpointPlanLeavesShapesItCannotWalk(t *testing.T) {
	for name, body := range map[string]string{
		"not json":          `{"model":`,
		"string content":    `{"model":"claude-sonnet-4-6","messages":[{"role":"user","content":"plain string"}]}`,
		"no messages":       `{"model":"claude-sonnet-4-6"}`,
		"marked but no gap": planBlocks(5, 0),
		"marked string bodies": `{"model":"claude-sonnet-4-6","system":[{"type":"text","text":"s",` + cacheControlField +
			`}],"messages":[{"role":"user","content":"plain"}]}`,
	} {
		t.Run(name, func(t *testing.T) {
			if out, ok := planCacheBreakpoints([]byte(body), true); ok {
				t.Fatalf("planner rewrote a body it should have left alone: %s", out)
			}
		})
	}
}

// TestBreakpointPlanSystemBlocksCountAsContent: a marker on the system tail says
// the caller IS caching content blocks, so the dead-zone fall-through must not
// fire. Only a TOOLS-only marker leaves the conversation genuinely uncached.
func TestBreakpointPlanSystemBlocksCountAsContent(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6",` +
		`"system":[{"type":"text","text":"sys",` + cacheControlField + `}],` +
		`"messages":[{"role":"user","content":[` + blocksWithMarks(21) + `]}]}`

	if out, ok := planCacheBreakpoints([]byte(body), true); ok {
		t.Fatalf("a system-tail breakpoint was treated as an uncached conversation: %s", out)
	}
}

// TestBreakpointPlanAdapterSeam pins the capability method the gateway calls.
func TestBreakpointPlanAdapterSeam(t *testing.T) {
	adapter := New("http://upstream").(Adapter)
	out, ok := adapter.PlanCacheBreakpoints([]byte(planBlocks(3)), providers.RequestMetadata{Provider: "anthropic"}, true)
	if !ok {
		t.Fatal("adapter seam declined a cold-start payg request")
	}
	if got := countBreakpoints(t, out); got == 0 {
		t.Fatal("adapter seam placed no breakpoint")
	}
}

func blocksWithMarks(count int, marked ...int) string {
	isMarked := map[int]bool{}
	for _, i := range marked {
		isMarked[i] = true
	}
	parts := make([]string, 0, count)
	for i := 0; i < count; i++ {
		block := `{"type":"text","text":"b` + itoaTest(i) + `"`
		if isMarked[i] {
			block += `,` + cacheControlField
		}
		parts = append(parts, block+`}`)
	}
	return strings.Join(parts, ",")
}

package anthropic

import (
	"context"
	"encoding/json"
	"io"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/jsonsplice"
)

// OptimizerID is the policy flag and x-cave-optimization label for this optimizer.
const OptimizerID = "anthropic-cache-breakpoints"

// ApplyProviderNativeTransforms applies at most one enabled Anthropic caching
// strategy. OptimizerID places an explicit breakpoint on the last non-deferred
// tool (or last system block). AutomaticPromptCacheOptimizerID adds Anthropic's
// top-level automatic 5-minute marker to a direct Messages request.
//
// It is conservative and idempotent: it runs only when policy enables one
// strategy (gateway callers own the request-wide runtime-mode gate), it never
// touches a request that already carries any cache_control (the caller is
// managing caching), and on any parse problem it passes the body through
// unchanged. The response stream to the client is unaffected — only the
// upstream request prefix is annotated.
func (a Adapter) ApplyProviderNativeTransforms(ctx context.Context, body providers.BodyReader, meta providers.RequestMetadata, policy providers.TransformPolicy) (providers.TransformResult, error) {
	data, err := io.ReadAll(body)
	if err != nil {
		return providers.TransformResult{Body: data, OptimizerIDs: []string{}}, nil
	}
	passthrough := providers.TransformResult{Body: data, OptimizerIDs: []string{}}
	// Record mode is an unconditional wire-preservation boundary. Both gateways
	// normally skip this adapter in record mode, but the shared adapter must be
	// safe when called directly (or by a future caller) too.
	if policy.RuntimeMode == "record" {
		return passthrough, nil
	}

	explicitEnabled := policy.OptimizerEnabled(OptimizerID)
	automaticEnabled := policy.OptimizerEnabled(AutomaticPromptCacheOptimizerID)
	if !explicitEnabled && !automaticEnabled {
		return passthrough, nil
	}
	// The provider counts an automatic marker toward the four-breakpoint limit.
	// Do not combine Caveman strategies because precedence depends on caller
	// breakpoints and TTLs that the adapter cannot safely infer.
	if explicitEnabled && automaticEnabled {
		return passthrough, nil
	}
	if policy.AuthMode != "" && policy.AuthMode != "payg" {
		return passthrough, nil
	}
	if automaticEnabled && !automaticPromptCacheMessagesEndpoint(meta) {
		return passthrough, nil
	}
	var root map[string]any
	if json.Unmarshal(data, &root) != nil {
		return passthrough, nil
	}
	// Respect caller-managed cache breakpoints after JSON decoding. Raw byte
	// search is insufficient because a valid key may use a Unicode escape such
	// as cache\u005fcontrol; attributing that caller cache to this optimizer
	// would mint false verified savings.
	if containsJSONKey(root, "cache_control") {
		return passthrough, nil
	}

	if automaticEnabled {
		out, ok := injectAutomaticPromptCacheRaw(data)
		if !ok || !json.Valid(out) {
			return passthrough, nil
		}
		return providers.TransformResult{Body: out, OptimizerIDs: []string{AutomaticPromptCacheOptimizerID}}, nil
	}

	out, ok := injectBreakpointRaw(data, root)
	if !ok {
		return passthrough, nil
	}
	if !json.Valid(out) {
		return passthrough, nil
	}
	return providers.TransformResult{Body: out, OptimizerIDs: []string{OptimizerID}}, nil
}

func injectBreakpointRaw(data []byte, decoded map[string]any) ([]byte, bool) {
	root, ok := jsonsplice.Root(data)
	if !ok {
		return nil, false
	}
	cacheControl := []byte(`{"type":"ephemeral"}`)

	if tools, found := jsonsplice.Field(data, root, "tools"); found {
		if elements, valid := jsonsplice.Elements(data, tools); valid {
			decodedTools, _ := decoded["tools"].([]any)
			for i := len(elements) - 1; i >= 0; i-- {
				if i < len(decodedTools) && deferredTool(decodedTools[i]) {
					continue
				}
				element := elements[i]
				if element.Start < element.End && data[element.Start] == '{' {
					out, err := jsonsplice.AppendObjectFields(data, element,
						jsonsplice.FieldInsertion{Name: "cache_control", Value: cacheControl},
					)
					return out, err == nil
				}
			}
		}
	}

	system, found := jsonsplice.Field(data, root, "system")
	if !found || system.Start >= system.End {
		return nil, false
	}
	switch data[system.Start] {
	case '"':
		replacement := make([]byte, 0, system.End-system.Start+72)
		replacement = append(replacement, []byte(`[{"type":"text","text":`)...)
		replacement = append(replacement, data[system.Start:system.End]...)
		replacement = append(replacement, []byte(`,"cache_control":{"type":"ephemeral"}}]`)...)
		out, err := jsonsplice.ReplaceRaw(data, system, replacement)
		return out, err == nil
	case '[':
		elements, valid := jsonsplice.Elements(data, system)
		if !valid {
			return nil, false
		}
		for i := len(elements) - 1; i >= 0; i-- {
			element := elements[i]
			if element.Start < element.End && data[element.Start] == '{' {
				out, err := jsonsplice.AppendObjectFields(data, element,
					jsonsplice.FieldInsertion{Name: "cache_control", Value: cacheControl},
				)
				return out, err == nil
			}
		}
	}
	return nil, false
}

func containsJSONKey(value any, key string) bool {
	switch node := value.(type) {
	case map[string]any:
		for k, child := range node {
			if k == key || containsJSONKey(child, key) {
				return true
			}
		}
	case []any:
		for _, child := range node {
			if containsJSONKey(child, key) {
				return true
			}
		}
	}
	return false
}

func deferredTool(value any) bool {
	tool, ok := value.(map[string]any)
	if !ok {
		return false
	}
	deferred, _ := tool["defer_loading"].(bool)
	return deferred
}

// injectBreakpoint mutates root in place, placing one ephemeral cache_control on
// the stable prefix. Returns true if a breakpoint was placed.
func injectBreakpoint(root map[string]any) bool {
	// Prefer caching tools (they sit before the system+messages and are the most
	// stable, largest reusable prefix). A cache_control on the last tool caches
	// all tools.
	if tools, ok := root["tools"].([]any); ok && len(tools) > 0 {
		for i := len(tools) - 1; i >= 0; i-- {
			if deferredTool(tools[i]) {
				continue
			}
			if tool, ok := tools[i].(map[string]any); ok {
				tool["cache_control"] = ephemeral()
				return true
			}
		}
	}

	// No tools: cache the system prompt.
	switch sys := root["system"].(type) {
	case string:
		if sys == "" {
			return false
		}
		root["system"] = []any{map[string]any{
			"type":          "text",
			"text":          sys,
			"cache_control": ephemeral(),
		}}
		return true
	case []any:
		for i := len(sys) - 1; i >= 0; i-- {
			if block, ok := sys[i].(map[string]any); ok {
				block["cache_control"] = ephemeral()
				return true
			}
		}
	}
	return false
}

func ephemeral() map[string]any {
	return map[string]any{"type": "ephemeral"}
}

package anthropic

import (
	"context"
	"encoding/json"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func enabled() providers.TransformPolicy {
	return providers.TransformPolicy{RuntimeMode: "active", Optimizers: map[string]bool{OptimizerID: true}}
}

func apply(t *testing.T, body string, policy providers.TransformPolicy) providers.TransformResult {
	t.Helper()
	a := New("http://upstream").(Adapter)
	res, err := a.ApplyProviderNativeTransforms(context.Background(), strings.NewReader(body), providers.RequestMetadata{Provider: "anthropic"}, policy)
	if err != nil {
		t.Fatalf("transform error: %v", err)
	}
	return res
}

func decode(t *testing.T, b []byte) map[string]any {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatalf("result not valid JSON: %v", err)
	}
	return m
}

func TestCacheBreakpoint_ToolsGetBreakpoint(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","tools":[{"name":"a","input_schema":{}},{"name":"b","input_schema":{}}],"messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, enabled())

	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != OptimizerID {
		t.Fatalf("optimizer ids = %v, want [%s]", res.OptimizerIDs, OptimizerID)
	}
	root := decode(t, res.Body)
	tools := root["tools"].([]any)
	last := tools[1].(map[string]any)
	cc, ok := last["cache_control"].(map[string]any)
	if !ok || cc["type"] != "ephemeral" {
		t.Errorf("last tool missing ephemeral cache_control: %v", last)
	}
	// First tool untouched; model + messages preserved.
	if _, has := tools[0].(map[string]any)["cache_control"]; has {
		t.Error("only the last tool should carry the breakpoint")
	}
	if root["model"] != "claude-sonnet-4-6" {
		t.Error("model not preserved")
	}
	if msgs := root["messages"].([]any); len(msgs) != 1 {
		t.Error("messages not preserved")
	}
}

func TestCacheBreakpoint_SkipsDeferredTool(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","tools":[{"name":"loaded","input_schema":{}},{"name":"deferred","defer_loading":true,"input_schema":{}}],"messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, enabled())

	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != OptimizerID {
		t.Fatalf("optimizer ids = %v, want [%s]", res.OptimizerIDs, OptimizerID)
	}
	root := decode(t, res.Body)
	tools := root["tools"].([]any)
	loaded := tools[0].(map[string]any)
	deferred := tools[1].(map[string]any)
	if cc, _ := loaded["cache_control"].(map[string]any); cc["type"] != "ephemeral" {
		t.Fatalf("last non-deferred tool missing cache_control: %v", loaded)
	}
	if _, exists := deferred["cache_control"]; exists {
		t.Fatalf("deferred tool must not carry cache_control: %v", deferred)
	}
}

func TestCacheBreakpoint_AllDeferredToolsFallsBackToSystem(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","tools":[{"name":"deferred","defer_loading":true,"input_schema":{}}],"system":"stable prefix","messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, enabled())

	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != OptimizerID {
		t.Fatalf("optimizer ids = %v, want [%s]", res.OptimizerIDs, OptimizerID)
	}
	root := decode(t, res.Body)
	deferred := root["tools"].([]any)[0].(map[string]any)
	if _, exists := deferred["cache_control"]; exists {
		t.Fatalf("deferred tool must not carry cache_control: %v", deferred)
	}
	system := root["system"].([]any)[0].(map[string]any)
	if cc, _ := system["cache_control"].(map[string]any); cc["type"] != "ephemeral" {
		t.Fatalf("system fallback missing cache_control: %v", system)
	}
}

func TestCacheBreakpoint_SystemStringConverted(t *testing.T) {
	body := `{"model":"claude-sonnet-4-6","system":"You are a careful assistant.","messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, enabled())
	if len(res.OptimizerIDs) != 1 {
		t.Fatalf("expected optimizer applied, got %v", res.OptimizerIDs)
	}
	root := decode(t, res.Body)
	sys, ok := root["system"].([]any)
	if !ok || len(sys) != 1 {
		t.Fatalf("system not converted to block array: %v", root["system"])
	}
	block := sys[0].(map[string]any)
	if block["text"] != "You are a careful assistant." {
		t.Errorf("system text not preserved: %v", block["text"])
	}
	if cc, _ := block["cache_control"].(map[string]any); cc["type"] != "ephemeral" {
		t.Errorf("system block missing cache_control: %v", block)
	}
}

func TestCacheBreakpoint_SystemArrayLastBlock(t *testing.T) {
	body := `{"system":[{"type":"text","text":"a"},{"type":"text","text":"b"}],"messages":[]}`
	res := apply(t, body, enabled())
	root := decode(t, res.Body)
	sys := root["system"].([]any)
	if _, has := sys[0].(map[string]any)["cache_control"]; has {
		t.Error("only the last system block should carry the breakpoint")
	}
	if cc, _ := sys[1].(map[string]any)["cache_control"].(map[string]any); cc["type"] != "ephemeral" {
		t.Error("last system block missing cache_control")
	}
}

func TestCacheBreakpoint_PreservesUntouchedRawBytes(t *testing.T) {
	body := "{\n \"model\" : \"claude-sonnet-4-6\", \"tools\" : [ { \"name\" : \"a\", \"description\":\"<>&\" } ],\n \"messages\" : [ {\"role\":\"user\",\"content\":\"hi\"} ]\n}"
	res := apply(t, body, enabled())
	want := "{\n \"model\" : \"claude-sonnet-4-6\", \"tools\" : [ { \"name\" : \"a\", \"description\":\"<>&\",\"cache_control\":{\"type\":\"ephemeral\"} } ],\n \"messages\" : [ {\"role\":\"user\",\"content\":\"hi\"} ]\n}"
	if string(res.Body) != want {
		t.Fatalf("raw insertion reserialized untouched bytes:\n got %s\nwant %s", res.Body, want)
	}
}

func TestCacheBreakpoint_SystemStringPreservesEscapeSpelling(t *testing.T) {
	body := `{"system":"You are \u003cexact\u003e","messages":[]}`
	res := apply(t, body, enabled())
	if !strings.Contains(string(res.Body), `"text":"You are \u003cexact\u003e"`) {
		t.Fatalf("system string escape spelling changed: %s", res.Body)
	}
}

func TestCacheBreakpoint_DisabledIsPassthrough(t *testing.T) {
	body := `{"tools":[{"name":"a"}],"messages":[]}`
	res := apply(t, body, providers.TransformPolicy{RuntimeMode: "active", Optimizers: map[string]bool{}})
	if len(res.OptimizerIDs) != 0 {
		t.Errorf("disabled optimizer should not apply, got %v", res.OptimizerIDs)
	}
	if string(res.Body) != body {
		t.Errorf("disabled optimizer must pass body through unchanged")
	}
}

func TestCacheBreakpoint_NonPAYGIsPassthrough(t *testing.T) {
	body := `{"system":"stable prefix","messages":[{"role":"user","content":"hi"}]}`
	policy := enabled()
	policy.AuthMode = "subscription"
	res := apply(t, body, policy)
	if len(res.OptimizerIDs) != 0 {
		t.Fatalf("subscription must not apply cache breakpoint, got %v", res.OptimizerIDs)
	}
	if string(res.Body) != body {
		t.Fatalf("subscription cache-breakpoint gate must preserve bytes:\n got %s\nwant %s", res.Body, body)
	}
}

func TestCacheBreakpoint_IdempotentAndRespectsExisting(t *testing.T) {
	// Caller already manages caching -> passthrough, no double-claim.
	body := `{"tools":[{"name":"a","cache_control":{"type":"ephemeral"}}],"messages":[]}`
	res := apply(t, body, enabled())
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("existing cache_control must be respected (passthrough), got ids=%v", res.OptimizerIDs)
	}

	// Applying our own output again is a no-op (idempotent).
	once := apply(t, `{"tools":[{"name":"a"}],"messages":[]}`, enabled())
	twice := apply(t, string(once.Body), enabled())
	if len(twice.OptimizerIDs) != 0 {
		t.Errorf("re-applying should be idempotent, got %v", twice.OptimizerIDs)
	}
}

func TestCacheBreakpoint_UnicodeEscapedCallerKeyCannotMintAttribution(t *testing.T) {
	body := `{"tools":[{"name":"a","cache\u005fcontrol":{"type":"ephemeral"}}],"messages":[]}`
	res := apply(t, body, enabled())
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Fatalf("decoded caller cache_control must remain pass-through, got ids=%v body=%s", res.OptimizerIDs, res.Body)
	}
}

func TestCacheBreakpoint_NoStablePrefixOrBadJSON(t *testing.T) {
	// No tools, no system -> nothing to cache.
	res := apply(t, `{"messages":[{"role":"user","content":"hi"}]}`, enabled())
	if len(res.OptimizerIDs) != 0 {
		t.Errorf("no stable prefix should be passthrough, got %v", res.OptimizerIDs)
	}
	// Invalid JSON -> passthrough, no error.
	bad := apply(t, `not json`, enabled())
	if len(bad.OptimizerIDs) != 0 || string(bad.Body) != "not json" {
		t.Errorf("invalid JSON must pass through unchanged")
	}
}

package anthropic

// COGS regression guard for the gateway's per-request CPU cost.
//
// Why this exists: the pricing model in docs/strategy/PRICING_V2.md §1.3 is built
// on a measured claim — the byte-safe transform costs ~10 ns per byte of request
// body, which prices a million agentic requests at roughly EUR 0.13 of Scaleway
// compute. That claim is load-bearing for "the gateway hop is free" (§4.1), so it
// needs a guard: if the transform path ever regresses into super-linear behaviour
// or picks up a per-request allocation storm, the pricing conclusion changes and
// someone should notice here rather than on an invoice.
//
// Read ns/op against body size. The invariant to watch is MB/s staying roughly
// FLAT across the four sizes (linear CPU in body bytes). A collapse at the large
// sizes means the cost model in §1.3 is stale and PRICING_V2.md §1.3 + §3's margin
// table must be re-derived.
//
// Measured 2026-08-02 on Apple M3 Pro, Go 1.26.5 (the numbers quoted in the spec):
//
//	body_4KB_actual_8KB       92,473 ns/op    92.55 MB/s     323 allocs/op
//	body_20KB_actual_16KB    174,549 ns/op    96.31 MB/s     393 allocs/op
//	body_100KB_actual_56KB   540,047 ns/op   107.53 MB/s     719 allocs/op
//	body_400KB_actual_207KB1,951,058 ns/op   109.07 MB/s   1,926 allocs/op
//
// Run: go test ./proxy/providers/anthropic/ -run='^$' -bench=BenchmarkTransformCOGS
//
// Note this measures the transform only. Per §1.3 the gateway's dominant marginal
// cost is memory-seconds held during streaming, not CPU — that is a concurrency
// property and is not measurable here.

import (
	"context"
	"encoding/json"
	"fmt"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// buildCOGSBody builds a realistic Anthropic /v1/messages body of approximately
// the requested size: a system prompt, an 8-tool catalog, and a multi-turn
// message history — the shape an agentic caller actually sends.
func buildCOGSBody(approxKB int) string {
	filler := strings.Repeat("The agent must verify each claim against the ledger before reporting. ", 30)
	tools := make([]map[string]any, 0, 8)
	for i := 0; i < 8; i++ {
		tools = append(tools, map[string]any{
			"name":        fmt.Sprintf("tool_%d", i),
			"description": filler[:400],
			"input_schema": map[string]any{
				"type": "object",
				"properties": map[string]any{
					"query": map[string]any{"type": "string"},
					"limit": map[string]any{"type": "integer"},
				},
			},
		})
	}
	turns := approxKB / 2
	if turns < 2 {
		turns = 2
	}
	msgs := make([]map[string]any, 0, turns)
	for i := 0; i < turns; i++ {
		role := "user"
		if i%2 == 1 {
			role = "assistant"
		}
		msgs = append(msgs, map[string]any{"role": role, "content": filler[:1000]})
	}
	b, err := json.Marshal(map[string]any{
		"model":      "claude-sonnet-4-6",
		"max_tokens": 4096,
		"system":     []any{map[string]any{"type": "text", "text": filler}},
		"tools":      tools,
		"messages":   msgs,
	})
	if err != nil {
		panic(err)
	}
	return string(b)
}

func BenchmarkTransformCOGS(b *testing.B) {
	a := New("http://upstream").(Adapter)
	policy := providers.TransformPolicy{
		RuntimeMode: "active",
		Optimizers:  map[string]bool{OptimizerID: true},
	}
	for _, kb := range []int{4, 20, 100, 400} {
		body := buildCOGSBody(kb)
		b.Run(fmt.Sprintf("body_%dKB_actual_%dKB", kb, len(body)/1024), func(b *testing.B) {
			b.SetBytes(int64(len(body)))
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				res, err := a.ApplyProviderNativeTransforms(
					context.Background(),
					strings.NewReader(body),
					providers.RequestMetadata{Provider: "anthropic"},
					policy,
				)
				if err != nil {
					b.Fatalf("transform error: %v", err)
				}
				if len(res.Body) == 0 {
					b.Fatal("transform returned an empty body")
				}
			}
		})
	}
}

package anthropic

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"os"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// FrozenPrefixComponents returns exact JSON value bytes that Anthropic treats as
// frozen context: top-level system/tools plus messages below cache floor.
// Length-prefixed framing prevents concatenation ambiguity. Live tail stays out,
// so its growth cannot rotate observed prefix digest.
func (a Adapter) FrozenPrefixComponents(body []byte, meta providers.RequestMetadata) ([][]byte, bool) {
	if strings.Contains(meta.Endpoint, "count_tokens") {
		return nil, false
	}
	root, ok := rootObjectSpan(body)
	if !ok {
		return nil, false
	}
	messagesValue, ok := findObjectField(body, root, "messages")
	if !ok || messagesValue.start >= len(body) || body[messagesValue.start] != '[' {
		return nil, false
	}
	messages, ok := arrayElements(body, messagesValue)
	if !ok {
		return nil, false
	}
	rawMessages := make([]json.RawMessage, len(messages))
	for i, span := range messages {
		rawMessages[i] = append(json.RawMessage(nil), body[span.start:span.end]...)
	}
	floor := ComputeFrozenCount(rawMessages)
	if floor < 0 || floor > len(messages) {
		return nil, false
	}
	out := [][]byte{[]byte("cave.anthropic.frozen-prefix.v1")}
	for _, name := range []string{"system", "tools"} {
		if span, exists := findObjectField(body, root, name); exists {
			out = append(out, frozenField(name, body[span.start:span.end]))
		} else {
			out = append(out, frozenField(name, nil))
		}
	}
	for i := 0; i < floor; i++ {
		out = append(out, frozenField("message", body[messages[i].start:messages[i].end]))
	}
	return out, true
}

func frozenField(name string, value []byte) []byte {
	var length [8]byte
	binary.BigEndian.PutUint32(length[:4], uint32(len(name)))
	binary.BigEndian.PutUint32(length[4:], uint32(len(value)))
	out := append([]byte(nil), length[:]...)
	out = append(out, name...)
	out = append(out, value...)
	return out
}

// ExtractCompressible returns only the Anthropic live zone. For conversations
// that carry cache_control markers (Claude Code, caching SDKs) the live zone is
// the provider-uncacheable tail: every user or trailing injected system message
// at/after the frozen floor — content past the last breakpoint is never cached
// upstream, so compressing it can never bust a prefix. Without markers there is
// no way to know what the provider cached, so only the just-arrived latest user
// message qualifies. It never collects the top-level system field, tools,
// frozen messages, assistant messages, or non-text blocks, and reassembly
// byte-splices changed string values into the original request bytes.
func (a Adapter) ExtractCompressible(body []byte, meta providers.RequestMetadata) ([][]byte, func([][]byte) ([]byte, error), bool) {
	messageSpans, live, ok := messageZones(body, meta)
	if !ok || len(live) == 0 {
		return nil, nil, false
	}
	recovered := recoveryToolUseIDs(body, messageSpans)
	var candidates []spliceCandidate
	for i, span := range messageSpans {
		if live[i] {
			candidates = append(candidates, collectAnthropicCandidates(body, span, recovered)...)
		}
	}
	if len(candidates) == 0 {
		return nil, nil, false
	}
	segments := make([][]byte, len(candidates))
	for i, c := range candidates {
		segments[i] = append([]byte(nil), c.original...)
	}
	reassemble := func(reps [][]byte) ([]byte, error) {
		return spliceStringReplacements(body, candidates, reps)
	}
	return segments, reassemble, true
}

// ExtractStabilizable returns every content block the proxy may rewrite, each
// tagged with the cache zone it sits in: the live zone (Live, eligible for new
// compression) plus the frozen user/system blocks at or below the cache_control
// floor (eligible ONLY for byte-identical substitution of a replacement the proxy
// already emitted for those exact bytes).
//
// Frozen blocks have to be exposed because compression is not a one-turn event: a
// message compressed while it WAS the live zone arrives again on the next turn as
// the client's original bytes, now below the floor. Forwarding those originals
// would flip the upstream prefix back to a form the provider never cached and miss
// the cache entry the previous turn paid to create — so the caller substitutes the
// stored replacement and the prefix stays byte-stable for the whole conversation.
// Assistant blocks are never collected: the proxy never compresses them, so a
// substitution could never exist for them.
func (a Adapter) ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool) {
	messageSpans, live, ok := messageZones(body, meta)
	if !ok {
		return nil, nil, false
	}
	recovered := recoveryToolUseIDs(body, messageSpans)
	var candidates []spliceCandidate
	var blocks []providers.RewritableBlock
	for i, span := range messageSpans {
		if !live[i] {
			switch messageRole(body, span) {
			case "user", "system":
			default:
				continue
			}
		}
		for _, c := range collectAnthropicCandidates(body, span, recovered) {
			candidates = append(candidates, c)
			blocks = append(blocks, providers.RewritableBlock{
				Content: append([]byte(nil), c.original...),
				Live:    live[i],
				Kind:    c.kind,
			})
		}
	}
	if len(blocks) == 0 {
		return nil, nil, false
	}
	reassemble := func(reps [][]byte) ([]byte, error) {
		return spliceStringReplacements(body, candidates, reps)
	}
	return blocks, reassemble, true
}

// messageZones parses a request into its message spans plus the set of message
// indexes that form the live zone. It is the single definition of "live" shared by
// ExtractCompressible (live blocks only) and ExtractStabilizable (live + frozen),
// so the two can never disagree about where the cache floor sits.
func messageZones(body []byte, meta providers.RequestMetadata) ([]jsonSpan, map[int]bool, bool) {
	if strings.Contains(meta.Endpoint, "count_tokens") {
		return nil, nil, false
	}
	root, ok := rootObjectSpan(body)
	if !ok {
		return nil, nil, false
	}
	messagesSpan, ok := findObjectField(body, root, "messages")
	if !ok || messagesSpan.start >= len(body) || body[messagesSpan.start] != '[' {
		return nil, nil, false
	}
	messageSpans, ok := arrayElements(body, messagesSpan)
	if !ok || len(messageSpans) == 0 {
		return nil, nil, false
	}

	rawMessages := make([]json.RawMessage, 0, len(messageSpans))
	for _, span := range messageSpans {
		rawMessages = append(rawMessages, append(json.RawMessage(nil), body[span.start:span.end]...))
	}
	floor := ComputeFrozenCount(rawMessages)
	live := make(map[int]bool)
	if messagesHaveContentCacheControl(rawMessages) {
		for i := floor; i < len(messageSpans); i++ {
			switch messageRole(body, messageSpans[i]) {
			case "user", "system":
				live[i] = true
			}
		}
	} else {
		for i := len(messageSpans) - 1; i >= floor; i-- {
			if messageRole(body, messageSpans[i]) == "user" {
				live[i] = true
				break
			}
		}
	}
	return messageSpans, live, true
}

func messageRole(body []byte, msg jsonSpan) string {
	role, ok := objectStringField(body, msg, "role")
	if !ok {
		return ""
	}
	return role
}

func objectStringField(body []byte, obj jsonSpan, field string) (string, bool) {
	value, ok := findObjectField(body, obj, field)
	if !ok || !isJSONString(body, value) {
		return "", false
	}
	return decodeJSONString(body[value.start:value.end])
}

// recoveryToolUseIDs collects the tool_use ids of every caveman recovery call in
// the conversation, so the tool_result answering one can be left alone. See
// providers.IsRecoveryToolName for why compressing recovered bytes strands the
// agent with no path back to its own data.
func recoveryToolUseIDs(body []byte, messageSpans []jsonSpan) map[string]bool {
	ids := make(map[string]bool)
	for _, msg := range messageSpans {
		if messageRole(body, msg) != "assistant" {
			continue
		}
		content, ok := findObjectField(body, msg, "content")
		if !ok || content.start >= content.end || body[content.start] != '[' {
			continue
		}
		blocks, ok := arrayElements(body, content)
		if !ok {
			continue
		}
		for _, block := range blocks {
			if block.start >= block.end || body[block.start] != '{' {
				continue
			}
			if typ, _ := objectStringField(body, block, "type"); typ != "tool_use" {
				continue
			}
			name, _ := objectStringField(body, block, "name")
			if !providers.IsRecoveryToolName(name) {
				continue
			}
			if id, ok := objectStringField(body, block, "id"); ok && id != "" {
				ids[id] = true
			}
		}
	}
	return ids
}

func collectAnthropicCandidates(body []byte, msg jsonSpan, recovered map[string]bool) []spliceCandidate {
	content, ok := findObjectField(body, msg, "content")
	if !ok {
		return nil
	}
	var out []spliceCandidate
	switch {
	case isJSONString(body, content):
		collectStringCandidate(body, content, &out, false, "history")
	case content.start < content.end && body[content.start] == '[':
		collectAnthropicBlocks(body, content, &out, false, recovered)
	}
	return out
}

func collectAnthropicBlocks(body []byte, blocksSpan jsonSpan, out *[]spliceCandidate, inToolResult bool, recovered map[string]bool) {
	blocks, ok := arrayElements(body, blocksSpan)
	if !ok {
		return
	}
	for _, block := range blocks {
		if block.start >= block.end || body[block.start] != '{' {
			continue
		}
		typ, ok := objectStringField(body, block, "type")
		if !ok {
			continue
		}
		switch typ {
		case "text":
			if textSpan, ok := findObjectField(body, block, "text"); ok && isJSONString(body, textSpan) {
				kind := "history"
				if inToolResult {
					kind = "tool_result"
				}
				collectStringCandidate(body, textSpan, out, inToolResult, kind)
			}
		case "tool_result":
			// Recovered bytes are never a compression candidate — not on the turn they
			// arrive, and not as frozen history afterwards, because collecting them at
			// all would let the prefix cache substitute the elision back in.
			if id, ok := objectStringField(body, block, "tool_use_id"); ok && recovered[id] {
				continue
			}
			content, ok := findObjectField(body, block, "content")
			if !ok {
				continue
			}
			switch {
			case isJSONString(body, content):
				collectStringCandidate(body, content, out, true, "tool_result")
			case content.start < content.end && body[content.start] == '[':
				collectAnthropicBlocks(body, content, out, true, recovered)
			}
		}
	}
}

func collectStringCandidate(
	body []byte,
	span jsonSpan,
	out *[]spliceCandidate,
	allowForcedTOON bool,
	kind string,
) {
	value, ok := decodeJSONString(body[span.start:span.end])
	if !ok {
		return
	}
	original := []byte(value)
	if len(original) < minCompressBlockBytes && !(allowForcedTOON && forcedTOONCandidate(original)) {
		return
	}
	*out = append(*out, spliceCandidate{jsonSpan: span, original: original, kind: kind})
}

func forcedTOONCandidate(original []byte) bool {
	if !strings.EqualFold(os.Getenv("CAVE_ENGINE_TOON"), "best-of") {
		return false
	}
	trimmed := bytes.TrimSpace(original)
	return len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[')
}

