func TestParseNonNegativeInt(t *testing.T) {
	maxInt := strconv.FormatUint(uint64(math.MaxInt), 10)
	tests := []struct {
		name  string
		body  string
		field string
		want  int
		ok    bool
	}{
		{name: "zero", body: `{"count":0}`, field: "count", want: 0, ok: true},
		{name: "positive", body: `{"count":42}`, field: "count", want: 42, ok: true},
		{name: "max int", body: `{"count":` + maxInt + `}`, field: "count", want: math.MaxInt, ok: true},
		{name: "missing", body: `{}`, field: "count"},
		{name: "negative", body: `{"count":-1}`, field: "count"},
		{name: "decimal", body: `{"count":1.5}`, field: "count"},
		{name: "string", body: `{"count":"1"}`, field: "count"},
		{name: "null", body: `{"count":null}`, field: "count"},
		{name: "overflow", body: `{"count":18446744073709551615}`, field: "count"},
		{name: "duplicate target key", body: `{"count":1,"count":2}`, field: "count"},
		{name: "duplicate unrelated key", body: `{"other":1,"other":2,"count":3}`, field: "count"},
		{name: "trailing JSON value", body: `{"count":1}{}`, field: "count"},
		{name: "trailing non-whitespace", body: `{"count":1}x`, field: "count"},
		{name: "invalid JSON", body: `{`, field: "count"},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			got, ok := ParseNonNegativeInt([]byte(test.body), test.field)
			if got != test.want || ok != test.ok {
				t.Fatalf("ParseNonNegativeInt() = (%d, %v), want (%d, %v)", got, ok, test.want, test.ok)
			}
		})
	}
}

package jsonsplice

import (
	"bytes"
	"encoding/json"
	"fmt"
)

type Span struct{ Start, End int }

type Candidate struct {
	Span
	Original []byte
}

type FieldInsertion struct {
	Name  string
	Value []byte
}

func Root(body []byte) (Span, bool) {
	if !json.Valid(body) {
		return Span{}, false
	}
	start := space(body, 0)
	end, ok := value(body, start)
	return Span{start, end}, ok && start < len(body) && body[start] == '{' && space(body, end) == len(body)
}

func Field(body []byte, object Span, name string) (Span, bool) {
	if object.Start < 0 || object.End > len(body) || object.Start >= object.End ||
		body[object.Start] != '{' || body[object.End-1] != '}' {
		return Span{}, false
	}
	for i := space(body, object.Start+1); i < object.End && body[i] != '}'; {
		keyEnd, ok := stringEnd(body, i)
		if !ok {
			return Span{}, false
		}
		var key string
		if json.Unmarshal(body[i:keyEnd], &key) != nil {
			return Span{}, false
		}
		i = space(body, keyEnd)
		if i >= object.End || body[i] != ':' {
			return Span{}, false
		}
		start := space(body, i+1)
		end, ok := value(body, start)
		if !ok {
			return Span{}, false
		}
		if key == name {
			return Span{start, end}, true
		}
		i = space(body, end)
		if i < object.End && body[i] == ',' {
			i = space(body, i+1)
		}
	}
	return Span{}, false
}

func Elements(body []byte, array Span) ([]Span, bool) {
	if array.Start < 0 || array.End > len(body) || array.Start >= array.End ||
		body[array.Start] != '[' || body[array.End-1] != ']' {
		return nil, false
	}
	var out []Span
	for i := space(body, array.Start+1); i < array.End && body[i] != ']'; {
		end, ok := value(body, i)
		if !ok {
			return nil, false
		}
		out = append(out, Span{i, end})
		i = space(body, end)
		if i < array.End && body[i] == ',' {
			i = space(body, i+1)
		}
	}
	return out, true
}

func String(body []byte, span Span) (string, bool) {
	if span.Start < 0 || span.End > len(body) || span.Start >= span.End || body[span.Start] != '"' {
		return "", false
	}
	var out string
	if json.Unmarshal(body[span.Start:span.End], &out) != nil {
		return "", false
	}
	return out, true
}

func StringField(body []byte, object Span, name string) (string, bool) {
	span, ok := Field(body, object, name)
	if !ok {
		return "", false
	}
	return String(body, span)
}

func Replace(body []byte, candidates []Candidate, replacements [][]byte) ([]byte, error) {
	if len(candidates) != len(replacements) {
		return nil, fmt.Errorf("json splice: %d replacements for %d candidates", len(replacements), len(candidates))
	}
	var out []byte
	last := 0
	for i, candidate := range candidates {
		if candidate.Start < last || candidate.End > len(body) || candidate.Start >= candidate.End {
			return nil, fmt.Errorf("json splice: invalid range")
		}
		replacement := replacements[i]
		if replacement == nil || bytes.Equal(replacement, candidate.Original) {
			continue
		}
		quoted, err := quote(string(replacement))
		if err != nil {
			return nil, err
		}
		if out == nil {
			out = make([]byte, 0, len(body)-len(candidate.Original)+len(replacement))
		}
		out = append(out, body[last:candidate.Start]...)
		out = append(out, quoted...)
		last = candidate.End
	}
	if out == nil {
		return body, nil
	}
	return append(out, body[last:]...), nil
}

// ReplaceRaw replaces one JSON value while preserving every byte outside span.
// replacement must itself be valid JSON. Unlike Replace, it does not quote the
// replacement and is suitable for provider-envelope edits.
func ReplaceRaw(body []byte, span Span, replacement []byte) ([]byte, error) {
	if span.Start < 0 || span.End > len(body) || span.Start >= span.End {
		return nil, fmt.Errorf("json splice: invalid range")
	}
	if !json.Valid(replacement) {
		return nil, fmt.Errorf("json splice: replacement is not valid JSON")
	}
	out := make([]byte, 0, len(body)-(span.End-span.Start)+len(replacement))
	out = append(out, body[:span.Start]...)
	out = append(out, replacement...)
	out = append(out, body[span.End:]...)
	return out, nil
}

// AppendObjectFields inserts fields immediately before an object's closing
// brace. Existing bytes, whitespace, key order, and escapes remain untouched.
// Callers must reject existing decoded keys before calling this function.
func AppendObjectFields(body []byte, object Span, fields ...FieldInsertion) ([]byte, error) {
	if object.Start < 0 || object.End > len(body) || object.Start >= object.End ||
		body[object.Start] != '{' || body[object.End-1] != '}' {
		return nil, fmt.Errorf("json splice: invalid object range")
	}
	if len(fields) == 0 {
		return body, nil
	}

	insertAt := object.End - 1
	for insertAt > object.Start+1 && bytes.ContainsRune([]byte(" \n\r\t"), rune(body[insertAt-1])) {
		insertAt--
	}
	hasFields := insertAt > object.Start+1

	var addition bytes.Buffer
	if hasFields {
		addition.WriteByte(',')
	}
	for i, field := range fields {
		if field.Name == "" || !json.Valid(field.Value) {
			return nil, fmt.Errorf("json splice: invalid field insertion")
		}
		if i > 0 {
			addition.WriteByte(',')
		}
		name, err := json.Marshal(field.Name)
		if err != nil {
			return nil, err
		}
		addition.Write(name)
		addition.WriteByte(':')
		addition.Write(field.Value)
	}

	out := make([]byte, 0, len(body)+addition.Len())
	out = append(out, body[:insertAt]...)
	out = append(out, addition.Bytes()...)
	out = append(out, body[insertAt:]...)
	return out, nil
}

func value(body []byte, start int) (int, bool) {
	i := space(body, start)
	if i >= len(body) {
		return 0, false
	}
	if body[i] == '"' {
		return stringEnd(body, i)
	}
	if body[i] == '{' || body[i] == '[' {
		depth := 0
		for j := i; j < len(body); j++ {
			switch body[j] {
			case '"':
				end, ok := stringEnd(body, j)
				if !ok {
					return 0, false
				}
				j = end - 1
			case '{', '[':
				depth++
			case '}', ']':
				depth--
				if depth == 0 {
					return j + 1, true
				}
			}
		}
		return 0, false
	}
	j := i
	for j < len(body) && !bytes.ContainsRune([]byte(",}] \n\r\t"), rune(body[j])) {
		j++
	}
	return j, j > i
}

func stringEnd(body []byte, start int) (int, bool) {
	if start >= len(body) || body[start] != '"' {
		return 0, false
	}
	for i := start + 1; i < len(body); i++ {
		if body[i] == '\\' {
			i++
		} else if body[i] == '"' {
			return i + 1, true
		}
	}
	return 0, false
}

func space(body []byte, i int) int {
	for i < len(body) && bytes.ContainsRune([]byte(" \n\r\t"), rune(body[i])) {
		i++
	}
	return i
}

func quote(value string) ([]byte, error) {
	var buf bytes.Buffer
	encoder := json.NewEncoder(&buf)
	encoder.SetEscapeHTML(false)
	if err := encoder.Encode(value); err != nil {
		return nil, err
	}
	return bytes.TrimSuffix(buf.Bytes(), []byte("\n")), nil
}

package jsonsplice_test

import (
	"bytes"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers/jsonsplice"
)

func TestRootAcceptsOnlyCompleteObjects(t *testing.T) {
	tests := []struct {
		name string
		body string
		ok   bool
	}{
		{"object with whitespace", " \n {\"a\":1}\t", true},
		{"nested object", `{"a":[{"b":"brace } [ remains text"}]}`, true},
		{"array", `[]`, false},
		{"scalar", `1`, false},
		{"trailing value", `{} []`, false},
		{"malformed", `{"a":`, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			span, ok := jsonsplice.Root([]byte(tc.body))
			if ok != tc.ok {
				t.Fatalf("Root(%q) ok=%v, want %v", tc.body, ok, tc.ok)
			}
			if ok && string([]byte(tc.body)[span.Start:span.End]) != stringsTrimSpace(tc.body) {
				t.Fatalf("root span = %q", []byte(tc.body)[span.Start:span.End])
			}
		})
	}
}

func TestFieldElementsAndStringsNavigateWithoutReencoding(t *testing.T) {
	body := []byte(`{"escaped\u005fkey":"line\nvalue","items":[1,{"name":"second"},["nested"]],"flag":true}`)
	root, ok := jsonsplice.Root(body)
	if !ok {
		t.Fatal("root not found")
	}
	if got, ok := jsonsplice.StringField(body, root, "escaped_key"); !ok || got != "line\nvalue" {
		t.Fatalf("decoded string field = %q, %v", got, ok)
	}
	items, ok := jsonsplice.Field(body, root, "items")
	if !ok {
		t.Fatal("items not found")
	}
	elements, ok := jsonsplice.Elements(body, items)
	if !ok || len(elements) != 3 {
		t.Fatalf("elements = %+v, %v", elements, ok)
	}
	if string(body[elements[0].Start:elements[0].End]) != "1" ||
		string(body[elements[1].Start:elements[1].End]) != `{"name":"second"}` ||
		string(body[elements[2].Start:elements[2].End]) != `["nested"]` {
		t.Fatalf("element spans changed bytes: %q %q %q",
			body[elements[0].Start:elements[0].End],
			body[elements[1].Start:elements[1].End],
			body[elements[2].Start:elements[2].End])
	}
	secondName, ok := jsonsplice.StringField(body, elements[1], "name")
	if !ok || secondName != "second" {
		t.Fatalf("nested string field = %q, %v", secondName, ok)
	}
	if _, ok := jsonsplice.Field(body, root, "missing"); ok {
		t.Fatal("missing field reported present")
	}
	if _, ok := jsonsplice.StringField(body, root, "flag"); ok {
		t.Fatal("non-string field decoded as string")
	}
	if empty, ok := jsonsplice.Elements([]byte(`[]`), jsonsplice.Span{Start: 0, End: 2}); !ok || len(empty) != 0 {
		t.Fatalf("empty array = %+v, %v", empty, ok)
	}
}

func TestNavigationRejectsInvalidSpansAndMalformedContainers(t *testing.T) {
	body := []byte(`{"a":1}`)
	invalid := []jsonsplice.Span{
		{Start: -1, End: 2},
		{Start: 0, End: len(body) + 1},
		{Start: 2, End: 2},
		{Start: 1, End: len(body)},
	}
	for _, span := range invalid {
		if _, ok := jsonsplice.Field(body, span, "a"); ok {
			t.Errorf("Field accepted invalid span %+v", span)
		}
		if _, ok := jsonsplice.Elements(body, span); ok {
			t.Errorf("Elements accepted invalid span %+v", span)
		}
		if _, ok := jsonsplice.String(body, span); ok {
			t.Errorf("String accepted invalid span %+v", span)
		}
	}
	if _, ok := jsonsplice.Field([]byte(`{"a" 1}`), jsonsplice.Span{Start: 0, End: 7}, "a"); ok {
		t.Fatal("field parser accepted missing colon")
	}
	if _, ok := jsonsplice.Elements([]byte(`[{"a":1}`), jsonsplice.Span{Start: 0, End: 8}); ok {
		t.Fatal("elements parser accepted unterminated value")
	}
}

func TestReplaceQuotesChangedStringsAndPreservesEverythingElse(t *testing.T) {
	body := []byte(`{"a":"old","keep":"\u003c","b":"same"}`)
	root, _ := jsonsplice.Root(body)
	a, _ := jsonsplice.Field(body, root, "a")
	b, _ := jsonsplice.Field(body, root, "b")
	candidates := []jsonsplice.Candidate{
		{Span: a, Original: []byte("old")},
		{Span: b, Original: []byte("same")},
	}
	got, err := jsonsplice.Replace(body, candidates, [][]byte{[]byte("<new>\n"), []byte("same")})
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != `{"a":"<new>\n","keep":"\u003c","b":"same"}` {
		t.Fatalf("Replace output = %s", got)
	}

	unchanged, err := jsonsplice.Replace(body, candidates, [][]byte{nil, []byte("same")})
	if err != nil {
		t.Fatal(err)
	}
	if len(unchanged) > 0 && &unchanged[0] != &body[0] {
		t.Fatal("no-op replacement allocated or rewrote body")
	}
}

func TestReplaceRejectsCountAndRangeErrors(t *testing.T) {
	body := []byte(`{"a":"x","b":"y"}`)
	root, _ := jsonsplice.Root(body)
	a, _ := jsonsplice.Field(body, root, "a")
	b, _ := jsonsplice.Field(body, root, "b")
	if _, err := jsonsplice.Replace(body, []jsonsplice.Candidate{{Span: a}}, nil); err == nil {
		t.Fatal("mismatched replacement count accepted")
	}
	for _, candidates := range [][]jsonsplice.Candidate{
		{{Span: jsonsplice.Span{Start: -1, End: 2}}},
		{{Span: jsonsplice.Span{Start: 0, End: len(body) + 1}}},
		{{Span: jsonsplice.Span{Start: 2, End: 2}}},
		{{Span: b}, {Span: a}},
	} {
		replacements := make([][]byte, len(candidates))
		for i := range replacements {
			replacements[i] = []byte("changed")
		}
		if _, err := jsonsplice.Replace(body, candidates, replacements); err == nil {
			t.Fatalf("invalid candidates accepted: %+v", candidates)
		}
	}
}

func TestAppendObjectFieldsPreservesOriginalBytes(t *testing.T) {
	body := []byte("{\n  \"model\" : \"gpt-5.6\", \"messages\": [ {\"role\":\"user\",\"content\":\"<>&\"} ] \n}")
	root, ok := jsonsplice.Root(body)
	if !ok {
		t.Fatal("root not found")
	}
	got, err := jsonsplice.AppendObjectFields(body, root,
		jsonsplice.FieldInsertion{Name: "prompt_cache_key", Value: []byte(`"abc"`)},
		jsonsplice.FieldInsertion{Name: "reasoning_effort", Value: []byte(`"low"`)},
	)
	if err != nil {
		t.Fatal(err)
	}
	inserted := []byte(`,"prompt_cache_key":"abc","reasoning_effort":"low"`)
	want := bytes.Replace(body, []byte(" \n}"), append(inserted, ' ', '\n', '}'), 1)
	if !bytes.Equal(got, want) {
		t.Fatalf("raw insertion changed original bytes:\n got %s\nwant %s", got, want)
	}
}

func TestAppendObjectFieldsHandlesEmptyObject(t *testing.T) {
	body := []byte(`{  }`)
	root, ok := jsonsplice.Root(body)
	if !ok {
		t.Fatal("root not found")
	}
	got, err := jsonsplice.AppendObjectFields(body, root,
		jsonsplice.FieldInsertion{Name: "cache_control", Value: []byte(`{"type":"ephemeral"}`)},
	)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != `{"cache_control":{"type":"ephemeral"}  }` {
		t.Fatalf("unexpected insertion: %s", got)
	}
}

func TestAppendObjectFieldsValidatesInputsAndNoOpPreservesBody(t *testing.T) {
	body := []byte(`{"a":1}`)
	root, _ := jsonsplice.Root(body)
	got, err := jsonsplice.AppendObjectFields(body, root)
	if err != nil {
		t.Fatal(err)
	}
	if len(got) > 0 && &got[0] != &body[0] {
		t.Fatal("empty insertion allocated or rewrote body")
	}

	tests := []struct {
		name   string
		span   jsonsplice.Span
		fields []jsonsplice.FieldInsertion
	}{
		{"invalid object range", jsonsplice.Span{Start: 1, End: len(body)}, []jsonsplice.FieldInsertion{{Name: "b", Value: []byte("2")}}},
		{"empty name", root, []jsonsplice.FieldInsertion{{Value: []byte("2")}}},
		{"invalid JSON value", root, []jsonsplice.FieldInsertion{{Name: "b", Value: []byte(`{`)}}},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, err := jsonsplice.AppendObjectFields(body, tc.span, tc.fields...); err == nil {
				t.Fatal("invalid insertion accepted")
			}
		})
	}
}

func TestReplaceRawPreservesOutsideSpan(t *testing.T) {
	body := []byte(`{"system":"You \u003c exact","messages":[]}`)
	root, ok := jsonsplice.Root(body)
	if !ok {
		t.Fatal("root not found")
	}
	system, ok := jsonsplice.Field(body, root, "system")
	if !ok {
		t.Fatal("system not found")
	}
	replacement := append([]byte(`[{"type":"text","text":`), body[system.Start:system.End]...)
	replacement = append(replacement, []byte(`,"cache_control":{"type":"ephemeral"}}]`)...)
	got, err := jsonsplice.ReplaceRaw(body, system, replacement)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Contains(got, []byte(`"text":"You \u003c exact"`)) {
		t.Fatalf("original string spelling was not preserved: %s", got)
	}
	if !bytes.HasSuffix(got, []byte(`,"messages":[]}`)) {
		t.Fatalf("bytes after replaced span changed: %s", got)
	}
}

func TestReplaceRawRejectsInvalidRangeAndReplacement(t *testing.T) {
	body := []byte(`{"a":1}`)
	for _, span := range []jsonsplice.Span{
		{Start: -1, End: 2},
		{Start: 0, End: len(body) + 1},
		{Start: 2, End: 2},
	} {
		if _, err := jsonsplice.ReplaceRaw(body, span, []byte("null")); err == nil {
			t.Fatalf("invalid span accepted: %+v", span)
		}
	}
	if _, err := jsonsplice.ReplaceRaw(body, jsonsplice.Span{Start: 5, End: 6}, []byte(`{`)); err == nil {
		t.Fatal("invalid JSON replacement accepted")
	}
}

func stringsTrimSpace(value string) string {
	return string(bytes.TrimSpace([]byte(value)))
}

package openai

import (
	"bytes"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"io"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/jsonsplice"
)

// OptimizerID is the policy flag and x-cave-optimization label for this optimizer.
const OptimizerID = "openai-prompt-cache-key"

// Adapter embeds the shared Base and overrides ApplyProviderNativeTransforms to
// inject a stable OpenAI prompt_cache_key on the request's cacheable prefix.
type Adapter struct {
	providers.Base
}

// ApplyProviderNativeTransforms injects a top-level prompt_cache_key derived from
// the request's stable prefix (model + tools + leading system/instructions).
//
// OpenAI prompt caching is automatic for prefixes >= 1024 tokens; prompt_cache_key
// is combined with the prefix hash to increase routing affinity — requests that
// share the same prefix and key are more likely to land on the engine that
// already cached that prefix, raising cache-hit rate. It is non-semantic routing
// metadata the model never sees, so it is byte-safe at S1. It is an affinity
// key, not an explicit cache breakpoint: GPT-5.6's implicit breakpoint can still
// write a changing suffix, and those writes carry a provider price premium.
// Whether the key is net-positive therefore depends on later provider-observed
// reuse; applying it alone proves no savings.
//
// Conservative and idempotent, mirroring the Anthropic optimizer: runs only when
// policy enables it (the proxy already blocks transforms in record mode), never
// touches a request that already carries a prompt_cache_key, injects only when a
// stable prefix exists (tools or a system/instructions present), and passes the
// body through unchanged on any parse problem.
func (a Adapter) ApplyProviderNativeTransforms(ctx context.Context, body providers.BodyReader, meta providers.RequestMetadata, policy providers.TransformPolicy) (providers.TransformResult, error) {
	data, err := io.ReadAll(body)
	if err != nil {
		return providers.TransformResult{Body: data, OptimizerIDs: []string{}}, nil
	}
	passthrough := providers.TransformResult{Body: data, OptimizerIDs: []string{}}
	// Record mode is an unconditional wire-preservation boundary. The gateway
	// normally skips this adapter in record mode, but keep the adapter safe when
	// called directly (or by a future caller) as well.
	if policy.RuntimeMode == "record" {
		return passthrough, nil
	}

	cacheKeyOn := policy.OptimizerEnabled(OptimizerID)
	// Behavioral: output-brevity needs its flag AND a cleared eval gate.
	brevityOn := policy.OptimizerActive(BrevityOptimizerID)
	// Behavioral: reasoning-effort lowers the thinking budget, which can change
	// the answer, so it too needs its flag AND a cleared eval gate.
	reasoningOn := policy.OptimizerActive(ReasoningEffortOptimizerID)
	// Request envelope only, never touches model-visible content — but it DOES
	// add a client-visible SSE chunk to the response the caller receives (see
	// stream_usage.go), which is an observable effect outside what byte-safe
	// promises either way. Needs its flag AND a cleared eval gate, same as the
	// other optimizers in this list with any observable effect.
	streamUsageOn := policy.OptimizerActive(StreamUsageOptimizerID)
	if !cacheKeyOn && !brevityOn && !reasoningOn && !streamUsageOn {
		return passthrough, nil
	}

	var root map[string]any
	if json.Unmarshal(data, &root) != nil {
		return passthrough, nil
	}

	var ids []string
	if cacheKeyOn && applyPromptCacheKey(root) {
		ids = append(ids, OptimizerID)
	}
	if brevityOn && applyOutputBrevity(root) {
		ids = append(ids, BrevityOptimizerID)
	}
	if reasoningOn && applyReasoningEffort(root, meta.Endpoint) {
		ids = append(ids, ReasoningEffortOptimizerID)
	}
	if streamUsageOn && applyStreamIncludeUsage(root) {
		ids = append(ids, StreamUsageOptimizerID)
	}
	if len(ids) == 0 {
		return passthrough, nil
	}

	// Preferred path: splice the new top-level fields into the caller's ORIGINAL
	// bytes and leave every other byte alone, so the cache prefix stays stable.
	if out, ok := spliceTopLevelFields(data, root, ids, meta.Endpoint); ok {
		return providers.TransformResult{Body: out, OptimizerIDs: ids}, nil
	}
	// Fallback: re-marshal the mutated document. Reached when an applied
	// optimizer changed something a top-level splice cannot express — today only
	// stream_options.include_usage, which is nested. Byte-preservation is lost
	// for that request; the mutation is not.
	out, err := json.Marshal(root)
	if err != nil {
		return passthrough, nil
	}
	return providers.TransformResult{Body: out, OptimizerIDs: ids}, nil
}

// spliceTopLevelFields appends the fields named by ids to data, preserving every
// other byte of the original document.
//
// ok is false when the splice cannot represent what the applyX helpers did, and
// the caller must re-marshal instead. That is NOT a pass-through signal: an id
// this switch does not recognize must never abandon the whole transform, because
// doing so would silently drop prompt_cache_key whenever an unrelated optimizer
// happened to fire in the same request. This OpenAI affinity optimizer has no
// verified-savings method; its cache reads and writes are measured spend only.
func spliceTopLevelFields(data []byte, root map[string]any, ids []string, endpoint string) ([]byte, bool) {
	object, ok := jsonsplice.Root(data)
	if !ok {
		return nil, false
	}
	insertions := make([]jsonsplice.FieldInsertion, 0, len(ids))
	for _, id := range ids {
		var name string
		switch id {
		case OptimizerID:
			name = "prompt_cache_key"
		case BrevityOptimizerID:
			if _, responses := root["max_output_tokens"]; responses {
				name = "max_output_tokens"
			} else {
				name = "max_completion_tokens"
			}
		case ReasoningEffortOptimizerID:
			// Chat Completions carries this as a top-level field. Responses
			// carries it under reasoning.effort, which requires the fallback
			// re-marshal path below.
			if reasoningEndpointKind(endpoint) != reasoningEndpointChat {
				return nil, false
			}
			name = "reasoning_effort"
		case StreamUsageOptimizerID:
			// applyStreamIncludeUsage mutates stream_options.include_usage, a
			// NESTED field. There is no top-level insertion that describes it.
			return nil, false
		default:
			// Unknown id: fall back to the re-marshal, which is correct for any
			// mutation an applyX helper made to root.
			return nil, false
		}
		value, err := json.Marshal(root[name])
		if err != nil {
			return nil, false
		}
		insertions = append(insertions, jsonsplice.FieldInsertion{Name: name, Value: value})
	}
	out, err := jsonsplice.AppendObjectFields(data, object, insertions...)
	if err != nil {
		return nil, false
	}
	return out, true
}

// applyPromptCacheKey injects a stable prompt_cache_key on the request's
// cacheable prefix. Returns true if it changed root. Idempotent: skips a request
// that already carries a prompt_cache_key.
func applyPromptCacheKey(root map[string]any) bool {
	if _, exists := root["prompt_cache_key"]; exists {
		return false
	}
	sig, ok := prefixSignature(root)
	if !ok {
		return false
	}
	sum := sha256.Sum256(sig)
	root["prompt_cache_key"] = hex.EncodeToString(sum[:])[:32]
	return true
}

// prefixSignature builds a canonical, stable byte signature of the request's
// cacheable prefix. It re-marshals the extracted sub-values through encoding/json
// so two requests whose prefixes are logically identical but differ only in
// whitespace or key order produce the SAME signature (and thus the same key),
// while distinct prefix shapes produce distinct keys. Returns false when there is
// no stable prefix to key on (plain messages with no tools/system).
func prefixSignature(root map[string]any) ([]byte, bool) {
	var parts [][]byte
	stable := false

	if model, ok := root["model"].(string); ok && model != "" {
		parts = append(parts, []byte("model="+model))
	}

	// Tools sit before messages and are the most stable, largest reusable prefix.
	if tools, ok := root["tools"].([]any); ok && len(tools) > 0 {
		if b, err := json.Marshal(tools); err == nil {
			parts = append(parts, b)
			stable = true
		}
	}

	// Responses API: a top-level instructions string is the system equivalent.
	if instr, ok := root["instructions"].(string); ok && instr != "" {
		parts = append(parts, []byte(instr))
		stable = true
	}

	// Chat Completions: only the FIRST message can be the stable system prefix.
	if msgs, ok := root["messages"].([]any); ok && len(msgs) > 0 {
		if first, ok := msgs[0].(map[string]any); ok {
			if role, _ := first["role"].(string); role == "system" || role == "developer" {
				if b, err := json.Marshal(first["content"]); err == nil {
					parts = append(parts, b)
					stable = true
				}
			}
		}
	}

	if !stable {
		return nil, false
	}
	return bytes.Join(parts, []byte{0}), true
}

package openai

import (
	"context"
	"encoding/json"
	"reflect"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func enabled() providers.TransformPolicy {
	return providers.TransformPolicy{RuntimeMode: "active", Optimizers: map[string]bool{OptimizerID: true}}
}

func apply(t *testing.T, body string, policy providers.TransformPolicy) providers.TransformResult {
	return applyAtEndpoint(t, body, "", policy)
}

func applyAtEndpoint(t *testing.T, body, endpoint string, policy providers.TransformPolicy) providers.TransformResult {
	t.Helper()
	a := New("http://upstream").(Adapter)
	res, err := a.ApplyProviderNativeTransforms(context.Background(), strings.NewReader(body), providers.RequestMetadata{Provider: "openai", Endpoint: endpoint}, policy)
	if err != nil {
		t.Fatalf("transform error: %v", err)
	}
	return res
}

func decode(t *testing.T, b []byte) map[string]any {
	t.Helper()
	var m map[string]any
	if err := json.Unmarshal(b, &m); err != nil {
		t.Fatalf("result not valid JSON: %v", err)
	}
	return m
}

func TestPromptCacheKey_ToolsGetKey(t *testing.T) {
	body := `{"model":"gpt-5.5","tools":[{"type":"function","function":{"name":"a"}}],"messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, enabled())

	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != OptimizerID {
		t.Fatalf("optimizer ids = %v, want [%s]", res.OptimizerIDs, OptimizerID)
	}
	root := decode(t, res.Body)
	key, ok := root["prompt_cache_key"].(string)
	if !ok || len(key) != 32 {
		t.Fatalf("expected a 32-char prompt_cache_key, got %v", root["prompt_cache_key"])
	}
	// Byte-safe: only prompt_cache_key is added; every original field is preserved.
	assertOnlyKeyAdded(t, body, root)
}

func TestPromptCacheKey_SystemMessageGetsKey(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"system","content":"You are careful."},{"role":"user","content":"hi"}]}`
	res := apply(t, body, enabled())
	if len(res.OptimizerIDs) != 1 {
		t.Fatalf("expected optimizer applied for a system-prefixed request, got %v", res.OptimizerIDs)
	}
	assertOnlyKeyAdded(t, body, decode(t, res.Body))
}

func TestPromptCacheKey_InstructionsGetKey(t *testing.T) {
	// Responses API shape: top-level instructions is the system equivalent.
	body := `{"model":"gpt-5.5","instructions":"Answer tersely.","input":"hi"}`
	res := apply(t, body, enabled())
	if len(res.OptimizerIDs) != 1 {
		t.Fatalf("expected optimizer applied for instructions, got %v", res.OptimizerIDs)
	}
}

func TestPromptCacheKey_StableAcrossWhitespaceAndKeyOrder(t *testing.T) {
	// Same logical prefix, different byte form -> identical key (canonical hash).
	a := apply(t, `{"model":"gpt-5.5","tools":[{"type":"function","function":{"name":"a"}}],"messages":[{"role":"user","content":"x"}]}`, enabled())
	b := apply(t, `{"messages":[{"content":"y","role":"user"}],"tools":[{"function":{"name":"a"},"type":"function"}],"model":"gpt-5.5"}`, enabled())
	ka := decode(t, a.Body)["prompt_cache_key"]
	kb := decode(t, b.Body)["prompt_cache_key"]
	if ka != kb {
		t.Errorf("same logical prefix must produce the same key: %v vs %v", ka, kb)
	}
}

func TestPromptCacheKey_DistinctPrefixesDistinctKeys(t *testing.T) {
	a := apply(t, `{"model":"gpt-5.5","tools":[{"function":{"name":"a"}}],"messages":[]}`, enabled())
	b := apply(t, `{"model":"gpt-5.5","tools":[{"function":{"name":"b"}}],"messages":[]}`, enabled())
	if decode(t, a.Body)["prompt_cache_key"] == decode(t, b.Body)["prompt_cache_key"] {
		t.Error("different tool prefixes must produce different keys")
	}
}

func TestPromptCacheKey_DisabledIsPassthrough(t *testing.T) {
	body := `{"model":"gpt-5.5","tools":[{"function":{"name":"a"}}],"messages":[]}`
	res := apply(t, body, providers.TransformPolicy{RuntimeMode: "active", Optimizers: map[string]bool{}})
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("disabled optimizer must pass body through unchanged, got ids=%v", res.OptimizerIDs)
	}
}

func TestPromptCacheKey_RespectsExistingKey(t *testing.T) {
	body := `{"model":"gpt-5.5","prompt_cache_key":"caller-set","tools":[{"function":{"name":"a"}}],"messages":[]}`
	res := apply(t, body, enabled())
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("existing prompt_cache_key must be respected (passthrough), got ids=%v", res.OptimizerIDs)
	}
}

func TestPromptCacheKey_NoStablePrefixOrBadJSON(t *testing.T) {
	// Plain messages, no tools/system -> nothing stable to key on.
	res := apply(t, `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}]}`, enabled())
	if len(res.OptimizerIDs) != 0 {
		t.Errorf("no stable prefix should be passthrough, got %v", res.OptimizerIDs)
	}
	// Invalid JSON -> passthrough, no error.
	bad := apply(t, `not json`, enabled())
	if len(bad.OptimizerIDs) != 0 || string(bad.Body) != "not json" {
		t.Errorf("invalid JSON must pass through unchanged")
	}
}

func TestPromptCacheKey_Idempotent(t *testing.T) {
	once := apply(t, `{"model":"gpt-5.5","tools":[{"function":{"name":"a"}}],"messages":[]}`, enabled())
	twice := apply(t, string(once.Body), enabled())
	if len(twice.OptimizerIDs) != 0 {
		t.Errorf("re-applying should be idempotent (key already present), got %v", twice.OptimizerIDs)
	}
}

func TestPromptCacheKey_PreservesOriginalRawBytes(t *testing.T) {
	body := "{\n \"model\" : \"gpt-5.5\", \"tools\" : [{\"function\":{\"name\":\"a\",\"description\":\"<>&\"}}], \"messages\" : []\n}"
	res := apply(t, body, enabled())
	key := decode(t, res.Body)["prompt_cache_key"].(string)
	want := strings.Replace(body, "\n}", `,"prompt_cache_key":"`+key+"\"\n}", 1)
	if string(res.Body) != want {
		t.Fatalf("cache-key insertion reserialized untouched bytes:\n got %s\nwant %s", res.Body, want)
	}
}

// assertOnlyKeyAdded verifies the transform is semantically additive: the
// decoded result equals the decoded original plus exactly the prompt_cache_key.
func assertOnlyKeyAdded(t *testing.T, original string, result map[string]any) {
	t.Helper()
	var orig map[string]any
	if err := json.Unmarshal([]byte(original), &orig); err != nil {
		t.Fatalf("original not valid JSON: %v", err)
	}
	if _, ok := result["prompt_cache_key"]; !ok {
		t.Fatal("result missing prompt_cache_key")
	}
	stripped := map[string]any{}
	for k, v := range result {
		if k == "prompt_cache_key" {
			continue
		}
		stripped[k] = v
	}
	if !reflect.DeepEqual(orig, stripped) {
		t.Errorf("transform changed model-visible content.\n original: %v\n result-minus-key: %v", orig, stripped)
	}
}

package openai

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

const minCompressBlockBytes = 512

type jsonSpan struct {
	start int
	end   int
}

type spliceCandidate struct {
	jsonSpan
	original []byte
}

// zoneCandidate is one splice candidate plus the provider-cache zone it sits in.
// Live candidates belong to the just-arrived turn and may be newly compressed;
// frozen candidates are the same block types in EARLIER messages, exposed only so a
// replacement this proxy already emitted for those exact bytes can be substituted
// back byte-identically.
type zoneCandidate struct {
	spliceCandidate
	live bool
	kind string
}

// ExtractCompressible returns only OpenAI's live zone: the latest tool message
// plus the latest user message. It never collects system/developer/assistant
// content, and reassembly byte-splices changed string values into the original
// request bytes.
func (a Adapter) ExtractCompressible(body []byte, meta providers.RequestMetadata) ([][]byte, func([][]byte) ([]byte, error), bool) {
	return ExtractCompressible(body, meta)
}

// ExtractCompressible is exported so Azure OpenAI and OpenAI-compatible
// adapters can reuse the identical wire grammar without changing provider
// identity, routing, or header dispatch.
func ExtractCompressible(body []byte, meta providers.RequestMetadata) ([][]byte, func([][]byte) ([]byte, error), bool) {
	zones, ok := rewritableZones(body, meta, true)
	if !ok {
		return nil, nil, false
	}
	candidates := make([]spliceCandidate, 0, len(zones))
	for _, zone := range zones {
		if zone.live {
			candidates = append(candidates, zone.spliceCandidate)
		}
	}
	if len(candidates) == 0 {
		return nil, nil, false
	}
	segments := make([][]byte, len(candidates))
	for i, c := range candidates {
		segments[i] = append([]byte(nil), c.original...)
	}
	reassemble := func(reps [][]byte) ([]byte, error) {
		return spliceStringReplacements(body, candidates, reps)
	}
	return segments, reassemble, true
}

// ExtractStabilizable returns every content block the proxy may rewrite, each
// tagged with the cache zone it sits in: the live zone (Live, eligible for new
// compression) plus the same block types in earlier messages (frozen — eligible
// ONLY for byte-identical substitution of a replacement the proxy already emitted
// for those exact bytes).
//
// Frozen blocks have to be exposed because compression is not a one-turn event: a
// message compressed while it WAS the live zone arrives again on the next turn as
// the client's original bytes. OpenAI caches long prompt prefixes automatically, so
// forwarding those originals silently misses the cache entry the previous turn paid
// to create — the caller substitutes the stored replacement instead and the prefix
// stays byte-stable for the whole conversation. Assistant/system/developer blocks
// are never collected: the proxy never compresses them, so a substitution could
// never exist for them.
//
// Exported for the same reason ExtractCompressible is: Azure OpenAI and
// OpenAI-compatible adapters reuse the identical wire grammar.
func (a Adapter) ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool) {
	return ExtractStabilizable(body, meta)
}

func ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool) {
	zones, ok := rewritableZones(body, meta, false)
	if !ok || len(zones) == 0 {
		return nil, nil, false
	}
	candidates := make([]spliceCandidate, len(zones))
	blocks := make([]providers.RewritableBlock, len(zones))
	for i, zone := range zones {
		candidates[i] = zone.spliceCandidate
		blocks[i] = providers.RewritableBlock{
			Content: append([]byte(nil), zone.original...),
			Live:    zone.live,
			Kind:    zone.kind,
		}
	}
	reassemble := func(reps [][]byte) ([]byte, error) {
		return spliceStringReplacements(body, candidates, reps)
	}
	return blocks, reassemble, true
}

// rewritableZones is the single definition of OpenAI's rewrite zones, shared by
// ExtractCompressible (live only) and ExtractStabilizable (live + frozen), so the
// two can never disagree about which message is the live one. Candidates come back
// in document order — messages, then items, then content parts are all walked in
// order — which is the ascending, non-overlapping ordering the splicer requires.
//
// liveOnly is a pure cost switch for ExtractCompressible, which throws every frozen
// candidate away: it skips COLLECTING them, so a long conversation never pays to
// decode history the caller has already decided to discard. The live-zone RULE is
// unchanged — which message is live is still decided by the same full scan of roles
// — so the live candidates, their order, and the ok result are byte-for-byte what
// the full walk produces. Collecting a frozen candidate can never change ok
// (per-message parse problems are skipped, not failed), which is what makes the
// skip safe.
func rewritableZones(body []byte, meta providers.RequestMetadata, liveOnly bool) ([]zoneCandidate, bool) {
	root, ok := rootObjectSpan(body)
	if !ok {
		return nil, false
	}
	if strings.Contains(meta.Endpoint, "embeddings") {
		return nil, false
	}
	if strings.Contains(meta.Endpoint, "responses") {
		return responsesZones(body, root, liveOnly)
	}
	return chatZones(body, root, liveOnly)
}

func chatZones(body []byte, root jsonSpan, liveOnly bool) ([]zoneCandidate, bool) {
	messagesSpan, ok := findObjectField(body, root, "messages")
	if !ok || messagesSpan.start >= len(body) || body[messagesSpan.start] != '[' {
		return nil, false
	}
	messageSpans, ok := arrayElements(body, messagesSpan)
	if !ok || len(messageSpans) == 0 {
		return nil, false
	}
	live := latestOpenAITargets(body, messageSpans)
	recovered := chatRecoveryCallIDs(body, messageSpans)
	var out []zoneCandidate
	for i, msg := range messageSpans {
		if liveOnly && !live[i] {
			continue
		}
		role := messageRole(body, msg)
		if role != "user" && role != "tool" {
			continue
		}
		// Recovered bytes are never a compression candidate — see
		// providers.IsRecoveryToolName.
		if role == "tool" {
			if id, ok := objectStringField(body, msg, "tool_call_id"); ok && recovered[id] {
				continue
			}
		}
		for _, c := range collectOpenAICandidates(body, msg, role == "tool") {
			kind := "history"
			if role == "tool" {
				kind = "tool_result"
			}
			out = append(out, zoneCandidate{spliceCandidate: c, live: live[i], kind: kind})
		}
	}
	return out, true
}

func responsesZones(body []byte, root jsonSpan, liveOnly bool) ([]zoneCandidate, bool) {
	input, ok := findObjectField(body, root, "input")
	if !ok {
		return nil, false
	}
	if isJSONString(body, input) {
		// A bare string input carries no conversation history, so it is all live.
		var candidates []spliceCandidate
		collectStringCandidate(body, input, &candidates, false)
		return liveZones(candidates, "history"), true
	}
	if input.start >= input.end || body[input.start] != '[' {
		return nil, false
	}
	items, ok := arrayElements(body, input)
	if !ok {
		return nil, false
	}
	latestUser, latestTool := -1, -1
	recovered := make(map[string]bool)
	for i, item := range items {
		if item.start >= item.end || body[item.start] != '{' {
			continue
		}
		typ, _ := objectStringField(body, item, "type")
		role, _ := objectStringField(body, item, "role")
		switch {
		case typ == "function_call_output":
			latestTool = i
		case typ == "function_call":
			name, _ := objectStringField(body, item, "name")
			if providers.IsRecoveryToolName(name) {
				if id, ok := objectStringField(body, item, "call_id"); ok && id != "" {
					recovered[id] = true
				}
			}
		case role == "user":
			latestUser = i
		}
	}
	var out []zoneCandidate
	for i, item := range items {
		live := i == latestTool || i == latestUser
		if liveOnly && !live {
			continue
		}
		if item.start >= item.end || body[item.start] != '{' {
			continue
		}
		typ, _ := objectStringField(body, item, "type")
		role, _ := objectStringField(body, item, "role")
		var candidates []spliceCandidate
		switch {
		case typ == "function_call_output":
			// Recovered bytes are never a compression candidate — see
			// providers.IsRecoveryToolName.
			if id, ok := objectStringField(body, item, "call_id"); ok && recovered[id] {
				continue
			}
			output, found := findObjectField(body, item, "output")
			if !found || !isJSONString(body, output) {
				continue
			}
			collectStringCandidate(body, output, &candidates, true)
		case role == "user":
			candidates = collectResponsesContent(body, item)
		default:
			continue
		}
		for _, c := range candidates {
			kind := "history"
			if typ == "function_call_output" {
				kind = "tool_result"
			}
			out = append(out, zoneCandidate{spliceCandidate: c, live: live, kind: kind})
		}
	}
	return out, true
}

// chatRecoveryCallIDs collects the tool_call ids of every caveman recovery call
// in the chat grammar, so the tool message answering one can be left alone.
func chatRecoveryCallIDs(body []byte, messages []jsonSpan) map[string]bool {
	ids := make(map[string]bool)
	for _, msg := range messages {
		if messageRole(body, msg) != "assistant" {
			continue
		}
		calls, ok := findObjectField(body, msg, "tool_calls")
		if !ok || calls.start >= calls.end || body[calls.start] != '[' {
			continue
		}
		items, ok := arrayElements(body, calls)
		if !ok {
			continue
		}
		for _, call := range items {
			if call.start >= call.end || body[call.start] != '{' {
				continue
			}
			fn, ok := findObjectField(body, call, "function")
			if !ok || fn.start >= fn.end || body[fn.start] != '{' {
				continue
			}
			name, _ := objectStringField(body, fn, "name")
			if !providers.IsRecoveryToolName(name) {
				continue
			}
			if id, ok := objectStringField(body, call, "id"); ok && id != "" {
				ids[id] = true
			}
		}
	}
	return ids
}

func liveZones(candidates []spliceCandidate, kind string) []zoneCandidate {
	out := make([]zoneCandidate, len(candidates))
	for i, c := range candidates {
		out[i] = zoneCandidate{spliceCandidate: c, live: true, kind: kind}
	}
	return out
}

func collectResponsesContent(body []byte, item jsonSpan) []spliceCandidate {
	content, ok := findObjectField(body, item, "content")
	if !ok {
		return nil
	}
	var candidates []spliceCandidate
	if isJSONString(body, content) {
		collectStringCandidate(body, content, &candidates, false)
		return candidates
	}
	if content.start >= content.end || body[content.start] != '[' {
		return nil
	}
	parts, ok := arrayElements(body, content)
	if !ok {
		return nil
	}
	for _, part := range parts {
		typ, _ := objectStringField(body, part, "type")
		if typ != "input_text" && typ != "text" {
			continue
		}
		if text, found := findObjectField(body, part, "text"); found && isJSONString(body, text) {
			collectStringCandidate(body, text, &candidates, false)
		}
	}
	return candidates
}

// latestOpenAITargets is the live-zone rule for the chat grammar: the latest tool
// message and the latest user message. Everything before them is history the
// provider may already have cached automatically.
func latestOpenAITargets(body []byte, messages []jsonSpan) map[int]bool {
	latestUser := -1
	latestTool := -1
	for i, msg := range messages {
		switch messageRole(body, msg) {
		case "user":
			latestUser = i
		case "tool":
			latestTool = i
		}
	}
	targets := map[int]bool{}
	if latestTool >= 0 {
		targets[latestTool] = true
	}
	if latestUser >= 0 {
		targets[latestUser] = true
	}
	return targets
}

func collectOpenAICandidates(body []byte, msg jsonSpan, allowForcedTOON bool) []spliceCandidate {
	content, ok := findObjectField(body, msg, "content")
	if !ok {
		return nil
	}
	var out []spliceCandidate
	switch {
	case isJSONString(body, content):
		collectStringCandidate(body, content, &out, allowForcedTOON)
	case content.start < content.end && body[content.start] == '[':
		parts, ok := arrayElements(body, content)
		if !ok {
			return nil
		}
		for _, part := range parts {
			if part.start >= part.end || body[part.start] != '{' {
				continue
			}
			typ, ok := objectStringField(body, part, "type")
			if !ok {
				continue
			}
			switch typ {
			case "text", "input_text", "output_text":
				if textSpan, ok := findObjectField(body, part, "text"); ok && isJSONString(body, textSpan) {
					collectStringCandidate(body, textSpan, &out, allowForcedTOON)
				}
			}
		}
	}
	return out
}

func collectStringCandidate(body []byte, span jsonSpan, out *[]spliceCandidate, allowForcedTOON bool) {
	value, ok := decodeJSONString(body[span.start:span.end])
	if !ok {
		return
	}
	original := []byte(value)
	if len(original) < minCompressBlockBytes && !(allowForcedTOON && forcedTOONCandidate(original)) {
		return
	}
	*out = append(*out, spliceCandidate{jsonSpan: span, original: original})
}

func forcedTOONCandidate(original []byte) bool {
	if !strings.EqualFold(os.Getenv("CAVE_ENGINE_TOON"), "best-of") {
		return false
	}
	trimmed := bytes.TrimSpace(original)
	return len(trimmed) > 0 && (trimmed[0] == '{' || trimmed[0] == '[')
}

func messageRole(body []byte, msg jsonSpan) string {
	role, ok := objectStringField(body, msg, "role")
	if !ok {
		return ""
	}
	return role
}

func objectStringField(body []byte, obj jsonSpan, field string) (string, bool) {
	value, ok := findObjectField(body, obj, field)
	if !ok || !isJSONString(body, value) {
		return "", false
	}
	return decodeJSONString(body[value.start:value.end])
}

func rootObjectSpan(body []byte) (jsonSpan, bool) {
	start := skipJSONSpace(body, 0)
	if start >= len(body) || body[start] != '{' {
		return jsonSpan{}, false
	}
	end, ok := scanJSONValue(body, start)
	if !ok {
		return jsonSpan{}, false
	}
	if skipJSONSpace(body, end) != len(body) {
		return jsonSpan{}, false
	}
	return jsonSpan{start: start, end: end}, true
}

func findObjectField(body []byte, obj jsonSpan, field string) (jsonSpan, bool) {
	if obj.start < 0 || obj.end > len(body) || obj.start >= obj.end || body[obj.start] != '{' {
		return jsonSpan{}, false
	}
	i := skipJSONSpace(body, obj.start+1)
	for i < obj.end {
		if body[i] == '}' {
			return jsonSpan{}, false
		}
		if body[i] != '"' {
			return jsonSpan{}, false
		}
		keyStart := i
		keyEnd, ok := scanJSONString(body, keyStart)
		if !ok {
			return jsonSpan{}, false
		}
		key, ok := decodeJSONString(body[keyStart:keyEnd])
		if !ok {
			return jsonSpan{}, false
		}
		i = skipJSONSpace(body, keyEnd)
		if i >= obj.end || body[i] != ':' {
			return jsonSpan{}, false
		}
		valueStart := skipJSONSpace(body, i+1)
		valueEnd, ok := scanJSONValue(body, valueStart)
		if !ok {
			return jsonSpan{}, false
		}
		if key == field {
			return jsonSpan{start: valueStart, end: valueEnd}, true
		}
		i = skipJSONSpace(body, valueEnd)
		if i < obj.end && body[i] == ',' {
			i = skipJSONSpace(body, i+1)
			continue
		}
	}
	return jsonSpan{}, false
}

func arrayElements(body []byte, arr jsonSpan) ([]jsonSpan, bool) {
	if arr.start < 0 || arr.end > len(body) || arr.start >= arr.end || body[arr.start] != '[' {
		return nil, false
	}
	var out []jsonSpan
	i := skipJSONSpace(body, arr.start+1)
	for i < arr.end {
		if body[i] == ']' {
			return out, true
		}
		valueEnd, ok := scanJSONValue(body, i)
		if !ok {
			return nil, false
		}
		out = append(out, jsonSpan{start: i, end: valueEnd})
		i = skipJSONSpace(body, valueEnd)
		if i < arr.end && body[i] == ',' {
			i = skipJSONSpace(body, i+1)
			continue
		}
	}
	return nil, false
}

func scanJSONValue(body []byte, start int) (int, bool) {
	i := skipJSONSpace(body, start)
	if i >= len(body) {
		return 0, false
	}
	switch body[i] {
	case '"':
		return scanJSONString(body, i)
	case '{', '[':
		depth := 0
		for j := i; j < len(body); j++ {
			switch body[j] {
			case '"':
				end, ok := scanJSONString(body, j)
				if !ok {
					return 0, false
				}
				j = end - 1
			case '{', '[':
				depth++
			case '}', ']':
				depth--
				if depth == 0 {
					return j + 1, true
				}
				if depth < 0 {
					return 0, false
				}
			}
		}
		return 0, false
	default:
		j := i
		for j < len(body) {
			switch body[j] {
			case ',', '}', ']', ' ', '\n', '\r', '\t':
				if j == i {
					return 0, false
				}
				return j, true
			default:
				j++
			}
		}
		return j, j > i
	}
}

func scanJSONString(body []byte, start int) (int, bool) {
	if start >= len(body) || body[start] != '"' {
		return 0, false
	}
	for i := start + 1; i < len(body); i++ {
		switch body[i] {
		case '\\':
			i++
		case '"':
			return i + 1, true
		}
	}
	return 0, false
}

func skipJSONSpace(body []byte, i int) int {
	for i < len(body) {
		switch body[i] {
		case ' ', '\n', '\r', '\t':
			i++
		default:
			return i
		}
	}
	return i
}

func decodeJSONString(raw []byte) (string, bool) {
	var s string
	if json.Unmarshal(raw, &s) != nil {
		return "", false
	}
	return s, true
}

func isJSONString(body []byte, span jsonSpan) bool {
	return span.start < span.end && span.start >= 0 && span.end <= len(body) && body[span.start] == '"'
}

func quoteJSONStringNoHTML(s string) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	if err := enc.Encode(s); err != nil {
		return nil, err
	}
	return bytes.TrimSuffix(buf.Bytes(), []byte("\n")), nil
}

func spliceStringReplacements(body []byte, candidates []spliceCandidate, reps [][]byte) ([]byte, error) {
	if len(reps) != len(candidates) {
		return nil, fmt.Errorf("openai compress: %d replacements for %d segments", len(reps), len(candidates))
	}
	var out []byte
	last := 0
	changed := false
	for i, c := range candidates {
		if c.start < last || c.end > len(body) || c.start >= c.end {
			return nil, fmt.Errorf("openai compress: invalid splice range")
		}
		rep := reps[i]
		if rep == nil || bytes.Equal(rep, c.original) {
			continue
		}
		quoted, err := quoteJSONStringNoHTML(string(rep))
		if err != nil {
			return nil, err
		}
		if !changed {
			out = make([]byte, 0, len(body)-len(c.original)+len(rep))
		}
		out = append(out, body[last:c.start]...)
		out = append(out, quoted...)
		last = c.end
		changed = true
	}
	if !changed {
		return body, nil
	}
	out = append(out, body[last:]...)
	return out, nil
}

