	}
	if !bytes.HasPrefix(out, []byte(` { "model":"gpt-5.5", "input":`)) || !bytes.HasSuffix(out, []byte(`, "temperature":0 } `)) || !json.Valid(bytes.TrimSpace(out)) {
		t.Fatalf("splice changed envelope: %s", out)
