import (
	"context"
	"net/http"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func New(baseURL string) providers.Adapter {
	return Adapter{Base: providers.Base{Provider: "openai", BaseURL: baseURL, Routes: []string{"/v1/chat/completions", "/v1/responses", "/v1/embeddings", "/openai/v1/chat/completions", "/openai/v1/responses", "/openai/v1/embeddings"}}}
}

func (a Adapter) InspectRequest(ctx context.Context, body providers.BodyReader, headers http.Header) (providers.RequestMetadata, error) {
	meta, err := a.Base.InspectRequest(ctx, body, headers)
	if path := headers.Get("x-cave-route-path"); path != "" {
		meta.Endpoint = path
	}
	return meta, err
}

package openai

// BrevityOptimizerID is the policy flag / x-cave-optimization label for the
// output-brevity optimizer.
const BrevityOptimizerID = "output-brevity"

// brevityMaxOutputTokens is the provider-native output cap this optimizer applies
// when the caller has not set one. It bounds runaway generations without
// truncating typical answers; because it CAN change output it is opt-in and
// eval-gated (see ApplyProviderNativeTransforms / docs/optimizations.md).
const brevityMaxOutputTokens = 512

// applyOutputBrevity adds a provider-native output cap when the caller hasn't
// set one. Responses API uses max_output_tokens; Chat Completions uses
// max_completion_tokens. Returns true if it changed root. It respects any cap the
// caller already set (never raises or lowers it).
//
// Unlike the cache optimizers this is NOT byte-safe — it can shorten model
// output — which is exactly why it runs only behind both a policy flag and a
// cleared eval gate.
func applyOutputBrevity(root map[string]any) bool {
	// Responses API: top-level input or instructions present.
	_, hasInput := root["input"]
	_, hasInstr := root["instructions"]
	if hasInput || hasInstr {
		if _, set := root["max_output_tokens"]; set {
			return false
		}
		root["max_output_tokens"] = brevityMaxOutputTokens
		return true
	}
	// Chat Completions: messages present.
	if _, hasMsgs := root["messages"]; hasMsgs {
		if _, set := root["max_completion_tokens"]; set {
			return false
		}
		if _, set := root["max_tokens"]; set {
			return false
		}
		root["max_completion_tokens"] = brevityMaxOutputTokens
		return true
	}
	return false
}

package openai

import (
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func brevityPolicy(flag, gate bool) providers.TransformPolicy {
	return providers.TransformPolicy{
		RuntimeMode: "active",
		Optimizers:  map[string]bool{BrevityOptimizerID: flag},
		EvalGates:   map[string]bool{BrevityOptimizerID: gate},
	}
}

func TestBrevity_RequiresBothFlagAndEvalGate(t *testing.T) {
	body := `{"model":"gpt-5.5","input":"hi"}`

	// Flag on, eval gate NOT cleared -> must not apply (the whole point of W8).
	r := apply(t, body, brevityPolicy(true, false))
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("brevity must not run without a cleared eval gate, got %v", r.OptimizerIDs)
	}

	// Eval gate cleared, flag off -> must not apply.
	r = apply(t, body, brevityPolicy(false, true))
	if len(r.OptimizerIDs) != 0 {
		t.Fatalf("brevity must not run without the policy flag, got %v", r.OptimizerIDs)
	}

	// Both -> applies and adds the provider-native cap.
	r = apply(t, body, brevityPolicy(true, true))
	if len(r.OptimizerIDs) != 1 || r.OptimizerIDs[0] != BrevityOptimizerID {
		t.Fatalf("both flag + eval gate must apply brevity, got %v", r.OptimizerIDs)
	}
	if got := decode(t, r.Body)["max_output_tokens"]; got != float64(brevityMaxOutputTokens) {
		t.Fatalf("max_output_tokens = %v, want %d", got, brevityMaxOutputTokens)
	}
}

func TestBrevity_RecordModePassThrough(t *testing.T) {
	body := `{"model":"gpt-5.5","input":"hi"}`
	r := apply(t, body, providers.TransformPolicy{RuntimeMode: "record", Optimizers: map[string]bool{}, EvalGates: map[string]bool{}})
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("record/no-optimizer must pass through unchanged")
	}
}

func TestBrevity_RespectsCallerCap(t *testing.T) {
	body := `{"model":"gpt-5.5","input":"hi","max_output_tokens":99}`
	r := apply(t, body, brevityPolicy(true, true))
	if len(r.OptimizerIDs) != 0 {
		t.Fatalf("brevity must respect a caller-set cap, got %v", r.OptimizerIDs)
	}
}

func TestBrevity_ChatCompletionsUsesMaxCompletionTokens(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}]}`
	r := apply(t, body, brevityPolicy(true, true))
	if got := decode(t, r.Body)["max_completion_tokens"]; got != float64(brevityMaxOutputTokens) {
		t.Fatalf("max_completion_tokens = %v, want %d", got, brevityMaxOutputTokens)
	}
}

// Both optimizers can run together (pipeline): cache key + brevity.
func TestBrevity_ComposesWithCacheKey(t *testing.T) {
	body := `{"model":"gpt-5.5","instructions":"You are terse.","input":"hi"}`
	policy := providers.TransformPolicy{
		RuntimeMode: "active",
		Optimizers:  map[string]bool{OptimizerID: true, BrevityOptimizerID: true},
		EvalGates:   map[string]bool{BrevityOptimizerID: true},
	}
	r := apply(t, body, policy)
	if len(r.OptimizerIDs) != 2 {
		t.Fatalf("expected both optimizers applied, got %v", r.OptimizerIDs)
	}
	root := decode(t, r.Body)
	if root["prompt_cache_key"] == nil || root["max_output_tokens"] == nil {
		t.Fatalf("expected both prompt_cache_key and max_output_tokens, got %v", root)
	}
}

package openai

import (
	"bytes"
	"encoding/json"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// Zone tagging for the cross-turn prefix fix. OpenAI caches long prompt prefixes
// automatically, so a message this proxy compressed while it was the live zone must
// keep going upstream as those SAME bytes once it drops into the history — which
// means the adapter has to expose the history blocks too, marked frozen so they can
// only ever be substituted, never newly compressed.

func openaiAdapter() Adapter { return New("https://api.openai.com").(Adapter) }

func chatMeta() providers.RequestMetadata {
	return providers.RequestMetadata{Provider: "openai", Endpoint: "/v1/chat/completions"}
}

// TestExtractStabilizable_ChatTagsFrozenAndLiveBlocks pins the chat grammar's zones:
// the latest tool and latest user message are Live, every EARLIER user/tool message
// is frozen (substitute-only), and system/assistant messages are never exposed at
// all because the proxy never compresses them.
func TestExtractStabilizable_ChatTagsFrozenAndLiveBlocks(t *testing.T) {
	oldUser := strings.Repeat("OLD_USER ", 80)
	oldTool := strings.Repeat("OLD_TOOL ", 80)
	system := strings.Repeat("SYSTEM ", 80)
	assistant := strings.Repeat("ASSISTANT ", 80)
	liveTool := strings.Repeat("LIVE_TOOL ", 80)
	liveUser := strings.Repeat("LIVE_USER ", 80)
	body := []byte(`{"model":"gpt-5.5","messages":[` +
		`{"role":"system","content":"` + system + `"},` +
		`{"role":"user","content":"` + oldUser + `"},` +
		`{"role":"tool","tool_call_id":"old","content":"` + oldTool + `"},` +
		`{"role":"assistant","content":"` + assistant + `"},` +
		`{"role":"tool","tool_call_id":"new","content":"` + liveTool + `"},` +
		`{"role":"user","content":[{"type":"text","text":"` + liveUser + `"}]}` +
		`]}`)

	blocks, reassemble, ok := openaiAdapter().ExtractStabilizable(body, chatMeta())
	if !ok {
		t.Fatal("ExtractStabilizable ok=false")
	}
	want := []struct {
		text string
		live bool
		kind string
	}{
		{oldUser, false, "history"},
		{oldTool, false, "tool_result"},
		{liveTool, true, "tool_result"},
		{liveUser, true, "history"},
	}
	if len(blocks) != len(want) {
		t.Fatalf("blocks = %d, want %d", len(blocks), len(want))
	}
	for i, w := range want {
		if string(blocks[i].Content) != w.text || blocks[i].Live != w.live || blocks[i].Kind != w.kind {
			t.Fatalf("block %d = live:%v %q..., want live:%v %q...", i, blocks[i].Live, string(blocks[i].Content)[:10], w.live, w.text[:10])
		}
	}

	// The reassembler still byte-splices: substituting one frozen block and leaving
	// the rest nil must change only that block's bytes.
	out, err := reassemble([][]byte{[]byte("SUBSTITUTED"), nil, nil, nil})
	if err != nil {
		t.Fatalf("reassemble: %v", err)
	}
	if !bytes.Contains(out, []byte(`"content":"SUBSTITUTED"`)) {
		t.Fatalf("frozen block was not substituted: %s", out)
	}
	for _, untouched := range []string{system, oldTool, assistant, liveTool, liveUser} {
		if !bytes.Contains(out, []byte(untouched)) {
			t.Fatalf("untouched block changed: %s", out)
		}
	}
	if !json.Valid(out) {
		t.Fatalf("splice produced invalid JSON: %s", out)
	}
}

// TestExtractStabilizable_ResponsesTagsFrozenAndLiveBlocks runs the same rule over
// the Responses grammar: the latest function_call_output and the latest user item
// are Live, earlier ones frozen, assistant items never exposed.
func TestExtractStabilizable_ResponsesTagsFrozenAndLiveBlocks(t *testing.T) {
	oldUser := strings.Repeat("OLD_USER ", 80)
	oldOutput := strings.Repeat("OLD_OUTPUT ", 80)
	assistant := strings.Repeat("ASSISTANT ", 80)
	liveOutput := strings.Repeat("LIVE_OUTPUT ", 80)
	liveUser := strings.Repeat("LIVE_USER ", 80)
	body := []byte(`{"model":"gpt-5.5","input":[` +
		`{"type":"message","role":"user","content":[{"type":"input_text","text":"` + oldUser + `"}]},` +
		`{"type":"function_call_output","call_id":"c1","output":"` + oldOutput + `"},` +
		`{"type":"message","role":"assistant","content":[{"type":"output_text","text":"` + assistant + `"}]},` +
		`{"type":"function_call_output","call_id":"c2","output":"` + liveOutput + `"},` +
		`{"type":"message","role":"user","content":[{"type":"input_text","text":"` + liveUser + `"}]}` +
		`]}`)

	blocks, _, ok := openaiAdapter().ExtractStabilizable(body, providers.RequestMetadata{Provider: "openai", Endpoint: "/v1/responses"})
	if !ok {
		t.Fatal("ExtractStabilizable ok=false")
	}
	want := []struct {
		text string
		live bool
		kind string
	}{
		{oldUser, false, "history"},
		{oldOutput, false, "tool_result"},
		{liveOutput, true, "tool_result"},
		{liveUser, true, "history"},
	}
	if len(blocks) != len(want) {
		t.Fatalf("blocks = %d, want %d", len(blocks), len(want))
	}
	for i, w := range want {
		if string(blocks[i].Content) != w.text || blocks[i].Live != w.live || blocks[i].Kind != w.kind {
			t.Fatalf("block %d = live:%v %q..., want live:%v %q...", i, blocks[i].Live, string(blocks[i].Content)[:10], w.live, w.text[:10])
		}
	}
}

// TestExtractStabilizable_MatchesExtractCompressibleLiveZone is the no-drift pin:
// both extractors read the same zone definition, so the Live blocks of one must be
// exactly the segments of the other, in the same order.
func TestExtractStabilizable_MatchesExtractCompressibleLiveZone(t *testing.T) {
	for name, tc := range map[string]struct {
		body     string
		endpoint string
	}{
		"chat": {
			body: `{"model":"gpt-5.5","messages":[` +
				`{"role":"user","content":"` + strings.Repeat("A ", 400) + `"},` +
				`{"role":"assistant","content":"` + strings.Repeat("B ", 400) + `"},` +
				`{"role":"tool","tool_call_id":"t","content":"` + strings.Repeat("C ", 400) + `"},` +
				`{"role":"user","content":"` + strings.Repeat("D ", 400) + `"}]}`,
			endpoint: "/v1/chat/completions",
		},
		"responses": {
			body: `{"model":"gpt-5.5","input":[` +
				`{"type":"message","role":"user","content":[{"type":"input_text","text":"` + strings.Repeat("A ", 400) + `"}]},` +
				`{"type":"function_call_output","call_id":"c1","output":"` + strings.Repeat("B ", 400) + `"},` +
				`{"type":"message","role":"user","content":[{"type":"input_text","text":"` + strings.Repeat("C ", 400) + `"}]}]}`,
			endpoint: "/v1/responses",
		},
		"responses string input": {
			body:     `{"model":"gpt-5.5","input":"` + strings.Repeat("A ", 400) + `"}`,
			endpoint: "/v1/responses",
		},
	} {
		t.Run(name, func(t *testing.T) {
			meta := providers.RequestMetadata{Provider: "openai", Endpoint: tc.endpoint}
			segments, _, segOK := openaiAdapter().ExtractCompressible([]byte(tc.body), meta)
			blocks, _, blockOK := openaiAdapter().ExtractStabilizable([]byte(tc.body), meta)
			if !segOK || !blockOK {
				t.Fatalf("ok = %v/%v, want both true", segOK, blockOK)
			}
			var live [][]byte
			for _, b := range blocks {
				if b.Live {
					live = append(live, b.Content)
				}
			}
			if len(live) != len(segments) {
				t.Fatalf("live blocks = %d, compressible segments = %d", len(live), len(segments))
			}
			for i := range segments {
				if !bytes.Equal(live[i], segments[i]) {
					t.Fatalf("live block %d diverged from the compressible segment", i)
				}
			}
		})
	}
}

// TestExtractStabilizable_OptsOutWhereCompressionDoes keeps the carve-outs aligned:
// an endpoint whose bytes must be preserved exposes no blocks at all, so no
// substitution can reach it either.
func TestExtractStabilizable_OptsOutWhereCompressionDoes(t *testing.T) {
	large := strings.Repeat("X ", 400)
	cases := map[string]struct {
		body     string
		endpoint string
	}{
		"embeddings":      {`{"model":"text-embedding-3-large","input":"` + large + `"}`, "/v1/embeddings"},
		"malformed":       {`not json`, "/v1/chat/completions"},
		"no messages":     {`{"model":"gpt-5.5"}`, "/v1/chat/completions"},
		"assistant only":  {`{"model":"gpt-5.5","messages":[{"role":"assistant","content":"` + large + `"}]}`, "/v1/chat/completions"},
		"below threshold": {`{"model":"gpt-5.5","messages":[{"role":"user","content":"tiny"}]}`, "/v1/chat/completions"},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			if _, _, ok := openaiAdapter().ExtractStabilizable([]byte(tc.body), providers.RequestMetadata{Provider: "openai", Endpoint: tc.endpoint}); ok {
				t.Fatal("ExtractStabilizable must opt out")
			}
		})
	}
}

package openai

import "strings"

// ReasoningEffortOptimizerID is the policy flag / x-cave-optimization label for
// the reasoning-effort optimizer.
const ReasoningEffortOptimizerID = "reasoning-effort"

// reasoningEffortHint is the provider-native reasoning effort value this
// optimizer applies when the caller has not set one. It is deliberately LOW,
// not high: the whole point is to spend fewer thinking tokens on work that does
// not need them. The endpoint-specific wire spelling is selected below (Chat
// Completions: reasoning_effort; Responses: reasoning.effort).
const reasoningEffortHint = "low"

type reasoningEndpoint uint8

const (
	reasoningEndpointUnknown reasoningEndpoint = iota
	reasoningEndpointChat
	reasoningEndpointResponses
)

// reasoningEndpointKind deliberately recognizes only the routes owned by this
// adapter. Unknown paths, path prefixes, and malformed aliases fail closed so
// a route cannot receive the grammar of a different OpenAI API surface.
func reasoningEndpointKind(endpoint string) reasoningEndpoint {
	switch endpoint {
	case "/v1/chat/completions", "/openai/v1/chat/completions":
		return reasoningEndpointChat
	case "/v1/responses", "/openai/v1/responses":
		return reasoningEndpointResponses
	default:
		return reasoningEndpointUnknown
	}
}

// applyReasoningEffort adds a provider-native reasoning effort hint when the
// caller has not set one AND the request targets a known endpoint/model/body
// shape that supports it. Returns true if it changed root.
//
// Why eval-gated rather than purely byte-safe: the gateway never alters
// model-visible bytes here (reasoning is request envelope, not message
// content), but a lower thinking budget CAN change the model's answer — exactly
// like output-brevity. So it runs only behind both a policy flag and a cleared
// eval gate, and it is the gate that protects the hard-task tail where dialing
// reasoning down silently degrades quality.
//
// Conservative and idempotent: never overrides a caller-set reasoning value,
// and never injects the field on a model that does not support it (which would
// turn an optimization into a 400 from the provider).
func applyReasoningEffort(root map[string]any, endpoint string) bool {
	kind := reasoningEndpointKind(endpoint)
	if kind == reasoningEndpointUnknown || !reasoningRequestShape(root, kind) {
		return false
	}
	// Read the model from the upstream-bound body (the bytes the capability check
	// must agree with), not from telemetry meta — a missing or non-string model
	// yields "" and a safe no-op.
	model, _ := root["model"].(string)
	if !supportsReasoningEffortForEndpoint(model, kind) {
		return false
	}

	switch kind {
	case reasoningEndpointChat:
		// A caller-provided value, including null or a malformed type, remains
		// authoritative. A nested Responses-style field is ambiguous on Chat
		// and must not be rewritten into a second grammar.
		if _, set := root["reasoning_effort"]; set {
			return false
		}
		if _, set := root["reasoning"]; set {
			return false
		}
		root["reasoning_effort"] = reasoningEffortHint
		return true

	case reasoningEndpointResponses:
		// Responses has no top-level reasoning_effort field. Preserve one if a
		// caller supplied it rather than trying to repair an ambiguous request.
		if _, set := root["reasoning_effort"]; set {
			return false
		}
		if raw, set := root["reasoning"]; set {
			reasoning, ok := raw.(map[string]any)
			if !ok {
				return false
			}
			if _, set := reasoning["effort"]; set {
				return false
			}
			reasoning["effort"] = reasoningEffortHint
			return true
		}
		root["reasoning"] = map[string]any{"effort": reasoningEffortHint}
		return true
	}

	return false
}

// reasoningRequestShape proves enough of the request grammar to avoid adding
// an endpoint-specific field to an unrelated or malformed JSON object. It is
// intentionally conservative: unknown fields remain untouched, but the
// endpoint's distinguishing input field must have the documented JSON type.
func reasoningRequestShape(root map[string]any, endpoint reasoningEndpoint) bool {
	model, ok := root["model"].(string)
	if !ok || strings.TrimSpace(model) == "" {
		return false
	}

	switch endpoint {
	case reasoningEndpointChat:
		messages, ok := root["messages"].([]any)
		return ok && len(messages) > 0

	case reasoningEndpointResponses:
		// A Chat body on the Responses route is not a safe basis for a nested
		// transform. Responses requests identify their input via input,
		// instructions, or a previous response id.
		if _, hasMessages := root["messages"]; hasMessages {
			return false
		}
		if input, exists := root["input"]; exists {
			switch input.(type) {
			case string, []any:
				return true
			default:
				return false
			}
		}
		if instructions, exists := root["instructions"]; exists {
			_, ok := instructions.(string)
			return ok
		}
		if previous, exists := root["previous_response_id"]; exists {
			_, ok := previous.(string)
			return ok
		}
	}

	return false
}

// supportsReasoningEffort reports whether an OpenAI model belongs to a current
// reasoning family. Only reasoning models accept this parameter; setting it on
// a non-reasoning model (e.g. gpt-4o) is rejected by the API, so we gate on
// capability to stay byte-safe in spirit — an optimizer must never break a
// request it cannot improve.
//
// A family prefix matches when the model is exactly the prefix or continues
// with a version separator ('-' or '.'), so "gpt-5" matches "gpt-5",
// "gpt-5-pro", and "gpt-5.5" but not "gpt-50". (This intentionally treats
// '.' as a separator, unlike detectors.isPremiumModel, because gpt-5.5 IS a
// reasoning model.)
func supportsReasoningEffort(model string) bool {
	if model == "" {
		return false
	}
	// gpt-5 family (gpt-5, gpt-5.x, gpt-5-*) are reasoning models.
	if hasModelPrefix(model, "gpt-5") {
		return true
	}
	// o-series reasoning models: o1, o3, o4 (and dated/suffixed variants).
	for _, fam := range []string{"o1", "o3", "o4"} {
		if hasModelPrefix(model, fam) {
			return true
		}
	}
	return false
}

// supportsReasoningEffortForEndpoint keeps the existing reasoning-family
// capability check while excluding Pro variants whose current model contracts
// do not document the low effort this optimizer uses. This applies to both
// endpoint grammars: mapping upward to medium/high would no longer be the
// savings optimization, so unsupported Pro aliases and dated snapshots pass
// through instead of risking a provider 4xx.
func supportsReasoningEffortForEndpoint(model string, _ reasoningEndpoint) bool {
	if !supportsReasoningEffort(model) || hasUnsupportedProReasoningEffort(model) {
		return false
	}
	return true
}

// hasUnsupportedProReasoningEffort recognizes a Pro segment anywhere after a
// supported reasoning-family prefix. OpenAI documents Pro slugs and dated
// snapshots with this segment (gpt-5-pro, gpt-5.4-pro-..., o3-pro-...); a
// segment-aware check also fail-closes a newly introduced alias without
// inventing a model-specific allowlist. GPT-5.6's supported `reasoning.mode:
// pro` is not a `-pro` model slug and therefore remains eligible when its
// documented low effort is supported.
func hasUnsupportedProReasoningEffort(model string) bool {
	for _, family := range []string{"gpt-5", "o1", "o3", "o4"} {
		if !hasModelPrefix(model, family) {
			continue
		}
		suffix := model[len(family):]
		for _, segment := range strings.FieldsFunc(suffix, func(r rune) bool { return r == '-' || r == '.' }) {
			if segment == "pro" {
				return true
			}
		}
	}
	return false
}

// hasModelPrefix reports whether model equals prefix or begins with prefix
// followed by a version/variant separator ('-' or '.'). This keeps "gpt-5"
// from matching "gpt-50" while still matching "gpt-5.5" and "gpt-5-pro".
func hasModelPrefix(model, prefix string) bool {
	if model == prefix {
		return true
	}
	if !strings.HasPrefix(model, prefix) {
		return false
	}
	next := model[len(prefix)]
	return next == '-' || next == '.'
}

package openai

import (
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func reasoningPolicy(flag, gate bool) providers.TransformPolicy {
	return providers.TransformPolicy{
		RuntimeMode: "active",
		Optimizers:  map[string]bool{ReasoningEffortOptimizerID: flag},
		EvalGates:   map[string]bool{ReasoningEffortOptimizerID: gate},
	}
}

func TestReasoningEffort_RequiresBothFlagAndEvalGate(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"solve this"}]}`
	endpoint := "/v1/chat/completions"

	// Flag on, eval gate NOT cleared -> must not apply.
	r := applyAtEndpoint(t, body, endpoint, reasoningPolicy(true, false))
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("reasoning-effort must not run without a cleared eval gate, got %v", r.OptimizerIDs)
	}

	// Eval gate cleared, flag off -> must not apply.
	r = applyAtEndpoint(t, body, endpoint, reasoningPolicy(false, true))
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("reasoning-effort must not run without the policy flag, got %v", r.OptimizerIDs)
	}

	// Both -> applies and sets reasoning_effort to the (low) hint.
	r = applyAtEndpoint(t, body, endpoint, reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 1 || r.OptimizerIDs[0] != ReasoningEffortOptimizerID {
		t.Fatalf("both flag + eval gate must apply reasoning-effort, got %v", r.OptimizerIDs)
	}
	if got := decode(t, r.Body)["reasoning_effort"]; got != reasoningEffortHint {
		t.Fatalf("reasoning_effort = %v, want %q", got, reasoningEffortHint)
	}
}

func TestReasoningEffort_LowersNotRaises(t *testing.T) {
	// The cost-saving direction must be DOWN: the hint is "low", never "high".
	if reasoningEffortHint != "low" {
		t.Fatalf("reasoning-effort hint must be a reduction (low), got %q", reasoningEffortHint)
	}
}

// TestReasoningEffort_DisabledIsPassthrough checks the adapter layer: with the
// optimizer disabled the body is untouched, including when a direct caller
// supplies record mode.
func TestReasoningEffort_DisabledIsPassthrough(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"solve"}]}`
	r := applyAtEndpoint(t, body, "/v1/chat/completions", providers.TransformPolicy{RuntimeMode: "record", Optimizers: map[string]bool{ReasoningEffortOptimizerID: true}, EvalGates: map[string]bool{ReasoningEffortOptimizerID: true}})
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("disabled optimizer must pass through unchanged")
	}
}

func TestReasoningEffort_RespectsCallerEffort(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}],"reasoning_effort":"high"}`
	r := applyAtEndpoint(t, body, "/v1/chat/completions", reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("reasoning-effort must respect a caller-set value, got %v", r.OptimizerIDs)
	}
}

func TestReasoningEffort_SkipsNonReasoningModel(t *testing.T) {
	// Injecting reasoning_effort on a non-reasoning model (gpt-4o) would be
	// rejected by the API, so the optimizer must leave it untouched.
	body := `{"model":"gpt-4o","messages":[{"role":"user","content":"hi"}]}`
	r := applyAtEndpoint(t, body, "/v1/chat/completions", reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 0 || string(r.Body) != body {
		t.Fatalf("reasoning-effort must not touch a non-reasoning model, got %v", r.OptimizerIDs)
	}
}

func TestReasoningEffort_ByteSafeOnlyFieldAdded(t *testing.T) {
	body := `{"model":"o3","messages":[{"role":"user","content":"hi"}],"temperature":1}`
	r := applyAtEndpoint(t, body, "/v1/chat/completions", reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 1 {
		t.Fatalf("expected reasoning-effort to apply on a reasoning model, got %v", r.OptimizerIDs)
	}
	out := decode(t, r.Body)
	if out["reasoning_effort"] != reasoningEffortHint {
		t.Fatalf("reasoning_effort not set: %v", out["reasoning_effort"])
	}
	// Nothing model-visible changed: model, messages, temperature intact.
	if out["model"] != "o3" || out["temperature"] != float64(1) {
		t.Fatalf("transform altered model-visible fields: %v", out)
	}
	if _, ok := out["messages"]; !ok {
		t.Fatalf("messages dropped by transform")
	}
}

func TestReasoningEffort_ResponsesUsesNestedEffort(t *testing.T) {
	body := `{"model":"gpt-5.5","input":"solve this","temperature":0.2}`
	r := applyAtEndpoint(t, body, "/v1/responses", reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 1 || r.OptimizerIDs[0] != ReasoningEffortOptimizerID {
		t.Fatalf("expected Responses reasoning transform, got %v", r.OptimizerIDs)
	}
	out := decode(t, r.Body)
	reasoning, ok := out["reasoning"].(map[string]any)
	if !ok || reasoning["effort"] != reasoningEffortHint {
		t.Fatalf("Responses reasoning.effort = %v, want %q", out["reasoning"], reasoningEffortHint)
	}
	if _, topLevel := out["reasoning_effort"]; topLevel {
		t.Fatalf("Responses request must not receive Chat's top-level reasoning_effort: %v", out)
	}
	if out["model"] != "gpt-5.5" || out["input"] != "solve this" || out["temperature"] != float64(0.2) {
		t.Fatalf("Responses transform altered existing fields: %v", out)
	}
}

func TestReasoningEffort_ResponsesRouteAliasUsesNestedEffort(t *testing.T) {
	body := `{"model":"o3","input":"hi"}`
	r := applyAtEndpoint(t, body, "/openai/v1/responses", reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 1 {
		t.Fatalf("expected aliased Responses route to transform, got %v", r.OptimizerIDs)
	}
	reasoning, ok := decode(t, r.Body)["reasoning"].(map[string]any)
	if !ok || reasoning["effort"] != reasoningEffortHint {
		t.Fatalf("aliased Responses request missing nested effort: %v", reasoning)
	}
}

func TestReasoningEffort_ResponsesPreservesExistingReasoningFields(t *testing.T) {
	body := `{"model":"gpt-5.5","input":"hi","reasoning":{"summary":"auto","custom":"keep"}}`
	r := applyAtEndpoint(t, body, "/v1/responses", reasoningPolicy(true, true))
	if len(r.OptimizerIDs) != 1 {
		t.Fatalf("expected Responses reasoning transform, got %v", r.OptimizerIDs)
	}
	reasoning, ok := decode(t, r.Body)["reasoning"].(map[string]any)
	if !ok {
		t.Fatalf("reasoning object was not preserved: %v", r.Body)
	}
	if reasoning["effort"] != reasoningEffortHint || reasoning["summary"] != "auto" || reasoning["custom"] != "keep" {
		t.Fatalf("nested reasoning fields changed or were dropped: %v", reasoning)
	}
}

func TestReasoningEffort_PreservesCallerSettingsPerEndpoint(t *testing.T) {
	cases := []struct {
		name     string
		endpoint string
		body     string
	}{
		{
			name:     "chat top-level effort",
			endpoint: "/v1/chat/completions",
			body:     `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}],"reasoning_effort":"high"}`,
		},
		{
			name:     "responses nested effort",
			endpoint: "/v1/responses",
			body:     `{"model":"gpt-5.5","input":"hi","reasoning":{"summary":"auto","effort":"high"}}`,
		},
		{
			name:     "responses top-level caller field",
			endpoint: "/v1/responses",
			body:     `{"model":"gpt-5.5","input":"hi","reasoning_effort":"high"}`,
		},
		{
			name:     "chat nested ambiguous field",
			endpoint: "/v1/chat/completions",
			body:     `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}],"reasoning":{"effort":"high"}}`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := applyAtEndpoint(t, tc.body, tc.endpoint, reasoningPolicy(true, true))
			if len(r.OptimizerIDs) != 0 || string(r.Body) != tc.body {
				t.Fatalf("caller setting must be preserved exactly, ids=%v body=%s", r.OptimizerIDs, r.Body)
			}
		})
	}
}

func TestReasoningEffort_UnknownEndpointOrShapePassesThrough(t *testing.T) {
	cases := []struct {
		name     string
		endpoint string
		body     string
	}{
		{
			name:     "unknown route",
			endpoint: "/v1/responses-anything",
			body:     `{"model":"gpt-5.5","input":"hi"}`,
		},
		{
			name:     "missing route metadata",
			endpoint: "",
			body:     `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}]}`,
		},
		{
			name:     "chat body on Responses route",
			endpoint: "/v1/responses",
			body:     `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}]}`,
		},
		{
			name:     "responses body on Chat route",
			endpoint: "/v1/chat/completions",
			body:     `{"model":"gpt-5.5","input":"hi"}`,
		},
		{
			name:     "malformed chat messages",
			endpoint: "/v1/chat/completions",
			body:     `{"model":"gpt-5.5","messages":{"role":"user"}}`,
		},
		{
			name:     "empty chat messages",
			endpoint: "/v1/chat/completions",
			body:     `{"model":"gpt-5.5","messages":[]}`,
		},
		{
			name:     "malformed Responses input",
			endpoint: "/v1/responses",
			body:     `{"model":"gpt-5.5","input":{"text":"hi"}}`,
		},
		{
			name:     "invalid JSON",
			endpoint: "/v1/responses",
			body:     `{"model":"gpt-5.5","input":`,
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := applyAtEndpoint(t, tc.body, tc.endpoint, reasoningPolicy(true, true))
			if len(r.OptimizerIDs) != 0 || string(r.Body) != tc.body {
				t.Fatalf("ambiguous request must pass through exactly, ids=%v body=%s", r.OptimizerIDs, r.Body)
			}
		})
	}
}

func TestReasoningEffort_SkipsUnsupportedProModelsOnBothEndpoints(t *testing.T) {
	models := []string{
		"gpt-5-pro",
		"gpt-5-pro-2025-10-06",
		"gpt-5.2-pro",
		"gpt-5.2-pro-2025-12-11",
		"gpt-5.4-pro",
		"gpt-5.4-pro-2026-03-05",
		"gpt-5.5-pro",
		"gpt-5.5-pro-2026-04-23",
		"o1-pro",
		"o1-pro-2025-03-19",
		"o3-pro",
		"o3-pro-2025-06-10",
	}
	for _, model := range models {
		for _, tc := range []struct {
			name     string
			endpoint string
			body     string
		}{
			{name: "chat", endpoint: "/v1/chat/completions", body: `{"model":"` + model + `","messages":[{"role":"user","content":"hi"}]}`},
			{name: "responses", endpoint: "/v1/responses", body: `{"model":"` + model + `","input":"hi"}`},
		} {
			t.Run(model+"/"+tc.name, func(t *testing.T) {
				r := applyAtEndpoint(t, tc.body, tc.endpoint, reasoningPolicy(true, true))
				if len(r.OptimizerIDs) != 0 || string(r.Body) != tc.body {
					t.Fatalf("unsupported Pro model must pass through exactly, ids=%v body=%s", r.OptimizerIDs, r.Body)
				}
			})
		}
	}
}

func TestSupportsReasoningEffortForEndpointSkipsProAliases(t *testing.T) {
	for _, model := range []string{
		"gpt-5-pro",
		"gpt-5.5-pro-2026-04-23",
		"o3-pro-2025-06-10",
	} {
		for _, endpoint := range []reasoningEndpoint{reasoningEndpointChat, reasoningEndpointResponses} {
			if supportsReasoningEffortForEndpoint(model, endpoint) {
				t.Errorf("supportsReasoningEffortForEndpoint(%q,%d) = true, want false", model, endpoint)
			}
		}
	}
	for _, model := range []string{"gpt-5.5", "o3", "o4-mini"} {
		for _, endpoint := range []reasoningEndpoint{reasoningEndpointChat, reasoningEndpointResponses} {
			if !supportsReasoningEffortForEndpoint(model, endpoint) {
				t.Errorf("supportsReasoningEffortForEndpoint(%q,%d) = false, want true", model, endpoint)
			}
		}
	}
}

func TestSupportsReasoningEffort(t *testing.T) {
	yes := []string{"gpt-5", "gpt-5.5", "gpt-5-pro", "o1", "o1-2025-01-01", "o3", "o3-mini", "o3-2025-04-16", "o4-mini", "o4-mini-2025-04-16"}
	no := []string{"", "gpt-4o", "gpt-4-turbo", "gpt-50", "claude-opus-4", "gemini-2.5-pro", "o10", "o30", "o100"}
	for _, m := range yes {
		if !supportsReasoningEffort(m) {
			t.Errorf("supportsReasoningEffort(%q) = false, want true", m)
		}
	}
	for _, m := range no {
		if supportsReasoningEffort(m) {
			t.Errorf("supportsReasoningEffort(%q) = true, want false", m)
		}
	}
}

package openai

import (
	"bytes"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

var recoveredPayload = strings.Repeat("bibliography entry the agent must enumerate exhaustively ", 40)

// rewritable returns the blocks the proxy may rewrite. An ok=false result means
// the adapter found nothing rewritable at all, which is the strongest form of
// "not a candidate" — so it is reported as an empty set, not a failure.
func rewritable(t *testing.T, body []byte, endpoint string) []providers.RewritableBlock {
	t.Helper()
	blocks, _, ok := ExtractStabilizable(body, providers.RequestMetadata{Provider: "openai", Endpoint: endpoint})
	if !ok {
		return nil
	}
	return blocks
}

func blockContains(blocks []providers.RewritableBlock, want string) bool {
	for _, b := range blocks {
		if bytes.Contains(b.Content, []byte(want)) {
			return true
		}
	}
	return false
}

// A tool message answering caveman_retrieve carries the exact bytes an earlier
// elision removed. Exposing it as rewritable lets the prefix cache substitute
// that same elision straight back in, leaving the agent no path to its own data.
func TestChatRecoveryToolResultIsNotRewritable(t *testing.T) {
	body := []byte(`{"model":"gpt-5.5","messages":[` +
		`{"role":"user","content":"find the fake citations"},` +
		`{"role":"assistant","tool_calls":[{"id":"call_ret","type":"function","function":{"name":"mcp__caveman__caveman_retrieve","arguments":"{}"}}]},` +
		`{"role":"tool","tool_call_id":"call_ret","content":"` + recoveredPayload + `"}]}`)

	blocks := rewritable(t, body, "/v1/chat/completions")
	if blockContains(blocks, recoveredPayload) {
		t.Fatalf("recovered tool message must not be rewritable; got %d blocks", len(blocks))
	}
}

// An ordinary tool message stays rewritable — the exemption must be keyed on the
// recovery tool, not on tool messages generally.
func TestChatOrdinaryToolResultStaysRewritable(t *testing.T) {
	body := []byte(`{"model":"gpt-5.5","messages":[` +
		`{"role":"user","content":"find the fake citations"},` +
		`{"role":"assistant","tool_calls":[{"id":"call_read","type":"function","function":{"name":"Read","arguments":"{}"}}]},` +
		`{"role":"tool","tool_call_id":"call_read","content":"` + recoveredPayload + `"}]}`)

	blocks := rewritable(t, body, "/v1/chat/completions")
	if !blockContains(blocks, recoveredPayload) {
		t.Fatal("an ordinary tool result must remain rewritable")
	}
}

func TestResponsesRecoveryOutputIsNotRewritable(t *testing.T) {
	body := []byte(`{"model":"gpt-5.5","input":[` +
		`{"type":"message","role":"user","content":[{"type":"input_text","text":"find the fake citations"}]},` +
		`{"type":"function_call","call_id":"call_ret","name":"caveman_retrieve","arguments":"{}"},` +
		`{"type":"function_call_output","call_id":"call_ret","output":"` + recoveredPayload + `"}]}`)

	blocks := rewritable(t, body, "/v1/responses")
	if blockContains(blocks, recoveredPayload) {
		t.Fatalf("recovered function_call_output must not be rewritable; got %d blocks", len(blocks))
	}
}

func TestResponsesOrdinaryOutputStaysRewritable(t *testing.T) {
	body := []byte(`{"model":"gpt-5.5","input":[` +
		`{"type":"message","role":"user","content":[{"type":"input_text","text":"find the fake citations"}]},` +
		`{"type":"function_call","call_id":"call_read","name":"Read","arguments":"{}"},` +
		`{"type":"function_call_output","call_id":"call_read","output":"` + recoveredPayload + `"}]}`)

	blocks := rewritable(t, body, "/v1/responses")
	if !blockContains(blocks, recoveredPayload) {
		t.Fatal("an ordinary function_call_output must remain rewritable")
	}
}

package openai

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/jsonsplice"
)

// SessionCacheKeyID labels the session-scoped prompt_cache_key on
// x-cave-optimization and on the telemetry row.
//
// It mints nothing. OpenAI prompt caching is automatic; prompt_cache_key is
// routing affinity, so the field alone cannot prove an incremental cache hit —
// which is exactly why the gateway's cacheOptimizerIDs set has never contained an
// OpenAI key, and why this id is not added to it either.
const SessionCacheKeyID = "openai-session-prompt-cache-key"

// sessionCacheKeyDomain separates this hash from any other sha256 of the same
// input, so the key can never be confused with (or reversed into) an identifier
// used elsewhere.
const sessionCacheKeyDomain = "caveman.session-prompt-cache-key.v1:"

// PlanCacheBreakpoints sets a per-session prompt_cache_key.
//
// OpenAI 5.6+ dropped the fallback to the longest unmarked prefix, so cache
// routing is load-bearing: requests that share a prefix AND a key are routed to
// the machine that already holds that prefix. A session is the right key scope —
// one agent run is one conversation growing by append — and it is stable for the
// life of that run.
//
// The key is sha256(domain + session id), hex, truncated to 16 characters. The
// raw session id never reaches the provider: x-cave-session is caller-supplied
// and may carry user content, so it is hashed rather than forwarded.
//
// Precedence, stated explicitly because two optimizers write the same field: the
// PREFIX-SIGNATURE optimizer in cache_key.go WINS. It runs earlier, inside
// ApplyProviderNativeTransforms, so when an operator has both enabled this
// function finds a key already present and declines. That is the right way round
// — a key derived from the actual cacheable prefix is at least as good a routing
// scope as the session, and silently replacing an optimizer's output from a later
// pipeline stage would make the upstream bytes depend on stage ordering rather
// than on config. The same rule covers a key the CALLER set: never overwritten.
// Any parse problem leaves the body unchanged.
func (a Adapter) PlanCacheBreakpoints(body []byte, meta providers.RequestMetadata, payg bool) ([]byte, bool) {
	if !payg || meta.SessionID == "" {
		return nil, false
	}
	var root map[string]any
	if json.Unmarshal(body, &root) != nil {
		return nil, false
	}
	if _, exists := root["prompt_cache_key"]; exists {
		return nil, false
	}
	object, ok := jsonsplice.Root(body)
	if !ok {
		return nil, false
	}
	key, err := json.Marshal(SessionCacheKey(meta.SessionID))
	if err != nil {
		return nil, false
	}
	out, err := jsonsplice.AppendObjectFields(body, object,
		jsonsplice.FieldInsertion{Name: "prompt_cache_key", Value: key},
	)
	if err != nil || !json.Valid(out) {
		return nil, false
	}
	return out, true
}

// SessionCacheKey is the stable, content-blind key derived from a session id.
func SessionCacheKey(sessionID string) string {
	sum := sha256.Sum256([]byte(sessionCacheKeyDomain + sessionID))
	return hex.EncodeToString(sum[:])[:16]
}

package openai

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// OpenAI 5.6+ removed the fallback to the longest unmarked prefix, so
// prompt_cache_key became load-bearing routing metadata. The planner sets one per
// session — hashed, never the raw caller-supplied id — and never over an existing
// key.

const sessionKeyBody = `{"model":"gpt-5.6","instructions":"You are a coding agent.","input":"hello"}`

func planSessionKey(t *testing.T, body, session string, payg bool) ([]byte, bool) {
	t.Helper()
	adapter := New("http://upstream").(Adapter)
	return adapter.PlanCacheBreakpoints([]byte(body), providers.RequestMetadata{
		Provider:  "openai",
		SessionID: session,
	}, payg)
}

func TestSessionCacheKeySetsAStableHashedKey(t *testing.T) {
	out, ok := planSessionKey(t, sessionKeyBody, "sess-abc.123", true)
	if !ok {
		t.Fatal("planner declined a payg request with a session and no key")
	}
	var root map[string]any
	if err := json.Unmarshal(out, &root); err != nil {
		t.Fatalf("invalid JSON: %v", err)
	}
	key, isString := root["prompt_cache_key"].(string)
	if !isString || key == "" {
		t.Fatalf("prompt_cache_key missing: %s", out)
	}
	if len(key) != 16 {
		t.Fatalf("key = %q (%d chars), want a 16-char hash prefix", key, len(key))
	}
	// The raw session id is caller-supplied and may carry user content. It must
	// never reach the provider, in whole or as a substring of the key.
	if strings.Contains(string(out), "sess-abc.123") {
		t.Fatalf("the raw session id was forwarded upstream: %s", out)
	}
	if key != SessionCacheKey("sess-abc.123") {
		t.Fatalf("key %q is not the documented derivation", key)
	}

	// Stability: the same session produces the same key on every later call, which
	// is the entire point — a key that moved would scatter the session's requests
	// across cache-holding machines.
	again, ok := planSessionKey(t, sessionKeyBody, "sess-abc.123", true)
	if !ok || string(again) != string(out) {
		t.Fatalf("key is not stable across calls:\n first %s\nsecond %s", out, again)
	}
	// Distinct sessions get distinct keys.
	if SessionCacheKey("sess-abc.123") == SessionCacheKey("sess-other") {
		t.Fatal("two sessions collided on one key")
	}
}

func TestSessionCacheKeyPreconditions(t *testing.T) {
	for _, tc := range []struct {
		name    string
		body    string
		session string
		payg    bool
	}{
		{name: "no session header", body: sessionKeyBody, session: "", payg: true},
		{name: "not payg", body: sessionKeyBody, session: "sess-abc", payg: false},
		{
			name:    "caller already set a key",
			body:    `{"model":"gpt-5.6","input":"hi","prompt_cache_key":"caller-owned"}`,
			session: "sess-abc",
			payg:    true,
		},
		{name: "not json", body: `{"model":`, session: "sess-abc", payg: true},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if out, ok := planSessionKey(t, tc.body, tc.session, tc.payg); ok {
				t.Fatalf("planner rewrote a body it should have left alone: %s", out)
			}
		})
	}
}

// TestSessionCacheKeyNeverOverwritesThePrefixOptimizer: cache_key.go's
// prefix-signature optimizer may already have set the field on the same request.
// The session planner runs after it and must leave that key alone.
func TestSessionCacheKeyNeverOverwritesThePrefixOptimizer(t *testing.T) {
	adapter := New("http://upstream").(Adapter)
	transformed, err := adapter.ApplyProviderNativeTransforms(nil, strings.NewReader(sessionKeyBody),
		providers.RequestMetadata{Provider: "openai"},
		providers.TransformPolicy{RuntimeMode: "active", Optimizers: map[string]bool{OptimizerID: true}})
	if err != nil {
		t.Fatalf("prefix optimizer error: %v", err)
	}
	var root map[string]any
	if err := json.Unmarshal(transformed.Body, &root); err != nil {
		t.Fatalf("invalid JSON: %v", err)
	}
	existing, ok := root["prompt_cache_key"].(string)
	if !ok || existing == "" {
		t.Fatalf("fixture did not exercise the prefix optimizer: %s", transformed.Body)
	}

	if out, ok := planSessionKey(t, string(transformed.Body), "sess-abc", true); ok {
		t.Fatalf("session planner overwrote an existing prompt_cache_key: %s", out)
	}
}

package openai

// StreamUsageOptimizerID is the policy flag / x-cave-optimization label for the
// stream-usage optimizer.
const StreamUsageOptimizerID = "openai-stream-usage"

// applyStreamIncludeUsage asks the provider for a final usage chunk on a
// streamed OpenAI-shaped call by setting stream_options.include_usage = true.
// Returns true if it changed root.
//
// Why: streamed OpenAI-shaped calls return no usage block unless the request
// carries this flag, so without it the gateway has no provider-reported token
// counts for streamed traffic and must derive them instead — a worse money
// truth. This is envelope metadata the model never sees (it changes what the
// SSE stream ends with, not what the model reads or answers), so it does not
// violate byte-safe as that rule is written today (model-visible bytes only).
// But it DOES add one extra client-visible SSE chunk to the stream the caller
// receives (a final `data: {...,"usage":{...}}` event before `[DONE]`) — a
// change to the RESPONSE bytes the client sees, which sits outside a promise
// byte-safe doesn't currently make either way, not inside it. Every
// OpenAI-compatible client already knows to either consume or ignore an
// extra chunk shaped exactly like OpenAI's own documented include_usage
// behavior, so this is an acceptable, disclosed side effect — but "acceptable
// and disclosed" is a judgment call an operator makes, not something that
// follows from byte-safe alone. That is why this optimizer requires BOTH its
// policy flag AND a cleared eval gate (OptimizerActive, not just
// OptimizerEnabled) — the same bar every other optimizer with an
// observable effect on what the caller receives already has to clear.
//
// Conservative and idempotent: never overrides an explicit client choice.
//   - Only applies to bodies whose top-level shape is Chat Completions, the one
//     OpenAI API that documents stream_options.include_usage. A streamed
//     Responses request is left untouched (see isChatCompletionsShape).
//   - No stream_options at all: adds {"include_usage": true}.
//   - stream_options present without an include_usage key: merges the field in,
//     preserving every other key the caller set.
//   - stream_options.include_usage already set (true OR false): left untouched.
//     false is a deliberate client choice and must never be flipped to true.
//   - stream_options present but not a JSON object: left untouched rather than
//     guessed at.
//   - Only applies when the request is actually streaming ("stream": true);
//     non-streaming requests are untouched.
func applyStreamIncludeUsage(root map[string]any) bool {
	streaming, _ := root["stream"].(bool)
	if !streaming {
		return false
	}
	if !isChatCompletionsShape(root) {
		return false
	}

	existing, present := root["stream_options"]
	if !present {
		root["stream_options"] = map[string]any{"include_usage": true}
		return true
	}

	so, ok := existing.(map[string]any)
	if !ok {
		return false
	}
	if _, has := so["include_usage"]; has {
		return false
	}
	so["include_usage"] = true
	return true
}

// isChatCompletionsShape reports whether root is a Chat Completions body, using
// the same top-level discriminators applyOutputBrevity already uses: Responses
// carries `input` and/or `instructions`, Chat Completions carries `messages`.
//
// This gate exists because stream_options is a Chat-Completions-only parameter.
// The Responses API streams usage in its own terminal event and has no
// stream_options field at all, so injecting one there sends the provider a
// parameter it does not accept — turning an optimizer that is supposed to
// improve the money truth into a 400 on the caller's request. Unrecognized
// shapes fail closed (no injection) rather than being guessed at: the cost of
// not injecting is a request whose usage must be derived, which is exactly the
// state every non-Chat-Completions request is already in.
func isChatCompletionsShape(root map[string]any) bool {
	if _, hasInput := root["input"]; hasInput {
		return false
	}
	if _, hasInstructions := root["instructions"]; hasInstructions {
		return false
	}
	_, hasMessages := root["messages"]
	return hasMessages
}

package openai

import (
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// C8 review finding 5: this optimizer adds a client-visible SSE chunk to the
// response (an observable effect outside what byte-safe promises), so like
// reasoning-effort and output-brevity it needs OptimizerActive — flag AND a
// cleared eval gate — not just OptimizerEnabled.
func streamUsageEnabled() providers.TransformPolicy {
	return providers.TransformPolicy{
		RuntimeMode: "active",
		Optimizers:  map[string]bool{StreamUsageOptimizerID: true},
		EvalGates:   map[string]bool{StreamUsageOptimizerID: true},
	}
}

func TestStreamUsage_InjectsWhenAbsent(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, streamUsageEnabled())

	if len(res.OptimizerIDs) != 1 || res.OptimizerIDs[0] != StreamUsageOptimizerID {
		t.Fatalf("optimizer ids = %v, want [%s]", res.OptimizerIDs, StreamUsageOptimizerID)
	}
	root := decode(t, res.Body)
	so, ok := root["stream_options"].(map[string]any)
	if !ok {
		t.Fatalf("expected stream_options object, got %v", root["stream_options"])
	}
	if include, ok := so["include_usage"].(bool); !ok || !include {
		t.Fatalf("expected stream_options.include_usage = true, got %v", so["include_usage"])
	}
}

func TestStreamUsage_MergesIntoExistingStreamOptionsWithoutIncludeUsage(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"stream_options":{"some_other_field":true},"messages":[]}`
	res := apply(t, body, streamUsageEnabled())

	if len(res.OptimizerIDs) != 1 {
		t.Fatalf("expected optimizer applied, got %v", res.OptimizerIDs)
	}
	root := decode(t, res.Body)
	so := root["stream_options"].(map[string]any)
	if include, ok := so["include_usage"].(bool); !ok || !include {
		t.Fatalf("expected include_usage = true merged in, got %v", so["include_usage"])
	}
	if other, ok := so["some_other_field"].(bool); !ok || !other {
		t.Fatalf("expected caller's other stream_options field preserved, got %v", so["some_other_field"])
	}
}

// The core rule: an explicit client choice of include_usage:false is a DELIBERATE
// choice and must never be overwritten, even though the gateway would normally
// want usage data for the money truth.
func TestStreamUsage_NeverOverwritesExplicitFalse(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"stream_options":{"include_usage":false},"messages":[]}`
	res := apply(t, body, streamUsageEnabled())

	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("explicit include_usage:false must be respected (passthrough), got ids=%v body=%s", res.OptimizerIDs, res.Body)
	}
}

func TestStreamUsage_IdempotentWhenAlreadyTrue(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"stream_options":{"include_usage":true},"messages":[]}`
	res := apply(t, body, streamUsageEnabled())

	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("already-true include_usage must be passthrough (no re-injection), got ids=%v", res.OptimizerIDs)
	}
}

func TestStreamUsage_NonStreamingRequestUntouched(t *testing.T) {
	body := `{"model":"gpt-5.5","messages":[{"role":"user","content":"hi"}]}`
	res := apply(t, body, streamUsageEnabled())

	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("non-streaming request must be untouched, got ids=%v", res.OptimizerIDs)
	}
}

// CW 2: stream_options is a Chat-Completions-only parameter. A streamed
// Responses request was getting one injected, which sends the provider a field
// the Responses API does not accept — the optimizer that exists to improve the
// money truth turning into a 400 on the caller's request. Mirrors the
// endpoint/shape gate applyOutputBrevity already has.
func TestStreamUsage_StreamedResponsesBodyIsUntouched(t *testing.T) {
	for name, body := range map[string]string{
		"input":                      `{"model":"gpt-5.5","stream":true,"input":"hi"}`,
		"instructions":               `{"model":"gpt-5.5","stream":true,"instructions":"be terse","input":[]}`,
		"neither messages nor input": `{"model":"gpt-5.5","stream":true}`,
	} {
		t.Run(name, func(t *testing.T) {
			res := apply(t, body, streamUsageEnabled())
			if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
				t.Errorf("non-Chat-Completions body must be untouched, got ids=%v body=%s", res.OptimizerIDs, res.Body)
			}
		})
	}
}

func TestStreamUsage_DisabledIsPassthrough(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"messages":[]}`
	res := apply(t, body, providers.TransformPolicy{RuntimeMode: "active", Optimizers: map[string]bool{}})
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("disabled optimizer must pass body through unchanged, got ids=%v", res.OptimizerIDs)
	}
}

// C8 review finding 5: the flag alone must not be enough — an uncleared eval
// gate must block injection exactly like it blocks output-brevity/
// reasoning-effort, since this now goes through OptimizerActive.
func TestStreamUsage_FlagWithoutEvalGateIsPassthrough(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"messages":[]}`
	policy := providers.TransformPolicy{
		RuntimeMode: "active",
		Optimizers:  map[string]bool{StreamUsageOptimizerID: true},
		EvalGates:   map[string]bool{StreamUsageOptimizerID: false},
	}
	res := apply(t, body, policy)
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("flag without a cleared eval gate must not inject, got ids=%v body=%s", res.OptimizerIDs, res.Body)
	}
}

func TestStreamUsage_MalformedBodyPassesThroughUnchanged(t *testing.T) {
	bad := apply(t, "not json", streamUsageEnabled())
	if len(bad.OptimizerIDs) != 0 || string(bad.Body) != "not json" {
		t.Errorf("invalid JSON must pass through unchanged, got ids=%v body=%s", bad.OptimizerIDs, bad.Body)
	}
}

// stream_options present but not an object shape (malformed on the client's
// part) must not be guessed at — leave it exactly as sent.
func TestStreamUsage_NonObjectStreamOptionsUntouched(t *testing.T) {
	body := `{"model":"gpt-5.5","stream":true,"stream_options":"weird","messages":[]}`
	res := apply(t, body, streamUsageEnabled())
	if len(res.OptimizerIDs) != 0 || string(res.Body) != body {
		t.Errorf("non-object stream_options must be left untouched, got ids=%v", res.OptimizerIDs)
	}
}

package openaicompat

import (
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

func TestNamedAdapterReusesOpenAIResponsesGrammar(t *testing.T) {
	live := strings.Repeat("COMPAT_LIVE ", 60)
	body := []byte(`{"model":"x","input":"` + live + `"}`)
	adapter, err := NewNamed("groq", "https://api.groq.com/openai")
	if err != nil {
		t.Fatal(err)
	}
	segments, reassemble, ok := adapter.ExtractCompressible(body, providers.RequestMetadata{Endpoint: "/compat/groq/v1/responses"})
	if !ok || len(segments) != 1 || string(segments[0]) != live {
		t.Fatalf("segments=%q ok=%v", segments, ok)
	}
	out, err := reassemble([][]byte{[]byte("SHORT")})
	if err != nil || !strings.Contains(string(out), `"input":"SHORT"`) {
		t.Fatalf("out=%s err=%v", out, err)
	}
}

// prefixStabilizer mirrors the gateway's optional adapter capability. BOTH compat
// adapter shapes must satisfy it the same way they inherit compression, or a compat
// conversation would compress a turn and then flip the prefix back to the client's
// originals on the next one.
type prefixStabilizer interface {
	ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool)
}

func TestExtractStabilizableInheritsOpenAIZones(t *testing.T) {
	older := strings.Repeat("COMPAT_OLDER ", 60)
	live := strings.Repeat("COMPAT_LIVE ", 60)
	body := []byte(`{"model":"x","messages":[` +
		`{"role":"user","content":"` + older + `"},` +
		`{"role":"assistant","content":"ok"},` +
		`{"role":"user","content":"` + live + `"}]}`)
	named, err := NewNamed("groq", "https://api.groq.com/openai")
	if err != nil {
		t.Fatal(err)
	}
	for name, candidate := range map[string]providers.Adapter{
		"mount": New("https://api.groq.com/openai"),
		"named": named,
	} {
		t.Run(name, func(t *testing.T) {
			adapter, ok := candidate.(prefixStabilizer)
			if !ok {
				t.Fatal("compat adapter must expose ExtractStabilizable")
			}
			blocks, _, ok := adapter.ExtractStabilizable(body, providers.RequestMetadata{Endpoint: "/compat/groq/v1/chat/completions"})
			if !ok || len(blocks) != 2 {
				t.Fatalf("blocks=%d ok=%v", len(blocks), ok)
			}
			if blocks[0].Live || string(blocks[0].Content) != older {
				t.Fatalf("block 0 should be the frozen earlier turn, got live:%v", blocks[0].Live)
			}
			if !blocks[1].Live || string(blocks[1].Content) != live {
				t.Fatalf("block 1 should be the live latest turn, got live:%v", blocks[1].Live)
			}
		})
	}
}

package openaicompat

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"regexp"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/proxy/providers/openai"
)

var validName = regexp.MustCompile(`^[a-z0-9][a-z0-9._-]{0,63}$`)

func New(baseURL string) providers.Adapter {
	return Adapter{Base: providers.Base{Provider: "openai_compatible", BaseURL: baseURL, Routes: []string{"/compat/"}}}
}

type Adapter struct{ providers.Base }

// MatchRoute rejects path spellings whose decoded form could claim a different
// compatibility mount than the caller sent. The gateway performs the same
// check against URL.RawPath before it selects an adapter; this decoded check
// keeps direct adapter users fail-closed as well.
func (a Adapter) MatchRoute(method, path string) bool {
	if err := validateCompatPath(path, ""); err != nil {
		return false
	}
	return a.Base.MatchRoute(method, path)
}

// ResolveUpstreamURL removes only the default public /compat mount before
// resolving the provider path. Named adapters and the reserved legacy routes
// keep their dedicated resolver/compatibility behavior; this method exists for
// the bare providers.openai_compatible route only.
func (a Adapter) ResolveUpstreamURL(_ context.Context, req *http.Request, route providers.RouteContext) (*url.URL, error) {
	if req == nil || req.URL == nil || !strings.HasPrefix(req.URL.Path, "/compat/") {
		path := ""
		if req != nil && req.URL != nil {
			path = req.URL.Path
		}
		return nil, fmt.Errorf("compat route %q does not match default /compat/ mount", path)
	}
	if err := validateCompatPath(req.URL.Path, req.URL.RawPath); err != nil {
		return nil, err
	}

	// /compat/stub and /compat/openai-compatible were the original default
	// routes. They share the same strict path and query handling as the bare
	// mount, but retain their historical prefix stripping.
	requestPath := strings.TrimPrefix(req.URL.Path, "/compat")
	for _, legacy := range []string{"/stub", "/openai-compatible"} {
		if hasCompatPrefix(req.URL.Path, "/compat"+legacy) {
			requestPath = strings.TrimPrefix(req.URL.Path, "/compat"+legacy)
			break
		}
	}

	baseURL := a.Base.BaseURL
	if route.BaseURL != "" {
		baseURL = route.BaseURL
	}
	base, err := parseBaseURL(baseURL, a.Base.Provider)
	if err != nil {
		return nil, err
	}

	base.Path = joinCompatPath(base.Path, requestPath)
	// The parsed base URL may carry an encoded path hint that no longer matches
	// the joined decoded path. Clearing it lets net/url encode the final path
	// from Path without retaining stale escaping.
	base.RawPath = ""
	base.RawQuery = joinCompatQuery(base.RawQuery, req.URL.RawQuery)
	return base, nil
}

// joinCompatPath appends the public route's provider path to the configured
// base path, collapsing an overlapping segment. Ollama's documented base URL
// is /v1 while the compatibility request is /compat/v1/..., so the overlap must
// not become /v1/v1/.... Other configured prefixes (for example /api) remain
// intact.
func joinCompatPath(basePath, requestPath string) string {
	baseParts := splitCompatPath(basePath)
	requestParts := splitCompatPath(requestPath)
	if len(baseParts) == 0 {
		return "/" + strings.Join(requestParts, "/")
	}
	if len(requestParts) == 0 {
		return "/" + strings.Join(baseParts, "/")
	}
	maxOverlap := len(baseParts)
	if len(requestParts) < maxOverlap {
		maxOverlap = len(requestParts)
	}
	for overlap := maxOverlap; overlap > 0; overlap-- {
		match := true
		for i := 0; i < overlap; i++ {
			if baseParts[len(baseParts)-overlap+i] != requestParts[i] {
				match = false
				break
			}
		}
		if match {
			joined := append(append([]string{}, baseParts...), requestParts[overlap:]...)
			return "/" + strings.Join(joined, "/")
		}
	}
	return "/" + strings.Join(append(baseParts, requestParts...), "/")
}

func splitCompatPath(path string) []string {
	trimmed := strings.Trim(path, "/")
	if trimmed == "" {
		return nil
	}
	return strings.Split(trimmed, "/")
}

func hasCompatPrefix(path, prefix string) bool {
	return path == prefix || strings.HasPrefix(path, prefix+"/")
}

func joinCompatQuery(baseQuery, requestQuery string) string {
	switch {
	case baseQuery == "":
		return requestQuery
	case requestQuery == "":
		return baseQuery
	default:
		return baseQuery + "&" + requestQuery
	}
}

func (a Adapter) InspectRequest(ctx context.Context, body providers.BodyReader, headers http.Header) (providers.RequestMetadata, error) {
	return inspectOpenAICompatible(ctx, a.Base, body, headers)
}

func (a Adapter) ExtractCompressible(body []byte, meta providers.RequestMetadata) ([][]byte, func([][]byte) ([]byte, error), bool) {
	return openai.ExtractCompressible(body, meta)
}

func (a Adapter) ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool) {
	return openai.ExtractStabilizable(body, meta)
}

func (a namedAdapter) ExtractCompressible(body []byte, meta providers.RequestMetadata) ([][]byte, func([][]byte) ([]byte, error), bool) {
	return openai.ExtractCompressible(body, meta)
}

func (a namedAdapter) ExtractStabilizable(body []byte, meta providers.RequestMetadata) ([]providers.RewritableBlock, func([][]byte) ([]byte, error), bool) {
	return openai.ExtractStabilizable(body, meta)
}

type namedAdapter struct {
	providers.Base
	prefix string
}

func (a namedAdapter) MatchRoute(method, path string) bool {
	if err := validateCompatPath(path, ""); err != nil {
		return false
	}
	return a.Base.MatchRoute(method, path)
}

func (a namedAdapter) InspectRequest(ctx context.Context, body providers.BodyReader, headers http.Header) (providers.RequestMetadata, error) {
	return inspectOpenAICompatible(ctx, a.Base, body, headers)
}

func inspectOpenAICompatible(ctx context.Context, base providers.Base, body providers.BodyReader, headers http.Header) (providers.RequestMetadata, error) {
	meta, err := base.InspectRequest(ctx, body, headers)
	if path := headers.Get("x-cave-route-path"); path != "" {
		meta.Endpoint = path
	}
	return meta, err
}

// NewNamed builds a dedicated OpenAI-compatible upstream mounted at
// /compat/<name>/. The provider enum intentionally stays openai_compatible so
// usage/cost telemetry keeps using the shared OpenAI-shape parser.
func NewNamed(name, baseURL string) (providers.Adapter, error) {
	if err := ValidateName(name); err != nil {
		return nil, err
	}
	baseURL = strings.TrimSpace(baseURL)
	if err := ValidateBaseURL(baseURL); err != nil {
		return nil, fmt.Errorf("compat upstream %q base_url: %w", name, err)
	}
	prefix := "/compat/" + name
	return namedAdapter{
		Base: providers.Base{
			Provider: "openai_compatible",
			BaseURL:  baseURL,
			Routes:   []string{prefix + "/"},
		},
		prefix: prefix,
	}, nil
}

func ValidateName(name string) error {
	if !validName.MatchString(name) {
		return fmt.Errorf("compat upstream name %q must match [a-z0-9][a-z0-9._-]{0,63}", name)
	}
	switch name {
	case "stub", "openai-compatible":
		return fmt.Errorf("compat upstream name %q is reserved", name)
	default:
		return nil
	}
}

func ValidateBaseURL(raw string) error {
	_, err := parseBaseURL(raw, "compat")
	return err
}

// ResolveUpstreamURL intentionally ignores RouteContext.BaseURL. Named mounts
// are configured as independent static upstreams (`compat:` in standalone or
// CAVE_COMPAT_UPSTREAMS in managed mode); applying the generic project
// openai_compatible override here would collapse every named route onto one
// target. The default /compat/ adapter is the route that honors BaseURL.
func (a namedAdapter) ResolveUpstreamURL(_ context.Context, req *http.Request, _ providers.RouteContext) (*url.URL, error) {
	if req == nil || req.URL == nil {
		return nil, fmt.Errorf("compat request URL is missing")
	}
	if err := validateCompatPath(req.URL.Path, req.URL.RawPath); err != nil {
		return nil, err
	}
	base, err := parseBaseURL(a.BaseURL, a.Provider)
	if err != nil {
		return nil, err
	}
	if !strings.HasPrefix(req.URL.Path, a.prefix+"/") {
		return nil, fmt.Errorf("compat route %q does not match prefix %q", req.URL.Path, a.prefix+"/")
	}
	path := strings.TrimPrefix(req.URL.Path, a.prefix)
	base.Path = joinCompatPath(base.Path, path)
	base.RawPath = ""
	base.RawQuery = joinCompatQuery(base.RawQuery, req.URL.RawQuery)
	return base, nil
}

// ValidateRequestPath rejects ambiguous path encodings before adapter selection.
// Gateways call this with the original URL (including RawPath), while the
// adapter MatchRoute/ResolveUpstreamURL checks provide a second fail-closed
// boundary for direct callers.
func ValidateRequestPath(u *url.URL) error {
	if u == nil {
		return fmt.Errorf("request URL is missing")
	}
	if !strings.HasPrefix(u.Path, "/compat/") {
		return nil
	}
	return validateCompatPath(u.Path, u.RawPath)
}

func validateCompatPath(path, rawPath string) error {
	if !strings.HasPrefix(path, "/compat/") {
		return nil
	}
	if err := validatePathComponents(path, rawPath); err != nil {
		return fmt.Errorf("compat route path rejected: %w", err)
	}
	return nil
}

func validatePathComponents(path, rawPath string) error {
	if strings.Contains(path, `\`) {
		return fmt.Errorf("backslash is not allowed in path")
	}
	segments := strings.Split(path, "/")
	for i, segment := range segments {
		if segment == "" && i > 0 && i < len(segments)-1 {
			return fmt.Errorf("repeated path separators are not allowed")
		}
		if segment == "." || segment == ".." {
			return fmt.Errorf("dot segments are not allowed in path")
		}
	}
	// URL.Path is decoded by net/url while RawPath retains a valid escaped
	// spelling. Reject separators, backslashes, and dot bytes in either form so
	// a path cannot change route identity after another decoder or proxy hop.
	for _, escape := range []string{"%2f", "%5c", "%2e"} {
		if strings.Contains(strings.ToLower(path), escape) || strings.Contains(strings.ToLower(rawPath), escape) {
			return fmt.Errorf("ambiguous escaped path sequence %s", escape)
		}
	}
	return nil
}

func parseBaseURL(raw, provider string) (*url.URL, error) {
	if strings.TrimSpace(raw) == "" {
		return nil, fmt.Errorf("provider %q has no configured upstream URL", provider)
	}
	u, err := url.Parse(strings.TrimSpace(raw))
	if err != nil {
		return nil, err
	}
	if u.Scheme != "http" && u.Scheme != "https" {
		return nil, fmt.Errorf("provider %q upstream URL scheme %q is not allowed", provider, u.Scheme)
	}
	if !u.IsAbs() || u.Host == "" || u.Hostname() == "" {
		return nil, fmt.Errorf("provider %q upstream URL must be an absolute URL with a host", provider)
	}
	if u.User != nil {
		return nil, fmt.Errorf("provider %q upstream URL must not include userinfo", provider)
	}
	if u.Fragment != "" {
		return nil, fmt.Errorf("provider %q upstream URL must not include a fragment", provider)
	}
	if err := validatePathComponents(u.Path, u.RawPath); err != nil {
		return nil, fmt.Errorf("provider %q upstream URL path rejected: %w", provider, err)
	}
	return u, nil
}

