	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

const toolzoneBody = `{"model":"claude-sonnet-4-6","system":"be brief",` +
	`"tools":[{"name":"Read","title":"Read"},{"name":"Write","cache_control":{"type":"ephemeral"}}],` +
	`"messages":[{"role":"user","content":"hi"}]}`

func TestExtractToolCatalogReturnsExactBytesAndSplicesInPlace(t *testing.T) {
	meta := providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"}
	raw, reassemble, ok := providers.ExtractToolCatalog([]byte(toolzoneBody), meta)
	if !ok {
		t.Fatal("anthropic messages catalog was not extracted")
	}
	want := `[{"name":"Read","title":"Read"},{"name":"Write","cache_control":{"type":"ephemeral"}}]`
	if string(raw) != want {
		t.Fatalf("raw = %s\nwant = %s", raw, want)
	}
	out, err := reassemble([]byte(`[{"name":"Read"}]`))
	if err != nil {
		t.Fatal(err)
	}
	expected := strings.Replace(toolzoneBody, want, `[{"name":"Read"}]`, 1)
	if string(out) != expected {
		t.Fatalf("splice touched bytes outside the catalog:\n got %s\nwant %s", out, expected)
	}
}

func TestExtractToolCatalogFailsClosed(t *testing.T) {
	tests := []struct {
		name string
		body string
		meta providers.RequestMetadata
	}{
		{
			name: "openai is not covered yet",
			body: toolzoneBody,
			meta: providers.RequestMetadata{Provider: "openai", Endpoint: "/v1/chat/completions"},
		},
		{
			name: "gemini is not covered yet",
			body: toolzoneBody,
			meta: providers.RequestMetadata{Provider: "gemini", Endpoint: "/v1beta/models/x:generateContent"},
		},
		{
			name: "count_tokens must measure the body it was given",
			body: toolzoneBody,
			meta: providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages/count_tokens"},
		},
		{
			name: "no tools field",
			body: `{"model":"claude-sonnet-4-6","messages":[]}`,
			meta: providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"},
		},
		{
			name: "tools is not an array",
			body: `{"model":"claude-sonnet-4-6","tools":{"name":"Read"},"messages":[]}`,
			meta: providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"},
		},
		{
			name: "malformed body",
			body: `{"model":"claude-sonnet-4-6","tools":[`,
			meta: providers.RequestMetadata{Provider: "anthropic", Endpoint: "/v1/messages"},
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			if _, _, ok := providers.ExtractToolCatalog([]byte(tc.body), tc.meta); ok {
				t.Fatal("extraction must fail closed")
			}
		})
	}
}

package vertex

import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

// S19 regression: the Vertex adapter must pass the caller's Application Default
// Credentials (a fresh OAuth2 bearer token per request) straight through to the
// upstream Authorization header and persist NOTHING — the gateway holds no GCP
// secret. Statelessness is the "no persistence" guarantee at the adapter layer:
// the adapter struct carries no credential field, and two requests with different
// tokens each forward their own token with no bleed from a cached first token.
func TestVertexADCPassThroughNoPersistence(t *testing.T) {
	a := newAdapter(t)

	// (1) ADC pass-through: the caller-supplied token becomes the upstream bearer.
	const tokenA = "ya29.adc-token-AAA"
	reqA, _ := http.NewRequest(http.MethodPost, predictPath("google", geminiModel, "generateContent"), nil)
	outA, err := a.SanitizeAndMapHeaders(context.Background(), reqA, providers.Credential{Key: tokenA}, nil)
	if err != nil {
		t.Fatalf("sanitize A: %v", err)
	}
	if outA.Get("Authorization") != "Bearer "+tokenA {
		t.Errorf("request A Authorization = %q, want Bearer %s (ADC pass-through)", outA.Get("Authorization"), tokenA)
	}

	// (2) No persistence: a second request with a DIFFERENT token forwards ITS token,
	// proving the adapter retained nothing from request A.
	const tokenB = "ya29.adc-token-BBB"
	reqB, _ := http.NewRequest(http.MethodPost, predictPath("anthropic", "claude-3-5-sonnet", "rawPredict"), nil)
	outB, err := a.SanitizeAndMapHeaders(context.Background(), reqB, providers.Credential{Key: tokenB}, nil)
	if err != nil {
		t.Fatalf("sanitize B: %v", err)
	}
	if outB.Get("Authorization") != "Bearer "+tokenB {
		t.Errorf("request B Authorization = %q, want Bearer %s (no token persisted from A)", outB.Get("Authorization"), tokenB)
	}
	// Token A must not bleed into request B's headers.
	for name, vals := range outB {
		for _, v := range vals {
			if strings.Contains(v, tokenA) {
				t.Errorf("token A leaked into request B header %s = %q (adapter persisted a credential)", name, v)
			}
		}
	}

	// (3) The adapter forwards the credential ONLY as the upstream Authorization — it
	// is never echoed into any cave/inbound header (no persistence surface).
	for name, vals := range outA {
		if strings.EqualFold(name, "authorization") {
			continue
		}
		for _, v := range vals {
			if strings.Contains(v, tokenA) {
				t.Errorf("ADC token appears in non-auth header %s = %q", name, v)
			}
		}
	}
}

package vertex

import (
	"context"
	"fmt"
	"net/http"
	"net/url"
	"strings"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/shared/platform/env"
	"github.com/JuliusBrussee/caveman/shared/platform/ssrf"
)

// defaultPublishers is the built-in publisher allowlist. Operators override it
// with CAVE_VERTEX_PUBLISHER_ALLOWLIST (comma-separated). Pinning publishers to
// the families this gateway prices/supports keeps a client from invoking an
// unpriced partner model whose cost the catalog does not cover.
var defaultPublishers = []string{"google", "anthropic"}

// defaultModelPrefixes is the built-in model-id allowlist, matched as prefixes
// so versioned ids (gemini-2.5-pro, claude-sonnet-4-5@20250929) are covered.
// Operators override it with CAVE_VERTEX_MODEL_ALLOWLIST.
var defaultModelPrefixes = []string{"gemini-", "claude-"}

// ResolveUpstreamURL validates the Vertex request shape (publisher + model on
// the allowlist), enforces SSRF/host constraints against the aiplatform
// endpoint, and resolves the upstream URL. The /vertex prefix is stripped so the
// upstream path is the native aiplatform path
// (/v1/projects/{p}/locations/{l}/publishers/{pub}/models/{model}:{method}). The
// query string (e.g. ?alt=sse) is preserved unchanged — byte-safe passthrough.
func (a Adapter) ResolveUpstreamURL(ctx context.Context, req *http.Request, route providers.RouteContext) (*url.URL, error) {
	publisher, model, method := parsePredictPath(req.URL.Path)
	if publisher == "" || model == "" || method == "" {
		return nil, fmt.Errorf("vertex request path %q does not name a publisher, model, and method", req.URL.Path)
	}
	if !methodAllowed(publisher, method) {
		return nil, fmt.Errorf("vertex method %q is not allowed for publisher %q", method, publisher)
	}
	if !publisherAllowed(publisher) {
		return nil, fmt.Errorf("vertex publisher %q is not on the allowlist", publisher)
	}
	if !modelAllowed(model) {
		return nil, fmt.Errorf("vertex model %q is not on the allowlist", model)
	}

	baseURL := a.BaseURL
	if route.BaseURL != "" {
		baseURL = route.BaseURL
	}
	base, err := url.Parse(baseURL)
	if err != nil {
		return nil, fmt.Errorf("vertex base url invalid: %w", err)
	}
	base.Path = strings.TrimRight(base.Path, "/") + strings.TrimPrefix(req.URL.Path, "/vertex")
	base.RawQuery = req.URL.RawQuery

	// SSRF/host validation on the resolved endpoint. Active in managed (prod)
	// mode; local/self-hosted (stub) endpoints are permitted so the dry-run and
	// examples can target the provider-stub.
	if env.IsProduction() {
		if err := ssrf.ValidateURL(ctx, base.String(), ssrf.ManagedConfig()); err != nil {
			return nil, err
		}
		if host := base.Hostname(); !isVertexHost(host) {
			return nil, fmt.Errorf("vertex endpoint host %q is not an aiplatform host", host)
		}
	}
	return base, nil
}

func methodAllowed(publisher, method string) bool {
	switch publisher {
	case "google":
		return method == "generateContent" || method == "streamGenerateContent"
	case "anthropic":
		return method == "rawPredict" || method == "streamRawPredict"
	default:
		return false
	}
}

// InspectRequest fills in request metadata. Vertex carries the model id in the
// request path (.../models/{model}:{method}) rather than the body, so the model
// is resolved from the route path the proxy records in x-cave-route-path. The
// base inspector handles input bytes and message/tool counts.
func (a Adapter) InspectRequest(ctx context.Context, body providers.BodyReader, headers http.Header) (providers.RequestMetadata, error) {
	meta, err := a.Base.InspectRequest(ctx, body, headers)
	if err != nil {
		return meta, err
	}
	meta.Provider = a.Provider
	routePath := headers.Get("x-cave-route-path")
	if _, model, _ := parsePredictPath(routePath); model != "" {
		meta.Model = model
	}
	meta.Region = locationFromPredictPath(routePath)
	if requestType := strings.ToLower(strings.TrimSpace(headers.Get("x-vertex-ai-llm-request-type"))); requestType != "" {
		switch requestType {
		case "shared":
			meta.ServiceTier = "standard"
		case "dedicated":
			meta.ServiceTier = "provisioned_throughput"
		default:
			meta.PricingUnsupportedReason = "unsupported_traffic_type"
		}
	}
	// Streaming is selected by the method suffix (:streamGenerateContent /
	// :streamRawPredict), not by a body "stream" flag.
	if strings.Contains(routePath, ":streamGenerateContent") || strings.Contains(routePath, ":streamRawPredict") {
		meta.Stream = true
	}
	return meta, nil
}

// parsePredictPath extracts the publisher, model id, and method from a Vertex
// path of the form
// /vertex/v1/projects/{p}/locations/{l}/publishers/{publisher}/models/{model}:{method}.
// The model id may carry an @date version (claude-sonnet-4-5@20250929) but never
// a colon, so the trailing path segment splits on its last colon into
// model:method.
func parsePredictPath(path string) (publisher, model, method string) {
	rest := strings.TrimPrefix(path, "/vertex")
	parts := strings.Split(strings.TrimPrefix(rest, "/"), "/")
	for i, p := range parts {
		switch p {
		case "publishers":
			if i+1 < len(parts) {
				publisher = parts[i+1]
			}
		case "models":
			if i+1 < len(parts) {
				seg := parts[i+1]
				if idx := strings.LastIndex(seg, ":"); idx > 0 && idx < len(seg)-1 {
					model = seg[:idx]
					method = seg[idx+1:]
				}
			}
		}
	}
	return publisher, model, method
}

func locationFromPredictPath(path string) string {
	rest := strings.TrimPrefix(path, "/vertex")
	parts := strings.Split(strings.TrimPrefix(rest, "/"), "/")
	for i, part := range parts {
		if part == "locations" && i+1 < len(parts) {
			return parts[i+1]
		}
	}
	return ""
}

func publisherAllowed(publisher string) bool {
	return onAllowlist(publisher, allowlist("CAVE_VERTEX_PUBLISHER_ALLOWLIST", defaultPublishers), false)
}

func modelAllowed(model string) bool {
	return onAllowlist(model, allowlist("CAVE_VERTEX_MODEL_ALLOWLIST", defaultModelPrefixes), true)
}

// onAllowlist reports membership. When prefix is true an entry matches as a
// prefix of value (for versioned model ids); otherwise it is an exact match.
func onAllowlist(value string, list []string, prefix bool) bool {
	for _, entry := range list {
		if value == entry || (prefix && strings.HasPrefix(value, entry)) {
			return true
		}
	}
	return false
}

func allowlist(envKey string, fallback []string) []string {
	if raw := env.String(envKey, ""); raw != "" {
		out := []string{}
		for _, v := range strings.Split(raw, ",") {
			if v = strings.TrimSpace(v); v != "" {
				out = append(out, v)
			}
		}
		if len(out) > 0 {
			return out
		}
	}
	return fallback
}

// isVertexHost guards against the endpoint being repointed at a non-Vertex host
// in managed mode (defense-in-depth on top of the SSRF guard). It accepts the
// global host (aiplatform.googleapis.com), regional and global hosts
// ({location}-aiplatform.googleapis.com, incl. global-aiplatform...), and
// multi-region hosts (aiplatform.{us,eu}.rep.googleapis.com).
func isVertexHost(host string) bool {
	if host == "aiplatform.googleapis.com" {
		return true
	}
	if strings.HasSuffix(host, "-aiplatform.googleapis.com") {
		return true
	}
	if strings.HasPrefix(host, "aiplatform.") && strings.HasSuffix(host, ".rep.googleapis.com") {
		return true
	}
	return false
}

package vertex

import (
	"context"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
	"github.com/JuliusBrussee/caveman/shared/platform/catalog"
	"github.com/JuliusBrussee/caveman/shared/platform/cost"
)

// Gemini on Vertex returns usage in usageMetadata (camelCase). The shared
// ParseUsageBytes understands this shape, so the Vertex adapter needs no custom
// parser — this test proves the inherited path works end to end.
func TestParseUsage_GeminiUsageMetadata(t *testing.T) {
	a := newAdapter(t)
	body := `{"candidates":[{"content":{"parts":[{"text":"hi"}]}}],` +
		`"usageMetadata":{"promptTokenCount":1200,"candidatesTokenCount":340,"totalTokenCount":1580,"cachedContentTokenCount":600,"thoughtsTokenCount":40}}`
	usage, _, err := a.ParseUsage(context.Background(), http.Header{}, strings.NewReader(body))
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	if usage.InputTokens != 1200 || usage.OutputTokens != 380 {
		t.Errorf("tokens = %d/%d, want normalized total 1200/380", usage.InputTokens, usage.OutputTokens)
	}
	if usage.CachedInputTokens != 600 {
		t.Errorf("cached = %d, want 600", usage.CachedInputTokens)
	}
	if usage.ReasoningTokens != 40 {
		t.Errorf("reasoning = %d, want 40", usage.ReasoningTokens)
	}
	if usage.CacheStatus != "hit" {
		t.Errorf("cache_status = %q, want hit", usage.CacheStatus)
	}
}

// Claude on Vertex returns the native Anthropic Messages usage (snake_case),
// including cache telemetry. Also understood by the shared parser.
func TestParseUsage_ClaudeMessagesSnakeCaseWithCacheHit(t *testing.T) {
	a := newAdapter(t)
	body := `{"id":"msg_x","type":"message","role":"assistant","content":[{"type":"text","text":"hi"}],` +
		`"usage":{"input_tokens":200,"output_tokens":120,"cache_read_input_tokens":900,"cache_creation_input_tokens":0}}`
	usage, _, err := a.ParseUsage(context.Background(), http.Header{}, strings.NewReader(body))
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	if usage.InputTokens != 1100 || usage.OutputTokens != 120 {
		t.Errorf("tokens = %d/%d, want normalized total 1100/120", usage.InputTokens, usage.OutputTokens)
	}
	if usage.CachedInputTokens != 900 {
		t.Errorf("cached = %d, want 900", usage.CachedInputTokens)
	}
	if usage.CacheStatus != "hit" {
		t.Errorf("cache_status = %q, want hit", usage.CacheStatus)
	}
}

// No cache telemetry -> cache_status stays the honest "unknown".
func TestParseUsage_GeminiNoCacheStaysUnknown(t *testing.T) {
	a := newAdapter(t)
	body := `{"usageMetadata":{"promptTokenCount":500,"candidatesTokenCount":50,"totalTokenCount":550}}`
	usage, _, err := a.ParseUsage(context.Background(), http.Header{}, strings.NewReader(body))
	if err != nil {
		t.Fatalf("parse: %v", err)
	}
	if usage.CacheStatus != "unknown" {
		t.Errorf("cache_status = %q, want unknown (no cache telemetry)", usage.CacheStatus)
	}
}

// Catalog cost for a Vertex model in the catalog must be non-zero (the catalog
// entries were added with this adapter), proving usage+cost wiring.
func TestUsageAndCost_NonZeroForCatalogModels(t *testing.T) {
	for _, model := range []string{geminiModel, claudeModel} {
		price, version := catalog.Price("vertex", model)
		if strings.HasPrefix(version, "unpriced") {
			t.Fatalf("catalog missing vertex model %q (version=%q)", model, version)
		}
		if price.InputPerMillion <= 0 || price.OutputPerMillion <= 0 {
			t.Fatalf("catalog vertex price not set for %q: %+v", model, price)
		}
	}
}

// End-to-end: a Vertex request routed through the adapter against an
// aiplatform-shaped httptest stub records a truthful usage row — tokens and cost
// non-zero, cache_status honest, bearer token forwarded. Exercises
// ResolveUpstreamURL + (inherited) SanitizeAndMapHeaders + the real upstream
// call + ParseUsage together, for both model families.
func TestVertex_EndToEndTruthfulUsage(t *testing.T) {
	var sawAuth string
	stub := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		sawAuth = r.Header.Get("Authorization")
		w.Header().Set("content-type", "application/json")
		w.Header().Set("x-request-id", "vertex-stub-1")
		w.WriteHeader(http.StatusOK)
		if strings.Contains(r.URL.Path, "publishers/anthropic") {
			_, _ = w.Write([]byte(`{"id":"msg_x","type":"message","role":"assistant","content":[{"type":"text","text":"hi"}],` +
				`"usage":{"input_tokens":1500,"output_tokens":420,"cache_read_input_tokens":600,"cache_creation_input_tokens":0}}`))
			return
		}
		_, _ = w.Write([]byte(`{"candidates":[{"content":{"parts":[{"text":"hi"}]}}],` +
			`"usageMetadata":{"promptTokenCount":1500,"candidatesTokenCount":420,"totalTokenCount":1920,"cachedContentTokenCount":600}}`))
	}))
	defer stub.Close()

	a := New(stub.URL).(Adapter)

	cases := []struct {
		publisher string
		model     string
		method    string
		body      string
	}{
		{"google", geminiModel, "generateContent", `{"contents":[{"role":"user","parts":[{"text":"hi"}]}]}`},
		{"anthropic", claudeModel, "rawPredict", `{"anthropic_version":"vertex-2023-10-16","messages":[{"role":"user","content":"hi"}],"max_tokens":100}`},
	}
	for _, tc := range cases {
		path := predictPath(tc.publisher, tc.model, tc.method)
		inbound, _ := http.NewRequest(http.MethodPost, path, strings.NewReader(tc.body))
		inbound.Header.Set("content-type", "application/json")
		inbound.Header.Set("x-cave-route-path", path)

		upstreamURL, err := a.ResolveUpstreamURL(context.Background(), inbound, providers.RouteContext{})
		if err != nil {
			t.Fatalf("%s resolve: %v", tc.publisher, err)
		}
		headers, err := a.SanitizeAndMapHeaders(context.Background(), inbound, providers.Credential{Key: "ya29.vertex-access-token"}, nil)
		if err != nil {
			t.Fatalf("%s sanitize: %v", tc.publisher, err)
		}

		upReq, _ := http.NewRequest(http.MethodPost, upstreamURL.String(), strings.NewReader(tc.body))
		upReq.Header = headers
		resp, err := http.DefaultClient.Do(upReq)
		if err != nil {
			t.Fatalf("%s upstream call: %v", tc.publisher, err)
		}

		if !strings.HasPrefix(sawAuth, "Bearer ") {
			t.Errorf("%s: stub did not receive a Bearer Authorization header: %q", tc.publisher, sawAuth)
		}

		usage, _, err := a.ParseUsage(context.Background(), resp.Header, resp.Body)
		resp.Body.Close()
		if err != nil {
			t.Fatalf("%s parse usage: %v", tc.publisher, err)
		}
		if usage.InputTokens == 0 || usage.OutputTokens == 0 {
			t.Fatalf("%s: usage tokens are zero: %+v", tc.publisher, usage)
		}
		if usage.CachedInputTokens != 600 {
			t.Errorf("%s: cached = %d, want 600", tc.publisher, usage.CachedInputTokens)
		}
		if usage.CacheStatus != "hit" {
			t.Errorf("%s: cache_status = %q, want hit", tc.publisher, usage.CacheStatus)
		}
		if usage.ProviderRequestID != "vertex-stub-1" {
			t.Errorf("%s: provider request id = %q, want vertex-stub-1", tc.publisher, usage.ProviderRequestID)
		}

		price, _ := catalog.Price("vertex", tc.model)
		total := cost.EstimateUSD(price, cost.Usage{
			InputTokens:       usage.InputTokens - usage.CachedInputTokens,
			OutputTokens:      usage.OutputTokens,
			CachedInputTokens: usage.CachedInputTokens,
		})
		if total <= 0 {
			t.Fatalf("%s: cost = %v, want > 0 (truthful spend)", tc.publisher, total)
		}
	}
}

package vertex

import "github.com/JuliusBrussee/caveman/proxy/providers"

// Adapter is the Google Vertex AI gateway adapter. Like Bedrock, Vertex fronts
// multiple model families behind one cloud endpoint: Google Gemini
// (publishers/google, :generateContent) and Anthropic Claude
// (publishers/anthropic, :rawPredict). This adapter proxies both.
//
// It is deliberately thin. Vertex auth is a plain OAuth2 bearer token
// (Authorization: Bearer <google-access-token>), which the embedded
// providers.Base already emits in its default SanitizeAndMapHeaders case — so,
// unlike Bedrock, there is NO request signing here and NO custom header method.
// The caller (an SDK/CLI using Application Default Credentials or
// `gcloud auth print-access-token`) supplies a fresh access token per request;
// the gateway forwards it and holds no GCP secret.
//
// Usage parsing is likewise inherited: the shared providers.ParseUsageBytes
// already understands both shapes Vertex returns — Gemini camelCase
// (usageMetadata.promptTokenCount/candidatesTokenCount/cachedContentTokenCount/
// thoughtsTokenCount) and Claude snake_case (usage.input_tokens/
// cache_read_input_tokens/…). So there is no usage.go either.
//
// The ONLY Vertex-specific logic is upstream URL / host resolution (the
// aiplatform host family) plus a thin InspectRequest override for
// streaming-by-method. Both live in routing.go.
//
// Vertex is a byte-safe passthrough: the adapter swaps the base URL and sets the
// bearer header but never alters the model-visible request body, and registers
// no provider-native transform optimizers (the inherited pass-through
// Base.ApplyProviderNativeTransforms is used unchanged).
type Adapter struct {
	providers.Base
}

// Routes are the Vertex prediction paths the gateway proxies, prefixed with
// /vertex/. The native Vertex path carries the project, location, publisher,
// model, and method:
//
//	POST /vertex/v1/projects/{project}/locations/{location}/publishers/google/models/{model}:generateContent
//	POST /vertex/v1/projects/{project}/locations/{location}/publishers/google/models/{model}:streamGenerateContent
//	POST /vertex/v1/projects/{project}/locations/{location}/publishers/anthropic/models/{model}:rawPredict
//	POST /vertex/v1/projects/{project}/locations/{location}/publishers/anthropic/models/{model}:streamRawPredict
var Routes = []string{"/vertex/"}

// New constructs the Vertex adapter. baseURL is the aiplatform endpoint; in
// production it is a Vertex host (e.g. https://us-central1-aiplatform.googleapis.com
// or the global https://aiplatform.googleapis.com); locally it points at the
// provider-stub.
func New(baseURL string) providers.Adapter {
	return Adapter{Base: providers.Base{
		Provider: "vertex",
		BaseURL:  baseURL,
		Routes:   Routes,
	}}
}

package vertex

import (
	"context"
	"net/http"
	"strings"
	"testing"

	"github.com/JuliusBrussee/caveman/proxy/providers"
)

const stubBase = "https://us-central1-aiplatform.googleapis.com"
const geminiModel = "gemini-2.5-pro"
const claudeModel = "claude-sonnet-4-6"

func newAdapter(t *testing.T) Adapter {
	t.Helper()
	return New(stubBase).(Adapter)
}

// predictPath builds a native Vertex prediction path under the /vertex prefix.
func predictPath(publisher, model, method string) string {
	return "/vertex/v1/projects/demo-proj/locations/global/publishers/" + publisher + "/models/" + model + ":" + method
}

// --- Routing / allowlist -------------------------------------------------

func TestMatchRoute_VertexPredict(t *testing.T) {
	a := newAdapter(t)
	if !a.MatchRoute(http.MethodPost, predictPath("google", geminiModel, "generateContent")) {
		t.Error("vertex gemini route should match")
	}
	if !a.MatchRoute(http.MethodPost, predictPath("anthropic", claudeModel, "rawPredict")) {
		t.Error("vertex anthropic route should match")
	}
	if a.MatchRoute(http.MethodGet, predictPath("google", geminiModel, "generateContent")) {
		t.Error("only POST should match")
	}
	if a.MatchRoute(http.MethodPost, "/openai/v1/responses") {
		t.Error("non-vertex route must not match")
	}
}

func resolve(t *testing.T, a Adapter, path string) (string, error) {
	t.Helper()
	req, err := http.NewRequest(http.MethodPost, path, nil)
	if err != nil {
		t.Fatalf("bad url: %v", err)
	}
	u, err := a.ResolveUpstreamURL(context.Background(), req, providers.RouteContext{})
	if err != nil {
		return "", err
	}
	return u.String(), nil
}

func TestResolveUpstreamURL_StripsVertexPrefixAndKeepsQuery(t *testing.T) {
	a := newAdapter(t)
	path := predictPath("google", geminiModel, "streamGenerateContent") + "?alt=sse"
	got, err := resolve(t, a, path)
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	want := stubBase + "/v1/projects/demo-proj/locations/global/publishers/google/models/" + geminiModel + ":streamGenerateContent?alt=sse"
	if got != want {
		t.Errorf("upstream url = %q, want %q", got, want)
	}
}

func TestResolveUpstreamURL_ClaudeRawPredict(t *testing.T) {
	a := newAdapter(t)
	got, err := resolve(t, a, predictPath("anthropic", claudeModel, "rawPredict"))
	if err != nil {
		t.Fatalf("resolve: %v", err)
	}
	want := stubBase + "/v1/projects/demo-proj/locations/global/publishers/anthropic/models/" + claudeModel + ":rawPredict"
	if got != want {
		t.Errorf("upstream url = %q, want %q", got, want)
	}
}

func TestResolveUpstreamURL_RejectsUnknownPublisher(t *testing.T) {
	a := newAdapter(t)
	if _, err := resolve(t, a, predictPath("meta", "llama-3.1-405b", "rawPredict")); err == nil {
		t.Error("unlisted publisher should be rejected")
	}
}

func TestResolveUpstreamURL_RejectsUnknownModel(t *testing.T) {
	a := newAdapter(t)
	// google is allowed, but a non-gemini model is not on the model allowlist.
	if _, err := resolve(t, a, predictPath("google", "text-embedding-004", "predict")); err == nil {
		t.Error("unlisted model should be rejected")
	}
}

func TestResolveUpstreamURL_RejectsUnknownMethod(t *testing.T) {
	a := newAdapter(t)
	if _, err := resolve(t, a, predictPath("google", geminiModel, "predict")); err == nil {
		t.Error("unlisted Vertex method should be rejected")
	}
}

func TestResolveUpstreamURL_RejectsMalformedPath(t *testing.T) {
	a := newAdapter(t)
	// No :method suffix on the model segment.
	if _, err := resolve(t, a, "/vertex/v1/projects/p/locations/global/publishers/google/models/"+geminiModel); err == nil {
		t.Error("path without a method should be rejected")
	}
}

func TestParsePredictPath_VersionedModelWithAtDate(t *testing.T) {
	publisher, model, method := parsePredictPath(predictPath("anthropic", "claude-sonnet-4-5@20250929", "streamRawPredict"))
	if publisher != "anthropic" {
		t.Errorf("publisher = %q, want anthropic", publisher)
	}
	if model != "claude-sonnet-4-5@20250929" {
		t.Errorf("model = %q, want claude-sonnet-4-5@20250929", model)
	}
	if method != "streamRawPredict" {
		t.Errorf("method = %q, want streamRawPredict", method)
	}
}

func TestInspectRequest_ModelFromPathAndStream(t *testing.T) {
	a := newAdapter(t)

	// Gemini generateContent: model from path, not streaming.
	hg := http.Header{}
	hg.Set("x-cave-route-path", predictPath("google", geminiModel, "generateContent"))
	meta, err := a.InspectRequest(context.Background(), strings.NewReader(`{"contents":[]}`), hg)
	if err != nil {
		t.Fatalf("inspect: %v", err)
	}
	if meta.Provider != "vertex" {
		t.Errorf("provider = %q, want vertex", meta.Provider)
	}
	if meta.Model != geminiModel {
		t.Errorf("model = %q, want %q", meta.Model, geminiModel)
	}
	if meta.Stream {
		t.Error("generateContent should not set Stream")
	}

